void ErrorMessage::setMessage(const std::string &msg) {
    const std::string::size_type pos = msg.find('\n');
    if (pos == std::string::npos) {
        shortMessage = msg;
        verboseMessage = msg;
    } else {
        shortMessage = msg.substr(0, pos);
        verboseMessage = msg.substr(pos + 1);
    }
}

std::string callStackToString(const std::vector<FileLocation> &cs) {
    std::string str;
    for (size_t i = 0; i < cs.size(); ++i) {
        if (i > 0) str += " -> ";
        str += "[" + cs[i].file;
        if (cs[i].line != -1) str += ":" + std::to_string(cs[i].line);
        str += "]";
    }
    return str;
}

static void findAndReplace(std::string &source, const std::string &from, const std::string &to) {
    std::string::size_type pos = 0;
    while ((pos = source.find(from, pos)) != std::string::npos) {
        source.replace(pos, from.size(), to);
        pos += to.size();
    }
}

static std::string readCode(const std::string &file, int linenr, int column, const char endl[]) {
    std::ifstream fin(file);
    std::string line;
    while (linenr > 0 && std::getline(fin, line)) {
        linenr--;
    }
    const std::string::size_type endPos = line.find_last_not_of("\r\n\t ");
    if (endPos + 1 < line.size())
        line.erase(endPos + 1);
    std::string::size_type pos = 0;
    while ((pos = line.find('\t', pos)) != std::string::npos)
        line[pos] = ' ';
    return line + endl + std::string((column > 0 ? column - 1 : 0), ' ') + '^';
}

std::string ErrorMessage::toString(bool verbose, const std::string &templateFormat, const std::string &templateLocation) const {
    if (templateFormat.empty()) {
        std::string text;
        if (!callStack.empty()) {
            text += callStackToString(callStack);
            text += ": ";
        }
        if (severity != Severity::none) {
            text += '(';
            text += severityToString(severity);
            if (certainty == Certainty::inconclusive)
                text += ", inconclusive";
            text += ") ";
        }
        text += (verbose ? verboseMessage : shortMessage);
        return text;
    }

    std::string result = templateFormat;
    findAndReplace(result, "{id}", id);

    std::string::size_type pos1 = result.find("{inconclusive:");
    while (pos1 != std::string::npos) {
        const std::string::size_type pos2 = result.find('}', pos1 + 1);
        if (pos2 == std::string::npos) break;
        const std::string replaceFrom = result.substr(pos1, pos2 - pos1 + 1);
        const std::string replaceWith = (certainty == Certainty::inconclusive) ? result.substr(pos1 + 14, pos2 - pos1 - 14) : std::string();
        findAndReplace(result, replaceFrom, replaceWith);
        pos1 = result.find("{inconclusive:", pos1);
    }
    findAndReplace(result, "{severity}", severityToString(severity));
    findAndReplace(result, "{cwe}", std::to_string(cwe));
    findAndReplace(result, "{message}", verbose ? verboseMessage : shortMessage);
    if (!callStack.empty()) {
        if (result.find("{callstack}") != std::string::npos)
            findAndReplace(result, "{callstack}", callStackToString(callStack));
        findAndReplace(result, "{file}", callStack.back().file);
        findAndReplace(result, "{line}", std::to_string(callStack.back().line));
        findAndReplace(result, "{column}", std::to_string(callStack.back().column));
        if (result.find("{code}") != std::string::npos) {
            const std::string::size_type pos = result.find('\n');
            const char *endl = (pos == std::string::npos || pos == 0 || result[pos - 1] != '\r') ? "\n" : "\r\n";
            findAndReplace(result, "{code}", readCode(callStack.back().origFile, callStack.back().line, callStack.back().column, endl));
        }
    } else {
        findAndReplace(result, "{callstack}", "");
        findAndReplace(result, "{file}", "nofile");
        findAndReplace(result, "{line}", "0");
        findAndReplace(result, "{column}", "0");
        findAndReplace(result, "{code}", "");
    }

    if (!templateLocation.empty() && callStack.size() >= 2U) {
        for (const FileLocation &fileLocation : callStack) {
            std::string text = templateLocation;
            findAndReplace(text, "{file}", fileLocation.file);
            findAndReplace(text, "{line}", std::to_string(fileLocation.line));
            findAndReplace(text, "{column}", std::to_string(fileLocation.column));
            findAndReplace(text, "{info}", fileLocation.info.empty() ? shortMessage : fileLocation.info);
            if (text.find("{code}") != std::string::npos) {
                const std::string::size_type pos = text.find('\n');
                const char *endl = (pos == std::string::npos || pos == 0 || text[pos - 1] != '\r') ? "\n" : "\r\n";
                findAndReplace(text, "{code}", readCode(fileLocation.origFile, fileLocation.line, fileLocation.column, endl));
            }
            result += '\n' + text;
        }
    }

    // colors
    findAndReplace(result, "{reset}", color(0));
    findAndReplace(result, "{bold}", color(1));
    findAndReplace(result, "{dim}", color(2));
    findAndReplace(result, "{red}", color(31));
    findAndReplace(result, "{green}", color(32));
    findAndReplace(result, "{blue}", color(34));
    findAndReplace(result, "{magenta}", color(35));
    findAndReplace(result, "{default}", color(39));
    return result;
}

std::string xmlEscape(const std::string &s, bool attribute) {
    std::string r;
    for (char c : s) {
        switch (c) {
        case '&': r += "&amp;"; break;
        case '<': r += "&lt;"; break;
        case '>': r += "&gt;"; break;
        case '"': if (attribute) r += "&quot;"; else r += c; break;
        case '\'': if (attribute) r += "&apos;"; else r += c; break;
        default: r += c;
        }
    }
    return r;
}

std::string ErrorMessage::toXML() const {
    std::string s = "        <error";
    s += " id=\"" + xmlEscape(id, true) + "\"";
    s += " severity=\"" + severityToString(severity) + "\"";
    s += " msg=\"" + xmlEscape(shortMessage, true) + "\"";
    s += " verbose=\"" + xmlEscape(verboseMessage, true) + "\"";
    if (cwe > 0) s += " cwe=\"" + std::to_string(cwe) + "\"";
    if (hash > 0) s += " hash=\"" + std::to_string(hash) + "\"";
    if (certainty == Certainty::inconclusive) s += " inconclusive=\"true\"";
    if (!file0.empty()) s += " file0=\"" + xmlEscape(file0, true) + "\"";
    if (!guideline.empty()) s += " guideline=\"" + xmlEscape(guideline, true) + "\"";
    if (!classification.empty()) s += " classification=\"" + xmlEscape(classification, true) + "\"";
    bool hasChildren = !callStack.empty() || !symbolNames.empty();
    if (!hasChildren) {
        s += "/>";
        return s;
    }
    s += ">";
    for (auto it = callStack.rbegin(); it != callStack.rend(); ++it) {
        s += "\n            <location";
        s += " file=\"" + xmlEscape(it->file, true) + "\"";
        s += " line=\"" + std::to_string(it->line) + "\"";
        s += " column=\"" + std::to_string(it->column) + "\"";
        if (!it->info.empty()) s += " info=\"" + xmlEscape(it->info, true) + "\"";
        s += "/>";
    }
    for (const std::string &sym : symbolNames) {
        s += "\n            <symbol>" + xmlEscape(sym, false) + "</symbol>";
    }
    s += "\n        </error>";
    return s;
}

std::string ErrorMessage::key() const {
    return toString(false, "", "") + "|" + id;
}

bool isCriticalErrorId(const std::string &id) {
    static const char* const ids[] = {
        "cppcheckError", "cppcheckLimit", "internalAstError", "instantiationError", "internalError",
        "premium-internalError", "premium-invalidArgument", "premium-invalidLicense",
        "preprocessorErrorDirective", "syntaxError", "unknownMacro"
    };
    for (const char *i : ids) if (id == i) return true;
    return false;
}
