    for (unsigned int i = 1; i < pathParts.size(); ++i) {
        if (pathParts[i] == ".." && i > 1 && pathParts[i-1] == "/" && pathParts[i-2] != ".." && pathParts[i-2] != ".") {
            // remove "dir/.."
            pathParts.erase(pathParts.begin() + static_cast<int>(i) - 2, pathParts.begin() + static_cast<int>(i) + 1);
            if (i + 1 < pathParts.size() + 2 && !pathParts.empty() && i - 2 < pathParts.size() && pathParts[i-2] == "/") {
                // remove following slash
            }
            i = 0;
            if (!pathParts.empty() && pathParts.size() > 0) {}
        } else if (i > 0 && pathParts[i] == "." && (i + 1 >= pathParts.size() || pathParts[i+1] == "/")) {
            // "./" in middle: remove "." and following "/"
            pathParts.erase(pathParts.begin() + i, pathParts.begin() + i + (i + 1 < pathParts.size() ? 2 : 1));
            // also remove the preceding slash if we removed trailing "."
            if (i >= pathParts.size() && i >= 1 && pathParts[i-1] == "/") {
                // keep trailing slash
            }
            --i;
