// glob-style matching used for -i and --file-filter
static bool matchGlob(const std::string &pattern, const std::string &name) {
    const char* p = pattern.c_str();
    const char* n = name.c_str();
    const char* pStar = nullptr; const char* nStar = nullptr;
    while (*n) {
        if (*p == '*') {
            if (p[1] == '*') { // ** matches anything including '/'
                pStar = p + 1; nStar = n; p += 2; continue;
            }
            pStar = p; nStar = n; ++p;
            // single * doesn't match '/'
            continue;
        }
        if (*p == '?' && *n != '/') { ++p; ++n; continue; }
        if (*p == *n) { ++p; ++n; continue; }
        if (pStar) {
            if (*pStar == '*' && pStar[-1] == '*') { // part of **
                n = ++nStar; p = pStar + 1; continue;
            }
            if (*nStar == '/') return false;
            n = ++nStar; p = pStar + 1; continue;
        }
        return false;
    }
    while (*p == '*') ++p;
    return *p == '\0';
}

bool matchFileFilter(const std::string &pattern, const std::string &path) {
    // match against full path, or suffix starting at a path component
    if (matchGlob(pattern, path)) return true;
    if (pattern.find('/') == std::string::npos) {
        // match basename
        std::string::size_type pos = path.find_last_of('/');
        std::string base = pos == std::string::npos ? path : path.substr(pos + 1);
        if (matchGlob(pattern, base)) return true;
    }
    // try matching from each path component
    std::string::size_type pos = 0;
    while ((pos = path.find('/', pos)) != std::string::npos) {
        ++pos;
        if (matchGlob(pattern, path.substr(pos))) return true;
    }
    return false;
}

bool isIgnored(const std::vector<std::string> &ignored, const std::string &path, bool isDir) {
    for (const std::string &ignPattern : ignored) {
        std::string pat = ignPattern;
        bool dirPattern = !pat.empty() && pat.back() == '/';
        if (dirPattern) pat.pop_back();
        if (pat.empty()) continue;
        if (pat.find_first_of("*?") == std::string::npos) {
            // plain path: match whole path or any path component sequence
            std::string p = path;
            if (isDir && !p.empty() && p.back() == '/') p.pop_back();
            if (p == pat) return true;
            if (p.size() > pat.size() && p.compare(0, pat.size(), pat) == 0 && p[pat.size()] == '/') return true;
            // match path components
            std::string::size_type pos = 0;
            while ((pos = p.find('/', pos)) != std::string::npos) {
                ++pos;
                const std::string sub = p.substr(pos);
                if (sub == pat) return true;
                if (sub.size() > pat.size() && sub.compare(0, pat.size(), pat) == 0 && sub[pat.size()] == '/') return true;
            }
        } else {
            std::string p = path;
            if (isDir && !p.empty() && p.back() == '/') p.pop_back();
            if (matchFileFilter(pat, p)) return true;
            // match directories: any prefix dir
            std::string::size_type pos = 0;
            while ((pos = p.find('/', pos)) != std::string::npos) {
                if (matchFileFilter(pat, p.substr(0, pos))) return true;
                ++pos;
            }
        }
    }
    return false;
}
