bool Platform::set(const std::string &name) {
    if (name == "unix32") { type = Unix32; sizeof_long = 4; sizeof_pointer = 4; sizeof_size_t = 4; sizeof_long_double = 12; sizeof_wchar_t = 4; }
    else if (name == "unix64") { type = Unix64; sizeof_long = 8; sizeof_pointer = 8; sizeof_size_t = 8; sizeof_long_double = 16; sizeof_wchar_t = 4; }
    else if (name == "win32A" || name == "win32W") { type = (name == "win32A") ? Win32A : Win32W; sizeof_long = 4; sizeof_pointer = 4; sizeof_size_t = 4; sizeof_long_double = 8; sizeof_wchar_t = 2; }
    else if (name == "win64") { type = Win64; sizeof_long = 4; sizeof_pointer = 8; sizeof_size_t = 8; sizeof_long_double = 8; sizeof_wchar_t = 2; }
    else if (name == "native") { type = Native; sizeof_long = 8; sizeof_pointer = 8; sizeof_size_t = 8; sizeof_long_double = 16; sizeof_wchar_t = 4; }
    else if (name == "unspecified") { type = Unspecified; }
    else return false;
    return true;
}
std::string Platform::toString() const {
    switch (type) {
    case Unspecified: return "unspecified";
    case Native: return "native";
    case Win32A: return "win32A";
    case Win32W: return "win32W";
    case Win64: return "win64";
    case Unix32: return "unix32";
    case Unix64: return "unix64";
    case File: return "platformFile";
    }
    return "";
}

