static bool isInteger(const std::string &s) {
    if (s.empty()) return false;
    size_t i = 0;
    if (s[0] == '-' || s[0] == '+') { i = 1; if (s.size() == 1) return false; }
    for (; i < s.size(); ++i) if (!isdigit((unsigned char)s[i])) return false;
    return true;
}

bool CmdLineParser::parseNumberArg(const char* const arg, std::size_t offset, int &num, bool mustBePositive) {
    std::string argStr(arg + offset);
    if (!isInteger(argStr)) {
        printError("argument to '" + std::string(arg, offset) + "' is not valid - not an integer.");
        return false;
    }
    long long v = strtoll(argStr.c_str(), nullptr, 10);
    if (mustBePositive && v < 0) {
        printError("argument to '" + std::string(arg, offset) + "' needs to be a positive integer.");
        return false;
    }
    num = static_cast<int>(v);
    return true;
}

static bool isValidGlobPattern(const std::string &pattern) {
    for (std::string::const_iterator i = pattern.cbegin(); i != pattern.cend(); ++i) {
        if (*i == '*' || *i == '?') {
            const std::string::const_iterator j = i + 1;
            if (j != pattern.cend() && (*j == '*' || *j == '?')) return false;
        }
    }
    return true;
}

static bool isValidSuppressionId(const std::string &id) {
    if (id.empty()) return false;
    if (!(isalpha((unsigned char)id[0]) || id[0] == '*')) return false;
    for (char c : id) {
        if (!(isalnum((unsigned char)c) || c == '-' || c == '*' || c == '_' || c == '.')) return false;
    }
    return true;
}

// Parse a suppression specification "[error id]:[filename]:[line]"
static std::string parseSuppressionLine(const std::string &line, Suppression &s) {
    if (line.empty()) return "";
    // Format: id[:filename[:line]]
    std::string::size_type pos1 = line.find(':');
    std::string::size_type pos2 = std::string::npos;
    if (pos1 != std::string::npos) pos2 = line.rfind(':');
    s.errorId = (pos1 == std::string::npos) ? line : line.substr(0, pos1);
    if (pos1 != std::string::npos) {
        if (pos2 != std::string::npos && pos2 != pos1 && pos2 + 1 < line.size() && isInteger(line.substr(pos2 + 1))) {
            s.fileName = line.substr(pos1 + 1, pos2 - pos1 - 1);
            s.lineNumber = atoi(line.substr(pos2 + 1).c_str());
        } else {
            s.fileName = line.substr(pos1 + 1);
        }
    }
    if (s.errorId.empty()) return "Failed to add suppression. No id.";
    if (s.errorId != "*" || true) {
        // id validation: must start with alpha char (or '*')
        std::string id = s.errorId;
        if (!isValidSuppressionId(id)) return "Failed to add suppression. Invalid id \"" + id + "\"";
    }
    if (!s.fileName.empty()) {
        s.fileName = simplifyPath(s.fileName);
    }
    return "";
}

static std::string addSuppressionLine(Settings &settings, const std::string &line) {
    Suppression s;
    const std::string err = parseSuppressionLine(line, s);
    if (!err.empty()) return err;
    if (s.errorId.empty() && s.fileName.empty()) return "";
    // check for duplicates
    for (const Suppression &e : settings.suppressions) {
        if (e.errorId == s.errorId && e.fileName == s.fileName && e.lineNumber == s.lineNumber && e.symbolName == s.symbolName && e.type == s.type)
            return "";
    }
    settings.suppressions.push_back(s);
    return "";
}

static std::string parseSuppressionsFile(Settings &settings, std::istream &istr) {
    std::string line;
    while (std::getline(istr, line)) {
        // Skip empty lines and comments
        if (line.empty()) continue;
        if (line[0] == '#') continue;
        std::string::size_type c = line.find('#');
        if (c != std::string::npos) line.erase(c);
        // trim
        while (!line.empty() && (line.back() == ' ' || line.back() == '\t' || line.back() == '\r')) line.pop_back();
        if (line.empty()) continue;
        const std::string err = addSuppressionLine(settings, line);
        if (!err.empty()) return err;
    }
    return "";
}

static std::vector<std::string> splitString(const std::string &str, char sep) {
    std::vector<std::string> out;
    std::string::size_type start = 0;
    while (true) {
        std::string::size_type pos = str.find(sep, start);
        if (pos == std::string::npos) { out.push_back(str.substr(start)); break; }
        out.push_back(str.substr(start, pos - start));
        start = pos + 1;
    }
    return out;
}

static bool applyEnable(Settings &settings, const std::string &str, bool enable, std::string &errstr, const char* optname) {
    if (str.empty()) {
        errstr = std::string(optname) + " parameter is empty";
        return false;
    }
    std::string::size_type pos = 0;
    while (pos < str.size()) {
        std::string::size_type comma = str.find(',', pos);
        if (comma == std::string::npos) comma = str.size();
        std::string s = str.substr(pos, comma - pos);
        pos = comma + 1;
        if (s.empty()) {
            errstr = std::string(optname) + std::string(optname) + " parameter is empty";
            return false;
        }
        if (s == "all") {
            settings.sev_warning = settings.sev_style = settings.sev_performance = settings.sev_portability = settings.sev_information = enable;
            settings.checkUnusedFunction = enable;
            settings.checkMissingInclude = enable;
        } else if (s == "warning") settings.sev_warning = enable;
        else if (s == "style") {
            settings.sev_style = enable; settings.sev_warning = enable; settings.sev_performance = enable; settings.sev_portability = enable;
        }
        else if (s == "performance") settings.sev_performance = enable;
        else if (s == "portability") settings.sev_portability = enable;
        else if (s == "information") settings.sev_information = enable;
        else if (s == "unusedFunction") settings.checkUnusedFunction = enable;
        else if (s == "missingInclude") settings.checkMissingInclude = enable;
        else {
            errstr = std::string(optname) + " parameter with the unknown name '" + s + "'";
            return false;
        }
    }
    return true;
}

ParseResult CmdLineParser::parseFromArgs(int argc, const char* const argv[]) {
    if (argc <= 1) {
        printHelp();
        return ParseResult::Exit;
    }

    // pre-scan for options that print and exit
    for (int i = 1; i < argc; i++) {
        if (std::strcmp(argv[i], "--version") == 0) {
            printRaw(VERSION_STRING);
            return ParseResult::Exit;
        }
        if (std::strcmp(argv[i], "-h") == 0 || std::strcmp(argv[i], "--help") == 0) {
            printHelp();
            return ParseResult::Exit;
        }
        if (std::strcmp(argv[i], "--doc") == 0) {
            std::cout << DOC_TEXT;
            std::cout.flush();
            return ParseResult::Exit;
        }
        if (std::strcmp(argv[i], "--errorlist") == 0) {
            std::cout << ERRORLIST_TEXT;
            std::cout.flush();
            return ParseResult::Exit;
        }
    }

    bool def = false;
    bool maxconfigs = false;
    bool executorSet = false;
    bool outputFormatSet = false;
    bool xmlSet = false;
    bool xmlVersionSet = false;
    std::string executor;
    std::vector<std::string> pendingLibraries;

    for (int i = 1; i < argc; i++) {
        const char* const arg = argv[i];
        if (arg[0] == '-') {
            if (std::strncmp(arg, "--addon=", 8) == 0) {
                mSettings.addons.emplace_back(arg + 8);
            }
            else if (std::strncmp(arg, "--addon-python=", 15) == 0) {
                mSettings.addonPython = arg + 15;
            }
            else if (std::strcmp(arg, "--analyze-all-vs-configs") == 0) {
                mSettings.analyzeAllVsConfigs = true;
            }
            else if (std::strcmp(arg, "--check-config") == 0) {
                mSettings.checkConfiguration = true;
            }
            else if (std::strncmp(arg, "--check-level=", 14) == 0) {
                const std::string level = arg + 14;
                if (level == "reduced" || level == "normal" || level == "exhaustive") mSettings.checkLevel = level;
                else {
                    printError("unknown '--check-level' value '" + level + "'.");
                    return ParseResult::Fail;
                }
            }
            else if (std::strcmp(arg, "--check-library") == 0) {
                mSettings.checkLibrary = true;
            }
            else if (std::strcmp(arg, "--check-unused-templates") == 0) {
                mSettings.checkUnusedTemplates = true;
            }
            else if (std::strcmp(arg, "--no-check-unused-templates") == 0) {
                mSettings.checkUnusedTemplates = false;
            }
            else if (std::strncmp(arg, "--checkers-report=", 18) == 0) {
                mSettings.checkersReportFilename = arg + 18;
            }
            else if (std::strncmp(arg, "--clang", 7) == 0) {
                mSettings.clang = true;
                if (std::strncmp(arg, "--clang=", 8) == 0) {
                    mSettings.clangExecutable = arg + 8;
                } else if (std::strcmp(arg, "--clang") == 0) {
                    mSettings.clangExecutable = "clang";
                } else if (std::strcmp(arg, "--clang-tidy") == 0) {
                    mSettings.clang = false;
                    mSettings.clangTidy = true;
                } else {
                    printError("unrecognized command line option: \"" + std::string(arg) + "\".");
                    return ParseResult::Fail;
                }
            }
            else if (std::strncmp(arg, "--config-exclude=", 17) == 0) {
                mSettings.configExcludePaths.emplace_back(arg + 17);
            }
            else if (std::strncmp(arg, "--config-excludes-file=", 23) == 0) {
                const std::string fname = arg + 23;
                std::ifstream f(fname);
                if (!f.is_open()) {
                    printError("unable to open config excludes file at '" + fname + "'");
                    return ParseResult::Fail;
                }
                std::string line;
                while (std::getline(f, line)) {
                    if (!line.empty()) mSettings.configExcludePaths.push_back(line);
                }
            }
            else if (std::strcmp(arg, "--cpp-header-probe") == 0) {
                mSettings.cppHeaderProbe = true;
            }
            else if (std::strcmp(arg, "--no-cpp-header-probe") == 0) {
                mSettings.cppHeaderProbe = false;
            }
            else if (std::strncmp(arg, "--cppcheck-build-dir=", 21) == 0) {
                mSettings.buildDir = arg + 21;
                if (!mSettings.buildDir.empty() && mSettings.buildDir.back() == '/') mSettings.buildDir.pop_back();
            }
            else if (std::strcmp(arg, "--debug") == 0 || std::strcmp(arg, "--debug-normal") == 0) {
                mSettings.debugnormal = true;
            }
            else if (std::strcmp(arg, "--debug-simplified") == 0) {
                mSettings.debugSimplified = true;
            }
            else if (std::strcmp(arg, "--debug-symdb") == 0) {
                mSettings.debugSymdb = true;
            }
            else if (std::strcmp(arg, "--debug-ast") == 0) {
                mSettings.debugAst = true;
            }
            else if (std::strcmp(arg, "--debug-valueflow") == 0) {
                mSettings.debugValueflow = true;
            }
            else if (std::strcmp(arg, "--debug-template") == 0) {
                mSettings.debugTemplate = true;
            }
            else if (std::strcmp(arg, "--debug-clang-output") == 0) {
                mSettings.debugClangOutput = true;
            }
            else if (std::strcmp(arg, "--debug-ignore") == 0) {
                mSettings.debugIgnore = true;
            }
            else if (std::strncmp(arg, "--debug-lookup", 14) == 0) {
                if (std::strcmp(arg, "--debug-lookup") == 0 || std::strcmp(arg, "--debug-lookup=all") == 0) {
                    mSettings.debugLookup = true;
                    mSettings.debugLookupConfig = mSettings.debugLookupLibrary = mSettings.debugLookupPlatform = mSettings.debugLookupAddon = true;
                } else if (std::strncmp(arg, "--debug-lookup=", 15) == 0) {
                    const std::string what = arg + 15;
                    if (what == "addon") mSettings.debugLookupAddon = true;
                    else if (what == "config") mSettings.debugLookupConfig = true;
                    else if (what == "library") mSettings.debugLookupLibrary = true;
                    else if (what == "platform") mSettings.debugLookupPlatform = true;
                    else {
                        printError("unknown lookup '" + what + "'");
                        return ParseResult::Fail;
                    }
                } else {
                    printError("unrecognized command line option: \"" + std::string(arg) + "\".");
                    return ParseResult::Fail;
                }
            }
            else if (std::strcmp(arg, "--debug-warnings") == 0) {
                mSettings.debugwarnings = true;
            }
            else if (std::strncmp(arg, "--disable=", 10) == 0) {
                std::string err;
                if (!applyEnable(mSettings, arg + 10, false, err, "--disable")) {
                    printError(err);
                    return ParseResult::Fail;
                }
            }
            else if (std::strcmp(arg, "--dump") == 0) {
                mSettings.dump = true;
            }
            else if (std::strncmp(arg, "-D", 2) == 0) {
                std::string define;
                if (std::strcmp(arg, "-D") == 0) {
                    ++i;
                    if (i >= argc || argv[i][0] == '-') {
                        printError("argument to '-D' is missing.");
                        return ParseResult::Fail;
                    }
                    define = argv[i];
                } else {
                    define = arg + 2;
                }
                // No "=", append a "=1"
                if (define.find('=') == std::string::npos) define += "=1";
                if (!mSettings.userDefinesStr.empty()) mSettings.userDefinesStr += ";";
                mSettings.userDefinesStr += define;
                def = true;
            }
            else if (std::strcmp(arg, "--emit-duplicates") == 0) {
                mSettings.emitDuplicates = true;
            }
            else if (std::strncmp(arg, "--enable=", 9) == 0) {
                std::string err;
                if (!applyEnable(mSettings, arg + 9, true, err, "--enable")) {
                    printError(err);
                    return ParseResult::Fail;
                }
            }
            else if (std::strncmp(arg, "--error-exitcode=", 17) == 0) {
                if (!parseNumberArg(arg, 17, mSettings.exitCode)) return ParseResult::Fail;
            }
            else if (std::strncmp(arg, "--exception-handling", 20) == 0) {
                if (std::strcmp(arg, "--exception-handling") == 0) {
                    mSettings.exceptionHandling = true;
                    mSettings.exceptionOutput = "stderr";
                } else if (std::strncmp(arg, "--exception-handling=", 21) == 0) {
                    const std::string o = arg + 21;
                    if (o == "stdout" || o == "stderr") {
                        mSettings.exceptionHandling = true;
                        mSettings.exceptionOutput = o;
                    } else {
                        printError("invalid '--exception-handling' argument");
                        return ParseResult::Fail;
                    }
                } else {
                    printError("unrecognized command line option: \"" + std::string(arg) + "\".");
                    return ParseResult::Fail;
                }
            }
            else if (std::strncmp(arg, "--executor=", 11) == 0) {
                executor = arg + 11;
                if (executor == "thread" || executor == "process") executorSet = true;
                else {
                    printError("unknown executor: '" + executor + "'.");
                    return ParseResult::Fail;
                }
            }
            else if (std::strncmp(arg, "--exitcode-suppressions=", 24) == 0) {
                const std::string fname = arg + 24;
                std::ifstream f(fname);
                if (!f.is_open()) {
                    printError("couldn't open the file: \"" + fname + "\".");
                    return ParseResult::Fail;
                }
                // read and ignore
            }
            else if (std::strncmp(arg, "--file-filter=", 14) == 0) {
                const std::string ff = arg + 14;
                if (ff == "-") {
                    std::string line;
                    while (std::getline(std::cin, line)) {
                        if (!line.empty()) mSettings.fileFilters.push_back(line);
                    }
                } else if (!ff.empty()) {
                    mSettings.fileFilters.push_back(ff);
                }
            }
            else if (std::strncmp(arg, "--file-list=", 12) == 0) {
                const std::string fname = arg + 12;
                if (fname == "-") {
                    std::string line;
                    while (std::getline(std::cin, line)) {
                        if (!line.empty()) mPathNames.push_back(line);
                    }
                } else {
                    std::ifstream f(fname);
                    if (!f.is_open()) {
                        printError("couldn't open the file: \"" + fname + "\".");
                        return ParseResult::Fail;
                    }
                    std::string line;
                    while (std::getline(f, line)) {
                        if (!line.empty()) mPathNames.push_back(line);
                    }
                }
            }
            else if (std::strcmp(arg, "-f") == 0 || std::strcmp(arg, "--force") == 0) {
                mSettings.force = true;
            }
            else if (std::strcmp(arg, "--fsigned-char") == 0) {
                mSettings.defaultSign = 's';
            }
            else if (std::strcmp(arg, "--funsigned-char") == 0) {
                mSettings.defaultSign = 'u';
            }
            else if (std::strcmp(arg, "--filesdir") == 0) {
                printRaw(FILESDIR);
                return ParseResult::Exit;
            }
            else if (std::strncmp(arg, "-I", 2) == 0) {
                std::string path;
                if (std::strcmp(arg, "-I") == 0) {
                    ++i;
                    if (i >= argc || argv[i][0] == '-') {
                        printError("argument to '-I' is missing.");
                        return ParseResult::Fail;
                    }
                    path = argv[i];
                } else {
                    path = 2 + arg;
                }
                path = simplifyPath(path);
                if (path.empty() || path.back() != '/') path += '/';
                mSettings.includePaths.push_back(path);
            }
            else if (std::strncmp(arg, "--include=", 10) == 0) {
                mSettings.userIncludes.push_back(simplifyPath(arg + 10));
            }
            else if (std::strncmp(arg, "--includes-file=", 16) == 0) {
                const std::string fname = arg + 16;
                std::ifstream f(fname);
                if (!f.is_open()) {
                    printError("unable to open includes file at '" + fname + "'");
                    return ParseResult::Fail;
                }
                std::string line;
                while (std::getline(f, line)) {
                    if (line.empty()) continue;
                    std::string p = simplifyPath(line);
                    if (p.back() != '/') p += '/';
                    mSettings.includePaths.push_back(p);
                }
            }
            else if (std::strncmp(arg, "-i", 2) == 0) {
                std::string path;
                if (std::strcmp(arg, "-i") == 0) {
                    ++i;
                    if (i >= argc || argv[i][0] == '-') {
                        printError("argument to '-i' is missing.");
                        return ParseResult::Fail;
                    }
                    path = argv[i];
                } else {
                    path = 2 + arg;
                }
                if (!path.empty()) {
                    path = simplifyPath(path);
                    if (isDirectory(path)) {
                        if (path.back() != '/') path += '/';
                    }
                    mIgnoredPaths.emplace_back(std::move(path));
                }
            }
            else if (std::strcmp(arg, "--inconclusive") == 0) {
                mSettings.inconclusive = true;
            }
            else if (std::strcmp(arg, "--inline-suppr") == 0) {
                mSettings.inlineSuppressions = true;
            }
            else if (std::strncmp(arg, "-j", 2) == 0) {
                std::string numberString;
                if (std::strcmp(arg, "-j") == 0) {
                    ++i;
                    if (i >= argc || argv[i][0] == '-') {
                        printError("argument to '-j' is missing.");
                        return ParseResult::Fail;
                    }
                    numberString = argv[i];
                } else {
                    numberString = arg + 2;
                }
                if (!isInteger(numberString)) {
                    printError("argument to '-j' is not valid - not an integer.");
                    return ParseResult::Fail;
                }
                long long v = strtoll(numberString.c_str(), nullptr, 10);
                if (v <= 0) {
                    printError("argument for '-j' must be greater than 0.");
                    return ParseResult::Fail;
                }
                if (v > 1024) {
                    printError("argument for '-j' is allowed to be 1024 at max.");
                    return ParseResult::Fail;
                }
                mSettings.jobs = static_cast<int>(v);
            }
            else if (std::strncmp(arg, "-l", 2) == 0) {
                std::string numberString;
                if (std::strcmp(arg, "-l") == 0) {
                    ++i;
                    if (i >= argc || argv[i][0] == '-') {
                        printError("argument to '-l' is missing.");
                        return ParseResult::Fail;
                    }
                    numberString = argv[i];
                } else {
                    numberString = arg + 2;
                }
                if (!isInteger(numberString)) {
                    printError("argument to '-l' is not valid - not an integer.");
                    return ParseResult::Fail;
                }
                mSettings.loadAverage = atoi(numberString.c_str());
            }
            else if (std::strncmp(arg, "--language=", 11) == 0 || std::strcmp(arg, "-x") == 0) {
                std::string str;
                if (arg[2]) {
                    str = arg + 11;
                } else {
                    i++;
                    if (i >= argc || argv[i][0] == '-') {
                        printError("no language given to '-x' option.");
                        return ParseResult::Fail;
                    }
                    str = argv[i];
                }
                if (str == "c") mSettings.enforcedLang = Settings::C;
                else if (str == "c++") mSettings.enforcedLang = Settings::CPP;
                else {
                    printError("unknown language '" + str + "' enforced.");
                    return ParseResult::Fail;
                }
            }
            else if (std::strncmp(arg, "--library=", 10) == 0) {
                const std::string libs = arg + 10;
                if (libs.empty()) {
                    printError("empty library specified.");
                    return ParseResult::Fail;
                }
                for (const std::string &l : splitString(libs, ',')) {
                    mSettings.libraries.push_back(l);
                }
            }
            else if (std::strncmp(arg, "--max-configs=", 14) == 0) {
                int tmp;
                if (!parseNumberArg(arg, 14, tmp)) return ParseResult::Fail;
                if (tmp < 1) {
                    printError("argument to '--max-configs=' must be greater than 0.");
                    return ParseResult::Fail;
                }
                mSettings.maxConfigs = tmp;
                maxconfigs = true;
            }
            else if (std::strncmp(arg, "--max-ctu-depth=", 16) == 0) {
                if (!parseNumberArg(arg, 16, mSettings.maxCtuDepth)) return ParseResult::Fail;
            }
            else if (std::strncmp(arg, "--max-template-recursion=", 25) == 0) {
                if (!parseNumberArg(arg, 25, mSettings.maxTemplateRecursion)) return ParseResult::Fail;
            }
            else if (std::strcmp(arg, "--no-safety") == 0) {
                mSettings.safety = false;
            }
            else if (std::strncmp(arg, "--output-file=", 14) == 0) {
                mSettings.outputFile = simplifyPath(arg + 14);
            }
            else if (std::strncmp(arg, "--output-format=", 16) == 0) {
                const std::string format = arg + 16;
                if (format == "text") mSettings.outputFormat = OutputFormat::text;
                else if (format == "sarif") mSettings.outputFormat = OutputFormat::sarif;
                else if (format == "xml") { mSettings.outputFormat = OutputFormat::xml; mSettings.xmlVersion = 2; }
                else if (format == "xmlv2") { mSettings.outputFormat = OutputFormat::xml; mSettings.xmlVersion = 2; }
                else if (format == "xmlv3") { mSettings.outputFormat = OutputFormat::xml; mSettings.xmlVersion = 3; }
                else {
                    printError("argument to '--output-format=' must be 'text', 'sarif', 'xml' (deprecated), 'xmlv2' or 'xmlv3'.");
                    return ParseResult::Fail;
                }
                outputFormatSet = true;
            }
            else if (std::strncmp(arg, "--performance-valueflow-max-time=", 33) == 0) {
                if (!parseNumberArg(arg, 33, mSettings.performanceValueFlowMaxTime)) return ParseResult::Fail;
            }
            else if (std::strncmp(arg, "--performance-valueflow-max-if-count=", 37) == 0) {
                if (!parseNumberArg(arg, 37, mSettings.performanceValueFlowMaxIfCount)) return ParseResult::Fail;
            }
            else if (std::strncmp(arg, "--performance-valueflow-max-iterations=", 39) == 0) {
                if (!parseNumberArg(arg, 39, mSettings.performanceValueFlowMaxIterations)) return ParseResult::Fail;
            }
            else if (std::strncmp(arg, "--platform=", 11) == 0) {
                const std::string platform(11 + arg);
                if (mSettings.debugLookupPlatform) {
                    // builtin?
                    Platform tmp;
                    if (!tmp.set(platform)) {
                        std::cout << "looking for platform '" << platform << "'" << std::endl;
                        std::vector<std::string> paths;
                        const std::string cwd = getCurrentDir();
                        paths.push_back(cwd + "/" + platform + ".xml");
                        paths.push_back(cwd + "/platforms/" + platform + ".xml");
                        paths.push_back(mSettings.exepath + platform + ".xml");
                        paths.push_back(mSettings.exepath + "platforms/" + platform + ".xml");
                        paths.push_back(std::string(FILESDIR) + "/platforms/" + platform + ".xml");
                        for (const std::string &p : paths) {
                            std::cout << "try to load platform file '" << p << "' ... Error=XML_ERROR_FILE_NOT_FOUND ErrorID=3 (0x3) Line number=0: filename=" << p << std::endl;
                        }
                    }
                }
                if (!mSettings.platform.set(platform)) {
                    printError("unrecognized platform: '" + platform + "'.");
                    return ParseResult::Fail;
                }
                mSettings.platformString = platform;
            }
            else if (std::strncmp(arg, "--plist-output=", 15) == 0) {
                std::string path = simplifyPath(arg + 15);
                if (path.empty()) path = ".";
                if (!isDirectory(path)) {
                    printError("plist folder does not exist: '" + path + "'.");
                    return ParseResult::Fail;
                }
                if (path.back() != '/') path += '/';
                mSettings.plistOutput = path;
            }
            else if (std::strncmp(arg, "--project=", 10) == 0) {
                const std::string projectFile = arg + 10;
                if (!fileExists(projectFile)) {
                    printError("failed to open project '" + projectFile + "'. The file does not exist.");
                    return ParseResult::Fail;
                }
                const std::string ext = getFilenameExtension(projectFile, true);
                if (ext == ".sln" || ext == ".vcxproj" || ext == ".bpr" || ext == ".cppcheck" || getFilename(projectFile) == "compile_commands.json") {
                    printError("failed to load project '" + projectFile + "'. Project files are not supported.");
                } else {
                    printError("failed to load project '" + projectFile + "'. The format is unknown.");
                }
                return ParseResult::Fail;
            }
            else if (std::strncmp(arg, "--project-configuration=", 24) == 0) {
                mSettings.projectConfiguration = arg + 24;
            }
            else if (std::strcmp(arg, "-q") == 0 || std::strcmp(arg, "--quiet") == 0) {
                mSettings.quiet = true;
            }
            else if (std::strncmp(arg, "-rp", 3) == 0 || std::strncmp(arg, "--relative-paths", 16) == 0) {
                mSettings.relativePaths = true;
                if (arg[arg[1] == 'r' ? 3 : 16] == '=') {
                    std::string paths = arg + (arg[1] == 'r' ? 4 : 17);
                    for (;;) {
                        const std::string::size_type pos = paths.find(';');
                        if (pos == std::string::npos) {
                            mSettings.basePaths.push_back(simplifyPath(paths));
                            break;
                        }
                        mSettings.basePaths.push_back(simplifyPath(paths.substr(0, pos)));
                        paths.erase(0, pos + 1);
                    }
                } else if (std::strcmp(arg, "-rp") != 0 && std::strcmp(arg, "--relative-paths") != 0) {
                    printError("unrecognized command line option: \"" + std::string(arg) + "\".");
                    return ParseResult::Fail;
                }
            }
            else if (std::strcmp(arg, "--report-progress") == 0) {
                mSettings.reportProgress = true;
                mSettings.reportProgressVal = 10;
            }
            else if (std::strncmp(arg, "--report-type=", 14) == 0) {
                const std::string typeStr = arg + 14;
                static const char* types[] = {"normal", "autosar", "cert-c-2016", "cert-cpp-2016", "misra-c-2012", "misra-c-2023", "misra-c-2025", "misra-cpp-2008", "misra-cpp-2023"};
                bool found = false;
                for (const char* t : types) if (typeStr == t) found = true;
                if (!found) {
                    printError("Unknown report type '" + typeStr + "'");
                    return ParseResult::Fail;
                }
                mSettings.reportType = typeStr;
            }
            else if (std::strncmp(arg, "--rule=", 7) == 0) {
                printError("Option --rule cannot be used as Cppcheck has not been built with rules support.");
                return ParseResult::Fail;
            }
            else if (std::strncmp(arg, "--rule-file=", 12) == 0) {
                printError("Option --rule-file cannot be used as Cppcheck has not been built with rules support.");
                return ParseResult::Fail;
            }
            else if (std::strcmp(arg, "--safety") == 0) {
                mSettings.safety = true;
            }
            else if (std::strncmp(arg, "--showtime=", 11) == 0) {
                const std::string showtimeMode = arg + 11;
                if (showtimeMode == "file" || showtimeMode == "file-total" || showtimeMode == "summary" || showtimeMode == "top5" || showtimeMode == "top5_file" || showtimeMode == "top5_summary") {
                    mSettings.showtime = showtimeMode == "top5" ? "top5_file" : showtimeMode;
                    mSettings.showtimeSet = true;
                    if (showtimeMode == "top5") printMessage("--showtime=top5 is deprecated and will be removed in Cppcheck 2.14. Please use --showtime=top5_file or --showtime=top5_summary instead.");
                } else if (showtimeMode.empty() || showtimeMode == "none") {
                    mSettings.showtime = "none";
                } else {
                    printError("unrecognized --showtime mode: '" + showtimeMode + "'. Supported modes: file, file-total, summary, top5_file, top5_summary.");
                    return ParseResult::Fail;
                }
            }
            else if (std::strncmp(arg, "--std=", 6) == 0) {
                const std::string std = arg + 6;
                if (!mSettings.standards.setStd(std)) {
                    printError("unknown --std value '" + std + "'");
                    return ParseResult::Fail;
                }
            }
            else if (std::strncmp(arg, "--suppress=", 11) == 0) {
                const std::string suppression = arg + 11;
                const std::string err = addSuppressionLine(mSettings, suppression);
                if (!err.empty()) {
                    printError(err);
                    return ParseResult::Fail;
                }
            }
            else if (std::strncmp(arg, "--suppressions-list=", 20) == 0) {
                const std::string fname = arg + 20;
                std::ifstream f(fname);
                if (!f.is_open()) {
                    std::string message("couldn't open the file: \"");
                    message += fname;
                    message += "\".";
                    if (std::count(fname.cbegin(), fname.cend(), ',') > 0 || std::count(fname.cbegin(), fname.cend(), '.') > 1) {
                        message += "\nIf you want to pass two files, you can do it e.g. like this:";
                        message += "\n    cppcheck --suppressions-list=a.txt --suppressions-list=b.txt file.cpp";
                    }
                    printError(message);
                    return ParseResult::Fail;
                }
                const std::string err = parseSuppressionsFile(mSettings, f);
                if (!err.empty()) {
                    printError(err);
                    return ParseResult::Fail;
                }
            }
            else if (std::strncmp(arg, "--suppress-xml=", 15) == 0) {
                const std::string fname = arg + 15;
                std::ifstream f(fname);
                if (!f.is_open()) {
                    printError("failed to load suppressions XML '" + fname + "' (XML_ERROR_FILE_NOT_FOUND).");
                    return ParseResult::Fail;
                }
                // minimal XML suppression parsing
                std::stringstream ss; ss << f.rdbuf();
                std::string content = ss.str();
                std::string::size_type pos = 0;
                while ((pos = content.find("<suppress>", pos)) != std::string::npos) {
                    std::string::size_type end = content.find("</suppress>", pos);
                    if (end == std::string::npos) break;
                    std::string block = content.substr(pos, end - pos);
                    Suppression s;
                    auto getTag = [&](const char* tag) -> std::string {
                        std::string open = std::string("<") + tag + ">";
                        std::string close = std::string("</") + tag + ">";
                        std::string::size_type a = block.find(open);
                        if (a == std::string::npos) return "";
                        std::string::size_type b = block.find(close, a);
                        if (b == std::string::npos) return "";
                        return block.substr(a + open.size(), b - a - open.size());
                    };
                    s.errorId = getTag("id");
                    s.fileName = getTag("fileName");
                    std::string ln = getTag("lineNumber");
                    if (!ln.empty()) s.lineNumber = atoi(ln.c_str());
                    s.symbolName = getTag("symbolName");
                    if (!s.errorId.empty() || !s.fileName.empty()) mSettings.suppressions.push_back(s);
                    pos = end;
                }
            }
            else if (std::strncmp(arg, "--template=", 11) == 0) {
                mSettings.templateFormat = arg + 11;
                mSettings.templateSet = true;
                // replace "\n" "\t" "\r"
                auto repl = [](std::string &s, const std::string &from, const std::string &to) {
                    std::string::size_type p = 0;
                    while ((p = s.find(from, p)) != std::string::npos) { s.replace(p, from.size(), to); p += to.size(); }
                };
                if (mSettings.templateFormat == "gcc") {
                    mSettings.templateFormat = "{bold}{file}:{line}:{column}: {red}{inconclusive:{magenta}}{severity}:{inconclusive: inconclusive:}{default} {message} [{id}]{reset}\n{code}";
                    mSettings.templateLocation = "{bold}{file}:{line}:{column}: {dim}note:{reset} {info}\n{code}";
                } else if (mSettings.templateFormat == "daca2") {
                    mSettings.templateFormat = "{file}:{line}:{column}: {severity}:{inconclusive: inconclusive:} {message} [{id}]";
                    mSettings.templateLocation = "{file}:{line}:{column}: note: {info}";
                } else if (mSettings.templateFormat == "vs") {
                    mSettings.templateFormat = "{file}({line}): {severity}: {message}";
                } else if (mSettings.templateFormat == "edit") {
                    mSettings.templateFormat = "{file} +{line}: {severity}: {message}";
                } else if (mSettings.templateFormat == "cppcheck1") {
                    mSettings.templateFormat = "{callstack}: ({severity}{inconclusive:, inconclusive}) {message}";
                } else if (mSettings.templateFormat == "selfcheck") {
                    mSettings.templateFormat = "{file}:{line}:{column}: {severity}:{inconclusive: inconclusive:} {message} [{id}]\n{code}";
                    mSettings.templateLocation = "{file}:{line}:{column}: note: {info}\n{code}";
                } else if (mSettings.templateFormat == "simple") {
                    mSettings.templateFormat = "{file}:{line}:{column}: {severity}:{inconclusive: inconclusive:} {message} [{id}]";
                    mSettings.templateLocation = "";
                } else {
                    repl(mSettings.templateFormat, "\\b", "\b");
                    repl(mSettings.templateFormat, "\\n", "\n");
                    repl(mSettings.templateFormat, "\\r", "\r");
                    repl(mSettings.templateFormat, "\\t", "\t");
                }
            }
            else if (std::strncmp(arg, "--template-location=", 20) == 0) {
                mSettings.templateLocation = arg + 20;
                auto repl = [](std::string &s, const std::string &from, const std::string &to) {
                    std::string::size_type p = 0;
                    while ((p = s.find(from, p)) != std::string::npos) { s.replace(p, from.size(), to); p += to.size(); }
                };
                repl(mSettings.templateLocation, "\\b", "\b");
                repl(mSettings.templateLocation, "\\n", "\n");
                repl(mSettings.templateLocation, "\\r", "\r");
                repl(mSettings.templateLocation, "\\t", "\t");
            }
            else if (std::strncmp(arg, "--template-max-time=", 20) == 0) {
                if (!parseNumberArg(arg, 20, mSettings.templateMaxTime)) return ParseResult::Fail;
            }
            else if (std::strncmp(arg, "--typedef-max-time=", 19) == 0) {
                if (!parseNumberArg(arg, 19, mSettings.typedefMaxTime)) return ParseResult::Fail;
            }
            else if (std::strncmp(arg, "-U", 2) == 0) {
                std::string undef;
                if (std::strcmp(arg, "-U") == 0) {
                    ++i;
                    if (i >= argc || argv[i][0] == '-') {
                        printError("argument to '-U' is missing.");
                        return ParseResult::Fail;
                    }
                    undef = argv[i];
                } else {
                    undef = arg + 2;
                }
                mSettings.userUndefs.insert(undef);
            }
            else if (std::strncmp(arg, "--valueflow-max-iterations=", 27) == 0) {
                if (!parseNumberArg(arg, 27, mSettings.performanceValueFlowMaxIterations)) return ParseResult::Fail;
            }
            else if (std::strcmp(arg, "-v") == 0 || std::strcmp(arg, "--verbose") == 0) {
                mSettings.verbose = true;
            }
            else if (std::strcmp(arg, "-E") == 0) {
                mSettings.preprocessOnly = true;
                mSettings.quiet = true;
            }
            else if (std::strcmp(arg, "--xml") == 0) {
                mSettings.xml = true;
                xmlSet = true;
            }
            else if (std::strncmp(arg, "--xml-version=", 14) == 0) {
                int tmp;
                if (!parseNumberArg(arg, 14, tmp)) return ParseResult::Fail;
                if (tmp != 2 && tmp != 3) {
                    printError("'--xml-version' can only be 2 or 3.");
                    return ParseResult::Fail;
                }
                mSettings.xmlVersion = tmp;
                mSettings.xml = true;
                xmlVersionSet = true;
            }
            else {
                printError("unrecognized command line option: \"" + std::string(arg) + "\".");
                return ParseResult::Fail;
            }
        } else {
            mPathNames.emplace_back(simplifyPath(arg));
        }
    }

    if (outputFormatSet && (xmlSet || xmlVersionSet)) {
        printError("'--output-format' and '--xml...' may not be used in conjunction.");
        return ParseResult::Fail;
    }
    if (mSettings.xml) mSettings.outputFormat = OutputFormat::xml;

    if (!mSettings.projectConfiguration.empty()) {
        printError("--project-configuration has no effect - no Visual Studio project provided.");
        return ParseResult::Fail;
    }

    // Default template format..
    if (mSettings.templateFormat.empty()) {
        mSettings.templateFormat = "{bold}{file}:{line}:{column}: {red}{inconclusive:{magenta}}{severity}:{inconclusive: inconclusive:}{default} {message} [{id}]{reset}\n{code}";
        if (mSettings.templateLocation.empty())
            mSettings.templateLocation = "{bold}{file}:{line}:{column}: {dim}note:{reset} {info}\n{code}";
    }

    if (mSettings.force || maxconfigs) mSettings.maxConfigsSet = true;
    if (mSettings.force) mSettings.maxConfigs = INT_MAX;
    else if ((def || mSettings.preprocessOnly) && !maxconfigs) mSettings.maxConfigs = 1;

    if (mSettings.jobs > 1) {
        if (mSettings.checkUnusedFunction && mSettings.buildDir.empty()) {
            printMessage("unusedFunction check requires --cppcheck-build-dir to be active with -j.");
        }
    } else if (executorSet) {
        printMessage("'--executor' has no effect as only a single job will be used.");
    }

    if (!mSettings.buildDir.empty() && !isDirectory(mSettings.buildDir)) {
        printError("Directory '" + mSettings.buildDir + "' specified by --cppcheck-build-dir argument has to be existent.");
        return ParseResult::Fail;
    }

    if (mPathNames.empty()) {
        printError("no C or C++ source files found.");
        return ParseResult::Fail;
    }

    if (mSettings.basePaths.empty() && mSettings.relativePaths)
        mSettings.basePaths = mPathNames;

    (void)executor;
    return ParseResult::Success;
}

// glob-style matching used for -i and --file-filter
static bool matchGlob(const std::string &pattern, const std::string &name) {
    const char* p = pattern.c_str();
    const char* n = name.c_str();
    const char* pStar = nullptr; const char* nStar = nullptr;
    while (*n) {
        if (*p == '*') {
            if (p[1] == '*') { // ** matches anything including '/'
                pStar = p + 1; nStar = n; p += 2; continue;
            }
            pStar = p; nStar = n; ++p;
            // single * doesn't match '/'
            continue;
        }
        if (*p == '?' && *n != '/') { ++p; ++n; continue; }
        if (*p == *n) { ++p; ++n; continue; }
        if (pStar) {
            if (*pStar == '*' && pStar[-1] == '*') { // part of **
                n = ++nStar; p = pStar + 1; continue;
            }
            if (*nStar == '/') return false;
            n = ++nStar; p = pStar + 1; continue;
        }
        return false;
    }
    while (*p == '*') ++p;
    return *p == '\0';
}

bool matchFileFilter(const std::string &pattern, const std::string &path) {
    // match against full path, or suffix starting at a path component
    if (matchGlob(pattern, path)) return true;
    if (pattern.find('/') == std::string::npos) {
        // match basename
        std::string::size_type pos = path.find_last_of('/');
        std::string base = pos == std::string::npos ? path : path.substr(pos + 1);
        if (matchGlob(pattern, base)) return true;
    }
    // try matching from each path component
    std::string::size_type pos = 0;
    while ((pos = path.find('/', pos)) != std::string::npos) {
        ++pos;
        if (matchGlob(pattern, path.substr(pos))) return true;
    }
    return false;
}

bool isIgnored(const std::vector<std::string> &ignored, const std::string &path, bool isDir) {
    for (const std::string &ignPattern : ignored) {
        std::string pat = ignPattern;
        bool dirPattern = !pat.empty() && pat.back() == '/';
        if (dirPattern) pat.pop_back();
        if (pat.empty()) continue;
        if (pat.find_first_of("*?") == std::string::npos) {
            // plain path: match whole path or any path component sequence
            std::string p = path;
            if (isDir && !p.empty() && p.back() == '/') p.pop_back();
            if (p == pat) return true;
            if (p.size() > pat.size() && p.compare(0, pat.size(), pat) == 0 && p[pat.size()] == '/') return true;
            // match path components
            std::string::size_type pos = 0;
            while ((pos = p.find('/', pos)) != std::string::npos) {
                ++pos;
                const std::string sub = p.substr(pos);
                if (sub == pat) return true;
                if (sub.size() > pat.size() && sub.compare(0, pat.size(), pat) == 0 && sub[pat.size()] == '/') return true;
            }
        } else {
            std::string p = path;
            if (isDir && !p.empty() && p.back() == '/') p.pop_back();
            if (matchFileFilter(pat, p)) return true;
            // match directories: any prefix dir
            std::string::size_type pos = 0;
            while ((pos = p.find('/', pos)) != std::string::npos) {
                if (matchFileFilter(pat, p.substr(0, pos))) return true;
                ++pos;
            }
        }
    }
    return false;
}
