                if (semi != std::string::npos) {
                    std::string ent = t.substr(i + 1, semi - i - 1);
                    if (ent == "lt") r += '<';
                    else if (ent == "gt") r += '>';
                    else if (ent == "amp") r += '&';
                    else if (ent == "quot") r += '"';
                    else if (ent == "apos") r += '\'';
                    else if (!ent.empty() && ent[0] == '#') {
                        int code = (ent.size() > 1 && ent[1] == 'x') ? strtol(ent.c_str() + 2, nullptr, 16) : atoi(ent.c_str() + 1);
                        r += (char)code;
                    } else { r += t.substr(i, semi - i + 1); }
                    i = semi;
                    continue;
                }
            }
            r += t[i];
        }
        return r;
    }
    bool parseName(std::string &name) {
        size_t start = pos;
        while (pos < s.size() && (isalnum((unsigned char)s[pos]) || s[pos] == '_' || s[pos] == '-' || s[pos] == ':' || s[pos] == '.')) ++pos;
        name = s.substr(start, pos - start);
        return !name.empty();
    }
    bool parseElement(std::unique_ptr<XmlNode> &out) {
        // at '<'
        auto node = std::make_unique<XmlNode>();
        node->line = line;
        ++pos; // '<'
        if (!parseName(node->name)) return fail("XML_ERROR_PARSING_ELEMENT", 6);
        // attributes
        while (true) {
            skipWs();
            if (pos >= s.size()) return fail("XML_ERROR_PARSING_ELEMENT", 6);
            if (s[pos] == '/') {
                if (pos + 1 < s.size() && s[pos+1] == '>') { pos += 2; out = std::move(node); return true; }
                return fail("XML_ERROR_PARSING_ELEMENT", 6);
            }
            if (s[pos] == '>') { ++pos; break; }
            std::string an;
            if (!parseName(an)) return fail("XML_ERROR_PARSING_ATTRIBUTE", 7);
            skipWs();
            if (pos >= s.size() || s[pos] != '=') return fail("XML_ERROR_PARSING_ATTRIBUTE", 7);
            ++pos; skipWs();
            if (pos >= s.size() || (s[pos] != '"' && s[pos] != '\'')) return fail("XML_ERROR_PARSING_ATTRIBUTE", 7);
            char q = s[pos++];
            size_t end = s.find(q, pos);
            if (end == std::string::npos) return fail("XML_ERROR_PARSING_ATTRIBUTE", 7);
            std::string val = decode(s.substr(pos, end - pos));
            advanceTo(end + 1);
            node->attrs.emplace_back(an, val);
        }
        // content
        while (true) {
            if (pos >= s.size()) return fail("XML_ERROR_PARSING_ELEMENT", 6);
            if (s[pos] == '<') {
                if (startsWith("<!--")) {
                    size_t end = s.find("-->", pos);
                    if (end == std::string::npos) return fail("XML_ERROR_PARSING_COMMENT", 9);
                    advanceTo(end + 3);
                    continue;
                }
                if (startsWith("<![CDATA[")) {
                    size_t end = s.find("]]>", pos);
                    if (end == std::string::npos) return fail("XML_ERROR_PARSING_CDATA", 10);
                    node->text += s.substr(pos + 9, end - pos - 9);
                    advanceTo(end + 3);
                    continue;
                }
                if (startsWith("</")) {
                    size_t save = pos;
                    pos += 2;
                    std::string en;
                    parseName(en);
                    skipWs();
                    if (pos >= s.size() || s[pos] != '>' || en != node->name) { pos = save; return fail("XML_ERROR_MISMATCHED_ELEMENT", 15); }
                    ++pos;
                    out = std::move(node);
                    return true;
