                    size_t end = s.find("?>", pos);
                    if (end == std::string::npos) return fail("XML_ERROR_PARSING_DECLARATION", 11);
                    advanceTo(end + 2);
                    continue;
                }
                std::unique_ptr<XmlNode> child;
                if (!parseElement(child)) return false;
                node->children.push_back(std::move(child));
            } else {
                size_t end = s.find('<', pos);
                if (end == std::string::npos) return fail("XML_ERROR_PARSING_TEXT", 8);
                std::string t = s.substr(pos, end - pos);
                // trim whitespace-only text
                bool allws = true;
                for (char c : t) if (!isspace((unsigned char)c)) { allws = false; break; }
                if (!allws) node->text += decode(t);
                advanceTo(end);
            }
        }
    }
    bool parse() {
        skipWs();
        // BOM
        if (s.compare(0, 3, "\xEF\xBB\xBF") == 0) pos = 3;
        while (pos < s.size()) {
            skipWs();
            if (pos >= s.size()) break;
            if (s[pos] != '<') return fail("XML_ERROR_PARSING_TEXT", 8);
            if (startsWith("<?")) {
                size_t end = s.find("?>", pos);
                if (end == std::string::npos) return fail("XML_ERROR_PARSING_DECLARATION", 11);
                advanceTo(end + 2);
                continue;
            }
            if (startsWith("<!--")) {
                size_t end = s.find("-->", pos);
                if (end == std::string::npos) return fail("XML_ERROR_PARSING_COMMENT", 9);
                advanceTo(end + 3);
                continue;
            }
            if (startsWith("<!")) {
                size_t end = s.find('>', pos);
                if (end == std::string::npos) return fail("XML_ERROR_PARSING_UNKNOWN", 12);
                advanceTo(end + 1);
                continue;
            }
            std::unique_ptr<XmlNode> el;
            if (!parseElement(el)) return false;
            if (!doc.root) doc.root = std::move(el);
        }
        if (!doc.root) return fail("XML_ERROR_EMPTY_DOCUMENT", 13);
        return true;
    }
};
}

