static const char FILESDIR[] = "/usr/local/share/Cppcheck";

static bool readFile(const std::string &path, std::string &out) {
    std::ifstream f(path, std::ios::binary);
    if (!f.is_open()) return false;
    if (isDirectory(path)) return false;
    std::stringstream ss; ss << f.rdbuf();
    out = ss.str();
    return true;
}

Library::Error Library::load(const std::string &exepath, const std::string &path, bool debugLookup, std::string &lookupLog) {
    std::string fullfilename = path;
    const bool absolute = !path.empty() && path[0] == '/';
    if (!absolute && getFilenameExtension(fullfilename).empty())
        fullfilename += ".cfg";

    std::vector<std::string> candidates;
    candidates.push_back(fullfilename);
    if (!absolute) {
        candidates.push_back(exepath + fullfilename);
        candidates.push_back(exepath + "cfg/" + fullfilename);
        candidates.push_back(std::string(FILESDIR) + "/cfg/" + fullfilename);
    }
    std::string content;
    std::string found;
    for (const std::string &c : candidates) {
        if (debugLookup) lookupLog += "looking for library '" + c + "'\n";
        if (readFile(c, content)) { found = c; break; }
    }
    if (found.empty()) {
        if (debugLookup) lookupLog += "library not found: '" + path + "'\n";
        return Error(ErrorCode::FILE_NOT_FOUND);
    }
    return loadFromText(content, found);
}

static int toInt(const char* s, int def = 0) {
    if (!s) return def;
    return atoi(s);
}

Library::Error Library::loadFromText(const std::string &xml, const std::string &filename) {
    XmlDoc doc;
    if (!doc.parse(xml)) {
        std::cout << "Error=" << doc.errorName << " ErrorID=" << doc.errorId << " (0x" << std::hex << doc.errorId << std::dec << ") Line number=" << doc.errorLine << std::endl;
        return Error(ErrorCode::BAD_XML);
    }
    const XmlNode* root = doc.root.get();
    if (root->name != "def") return Error(ErrorCode::UNSUPPORTED_FORMAT, root->name);
    const char* format = root->attr("format");
    const int fmt = format ? atoi(format) : 1;
    if (fmt > 2) return Error(ErrorCode::UNSUPPORTED_FORMAT);

    std::set<std::string> unknown;
    for (const auto &nodePtr : root->children) {
        const XmlNode &node = *nodePtr;
        const std::string &nodename = node.name;
        if (nodename == "memory" || nodename == "resource") {
            const bool isResource = nodename == "resource";
            // group id
            ++nextGroupId;
            int gid = nextGroupId;
            for (const auto &mn : node.children) {
                const std::string &mname = mn->name;
                if (mname == "alloc" || mname == "realloc") {
                    LibAllocFunc af;
                    af.name = mn->text;
                    af.groupId = gid;
                    af.isResource = isResource;
                    af.isRealloc = (mname == "realloc");
                    const char* init = mn->attr("init");
                    af.initData = !(init && strcmp(init, "false") == 0);
                    af.arg = toInt(mn->attr("arg"), -1);
                    af.reallocArg = toInt(mn->attr("realloc-arg"), 1);
                    const char* bs = mn->attr("buffer-size");
                    if (bs) af.bufferSize = bs;
                    const char* nf = mn->attr("no-fail");
                    af.noFail = nf && strcmp(nf, "true") == 0;
                    allocFuncs[af.name] = af;
                } else if (mname == "dealloc") {
                    LibDeallocFunc df;
                    df.name = mn->text;
                    df.groupId = gid;
                    df.isResource = isResource;
                    df.arg = toInt(mn->attr("arg"), 1);
                    deallocFuncs[df.name] = df;
                } else if (mname == "use") {
                    // ignore
                } else {
                    unknown.insert(mname);
                }
            }
        }
        else if (nodename == "define") {
            const char* name = node.attr("name");
            if (!name) return Error(ErrorCode::MISSING_ATTRIBUTE, "name");
            const char* value = node.attr("value");
            if (!value) return Error(ErrorCode::MISSING_ATTRIBUTE, "value");
            std::string def = std::string(name) + " " + value;
            defines[name] = def;
            defineList.push_back(def);
        }
        else if (nodename == "function") {
            const char* name = node.attr("name");
            if (!name) return Error(ErrorCode::MISSING_ATTRIBUTE, "name");
            std::string names = name;
            std::vector<std::string> nameList;
            std::string::size_type start = 0;
            while (true) {
                std::string::size_type comma = names.find(',', start);
                nameList.push_back(names.substr(start, comma == std::string::npos ? std::string::npos : comma - start));
                if (comma == std::string::npos) break;
