static bool readFile(const std::string &path, std::string &out) {
    std::ifstream f(path, std::ios::binary);
    if (!f.is_open()) return false;
    if (isDirectory(path)) return false;
    std::stringstream ss; ss << f.rdbuf();
    out = ss.str();
    return true;
}

Library::Error Library::load(const std::string &exepath, const std::string &path, bool debugLookup, std::string &lookupLog) {
    std::string fullfilename = path;
    const bool absolute = !path.empty() && path[0] == '/';
    if (!absolute && getFilenameExtension(fullfilename).empty())
        fullfilename += ".cfg";

    std::vector<std::string> candidates;
    candidates.push_back(fullfilename);
    if (!absolute) {
        candidates.push_back(exepath + fullfilename);
        candidates.push_back(exepath + "cfg/" + fullfilename);
        candidates.push_back(std::string(FILESDIR) + "/cfg/" + fullfilename);
    }
    std::string content;
    std::string found;
    for (const std::string &c : candidates) {
        if (debugLookup) lookupLog += "looking for library '" + c + "'\n";
        if (readFile(c, content)) { found = c; break; }
    }
    if (found.empty()) {
        if (debugLookup) lookupLog += "library not found: '" + path + "'\n";
        return Error(ErrorCode::FILE_NOT_FOUND);
    }
    return loadFromText(content, found);
}

static int toInt(const char* s, int def = 0) {
    if (!s) return def;
    return atoi(s);
