                    pt.platforms.push_back(t);
                } else unknown.insert(pnname);
            }
            platformTypes[name] = pt;
        }
        else if (nodename == "entrypoint") {
            const char* name = node.attr("name");
            if (!name) return Error(ErrorCode::MISSING_ATTRIBUTE, "name");
            entrypoints.insert(name);
        }
        else if (nodename == "keyword") {
            // accepted
        }
        else {
            unknown.insert(nodename);
        }
    }
    if (!unknown.empty()) {
        std::string list;
        for (const std::string &u : unknown) {
            if (!list.empty()) list += ", ";
            list += u;
        }
        return Error(ErrorCode::UNKNOWN_ELEMENT, list);
    }
    (void)filename;
    return Error(ErrorCode::OK);
}
