static const char FILESDIR[] = "/usr/local/share/Cppcheck";

class StdLogger : public ErrorLogger {
public:
    explicit StdLogger(const Settings &settings) : mSettings(settings) {
        if (!settings.outputFile.empty()) {
            mErrorOutput = new std::ofstream(settings.outputFile);
        }
    }
    ~StdLogger() override {
        delete mErrorOutput;
    }
    void reportOut(const std::string &outmsg) override {
        if (mSettings.outputFormat == OutputFormat::xml) {
            // xml output goes to stderr, other output to stdout
        }
        std::cout << outmsg << std::endl;
    }
    void reportErr(const ErrorMessage &msg) override {
        if (mSettings.outputFormat == OutputFormat::sarif) {
            mErrorList.push_back(msg);
            return;
        }
        if (mSettings.outputFormat == OutputFormat::xml) {
            reportErrStr(msg.toXML());
        } else {
            reportErrStr(msg.toString(mSettings.verbose, mSettings.templateFormat, mSettings.templateLocation));
        }
    }
    void reportErrStr(const std::string &errmsg) {
        if (mErrorOutput) *mErrorOutput << errmsg << std::endl;
        else std::cerr << errmsg << std::endl;
    }
    void writeXmlHeader() {
        std::string h = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<results version=\"" + std::to_string(mSettings.xmlVersion) + "\">\n    <cppcheck version=\"2.19 dev\"/>\n    <errors>";
        reportErrStr(h);
    }
    void writeXmlFooter(const std::string &extra) {
        std::string f = "    </errors>";
        if (!extra.empty()) f += "\n" + extra;
        f += "\n</results>";
        reportErrStr(f);
    }
    void writeSarif();
    std::vector<ErrorMessage> mErrorList;
private:
    const Settings &mSettings;
    std::ofstream *mErrorOutput = nullptr;
};

static std::string jsonEscape(const std::string &s) {
    std::string r;
    for (char c : s) {
        switch (c) {
        case '"': r += "\\\""; break;
        case '\\': r += "\\\\"; break;
        case '/': r += "\\/"; break;
        case '\n': r += "\\n"; break;
        case '\r': r += "\\r"; break;
        case '\t': r += "\\t"; break;
        case '\b': r += "\\b"; break;
        case '\f': r += "\\f"; break;
        default:
            if ((unsigned char)c < 0x20) {
                char buf[8]; snprintf(buf, sizeof(buf), "\\u%04x", (unsigned char)c); r += buf;
            } else r += c;
        }
    }
    return r;
}

static std::string sarifLevel(Severity s) {
    switch (s) {
    case Severity::error: return "error";
    case Severity::warning: return "warning";
    default: return "note";
    }
}
static std::string sarifSecuritySeverity(const ErrorMessage &m) {
    switch (m.severity) {
    case Severity::error: return "9.9";
    case Severity::warning: return "8.5";
    case Severity::style: case Severity::performance: case Severity::portability: return "5.5";
    default: return "";
    }
}

void StdLogger::writeSarif() {
    std::string o;
    o += "{\n";
    o += "  \"version\": \"2.1.0\",\n";
    o += "  \"$schema\": \"https:\\/\\/docs.oasis-open.org\\/sarif\\/sarif\\/v2.1.0\\/errata01\\/os\\/schemas\\/sarif-schema-2.1.0.json\",\n";
    o += "  \"runs\": [\n    {\n      \"results\": [";
    bool first = true;
    std::vector<std::string> ruleOrder;
    std::map<std::string, const ErrorMessage*> rules;
    for (const ErrorMessage &m : mErrorList) {
        if (m.callStack.empty()) continue;
        if (!rules.count(m.id)) { rules[m.id] = &m; ruleOrder.push_back(m.id); }
        o += first ? "\n" : ",\n";
        first = false;
        o += "        {\n";
        o += "          \"level\": \"" + sarifLevel(m.severity) + "\",\n";
        o += "          \"locations\": [";
        bool firstLoc = true;
        for (const FileLocation &loc : m.callStack) {
            o += firstLoc ? "\n" : ",\n";
            firstLoc = false;
            o += "            {\n              \"physicalLocation\": {\n                \"artifactLocation\": {\n                  \"uri\": \"" + jsonEscape(loc.file) + "\"\n                },\n";
            o += "                \"region\": {\n                  \"endColumn\": " + std::to_string(loc.column) + ",\n                  \"endLine\": " + std::to_string(loc.line) + ",\n                  \"startColumn\": " + std::to_string(loc.column) + ",\n                  \"startLine\": " + std::to_string(loc.line) + "\n                }\n              }\n            }";
        }
        o += "\n          ],\n";
        o += "          \"message\": {\n            \"text\": \"" + jsonEscape(m.shortMessage) + "\"\n          },\n";
        o += "          \"ruleId\": \"" + jsonEscape(m.id) + "\"\n";
        o += "        }";
    }
    o += first ? "],\n" : "\n      ],\n";
    o += "      \"tool\": {\n        \"driver\": {\n          \"informationUri\": \"https:\\/\\/cppcheck.sourceforge.io\",\n          \"name\": \"Cppcheck\",\n          \"rules\": [";
    first = true;
    for (const std::string &id : ruleOrder) {
        const ErrorMessage &m = *rules[id];
        o += first ? "\n" : ",\n";
        first = false;
        o += "            {\n";
        o += "              \"defaultConfiguration\": {\n                \"level\": \"" + sarifLevel(m.severity) + "\"\n              },\n";
        o += "              \"fullDescription\": {\n                \"text\": \"" + jsonEscape(m.verboseMessage == m.shortMessage ? "" : "") + "\"\n              },\n";
        o += "              \"help\": {\n                \"text\": \"\"\n              },\n";
        o += "              \"id\": \"" + jsonEscape(id) + "\",\n";
        o += "              \"name\": \"\",\n";
        o += "              \"properties\": {\n                \"precision\": \"high\",\n                \"problem.severity\": \"" + sarifLevel(m.severity) + "\"";
        const std::string ss = sarifSecuritySeverity(m);
        if (m.cwe > 0 && !ss.empty()) {
            o += ",\n                \"security-severity\": \"" + ss + "\",\n                \"tags\": [\n                  \"external\\/cwe\\/cwe-" + std::to_string(m.cwe) + "\",\n                  \"security\"\n                ]";
        }
        o += "\n              },\n";
        o += "              \"shortDescription\": {\n                \"text\": \"\"\n              }\n";
        o += "            }";
    }
    o += first ? "],\n" : "\n          ],\n";
    o += "          \"semanticVersion\": \"2.19\"\n        }\n      }\n    }\n  ]\n}\n";
    reportErrStr(o);
}

static std::string getExePath() {
    char buf[PATH_MAX];
    ssize_t n = readlink("/proc/self/exe", buf, sizeof(buf) - 1);
    if (n > 0) { buf[n] = 0; return buf; }
    return "";
}

static bool acceptFile(const std::string &path, Settings::Language &lang, const std::set<std::string> &extraExt) {
    std::string ext = getFilenameExtension(path, false);
    if (ext == ".cpp" || ext == ".cxx" || ext == ".cc" || ext == ".c++" || ext == ".ipp" || ext == ".ixx" || ext == ".tpp" || ext == ".txx") { lang = Settings::CPP; return true; }
    if (ext == ".c") { lang = Settings::C; return true; }
    if (!ext.empty() && extraExt.count(ext)) { lang = Settings::CPP; return true; }
    return false;
}

static std::size_t fileSize(const std::string &path) {
    struct stat st;
    if (stat(path.c_str(), &st) == 0) return (std::size_t)st.st_size;
    return 0;
}

static void addFilesRecursive(std::map<std::string, FileWithDetails> &files, const std::string &path, const std::vector<std::string> &ignored, const std::set<std::string> &extraExt, bool debugIgnore) {
    DIR *dir = opendir(path.empty() ? "." : path.c_str());
    if (!dir) return;
    std::vector<std::string> entries;
    while (struct dirent *de = readdir(dir)) {
        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
        entries.push_back(de->d_name);
    }
    closedir(dir);
    std::sort(entries.begin(), entries.end());
    for (const std::string &e : entries) {
        std::string full = path;
        if (!full.empty() && full != "." ) { if (full.back() != '/') full += '/'; full += e; }
        else full = e;
        if (isDirectory(full)) {
            if (isIgnored(ignored, full + "/", true)) {
                if (debugIgnore) std::cout << "ignored path: " << full << std::endl;
                continue;
            }
            addFilesRecursive(files, full, ignored, extraExt, debugIgnore);
        } else {
            Settings::Language lang;
            if (!acceptFile(full, lang, extraExt)) continue;
            if (isIgnored(ignored, full, false)) {
                if (debugIgnore) std::cout << "ignored path: " << full << std::endl;
                continue;
            }
            FileWithDetails f;
            f.path = full; f.lang = lang; f.size = fileSize(full);
            files[full] = f;
        }
    }
}

int main(int argc, char **argv) {
    Settings settings;
    settings.exename = getExePath();
    settings.exepath = getPathFromFilename(settings.exename);

    CmdLineParser parser(settings);
    const ParseResult pr = parser.parseFromArgs(argc, argv);
    if (pr == ParseResult::Exit) return 0;
    if (pr == ParseResult::Fail) return 1;

    if (settings.debugLookupConfig) {
        std::cout << "looking for '" << FILESDIR << "/cppcheck.cfg'" << std::endl;
        std::cout << "looking for '" << settings.exepath << "cppcheck.cfg'" << std::endl;
        std::cout << "no configuration found" << std::endl;
    }

    // load libraries
    Library library;
    {
        std::string log;
        Library::Error err = library.load(settings.exepath, "std.cfg", settings.debugLookupLibrary, log);
        if (!log.empty()) std::cout << log;
        auto reportLibError = [&](const std::string &name, const Library::Error &e) -> bool {
            std::string errmsg;
            switch (e.code) {
            case Library::ErrorCode::OK: return true;
            case Library::ErrorCode::FILE_NOT_FOUND: errmsg = "File not found"; break;
            case Library::ErrorCode::BAD_XML: errmsg = "Bad XML"; break;
            case Library::ErrorCode::UNKNOWN_ELEMENT: errmsg = "Unexpected element"; break;
            case Library::ErrorCode::MISSING_ATTRIBUTE: errmsg = "Missing attribute"; break;
            case Library::ErrorCode::BAD_ATTRIBUTE_VALUE: errmsg = "Bad attribute value"; break;
            case Library::ErrorCode::UNSUPPORTED_FORMAT: errmsg = "File is of unsupported format version"; break;
            case Library::ErrorCode::DUPLICATE_PLATFORM_TYPE: errmsg = "Duplicate platform type"; break;
            case Library::ErrorCode::PLATFORM_TYPE_REDEFINED: errmsg = "Platform type redefined"; break;
            case Library::ErrorCode::DUPLICATE_DEFINE: errmsg = "Duplicate define"; break;
            }
            if (e.code == Library::ErrorCode::UNKNOWN_ELEMENT) {
                std::cout << "cppcheck: Found unknown elements in configuration file '" << name << "': " << e.reason << std::endl;
                return true;
            }
            if (!e.reason.empty()) errmsg += " '" + e.reason + "'";
            std::cout << "cppcheck: Failed to load library configuration file '" << name << "'. " << errmsg << std::endl;
            return false;
        };
        if (!reportLibError("std.cfg", err)) {
            if (err.code == Library::ErrorCode::FILE_NOT_FOUND) {
                std::cout << "Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. The Cppcheck binary was compiled with FILESDIR set to \"" << FILESDIR << "\" and will therefore search for std.cfg in " << FILESDIR << "/cfg." << std::endl;
            }
            return 1;
        }
        bool ok = true;
        for (const std::string &lib : settings.libraries) {
            std::string log2;
            Library::Error e = library.load(settings.exepath, lib, settings.debugLookupLibrary, log2);
            if (!log2.empty()) std::cout << log2;
            if (!reportLibError(lib, e)) ok = false;
        }
        if (!ok) return 1;
        // platform-specific library? windows.cfg loaded automatically for windows platforms
        if (settings.platform.isWindows()) {
            std::string log3;
            Library::Error e = library.load(settings.exepath, "windows.cfg", settings.debugLookupLibrary, log3);
            if (!log3.empty()) std::cout << log3;
            if (e.code == Library::ErrorCode::FILE_NOT_FOUND) {
                std::cout << "cppcheck: Failed to load library configuration file 'windows.cfg'. File not found" << std::endl;
                std::cout << "Failed to load windows.cfg. Your Cppcheck installation is broken, please re-install. The Cppcheck binary was compiled with FILESDIR set to \"" << FILESDIR << "\" and will therefore search for windows.cfg in " << FILESDIR << "/cfg." << std::endl;
                return 1;
            } else if (!reportLibError("windows.cfg", e)) return 1;
        }
    }

    // addons
    for (const std::string &addon : settings.addons) {
        std::string name = addon;
        if (getFilenameExtension(name).empty()) name += ".py";
        if (settings.debugLookupAddon) {
            std::cout << "looking for addon '" << name << "'" << std::endl;
            std::cout << "looking for addon '" << settings.exepath << name << "'" << std::endl;
            std::cout << "looking for addon '" << settings.exepath << "addons/" << name << "'" << std::endl;
            std::cout << "looking for addon '" << FILESDIR << "/" << name << "'" << std::endl;
            std::cout << "looking for addon '" << FILESDIR << "/addons/" << name << "'" << std::endl;
        }
        if (fileExists(name) || fileExists(settings.exepath + name) || fileExists(settings.exepath + "addons/" + name)) {
            // we do not support running addons
            continue;
        }
        std::cout << "Did not find addon " << name << std::endl;
        return 1;
    }

    // collect files
    std::map<std::string, FileWithDetails> files;
    const std::set<std::string> extraExt = library.markupExtensions;
    for (const std::string &pathname : parser.pathNames()) {
        std::string path = pathname;
        if (isDirectory(path)) {
            if (path == ".") path = "";
            else if (path.back() == '/') path.pop_back();
            if (!path.empty() && isIgnored(parser.ignoredPaths(), path + "/", true)) continue;
            addFilesRecursive(files, path, parser.ignoredPaths(), extraExt, settings.debugIgnore);
        } else if (fileExists(path)) {
            if (isIgnored(parser.ignoredPaths(), path, false)) {
                if (settings.debugIgnore) std::cout << "ignored path: " << path << std::endl;
                continue;
            }
            FileWithDetails f;
            f.path = path;
            Settings::Language lang;
            if (!acceptFile(path, lang, extraExt)) {
                std::string ext = getFilenameExtension(path);
                lang = Settings::CPP;
                if (ext == ".h" || ext == ".hpp" || ext == ".hh" || ext == ".hxx" || ext == ".h++") lang = Settings::CPP;
            }
            f.lang = lang;
            f.size = fileSize(path);
            files[path] = f;
        }
    }
    if (files.empty()) {
        std::cout << "cppcheck: error: could not find or open any of the paths given." << std::endl;
        if (!parser.ignoredPaths().empty())
            std::cout << "cppcheck: Maybe all paths were ignored?" << std::endl;
        return 1;
    }
    if (!settings.fileFilters.empty()) {
        std::map<std::string, FileWithDetails> filtered;
        for (const auto &f : files) {
            for (const std::string &filter : settings.fileFilters) {
                if (matchFileFilter(filter, f.first)) { filtered.insert(f); break; }
            }
        }
        if (filtered.empty()) {
            std::string filters;
            for (const std::string &filter : settings.fileFilters) filters += filter + " ";
            if (!filters.empty()) filters.pop_back();
            std::cout << "cppcheck: error: could not find any files matching the filter:" << filters << std::endl;
            return 1;
        }
        files = filtered;
    }

    if (!settings.outputFile.empty()) gDisableColors = true;

    StdLogger logger(settings);
    CppCheck cppcheck(settings, library, logger);

    if (settings.outputFormat == OutputFormat::xml) logger.writeXmlHeader();

    // check files
    std::size_t totalSize = 0;
    for (const auto &f : files) totalSize += f.second.size;
    std::size_t processedSize = 0;
    unsigned processedFiles = 0;
    unsigned totalErrors = 0;
    for (const auto &f : files) {
        const FileWithDetails &file = f.second;
        if (!settings.quiet) {
            std::string fname = file.path;
            logger.reportOut("Checking " + fname + " ...");
        }
        totalErrors += cppcheck.check(file);
        processedSize += file.size;
        ++processedFiles;
        if (!settings.quiet && files.size() > 1) {
            std::ostringstream oss;
            oss << processedFiles << '/' << files.size() << " files checked " << (totalSize > 0 ? (processedSize * 100 / totalSize) : 100) << "% done";
            logger.reportOut(oss.str());
        }
    }
    totalErrors += cppcheck.analyseWholeProgram();

    int returnValue = 0;
    if (totalErrors > 0 || cppcheck.mExitCode) returnValue = settings.exitCode;

    // unmatched suppressions
    if (settings.sev_information || settings.checkConfiguration) {
        bool err = false;
        const bool unusedFunctionCheck = settings.checkUnusedFunction;
        for (const auto &f : files) {
            for (Suppression &s : settings.suppressions) {
                if (!s.isLocal()) continue;
                if (s.matched || !s.checked) continue;
                if (s.type == Suppression::macro) continue;
                if (!unusedFunctionCheck && s.errorId == "unusedFunction") continue;
                if (s.fileName != f.first) continue;
                ErrorMessage msg;
                msg.callStack.emplace_back(s.fileName, s.lineNumber, 0);
                msg.id = "unmatchedSuppression";
                msg.severity = Severity::information;
                msg.setMessage("Unmatched suppression: " + s.errorId);
                // check if the unmatched suppression itself is suppressed
                if (cppcheck.isSuppressed(msg, true)) continue;
                logger.reportErr(msg);
                err = true;
            }
        }
        for (Suppression &s : settings.suppressions) {
            if (s.isLocal()) continue;
            if (s.matched) continue;
            if (s.type == Suppression::macro) continue;
            if (!unusedFunctionCheck && s.errorId == "unusedFunction") continue;
            if (s.isInline) continue;
            ErrorMessage msg;
            if (!s.fileName.empty()) msg.callStack.emplace_back(s.fileName, s.lineNumber, 0);
            msg.id = "unmatchedSuppression";
            msg.severity = Severity::information;
            msg.setMessage("Unmatched suppression: " + s.errorId);
            if (cppcheck.isSuppressed(msg, true)) continue;
            logger.reportErr(msg);
            err = true;
        }
        if (err && returnValue == 0) returnValue = settings.exitCode;
    }

    // checkers report
    std::string xmlExtra;
    if (settings.sev_information || settings.safety || !settings.checkersReportFilename.empty()) {
        int active = 0, total = 0;
        std::string text = checkersReportText(settings, cppcheck.activeCheckers, cppcheck.criticalErrors, active, total);
        if (!settings.checkersReportFilename.empty()) {
            std::ofstream fout(settings.checkersReportFilename);
            fout << text;
        }
        if (settings.sev_information || settings.safety) {
            ErrorMessage msg;
            msg.id = "checkersReport";
            msg.severity = Severity::information;
            std::string m = "Active checkers: " + std::to_string(active) + "/" + std::to_string(total);
            if (settings.checkersReportFilename.empty()) m += " (use --checkers-report=<filename> to see details)";
            msg.setMessage(m);
            if (!cppcheck.isSuppressed(msg, true)) {
                if (settings.outputFormat == OutputFormat::text || settings.outputFormat == OutputFormat::sarif)
                    logger.reportErr(msg);
                else if (settings.outputFormat == OutputFormat::xml && settings.xmlVersion == 2)
                    logger.reportErr(msg);
            }
        }
        if (settings.outputFormat == OutputFormat::xml && settings.xmlVersion == 3) {
            checkersReportXml(settings, cppcheck.activeCheckers, xmlExtra);
        }
    }

    if (settings.outputFormat == OutputFormat::xml) logger.writeXmlFooter(xmlExtra);
    else if (settings.outputFormat == OutputFormat::sarif) logger.writeSarif();

    if (settings.safety && !cppcheck.criticalErrors.empty() && returnValue == 0) returnValue = 1;
    return returnValue;
}
