std::set<std::string> computeActiveCheckers(const Settings &settings, bool isCPP, bool checkConfigOnly);

static bool reqSatisfied(const std::string &req, const Settings &s, bool isCPP) {
    if (req == "style") return s.sev_style;
    if (req == "warning") return s.sev_warning;
    if (req == "performance") return s.sev_performance;
    if (req == "portability") return s.sev_portability;
    if (req == "information") return s.sev_information;
    if (req == "inconclusive") return s.inconclusive;
    if (req == "unusedFunction") return s.checkUnusedFunction;
    if (req == "c++") return isCPP;
    if (req == "c") return isCPP; // CheckIO::checkCoutCerrMisusage is only run for C++ code
    if (req == "c++03") return true; // handled specially
    if (req == "c++11") return !isCPP || s.standards.cpp >= Standards::CPP11;
    if (req == "c99") return true;
    if (req == "platform") return s.platform.type != Platform::Unspecified;
    if (req == "windows-platform") return s.platform.isWindows();
    if (req == "safeChecks") return false;
    if (req == "notclang") return !s.clang;
    return true;
}

std::set<std::string> computeActiveCheckers(const Settings &s, bool isCPP, bool checkConfigOnly) {
    std::set<std::string> active;
    for (const CheckerInfo &c : checkersTable) {
        const std::string id = c.id;
        if (checkConfigOnly) {
            if (id.find("analyseWholeProgram") != std::string::npos || id == "CheckUnusedFunctions::check") active.insert(id);
            continue;
        }
        // class-level language restrictions
        const std::string cls = id.substr(0, id.find("::"));
        if (!isCPP && (cls == "CheckClass" || cls == "CheckStl" || cls == "CheckExceptionSafety") && id.find("analyseWholeProgram") == std::string::npos) continue;
        if (!isCPP && id == "CheckMemoryLeakInClass::check") continue;
        if (!isCPP && id == "CheckMemoryLeakNoVar::checkForUnsafeArgAlloc") continue;
        if (!isCPP && id == "CheckIO::checkCoutCerrMisusage") continue;
        // hidden conditions
        if (id == "CheckBufferOverrun::arrayIndexThenCheck" && !(s.sev_style || s.sev_portability)) continue;
        if (id == "CheckIO::invalidScanf" && !s.sev_warning) continue;
        if (id == "CheckMemoryLeakNoVar::checkForUnsafeArgAlloc" && !(s.inconclusive && s.sev_warning)) continue;
        if (id == "CheckUnusedFunctions::check" && !s.checkUnusedFunction) continue;
        bool ok = true;
        std::string req = c.req;
        std::stringstream ss(req);
        std::string item;
        while (std::getline(ss, item, ',')) {
            if (item.empty()) continue;
            if (item == "c++03") {
                // checkMissingOverride requires > c++03; CheckStl::size requires c++03
                if (id == "CheckStl::size") { if (s.standards.cpp != Standards::CPP03) ok = false; }
