// ---------------------------------------------------------------------------
// Raw tokenizer
// ---------------------------------------------------------------------------
void Preprocessor::tokenizeRaw(const std::string &codeIn, unsigned fileIndex, std::vector<PPToken> &out, std::vector<SuppressionComment> *comments) {
    // normalize line endings, keep track of positions
    std::string code;
    code.reserve(codeIn.size());
    for (size_t i = 0; i < codeIn.size(); ++i) {
        if (codeIn[i] == '\r') {
            if (i + 1 < codeIn.size() && codeIn[i+1] == '\n') continue;
            code += '\n';
        } else code += codeIn[i];
    }
    // strip UTF-8 BOM
    size_t pos = 0;
    if (code.compare(0, 3, "\xEF\xBB\xBF") == 0) pos = 3;

    int line = 1, col = 1;
    const size_t n = code.size();
    auto peek = [&](size_t off) -> char { return (pos + off < n) ? code[pos + off] : '\0'; };
    // handle backslash-newline: we implement by skipping it in a getc-like manner
    std::function<void()> advance = [&]() {
        if (pos >= n) return;
        if (code[pos] == '\n') { ++line; col = 1; } else ++col;
        ++pos;
    };
    // skip line splices
    auto skipSplice = [&]() {
        while (pos + 1 < n && code[pos] == '\\' && code[pos+1] == '\n') { pos += 2; ++line; col = 1; }
        // backslash followed by spaces then newline
        if (pos < n && code[pos] == '\\') {
            size_t p = pos + 1;
            while (p < n && (code[p] == ' ' || code[p] == '\t')) ++p;
            if (p < n && code[p] == '\n') { pos = p + 1; ++line; col = 1; }
        }
    };
    bool startOfLine = true;
    bool wsBefore = false;
    bool lastWasHashOnLine = false;
    bool lineHasCode = false;
    std::string lastDirective; // "include" if current line is #include
    int tokensOnLine = 0;
    while (pos < n) {
        skipSplice();
        if (pos >= n) break;
        char ch = code[pos];
        if (ch == '\n') { advance(); startOfLine = true; wsBefore = false; lineHasCode = false; tokensOnLine = 0; lastDirective.clear(); continue; }
        if (ch == ' ' || ch == '\t' || ch == '\f' || ch == '\v') { advance(); wsBefore = true; continue; }
        PPToken tok;
        tok.fileIndex = fileIndex;
        tok.line = line;
        tok.col = col;
        tok.whitespaceBefore = wsBefore;
        tok.startOfLine = startOfLine;
        wsBefore = false;
        startOfLine = false;
        std::string cur;
        if (ch == '/' && peek(1) == '/') {
            // line comment
            int cline = line, ccol = col;
            size_t start = pos;
            while (pos < n && code[pos] != '\n') {
                if (code[pos] == '\\' && pos + 1 < n && code[pos+1] == '\n') { pos += 2; ++line; col = 1; continue; }
                advance();
            }
            if (comments) comments->push_back({code.substr(start, pos - start), fileIndex, cline, ccol, lineHasCode, false});
            continue;
        }
        if (ch == '/' && peek(1) == '*') {
            int cline = line, ccol = col;
            size_t start = pos;
            advance(); advance();
            while (pos < n && !(code[pos] == '*' && peek(1) == '/')) advance();
            if (pos < n) { advance(); advance(); }
            if (comments) comments->push_back({code.substr(start, pos - start), fileIndex, cline, ccol, lineHasCode, true});
            continue;
        }
        lineHasCode = true;
        if (isNameChar(ch) && !isdigit((unsigned char)ch)) {
            // name, possibly string prefix
            while (pos < n && isNameChar(code[pos])) { cur += code[pos]; advance(); skipSplice(); }
            if (pos < n && (code[pos] == '"' || code[pos] == '\'') && (cur == "L" || cur == "u" || cur == "U" || cur == "u8" || cur == "R" || cur == "LR" || cur == "uR" || cur == "UR" || cur == "u8R")) {
                // prefixed literal
                if (cur.back() == 'R' && code[pos] == '"') {
                    // raw string
                    size_t p = pos + 1;
                    std::string delim;
                    while (p < n && code[p] != '(') delim += code[p++];
                    std::string endDelim = ")" + delim + "\"";
                    size_t endp = code.find(endDelim, p);
                    if (endp == std::string::npos) endp = n;
                    std::string raw = code.substr(p + 1, endp - p - 1);
                    // convert to ordinary string literal
                    std::string lit = "\"";
                    for (char c : raw) {
                        if (c == '\\') lit += "\\\\";
                        else if (c == '"') lit += "\\\"";
                        else if (c == '\n') lit += "\\n";
                        else if (c == '\t') lit += "\\t";
                        else lit += c;
                    }
                    lit += "\"";
                    std::string prefix = cur.substr(0, cur.size() - 1);
                    cur = prefix + lit;
                    while (pos < endp + endDelim.size() && pos < n) advance();
                } else {
                    char q = code[pos];
                    cur += q; advance();
                    while (pos < n && code[pos] != q && code[pos] != '\n') {
                        if (code[pos] == '\\') { cur += code[pos]; advance(); if (pos < n) { cur += code[pos]; advance(); } continue; }
                        cur += code[pos]; advance();
                    }
                    if (pos < n && code[pos] == q) { cur += q; advance(); }
                }
                tok.str = cur;
                out.push_back(tok);
                ++tokensOnLine;
                continue;
            }
            tok.str = cur;
            tok.name = true;
            if (tokensOnLine == 1 && !out.empty() && out.back().str == "#" && out.back().line == line) lastDirective = cur;
            out.push_back(tok);
            ++tokensOnLine;
            continue;
        }
        if (isdigit((unsigned char)ch) || (ch == '.' && isdigit((unsigned char)peek(1)))) {
            // number
            while (pos < n) {
                char c = code[pos];
                if (isNameChar(c) || c == '.' || c == '\'') { cur += c; advance(); skipSplice(); continue; }
                if ((c == '+' || c == '-') && !cur.empty() && (cur.back() == 'e' || cur.back() == 'E' || cur.back() == 'p' || cur.back() == 'P') && !(cur.size() > 1 && (cur[1] == 'x' || cur[1] == 'X') && (cur.back() == 'e' || cur.back() == 'E'))) { cur += c; advance(); continue; }
                break;
            }
            // remove digit separators
            std::string clean;
            for (char c : cur) if (c != '\'') clean += c;
            tok.str = clean;
            tok.number = true;
            out.push_back(tok);
            ++tokensOnLine;
            continue;
        }
        if (ch == '"' || ch == '\'') {
            char q = ch;
            cur += q; advance();
            while (pos < n && code[pos] != q && code[pos] != '\n') {
                if (code[pos] == '\\') {
                    cur += code[pos]; advance();
                    if (pos < n && code[pos] == '\n') { // line splice inside string
                        pos++; ++line; col = 1; cur.pop_back(); continue;
                    }
                    if (pos < n) { cur += code[pos]; advance(); }
                    continue;
                }
                cur += code[pos]; advance();
            }
            if (pos < n && code[pos] == q) { cur += q; advance(); }
            tok.str = cur;
            out.push_back(tok);
            ++tokensOnLine;
            continue;
        }
        // #include <...> : read header name as one token
        if (ch == '<' && lastDirective == "include" && tokensOnLine == 2) {
            while (pos < n && code[pos] != '>' && code[pos] != '\n') { cur += code[pos]; advance(); }
            if (pos < n && code[pos] == '>') { cur += '>'; advance(); }
            tok.str = cur;
            tok.op = true;
            out.push_back(tok);
            ++tokensOnLine;
            continue;
        }
        // operator (single char), combine later
        cur += ch;
        advance();
        tok.str = cur;
        tok.op = true;
        out.push_back(tok);
        ++tokensOnLine;
    }

    // combine operators (simplecpp::TokenList::combineOperators)
    std::vector<PPToken> combined;
    combined.reserve(out.size());
    std::stack<bool> executableScope;
    executableScope.push(false);
    for (size_t i = 0; i < out.size(); ++i) {
        PPToken tok = out[i];
        auto sameline = [&](const PPToken &a, const PPToken &b) { return a.fileIndex == b.fileIndex && a.line == b.line; };
        if (tok.op && tok.str == "{") {
            bool exe = false;
            if (!combined.empty()) {
                const PPToken &prev = combined.back();
                exe = (prev.op && prev.str == ")") || executableScope.top();
                if (prev.str == "=" ) exe = false;
            }
            executableScope.push(exe);
            combined.push_back(tok);
            continue;
        }
        if (tok.op && tok.str == "}") {
            if (executableScope.size() > 1) executableScope.pop();
            combined.push_back(tok);
            continue;
        }
        if (tok.op && tok.str == ".") {
            // ellipsis
            if (i + 2 < out.size() && out[i+1].str == "." && out[i+2].str == "." && out[i+1].col == tok.col + 1 && out[i+2].col == tok.col + 2 && sameline(tok, out[i+2])) {
                tok.str = "...";
                combined.push_back(tok);
                i += 2;
                continue;
            }
            // float literal "1." or ".5" handled: number followed by '.'
            if (!combined.empty() && combined.back().number && combined.back().col + (int)combined.back().str.size() == tok.col && sameline(combined.back(), tok)) {
                combined.back().str += ".";
                // digits after
                if (i + 1 < out.size() && out[i+1].number && out[i+1].col == tok.col + 1 && sameline(tok, out[i+1])) {
                    combined.back().str += out[i+1].str;
                    ++i;
                }
                continue;
            }
        }
        if (!tok.op || i + 1 >= out.size() || !out[i+1].op) { combined.push_back(tok); continue; }
        const PPToken &next = out[i+1];
        if (!sameline(tok, next) || tok.col + 1 != next.col) { combined.push_back(tok); continue; }
        if (next.str == "=" && strchr("=!<>+-*/%&|^", tok.str[0]) && tok.str.size() == 1) {
            if (tok.str == "&" && !executableScope.top()) {
                // don't combine &= if it is a reference declaration
                bool refDecl = false;
                if (!combined.empty()) {
                    const PPToken &prev = combined.back();
                    if (prev.name) {
                        // check if next after '=' is a name/number and previous looks like a type
                        refDecl = true;
                        // "a &= b" inside non-executable scope is rare; treat as ref decl only if next-next is name
                    }
                }
                if (refDecl) { combined.push_back(tok); continue; }
            }
            tok.str += "=";
            combined.push_back(tok);
            ++i;
            continue;
        }
        if ((tok.str == "|" || tok.str == "&") && tok.str == next.str) {
            tok.str += next.str; combined.push_back(tok); ++i; continue;
        }
        if (tok.str == ":" && next.str == ":") {
            tok.str += next.str; combined.push_back(tok); ++i; continue;
        }
        if (tok.str == "-" && next.str == ">") {
            tok.str += next.str; combined.push_back(tok); ++i; continue;
        }
        if ((tok.str == "<" || tok.str == ">") && tok.str == next.str) {
            tok.str += next.str;
            ++i;
            if (i + 1 < out.size() && out[i+1].str == "=" && out[i+1].op && out[i+1].col == next.col + 1 && sameline(next, out[i+1]) && !(i + 2 < out.size() && out[i+2].str == "=" && out[i+2].col == out[i+1].col + 1)) {
                tok.str += "=";
                ++i;
            }
            combined.push_back(tok);
            continue;
        }
        if ((tok.str == "+" || tok.str == "-") && tok.str == next.str) {
            if (!combined.empty() && combined.back().number) { combined.push_back(tok); continue; }
            if (i + 2 < out.size() && out[i+2].number) { combined.push_back(tok); continue; }
            tok.str += next.str; combined.push_back(tok); ++i; continue;
        }
        combined.push_back(tok);
    }
    out.swap(combined);
}

// ---------------------------------------------------------------------------
unsigned Preprocessor::fileIndexFor(const std::string &path) {
    for (size_t i = 0; i < mFiles.size(); ++i) if (mFiles[i] == path) return (unsigned)i;
    mFiles.push_back(path);
    return (unsigned)mFiles.size() - 1;
}

bool Preprocessor::readTokens(const std::string &path, unsigned fileIndex, std::vector<PPToken> &out) {
    std::ifstream f(path, std::ios::binary);
    if (!f.is_open()) return false;
    std::stringstream ss; ss << f.rdbuf();
    std::vector<SuppressionComment> comments;
    tokenizeRaw(ss.str(), fileIndex, out, &comments);
    allComments[fileIndex] = comments;
    return true;
}

bool Preprocessor::loadFile(const std::string &filename, std::string &errmsg) {
    mMainFile = filename;
    mFiles.clear();
    unsigned idx = fileIndexFor(filename);
    mRawTokens.clear();
    if (!readTokens(filename, idx, mRawTokens)) {
        errmsg = "Failed to open " + filename;
        return false;
    }
    mComments = allComments[idx];
    return true;
}

// ---------------------------------------------------------------------------
// Config detection (mirrors cppcheck's getConfigs)
// ---------------------------------------------------------------------------
namespace {
struct TokView {
    const std::vector<PPToken> &toks;
    size_t idx;
    const PPToken* get(size_t i) const { return i < toks.size() ? &toks[i] : nullptr; }
};

static bool sameline(const PPToken *a, const PPToken *b) {
    return a && b && a->fileIndex == b->fileIndex && a->line == b->line;
}

static bool isIntegerLiteral(const std::string &s) {
    if (s.empty()) return false;
    size_t i = 0;
    while (i < s.size() && isdigit((unsigned char)s[i])) ++i;
    if (i == 0) return false;
    // suffixes
    while (i < s.size() && (s[i] == 'L' || s[i] == 'l' || s[i] == 'U' || s[i] == 'u')) ++i;
    return i == s.size();
}

static std::string readcondition(const std::vector<PPToken> &toks, size_t ifIdx, const std::set<std::string> &defined, const std::set<std::string> &undefined, std::string &internalError) {
    const PPToken *iftok = &toks[ifIdx];
    const PPToken *cond = ifIdx + 1 < toks.size() ? &toks[ifIdx+1] : nullptr;
    if (!sameline(iftok, cond)) return "";
    const PPToken *next1 = ifIdx + 2 < toks.size() ? &toks[ifIdx+2] : nullptr;
    const PPToken *next2 = ifIdx + 3 < toks.size() ? &toks[ifIdx+3] : nullptr;
    const PPToken *next3 = ifIdx + 4 < toks.size() ? &toks[ifIdx+4] : nullptr;

    unsigned len = 1;
    if (sameline(iftok, next1)) len = 2;
    if (sameline(iftok, next2)) len = 3;
    if (sameline(iftok, next3)) len = 4;

    if (len == 1 && cond->str == "0") return "0";
    if (len == 1 && cond->name) {
        if (defined.find(cond->str) == defined.end()) return cond->str;
    }
    if (len == 2 && cond->op && cond->str == "!" && next1->name) {
        if (defined.find(next1->str) == defined.end()) return next1->str + "=0";
    }
    if (len == 3 && cond->op && cond->str == "(" && next1->name && next2->op && next2->str == ")") {
        if (defined.find(next1->str) == defined.end() && undefined.find(next1->str) == undefined.end()) return next1->str;
    }
    if (len == 3 && cond->name && (next1->str == "==" || next1->str == ">" || next1->str == "<" || next1->str == ">=" || next1->str == "<=") && next2->number) {
        if (defined.find(cond->str) == defined.end()) {
            if (next1->str == "==") return cond->str + '=' + next2->str;
            // compute a value that satisfies the condition
            const std::string &num = next2->str;
            if (!isIntegerLiteral(num) || (num.size() > 1 && num[0] == '0' && (num[1] == 'x' || num[1] == 'X'))) {
                internalError = "converting '" + num + "' to integer failed - not an integer";
                return "";
            }
            // strip suffix for calculation
            std::string digits; std::string suffix;
            for (char c : num) { if (isdigit((unsigned char)c)) digits += c; else suffix += c; }
            long long v = strtoll(digits.c_str(), nullptr, 10);
            if (next1->str == ">") v += 1;
            else if (next1->str == "<") v -= 1;
            return cond->str + '=' + std::to_string(v) + suffix;
        }
    }
    std::set<std::string> configset;
    for (size_t i = ifIdx + 1; i < toks.size() && sameline(iftok, &toks[i]); ++i) {
        const PPToken *c = &toks[i];
        if (c->op && c->str == "!") {
            const PPToken *nx = i + 1 < toks.size() ? &toks[i+1] : nullptr;
            if (!sameline(iftok, nx) || !nx->name) break;
            if (nx->str == "defined") continue;
            configset.insert(nx->str + "=0");
            continue;
        }
        if (c->str != "defined") continue;
        size_t di = i + 1;
        if (di >= toks.size()) break;
        const PPToken *dtok = &toks[di];
        if (dtok->op && dtok->str == "(") { ++di; dtok = di < toks.size() ? &toks[di] : nullptr; }
        if (dtok && sameline(iftok, dtok) && dtok->name && defined.find(dtok->str) == defined.end() && undefined.find(dtok->str) == undefined.end())
            configset.insert(dtok->str + "=" + dtok->str);
    }
    std::string cfgStr;
    for (const std::string &s : configset) {
        if (!cfgStr.empty()) cfgStr += ';';
        cfgStr += s;
    }
    return cfgStr;
}

static std::string cfgStr(const std::vector<std::string> &configs, const std::string &userDefines) {
    std::set<std::string> configs2(configs.begin(), configs.end());
    std::string ret;
    for (const std::string &c : configs2) {
        if (c.empty()) continue;
        if (c == "0") return "";
        if (!ret.empty()) ret += ';';
        ret += c;
    }
    if (!userDefines.empty()) {
        if (!ret.empty()) ret += ';';
        ret += userDefines;
    }
    return ret;
}

static bool isUndefined(const std::string &cfg, const std::set<std::string> &undefined) {
    for (std::string::size_type pos1 = 0; pos1 < cfg.size();) {
        const std::string::size_type pos2 = cfg.find(';', pos1);
        const std::string def = (pos2 == std::string::npos) ? cfg.substr(pos1) : cfg.substr(pos1, pos2 - pos1);
        const std::string::size_type eq = def.find('=');
        if (eq == std::string::npos && undefined.find(def) != undefined.end()) return true;
        if (eq != std::string::npos && undefined.find(def.substr(0, eq)) != undefined.end()) return true;
        pos1 = (pos2 == std::string::npos) ? pos2 : pos2 + 1U;
    }
    return false;
}

static bool getConfigsElseIsFalse(const std::vector<std::string> &configs_if, const std::string &userDefines) {
    return std::any_of(configs_if.cbegin(), configs_if.cend(), [&](const std::string &cfg) {
        return cfg == "0" || (!userDefines.empty() && userDefines.find(cfg) != std::string::npos);
    });
}

static size_t gotoEndIf(const std::vector<PPToken> &toks, size_t idx) {
    int level = 0;
    for (size_t i = idx; i < toks.size(); ++i) {
        if (!(toks[i].op && toks[i].str == "#") || (i > 0 && sameline(&toks[i-1], &toks[i]))) continue;
        if (i + 1 >= toks.size()) break;
        const std::string &cmd = toks[i+1].str;
        if (cmd == "if" || cmd == "ifdef" || cmd == "ifndef") ++level;
        else if (cmd == "endif") { --level; if (level <= 0) return i; }
    }
    return toks.size();
}

static void getConfigsImpl(const std::vector<PPToken> &toks, std::set<std::string> &defined, const std::string &userDefines, const std::set<std::string> &undefined, std::set<std::string> &ret, bool isHeader, std::string &internalError) {
    std::vector<std::string> configs_if;
    std::vector<std::string> configs_ifndef;
    std::string elseError;
    for (size_t i = 0; i < toks.size(); ++i) {
        const PPToken &tok = toks[i];
        if (!(tok.op && tok.str == "#") || (i > 0 && sameline(&toks[i-1], &tok))) continue;
        if (i + 1 >= toks.size() || !sameline(&tok, &toks[i+1])) continue;
        const PPToken &cmdtok = toks[i+1];
        const size_t cmdIdx = i + 1;
        if (cmdtok.str == "ifdef" || cmdtok.str == "ifndef" || cmdtok.str == "if") {
            std::string config;
            if (cmdtok.str == "ifdef" || cmdtok.str == "ifndef") {
                const PPToken *expr1 = cmdIdx + 1 < toks.size() ? &toks[cmdIdx+1] : nullptr;
                const PPToken *expr2 = cmdIdx + 2 < toks.size() ? &toks[cmdIdx+2] : nullptr;
                if (sameline(&tok, expr1) && expr1->name && !sameline(&tok, expr2))
                    config = expr1->str;
                if (defined.find(config) != defined.end()) config.clear();
                if (cmdtok.str == "ifdef" && !config.empty()) config = config + "=" + config;
            } else {
                config = readcondition(toks, cmdIdx, defined, undefined, internalError);
                if (!internalError.empty()) return;
            }
            if (isUndefined(config, undefined)) config.clear();

            bool ifndef = false;
            if (cmdtok.str == "ifndef") ifndef = true;
            else {
                // "if ! defined ( config )"
                const std::string match[] = {"if", "!", "defined", "(", config, ")"};
                ifndef = true;
                size_t k = cmdIdx;
                for (int m = 0; m < 6; ++m, ++k) {
                    if (k >= toks.size() || toks[k].str != match[m]) { ifndef = false; break; }
                }
            }
            // include guard..
            if (ifndef && isHeader) {
                bool includeGuard = true;
                for (size_t k = i; k-- > 0;) {
                    if (toks[k].fileIndex == tok.fileIndex) { includeGuard = false; break; }
                }
                if (includeGuard) {
                    configs_if.emplace_back();
                    configs_ifndef.emplace_back();
                    continue;
                }
            }
            configs_if.push_back((cmdtok.str == "ifndef") ? std::string() : config);
            configs_ifndef.push_back((cmdtok.str == "ifndef") ? config : std::string());
            ret.insert(cfgStr(configs_if, userDefines));
        } else if (cmdtok.str == "elif" || cmdtok.str == "else") {
            if (getConfigsElseIsFalse(configs_if, userDefines)) {
                size_t e = gotoEndIf(toks, i);
                if (e >= toks.size()) break;
                i = e - 1;
                continue;
            }
            if (cmdtok.str == "else" && cmdIdx + 2 < toks.size() && !sameline(&cmdtok, &toks[cmdIdx+1]) && sameline(&toks[cmdIdx+1], &toks[cmdIdx+2]) && toks[cmdIdx+1].op && toks[cmdIdx+1].str == "#" && toks[cmdIdx+2].str == "error") {
                const std::string &ifcfg = cfgStr(configs_if, userDefines);
                if (!ifcfg.empty()) {
                    if (!elseError.empty()) elseError += ';';
                    elseError += ifcfg;
                }
            }
            if (!configs_if.empty()) configs_if.pop_back();
            if (cmdtok.str == "elif") {
                std::string config = readcondition(toks, cmdIdx, defined, undefined, internalError);
                if (!internalError.empty()) return;
                if (isUndefined(config, undefined)) config.clear();
                configs_if.push_back(config);
                ret.insert(cfgStr(configs_if, userDefines));
            } else if (!configs_ifndef.empty()) {
                configs_if.push_back(configs_ifndef.back());
                ret.insert(cfgStr(configs_if, userDefines));
            }
        } else if (cmdtok.str == "endif" && !(cmdIdx + 1 < toks.size() && sameline(&tok, &toks[cmdIdx+1]))) {
            if (!configs_if.empty()) configs_if.pop_back();
            if (!configs_ifndef.empty()) configs_ifndef.pop_back();
        } else if (cmdtok.str == "error") {
            if (!configs_ifndef.empty() && !configs_ifndef.back().empty()) {
                if (configs_ifndef.size() == 1U) ret.erase("");
                std::vector<std::string> configs(configs_if);
                configs.push_back(configs_ifndef.back());
                ret.erase(cfgStr(configs, userDefines));
                std::set<std::string> temp;
                temp.swap(ret);
                for (const std::string &c : temp) {
                    if (c.find(configs_ifndef.back()) != std::string::npos) ret.insert(c);
                    else if (c.empty()) ret.insert("");
                    else ret.insert(c + ";" + configs_ifndef.back());
                }
                if (!elseError.empty()) elseError += ';';
                elseError += cfgStr(configs_if, userDefines);
            }
        } else if (cmdtok.str == "define" && cmdIdx + 1 < toks.size() && sameline(&tok, &toks[cmdIdx+1]) && toks[cmdIdx+1].name) {
            defined.insert(toks[cmdIdx+1].str);
        }
    }
    if (!elseError.empty()) ret.insert(elseError);
}
}

std::set<std::string> Preprocessor::getConfigs(const std::vector<std::string> &libraryDefines) const {
    std::set<std::string> ret = { "" };
    if (mRawTokens.empty()) return ret;
    std::set<std::string> defined = { "__cplusplus" };
    for (const std::string &d : libraryDefines) {
        std::string name = d.substr(0, d.find(' '));
        defined.insert(name);
    }
    std::string internalError;
    getConfigsImpl(mRawTokens, defined, mSettings.userDefinesStr, mSettings.userUndefs, ret, false, internalError);
    if (!internalError.empty()) throw std::runtime_error(internalError);
    // header files
    for (const auto &fc : mFileCache) {
        getConfigsImpl(fc.second, defined, mSettings.userDefinesStr, mSettings.userUndefs, ret, true, internalError);
        if (!internalError.empty()) throw std::runtime_error(internalError);
    }
    return ret;
}

// ---------------------------------------------------------------------------
// Macro expansion & directive processing
// ---------------------------------------------------------------------------
namespace {
struct Macro {
    std::string name;
    bool functionLike = false;
    bool variadic = false;
    std::vector<std::string> params;
    std::vector<PPToken> body;
    std::string defineStr;
    int lineDefined = 0;
};

struct PPState {
    std::map<std::string, Macro> macros;
    std::vector<PPError> *errors;
    std::set<std::string> *missingReported;
    Preprocessor *pp;
    const Settings *settings;
    bool reportMissing;
    int counter = 0;
    std::vector<std::string> *files;
    std::map<std::string, std::vector<PPToken>> *fileCache;
    std::set<std::string> pragmaOnce;
    std::set<std::string> includeStack;
    int includeDepth = 0;
};

class PPError_Exception : public std::exception {
public:
    PPError err;
    explicit PPError_Exception(PPError e) : err(std::move(e)) {}
};

static long long evalExpression(std::vector<PPToken> &toks, size_t &i, int prec, const PPState &st, bool &ok);

static long long parseNumber(const std::string &s, bool &ok) {
    ok = true;
    std::string t = s;
    // remove suffixes
    while (!t.empty() && (t.back() == 'L' || t.back() == 'l' || t.back() == 'U' || t.back() == 'u')) t.pop_back();
    if (t.empty()) { ok = false; return 0; }
    char *end = nullptr;
    long long v;
    if (t.size() > 1 && t[0] == '0' && (t[1] == 'x' || t[1] == 'X')) v = strtoll(t.c_str(), &end, 16);
    else if (t.size() > 1 && t[0] == '0' && (t[1] == 'b' || t[1] == 'B')) v = strtoll(t.c_str() + 2, &end, 2);
    else if (t.size() > 1 && t[0] == '0') v = strtoll(t.c_str(), &end, 8);
    else if (t.find_first_of(".eE") != std::string::npos && !(t.size() > 1 && t[0]=='0' && (t[1]=='x'||t[1]=='X'))) { v = (long long)strtod(t.c_str(), &end); }
    else v = strtoll(t.c_str(), &end, 10);
    if (!end || *end) ok = false;
    return v;
}

static long long charValue(const std::string &s) {
    size_t p = s.find('\'');
    if (p == std::string::npos || p + 1 >= s.size()) return 0;
    std::string inner = s.substr(p + 1, s.size() - p - 2);
    if (inner.empty()) return 0;
    if (inner[0] != '\\') return (unsigned char)inner[0];
    if (inner.size() < 2) return 0;
    switch (inner[1]) {
    case 'n': return '\n'; case 't': return '\t'; case 'r': return '\r'; case '0': return strtol(inner.c_str() + 1, nullptr, 8);
    case '\\': return '\\'; case '\'': return '\''; case '"': return '"'; case 'a': return 7; case 'b': return 8; case 'f': return 12; case 'v': return 11;
    case 'x': return strtol(inner.c_str() + 2, nullptr, 16);
    default: return inner[1];
    }
}

static long long evalPrimary(std::vector<PPToken> &toks, size_t &i, const PPState &st, bool &ok) {
    if (i >= toks.size()) { ok = false; return 0; }
    PPToken &t = toks[i];
    if (t.op && t.str == "(") {
        ++i;
        long long v = evalExpression(toks, i, 0, st, ok);
        if (i < toks.size() && toks[i].str == ")") ++i; else ok = false;
        return v;
    }
    if (t.op && (t.str == "!" || t.str == "-" || t.str == "+" || t.str == "~")) {
        std::string o = t.str; ++i;
        long long v = evalPrimary(toks, i, st, ok);
        if (o == "!") return !v;
        if (o == "-") return -v;
        if (o == "~") return ~v;
        return v;
    }
    if (t.number) { ++i; bool nok; long long v = parseNumber(t.str, nok); if (!nok) ok = false; return v; }
    if (t.isChar()) { ++i; return charValue(t.str); }
    if (t.name) {
        if (t.str == "defined") {
            ++i;
            bool paren = false;
            if (i < toks.size() && toks[i].str == "(") { paren = true; ++i; }
            if (i >= toks.size()) { ok = false; return 0; }
            std::string name = toks[i].str; ++i;
            if (paren) { if (i < toks.size() && toks[i].str == ")") ++i; else ok = false; }
            return st.macros.count(name) ? 1 : 0;
        }
        if (t.str == "true") { ++i; return 1; }
        if (t.str == "false") { ++i; return 0; }
        if (t.str == "__has_include" || t.str == "__has_include_next" || t.str == "__has_cpp_attribute" || t.str == "__has_attribute" || t.str == "__has_builtin" || t.str == "__has_feature" || t.str == "__has_extension" || t.str == "__is_identifier") {
            ++i;
            if (i < toks.size() && toks[i].str == "(") {
                int depth = 0;
                while (i < toks.size()) { if (toks[i].str == "(") ++depth; else if (toks[i].str == ")") { --depth; if (depth == 0) { ++i; break; } } ++i; }
            }
            return 0;
        }
        // undefined identifier -> 0 ; but a function-like call "name(" -> error
        ++i;
        if (i < toks.size() && toks[i].str == "(") { ok = false; return 0; }
        return 0;
    }
    ok = false;
    return 0;
}

static int binPrec(const std::string &op) {
    if (op == "*" || op == "/" || op == "%") return 10;
    if (op == "+" || op == "-") return 9;
    if (op == "<<" || op == ">>") return 8;
    if (op == "<" || op == ">" || op == "<=" || op == ">=") return 7;
    if (op == "==" || op == "!=") return 6;
    if (op == "&") return 5;
    if (op == "^") return 4;
    if (op == "|") return 3;
    if (op == "&&") return 2;
    if (op == "||") return 1;
    if (op == "?") return 0;
    return -1;
}

static long long evalExpression(std::vector<PPToken> &toks, size_t &i, int prec, const PPState &st, bool &ok) {
    long long lhs = evalPrimary(toks, i, st, ok);
    while (ok && i < toks.size()) {
        const std::string &op = toks[i].str;
        if (!toks[i].op) { ok = false; break; }
        int p = binPrec(op);
        if (p < 0 || p < prec) break;
        if (op == "?") {
            ++i;
            long long a = evalExpression(toks, i, 0, st, ok);
            if (i < toks.size() && toks[i].str == ":") ++i; else { ok = false; break; }
            long long b = evalExpression(toks, i, 0, st, ok);
            lhs = lhs ? a : b;
            continue;
        }
        ++i;
        long long rhs = evalExpression(toks, i, p + 1, st, ok);
        if (!ok) break;
        if (op == "*") lhs = lhs * rhs;
        else if (op == "/") { if (rhs == 0) { ok = false; break; } lhs = lhs / rhs; }
        else if (op == "%") { if (rhs == 0) { ok = false; break; } lhs = lhs % rhs; }
        else if (op == "+") lhs = lhs + rhs;
        else if (op == "-") lhs = lhs - rhs;
        else if (op == "<<") lhs = lhs << rhs;
        else if (op == ">>") lhs = lhs >> rhs;
        else if (op == "<") lhs = lhs < rhs;
        else if (op == ">") lhs = lhs > rhs;
        else if (op == "<=") lhs = lhs <= rhs;
        else if (op == ">=") lhs = lhs >= rhs;
        else if (op == "==") lhs = lhs == rhs;
        else if (op == "!=") lhs = lhs != rhs;
        else if (op == "&") lhs = lhs & rhs;
        else if (op == "^") lhs = lhs ^ rhs;
        else if (op == "|") lhs = lhs | rhs;
        else if (op == "&&") lhs = (lhs && rhs);
        else if (op == "||") lhs = (lhs || rhs);
    }
    return lhs;
}

static std::string stringifyTokens(const std::vector<PPToken> &toks, size_t from, size_t to) {
    std::string s;
    for (size_t i = from; i < to; ++i) {
        if (i > from && toks[i].whitespaceBefore) s += ' ';
        s += toks[i].str;
    }
    return s;
}

static bool parseMacroDefinition(const std::vector<PPToken> &toks, size_t nameIdx, size_t endIdx, Macro &m) {
    m.name = toks[nameIdx].str;
    m.lineDefined = toks[nameIdx].line;
    size_t i = nameIdx + 1;
    if (i < endIdx && toks[i].str == "(" && !toks[i].whitespaceBefore) {
        m.functionLike = true;
        ++i;
        while (i < endIdx && toks[i].str != ")") {
            if (toks[i].str == "...") { m.variadic = true; m.params.push_back("__VA_ARGS__"); }
            else if (toks[i].name) {
                std::string p = toks[i].str;
                if (i + 1 < endIdx && toks[i+1].str == "...") { m.variadic = true; ++i; }
                m.params.push_back(p);
            }
            ++i;
        }
        if (i < endIdx) ++i; // ')'
    }
    for (; i < endIdx; ++i) m.body.push_back(toks[i]);
    m.defineStr = stringifyTokens(toks, nameIdx, endIdx);
    return true;
}

static void expandTokens(std::vector<PPToken> &out, const std::vector<PPToken> &in, size_t from, size_t to, PPState &st, std::set<std::string> expanded, const PPToken *loc, const std::string &macroName);

static std::string stringifyArg(const std::vector<PPToken> &arg) {
    std::string s = "\"";
    for (size_t i = 0; i < arg.size(); ++i) {
        if (i > 0 && arg[i].whitespaceBefore) s += ' ';
        for (char c : arg[i].str) {
            if (c == '"' || c == '\\') { if (arg[i].isString() || arg[i].isChar() || c == '"') s += '\\'; }
            s += c;
        }
    }
    s += "\"";
    return s;
}

static void retokenizeInto(std::vector<PPToken> &out, const std::string &text, const PPToken &loc, const std::string &macroName) {
    std::vector<PPToken> tmp;
    Preprocessor::tokenizeRaw(text, loc.fileIndex, tmp, nullptr);
    for (PPToken &t : tmp) {
        t.line = loc.line; t.col = loc.col; t.fileIndex = loc.fileIndex; t.macro = macroName;
        out.push_back(t);
    }
}

// Expand macro invocation starting at in[idx] (name token). Returns index after invocation. If not expandable returns idx (and pushes nothing).
static size_t expandMacroAt(std::vector<PPToken> &out, const std::vector<PPToken> &in, size_t idx, size_t end, PPState &st, std::set<std::string> &expanded, const PPToken *loc) {
    const PPToken &nameTok = in[idx];
    auto it = st.macros.find(nameTok.str);
    const Macro &m = it->second;
    const PPToken useLoc = loc ? *loc : nameTok;
    if (!m.functionLike) {
        std::vector<PPToken> body = m.body;
        // handle ## in object-like
        std::vector<PPToken> body2;
        for (size_t i = 0; i < body.size(); ++i) {
            if (body[i].str == "##" && !body2.empty() && i + 1 < body.size()) {
                body2.back().str += body[i+1].str;
                PPToken merged = body2.back();
                std::vector<PPToken> re; Preprocessor::tokenizeRaw(merged.str, 0, re, nullptr);
                if (!re.empty()) { body2.back().str = re[0].str; body2.back().name = re[0].name; body2.back().number = re[0].number; body2.back().op = re[0].op; }
                ++i;
                continue;
            }
            body2.push_back(body[i]);
        }
        std::set<std::string> exp2 = expanded; exp2.insert(m.name);
        std::vector<PPToken> tmp;
        for (PPToken &t : body2) { t.line = useLoc.line; t.col = useLoc.col; t.fileIndex = useLoc.fileIndex; if (t.macro.empty()) t.macro = m.name; }
        expandTokens(out, body2, 0, body2.size(), st, exp2, &useLoc, m.name);
        return idx + 1;
    }
    // function-like: need '('
    size_t p = idx + 1;
    if (p >= end || in[p].str != "(") return idx; // not an invocation
    // collect args
    std::vector<std::vector<PPToken>> args;
    std::vector<PPToken> cur;
    int depth = 0;
    size_t q = p;
    bool closed = false;
    for (; q < end; ++q) {
        const PPToken &t = in[q];
        if (t.str == "(") { if (depth > 0) cur.push_back(t); ++depth; continue; }
        if (t.str == ")") { --depth; if (depth == 0) { closed = true; ++q; break; } cur.push_back(t); continue; }
        if (t.str == "," && depth == 1 && !(m.variadic && args.size() + 1 >= m.params.size())) { args.push_back(cur); cur.clear(); continue; }
        cur.push_back(t);
    }
    if (!closed) {
        PPError e; e.file = st.files->at(nameTok.fileIndex); e.line = nameTok.line; e.col = nameTok.col; e.id = "syntaxError";
        e.msg = "failed to expand '" + m.name + "', it is invalid to use a preprocessor directive as macro parameter";
        throw PPError_Exception(e);
    }
    if (!cur.empty() || !args.empty() || !m.params.empty()) args.push_back(cur);
    if (m.params.empty() && args.size() == 1 && args[0].empty()) args.clear();
    if (args.size() < m.params.size()) {
        if (m.variadic && args.size() + 1 == m.params.size()) args.emplace_back();
        else {
            PPError e; e.file = st.files->at(nameTok.fileIndex); e.line = nameTok.line; e.col = nameTok.col; e.id = "syntaxError";
            e.msg = "failed to expand '" + m.name + "', Wrong number of parameters for macro '" + m.name + "'.";
            throw PPError_Exception(e);
        }
    }
    if (args.size() > m.params.size() && !m.params.empty() && !m.variadic) {
        PPError e; e.file = st.files->at(nameTok.fileIndex); e.line = nameTok.line; e.col = nameTok.col; e.id = "syntaxError";
        e.msg = "failed to expand '" + m.name + "', Wrong number of parameters for macro '" + m.name + "'.";
        throw PPError_Exception(e);
    }
    auto paramIndex = [&](const std::string &s) -> int {
        for (size_t k = 0; k < m.params.size(); ++k) if (m.params[k] == s) return (int)k;
        return -1;
    };
    // substitute
    std::vector<PPToken> subst;
    const std::vector<PPToken> &body = m.body;
    for (size_t i = 0; i < body.size(); ++i) {
        const PPToken &bt = body[i];
        if (bt.str == "#" && i + 1 < body.size() && paramIndex(body[i+1].str) >= 0) {
            PPToken s = bt; s.str = stringifyArg(args[paramIndex(body[i+1].str)]); s.op = false; s.name = false;
            subst.push_back(s);
            ++i;
            continue;
        }
        if (bt.str == "##") {
            if (subst.empty() || i + 1 >= body.size()) continue;
            const PPToken &rhs = body[i+1];
            std::vector<PPToken> rhsToks;
            int pi = paramIndex(rhs.str);
            if (pi >= 0) rhsToks = args[pi]; else rhsToks.push_back(rhs);
            if (rhsToks.empty()) { ++i; continue; }
            if (subst.back().str.empty()) { subst.pop_back(); for (auto &t : rhsToks) subst.push_back(t); ++i; continue; }
            // merge last of subst with first of rhs
            std::string merged = subst.back().str + rhsToks[0].str;
            std::vector<PPToken> re; Preprocessor::tokenizeRaw(merged, 0, re, nullptr);
            PPToken mt = subst.back();
            if (re.size() == 1) { mt.str = re[0].str; mt.name = re[0].name; mt.number = re[0].number; mt.op = re[0].op; subst.back() = mt; }
            else { subst.back().str = merged; }
            for (size_t k = 1; k < rhsToks.size(); ++k) subst.push_back(rhsToks[k]);
            ++i;
            continue;
        }
        int pi = paramIndex(bt.str);
        if (pi >= 0) {
            // check if next is ## -> no expansion of arg
            bool nextIsPaste = (i + 1 < body.size() && body[i+1].str == "##");
            if (nextIsPaste) {
                if (args[pi].empty()) { PPToken e = bt; e.str = ""; subst.push_back(e); }
                for (const PPToken &t : args[pi]) subst.push_back(t);
            } else {
                // fully expand argument
                std::vector<PPToken> ex;
                std::set<std::string> exp2 = expanded;
                expandTokens(ex, args[pi], 0, args[pi].size(), st, exp2, &useLoc, "");
                for (PPToken &t : ex) { if (t.macro.empty()) t.macro = m.name; subst.push_back(t); }
            }
            continue;
        }
        subst.push_back(bt);
    }
    // remove empty placeholder tokens
    std::vector<PPToken> subst2;
    for (PPToken &t : subst) { if (t.str.empty()) continue; t.line = useLoc.line; t.col = useLoc.col; t.fileIndex = useLoc.fileIndex; if (t.macro.empty()) t.macro = m.name; subst2.push_back(t); }
    std::set<std::string> exp2 = expanded; exp2.insert(m.name);
    // rescan
    expandTokens(out, subst2, 0, subst2.size(), st, exp2, &useLoc, m.name);
    return q;
}

static void expandTokens(std::vector<PPToken> &out, const std::vector<PPToken> &in, size_t from, size_t to, PPState &st, std::set<std::string> expanded, const PPToken *loc, const std::string &macroName) {
    for (size_t i = from; i < to;) {
        const PPToken &t = in[i];
        if (t.name && !expanded.count(t.str)) {
            if (t.str == "__FILE__") {
                PPToken n = t; n.str = "\"" + st.files->at(t.fileIndex) + "\""; n.name = false; n.macro = "__FILE__";
                if (loc) { n.line = loc->line; n.col = loc->col; n.fileIndex = loc->fileIndex; }
                out.push_back(n); ++i; continue;
            }
            if (t.str == "__LINE__") {
                PPToken n = t; n.str = std::to_string(loc ? loc->line : t.line); n.name = false; n.number = true; n.macro = "__LINE__";
                if (loc) { n.line = loc->line; n.col = loc->col; n.fileIndex = loc->fileIndex; }
                out.push_back(n); ++i; continue;
            }
            if (t.str == "__COUNTER__") {
                PPToken n = t; n.str = std::to_string(st.counter++); n.name = false; n.number = true; n.macro = "__COUNTER__";
                out.push_back(n); ++i; continue;
            }
            auto it = st.macros.find(t.str);
            if (it != st.macros.end()) {
                size_t before = out.size();
                size_t ni = expandMacroAt(out, in, i, to, st, expanded, loc ? loc : &t);
                if (ni != i) { i = ni; (void)before; continue; }
            }
        }
        PPToken n = t;
        if (loc) { n.line = loc->line; n.col = loc->col; n.fileIndex = loc->fileIndex; if (n.macro.empty()) n.macro = macroName; }
        out.push_back(n);
        ++i;
    }
}

static std::string dirOf(const std::string &path) {
    std::string::size_type pos = path.find_last_of('/');
    if (pos == std::string::npos) return "";
    return path.substr(0, pos + 1);
}

struct IfState { bool active; bool anyTaken; bool parentActive; };

static void processTokens(const std::vector<PPToken> &toks, PPState &st, std::vector<PPToken> &out, const std::string &curFile);

static void handleInclude(const PPToken &hashTok, const PPToken &nameTok, PPState &st, std::vector<PPToken> &out, const std::string &curFile) {
    std::string header = nameTok.str;
    bool system = header[0] == '<';
    std::string name = header.substr(1, header.size() - 2);
    std::string found;
    if (!system) {
        std::string cand = dirOf(curFile) + name;
        if (fileExists(cand)) found = cand;
    }
    if (found.empty()) {
        for (const std::string &inc : st.settings->includePaths) {
            std::string cand = inc + name;
            if (fileExists(cand)) { found = cand; break; }
        }
    }
    if (found.empty()) {
        if (st.reportMissing) {
            const std::string key = header;
            if (!st.missingReported->count(key)) {
                st.missingReported->insert(key);
                PPError e;
                e.file = st.files->at(hashTok.fileIndex);
                e.line = hashTok.line;
                e.col = hashTok.col + 1;
                if (system) { e.id = "missingIncludeSystem"; e.msg = "Include file: " + header + " not found. Please note: Standard library headers do not need to be provided to get proper results."; }
                else { e.id = "missingInclude"; e.msg = "Include file: " + header + " not found."; }
                st.errors->push_back(e);
            }
        }
        return;
    }
    found = simplifyPath(found);
    if (st.pragmaOnce.count(found)) return;
    if (st.includeStack.count(found) || st.includeDepth > 200) return;
    unsigned idx = 0;
    bool have = false;
    for (size_t i = 0; i < st.files->size(); ++i) if (st.files->at(i) == found) { idx = (unsigned)i; have = true; break; }
    if (!have) { st.files->push_back(found); idx = (unsigned)st.files->size() - 1; }
    auto fc = st.fileCache->find(found);
    if (fc == st.fileCache->end()) {
        std::ifstream f(found, std::ios::binary);
        std::stringstream ss; ss << f.rdbuf();
        std::vector<PPToken> ftoks;
        std::vector<SuppressionComment> comments;
        Preprocessor::tokenizeRaw(ss.str(), idx, ftoks, &comments);
        st.pp->allComments[idx] = comments;
        fc = st.fileCache->emplace(found, ftoks).first;
    }
    st.includeStack.insert(found);
    ++st.includeDepth;
    processTokens(fc->second, st, out, found);
    --st.includeDepth;
    st.includeStack.erase(found);
}

static void processTokens(const std::vector<PPToken> &toks, PPState &st, std::vector<PPToken> &out, const std::string &curFile) {
    std::vector<IfState> ifs;
    auto active = [&]() { return ifs.empty() || ifs.back().active; };
    size_t i = 0;
    const size_t n = toks.size();
    while (i < n) {
        const PPToken &tok = toks[i];
        // directive?
        if (tok.op && tok.str == "#" && (i == 0 || !sameline(&toks[i-1], &tok))) {
            // collect directive line
            size_t j = i + 1;
            while (j < n && sameline(&tok, &toks[j])) ++j;
            // j = first token of next line
            if (i + 1 >= j) { i = j; continue; } // lone '#'
            const PPToken &cmd = toks[i+1];
            const std::string &c = cmd.str;
            if (c == "if" || c == "ifdef" || c == "ifndef") {
                bool parentActive = active();
                bool cond = false;
                if (parentActive) {
                    if (c == "ifdef" || c == "ifndef") {
                        bool def = (i + 2 < j) && st.macros.count(toks[i+2].str);
                        cond = (c == "ifdef") ? def : !def;
                    } else {
                        // expand macros in condition (except after defined)
                        std::vector<PPToken> condToks;
                        for (size_t k = i + 2; k < j; ++k) {
                            if (toks[k].name && toks[k].str == "defined") {
                                condToks.push_back(toks[k]);
                                size_t k2 = k + 1;
                                if (k2 < j && toks[k2].str == "(") { condToks.push_back(toks[k2]); ++k2; }
                                if (k2 < j) { condToks.push_back(toks[k2]); ++k2; }
                                if (k2 < j && toks[k2].str == ")") { condToks.push_back(toks[k2]); ++k2; }
                                k = k2 - 1;
                                continue;
                            }
                            if (toks[k].name && st.macros.count(toks[k].str)) {
                                std::set<std::string> exp;
                                size_t ni = expandMacroAt(condToks, toks, k, j, st, exp, nullptr);
                                if (ni != k) { k = ni - 1; continue; }
                            }
                            condToks.push_back(toks[k]);
                        }
                        size_t ci = 0;
                        bool ok = true;
                        long long v = evalExpression(condToks, ci, 0, st, ok);
                        if (ci != condToks.size()) ok = false;
                        if (!ok) {
                            PPError e; e.file = st.files->at(tok.fileIndex); e.line = tok.line; e.col = tok.col; e.id = "syntaxError";
                            e.msg = "failed to evaluate " + std::string("#") + c + " condition";
                            throw PPError_Exception(e);
                        }
                        cond = v != 0;
                    }
                }
                ifs.push_back({parentActive && cond, parentActive && cond, parentActive});
            } else if (c == "elif") {
                if (ifs.empty()) { PPError e; e.file = st.files->at(tok.fileIndex); e.line = tok.line; e.col = tok.col; e.id = "syntaxError"; e.msg = "#elif without #if"; throw PPError_Exception(e); }
                IfState &s = ifs.back();
                if (!s.parentActive || s.anyTaken) { s.active = false; }
                else {
                    std::vector<PPToken> condToks;
                    for (size_t k = i + 2; k < j; ++k) {
                        if (toks[k].name && toks[k].str == "defined") {
                            condToks.push_back(toks[k]);
                            size_t k2 = k + 1;
                            if (k2 < j && toks[k2].str == "(") { condToks.push_back(toks[k2]); ++k2; }
                            if (k2 < j) { condToks.push_back(toks[k2]); ++k2; }
                            if (k2 < j && toks[k2].str == ")") { condToks.push_back(toks[k2]); ++k2; }
                            k = k2 - 1;
                            continue;
                        }
                        if (toks[k].name && st.macros.count(toks[k].str)) {
                            std::set<std::string> exp;
                            size_t ni = expandMacroAt(condToks, toks, k, j, st, exp, nullptr);
                            if (ni != k) { k = ni - 1; continue; }
                        }
                        condToks.push_back(toks[k]);
                    }
                    size_t ci = 0; bool ok = true;
                    long long v = evalExpression(condToks, ci, 0, st, ok);
                    if (ci != condToks.size()) ok = false;
                    if (!ok) {
                        PPError e; e.file = st.files->at(tok.fileIndex); e.line = tok.line; e.col = tok.col; e.id = "syntaxError";
                        e.msg = "failed to evaluate #elif condition";
                        throw PPError_Exception(e);
                    }
                    s.active = v != 0;
                    if (s.active) s.anyTaken = true;
                }
            } else if (c == "else") {
                if (ifs.empty()) { PPError e; e.file = st.files->at(tok.fileIndex); e.line = tok.line; e.col = tok.col; e.id = "syntaxError"; e.msg = "#else without #if"; throw PPError_Exception(e); }
                IfState &s = ifs.back();
                s.active = s.parentActive && !s.anyTaken;
                if (s.active) s.anyTaken = true;
            } else if (c == "endif") {
                if (ifs.empty()) { PPError e; e.file = st.files->at(tok.fileIndex); e.line = tok.line; e.col = tok.col; e.id = "syntaxError"; e.msg = "#endif without #if"; throw PPError_Exception(e); }
                ifs.pop_back();
            } else if (!active()) {
                // skip
            } else if (c == "define") {
                if (i + 2 < j && toks[i+2].name) {
                    Macro m;
                    parseMacroDefinition(toks, i + 2, j, m);
                    st.macros[m.name] = m;
                } else {
                    PPError e; e.file = st.files->at(tok.fileIndex); e.line = tok.line; e.col = tok.col; e.id = "syntaxError";
                    e.msg = "No macro name given in #define directive"; throw PPError_Exception(e);
                }
            } else if (c == "undef") {
                if (i + 2 < j) st.macros.erase(toks[i+2].str);
            } else if (c == "include") {
                if (i + 2 < j) {
                    const PPToken &nt = toks[i+2];
                    if (nt.isString() || (nt.str.size() >= 2 && nt.str[0] == '<')) {
                        handleInclude(tok, nt, st, out, curFile);
                    } else {
                        // macro-expanded include
                        std::vector<PPToken> ex;
                        std::set<std::string> exp;
                        expandTokens(ex, toks, i + 2, j, st, exp, nullptr, "");
                        if (!ex.empty()) {
                            if (ex[0].isString()) handleInclude(tok, ex[0], st, out, curFile);
                            else if (ex[0].str == "<") {
                                PPToken t2 = ex[0];
                                std::string s = "<";
                                for (size_t k = 1; k < ex.size(); ++k) s += ex[k].str;
                                if (s.back() != '>') s += ">";
                                t2.str = s;
                                handleInclude(tok, t2, st, out, curFile);
                            } else if (ex[0].str.size() > 1 && ex[0].str[0] == '<') handleInclude(tok, ex[0], st, out, curFile);
                        }
                    }
                }
            } else if (c == "error") {
                PPError e; e.file = st.files->at(tok.fileIndex); e.line = tok.line; e.col = tok.col; e.id = "preprocessorErrorDirective";
                std::string msg = "#error";
                for (size_t k = i + 2; k < j; ++k) { msg += " "; msg += toks[k].str; }
                e.msg = msg;
                throw PPError_Exception(e);
            } else if (c == "warning") {
                // ignore
            } else if (c == "pragma") {
                if (i + 2 < j && toks[i+2].str == "once") st.pragmaOnce.insert(simplifyPath(curFile));
                else if (i + 2 < j && toks[i+2].str == "asm") {
                    // skip until #pragma endasm
                    size_t k = j;
                    while (k < n) {
                        if (toks[k].str == "#" && (k == 0 || !sameline(&toks[k-1], &toks[k])) && k + 2 < n && toks[k+1].str == "pragma" && toks[k+2].str == "endasm") {
                            size_t e = k + 1; while (e < n && sameline(&toks[k], &toks[e])) ++e;
                            j = e; break;
                        }
                        ++k;
                    }
                    if (k >= n) j = n;
                }
            } else if (c == "line") {
                // ignore
            } else {
                // unknown directive: ignore
            }
            i = j;
            continue;
        }
        if (!active()) { ++i; continue; }
        // normal token: expand macros
        if (tok.name && st.macros.count(tok.str)) {
            std::set<std::string> exp;
            size_t ni = expandMacroAt(out, toks, i, n, st, exp, nullptr);
            if (ni != i) { i = ni; continue; }
        }
        if (tok.name && tok.str == "__FILE__") {
            PPToken t2 = tok; t2.str = "\"" + st.files->at(tok.fileIndex) + "\""; t2.name = false; t2.macro = "__FILE__";
            out.push_back(t2); ++i; continue;
        }
        if (tok.name && tok.str == "__LINE__") {
            PPToken t2 = tok; t2.str = std::to_string(tok.line); t2.name = false; t2.number = true; t2.macro = "__LINE__";
            out.push_back(t2); ++i; continue;
        }
        if (tok.name && tok.str == "__COUNTER__") {
            PPToken t2 = tok; t2.str = std::to_string(st.counter++); t2.name = false; t2.number = true; t2.macro = "__COUNTER__";
            out.push_back(t2); ++i; continue;
        }
        out.push_back(tok);
        ++i;
    }
    if (!ifs.empty()) {
        PPError e; e.file = curFile; e.line = toks.empty() ? 1 : toks.back().line; e.col = 0; e.id = "syntaxError";
        e.msg = "#if/#else/#endif mismatch"; 
        // cppcheck reports via simplecpp: "Missing #endif"? we use generic
        throw PPError_Exception(e);
    }
}
}

std::vector<PPToken> Preprocessor::preprocess(const std::string &cfg, const std::vector<std::string> &libraryDefines, std::vector<PPError> &errors, bool reportMissingIncludes) {
    PPState st;
    st.errors = &errors;
    st.missingReported = &missingIncludesReported;
    st.pp = this;
    st.settings = &mSettings;
    st.reportMissing = reportMissingIncludes;
    st.files = &mFiles;
    st.fileCache = &mFileCache;

    auto addDefine = [&](const std::string &def) {
        // def is "NAME", "NAME=VALUE" or "NAME VALUE" or "NAME(args) VALUE"
        std::string text = def;
        std::string::size_type eq = text.find('=');
        std::string::size_type sp = text.find(' ');
        std::string::size_type paren = text.find('(');
        std::string nameAndParams, value;
        if (eq != std::string::npos && (sp == std::string::npos || eq < sp) && (paren == std::string::npos || eq < paren)) {
            nameAndParams = text.substr(0, eq); value = text.substr(eq + 1);
        } else if (sp != std::string::npos) {
            nameAndParams = text.substr(0, sp); value = text.substr(sp + 1);
        } else if (eq != std::string::npos) {
            // NAME(a,b)=VALUE
            nameAndParams = text.substr(0, eq); value = text.substr(eq + 1);
        } else { nameAndParams = text; value = "1"; }
        std::vector<PPToken> toks;
        tokenizeRaw(nameAndParams + " " + value, 0, toks, nullptr);
        if (toks.empty() || !toks[0].name) return;
        Macro m;
        parseMacroDefinition(toks, 0, toks.size(), m);
        // fix whitespace detection for "NAME VALUE" vs function-like: tokenizeRaw sets whitespaceBefore
        st.macros[m.name] = m;
    };
    // predefined
    addDefine("__cppcheck__");
    addDefine("__CPPCHECK_MAJOR__=2");
    addDefine("__CPPCHECK_MINOR__=19");
    addDefine("__CPPCHECK_DEVMINOR__=0");
    // library defines
    for (const std::string &d : libraryDefines) addDefine(d);
    // user defines from -D are part of cfg already (cfg string)
    // cfg defines
    {
        std::string::size_type start = 0;
        while (start < cfg.size()) {
            std::string::size_type semi = cfg.find(';', start);
            std::string def = cfg.substr(start, semi == std::string::npos ? std::string::npos : semi - start);
            if (!def.empty()) addDefine(def);
            if (semi == std::string::npos) break;
            start = semi + 1;
        }
    }
    for (const std::string &u : mSettings.userUndefs) st.macros.erase(u);

    std::vector<PPToken> out;
    try {
        // forced includes
        for (const std::string &inc : mSettings.userIncludes) {
            PPToken fake; fake.fileIndex = 0; fake.line = 0; fake.col = 0;
            PPToken nameTok; nameTok.str = "\"" + inc + "\"";
            handleInclude(fake, nameTok, st, out, "");
        }
        processTokens(mRawTokens, st, out, mMainFile);
    } catch (const PPError_Exception &e) {
        errors.push_back(e.err);
        PPError marker; marker.id = "__abort__";
        errors.push_back(marker);
    }
    return out;
}

std::string Preprocessor::stringify(const std::vector<PPToken> &tokens, const std::vector<std::string> &files) {
    std::string ret;
    int line = 1;
    unsigned fileIndex = 0;
    bool first = true;
    const PPToken *prev = nullptr;
    for (const PPToken &tok : tokens) {
        if (tok.fileIndex != fileIndex || tok.line < line) {
            // file change: emit #line marker (cppcheck comments it out)
            ret += "\n//#line " + std::to_string(tok.line) + " \"" + (tok.fileIndex < files.size() ? files[tok.fileIndex] : "") + "\"\n";
            line = tok.line;
            fileIndex = tok.fileIndex;
            first = true;
        }
        while (tok.line > line) { ret += '\n'; ++line; first = true; }
        if (!first) ret += ' ';
        if (!tok.macro.empty()) ret += ' ';
        ret += tok.str;
        first = false;
        prev = &tok;
    }
    (void)prev;
    return ret;
}
