const std::string &Token::strAt(int index) const {
    static const std::string empty;
    const Token *t = tokAt(index);
    return t ? t->str : empty;
}
const Token *Token::tokAt(int index) const {
    const Token *t = this;
    while (index > 0 && t) { t = t->next; --index; }
    while (index < 0 && t) { t = t->previous; ++index; }
    return t;
}
Token *Token::tokAt(int index) {
    Token *t = this;
    while (index > 0 && t) { t = t->next; --index; }
    while (index < 0 && t) { t = t->previous; ++index; }
    return t;
}
const Token *Token::linkAt(int index) const {
    const Token *t = tokAt(index);
    return t ? t->link : nullptr;
}
Token *Token::linkAt(int index) {
    Token *t = tokAt(index);
    return t ? t->link : nullptr;
}

bool Token::isUnaryPreOp() const {
    if (!astOperand1 || astOperand2) return false;
    if (str == "++" || str == "--") return astOperand1 == next; // prefix
    return str == "!" || str == "~" || str == "-" || str == "+" || str == "*" || str == "&";
}
bool Token::isUnaryPlusMinus() const { return (str == "+" || str == "-") && astOperand1 && !astOperand2; }

const Token *Token::nextArgument() const {
    for (const Token *tok = this; tok; tok = tok->next) {
        if (tok->str == "," && tok->link == nullptr) return tok->next;
        if (tok->link && (tok->str == "(" || tok->str == "[" || tok->str == "{" || tok->str == "<")) tok = tok->link;
        else if (tok->str == ")" || tok->str == ";" || tok->str == "}" || tok->str == "]") return nullptr;
    }
    return nullptr;
}

const Token *Token::findClosingBracket() const {
    if (str != "<") return nullptr;
    int depth = 0;
    for (const Token *t = this; t; t = t->next) {
        if (t->str == "<") ++depth;
        else if (t->str == ">") { --depth; if (depth == 0) return t; }
        else if (t->str == ">>") { depth -= 2; if (depth <= 0) return t; }
        else if (t->str == ";" || t->str == "{" || t->str == "}") return nullptr;
        else if (t->str == "(" && t->link) t = t->link;
    }
    return nullptr;
}
const Token *Token::findOpeningBracket() const {
    if (str != ">") return nullptr;
    int depth = 0;
    for (const Token *t = this; t; t = t->previous) {
        if (t->str == ">") ++depth;
        else if (t->str == "<") { --depth; if (depth == 0) return t; }
        else if (t->str == ";" || t->str == "{" || t->str == "}") return nullptr;
        else if (t->str == ")" && t->link) t = t->link;
    }
    return nullptr;
}

void Token::astOperand1Set(Token *t) {
    if (t) t->astParent = this;
    astOperand1 = t;
}
void Token::astOperand2Set(Token *t) {
    if (t) t->astParent = this;
    astOperand2 = t;
}
const Token *Token::astTop() const {
    const Token *t = this;
    while (t->astParent) t = t->astParent;
    return t;
}

