    if (!tok) return;
    if (tok->isExpandedMacro && !tok->macroName.empty() && false) { out += tok->macroName; return; }
    if (tok->str == "(" && tok->astOperand1) {
        if (tok->isCast) {
            out += "(";
            // cast type
            const Token *t = tok->next;
            while (t && t != tok->link) { out += t->str; if (t->next != tok->link && t->next && (t->next->isName() && t->isName())) out += ' '; t = t->next; }
            out += ")";
            exprString(tok->astOperand1, out);
            return;
        }
        // function call or parenthesized
        if (tok->astOperand2 || (tok->astOperand1 && tok->astOperand1->isName()) || (tok->astOperand1 && (tok->astOperand1->str == "." || tok->astOperand1->str == "::" || tok->astOperand1->str == "->" || tok->astOperand1->str == "[" || tok->astOperand1->str == "("))) {
            exprString(tok->astOperand1, out);
            out += "(";
            exprString(tok->astOperand2, out);
            out += ")";
            return;
        }
        out += "(";
        exprString(tok->astOperand1, out);
        out += ")";
        return;
    }
    if (tok->str == "[" && tok->astOperand1) {
        exprString(tok->astOperand1, out);
        out += "[";
        exprString(tok->astOperand2, out);
        out += "]";
        return;
    }
    if (tok->str == "{" && tok->astOperand1) {
        if (tok->astOperand1->isName() || tok->astOperand1->str == "::") exprString(tok->astOperand1, out);
        out += "{";
        exprString(tok->astOperand2, out);
        out += "}";
        return;
    }
    if (tok->astOperand1 && tok->astOperand2) {
        if (tok->str == "," ) {
            exprString(tok->astOperand1, out);
            out += ",";
            exprString(tok->astOperand2, out);
            return;
        }
        if (tok->str == "." || tok->str == "::" || tok->str == "->") {
            exprString(tok->astOperand1, out);
            out += tok->str;
            exprString(tok->astOperand2, out);
            return;
        }
        if (tok->str == "?") {
            exprString(tok->astOperand1, out);
            out += "?";
            exprString(tok->astOperand2, out);
            return;
        }
        if (tok->str == ":" && tok->astParent && tok->astParent->str == "?") {
            exprString(tok->astOperand1, out);
            out += ":";
            exprString(tok->astOperand2, out);
            return;
        }
        exprString(tok->astOperand1, out);
        out += tok->str;
        exprString(tok->astOperand2, out);
        return;
    }
    if (tok->astOperand1) {
        if ((tok->str == "++" || tok->str == "--") && tok->astOperand1 == tok->previous) {
            exprString(tok->astOperand1, out);
            out += tok->str;
            return;
        }
        if (tok->str == "sizeof" || tok->str == "return" || tok->str == "throw" || tok->str == "delete" || tok->str == "new") {
            out += tok->str;
            if (tok->str == "sizeof") { out += "("; exprString(tok->astOperand1, out); out += ")"; }
            else { out += " "; exprString(tok->astOperand1, out); }
            return;
        }
        out += tok->str;
        exprString(tok->astOperand1, out);
        return;
    }
    out += tok->originalName.empty() ? tok->str : tok->str;
}

