bool isNumberLiteral(const std::string &s) {
    if (s.empty()) return false;
    return isdigit((unsigned char)s[0]) || (s[0] == '.' && s.size() > 1 && isdigit((unsigned char)s[1])) || ((s[0] == '-' || s[0] == '+') && s.size() > 1 && isdigit((unsigned char)s[1]));
}
bool isIntLiteral(const std::string &s) {
    if (!isNumberLiteral(s)) return false;
    if (s.size() > 2 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) return true;
    return s.find_first_of(".eE") == std::string::npos;
}
long long toLongNumber(const std::string &str) {
    std::string s = str;
    bool neg = false;
    if (!s.empty() && s[0] == '-') { neg = true; s = s.substr(1); }
    else if (!s.empty() && s[0] == '+') s = s.substr(1);
    while (!s.empty() && (s.back() == 'L' || s.back() == 'l' || s.back() == 'U' || s.back() == 'u' || s.back() == 'z' || s.back() == 'Z')) s.pop_back();
    long long v = 0;
    if (s.size() > 1 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) v = (long long)strtoull(s.c_str(), nullptr, 16);
    else if (s.size() > 1 && s[0] == '0' && (s[1] == 'b' || s[1] == 'B')) v = (long long)strtoull(s.c_str() + 2, nullptr, 2);
    else if (s.size() > 1 && s[0] == '0' && isdigit((unsigned char)s[1])) v = (long long)strtoull(s.c_str(), nullptr, 8);
    else if (s.find_first_of(".eE") != std::string::npos) v = (long long)strtod(s.c_str(), nullptr);
    else if (!s.empty() && s[0] == '\'') {
        // char literal
        std::string inner = s.substr(1, s.size() - 2);
        if (inner.empty()) v = 0;
        else if (inner[0] != '\\') v = (unsigned char)inner[0];
        else if (inner.size() >= 2) {
            switch (inner[1]) {
            case 'n': v = '\n'; break; case 't': v = '\t'; break; case 'r': v = '\r'; break; case '0': v = strtol(inner.c_str()+1, nullptr, 8); break;
            case '\\': v = '\\'; break; case '\'': v = '\''; break; case '"': v = '"'; break; case 'a': v = 7; break; case 'b': v = 8; break; case 'f': v = 12; break; case 'v': v = 11; break;
            case 'x': v = strtol(inner.c_str()+2, nullptr, 16); break;
            default: v = inner[1];
            }
        }
    }
    else v = (long long)strtoull(s.c_str(), nullptr, 10);
    return neg ? -v : v;
}
