// ---------------------------------------------------------------------------
// Pattern matching (subset of cppcheck's Token::Match)
// Supported: literal strings, %any% %name% %var% %type% %num% %str% %char% %bool% %op% %cop% %or% %oror% %comp% %assign% %varid%
//            !!str (not), alternatives a|b|c, [abc] single char, "!!" etc
// ---------------------------------------------------------------------------
static bool matchSingle(const Token *tok, const std::string &pat, unsigned varid) {
    if (pat == "%any%") return true;
    if (pat == "%name%") return tok->isName();
    if (pat == "%var%") return tok->varId != 0;
    if (pat == "%type%") return tok->isName() && tok->varId == 0 && !(tok->isKeyword() && !isStandardTypeStr(tok->str) && tok->str != "struct" && tok->str != "union" && tok->str != "enum" && tok->str != "class" && tok->str != "const");
    if (pat == "%num%") return tok->isNumber();
    if (pat == "%str%") return tok->tokType == Token::eString;
    if (pat == "%char%") return tok->tokType == Token::eChar;
    if (pat == "%bool%") return tok->tokType == Token::eBoolean;
    if (pat == "%op%") return tok->isOp();
    if (pat == "%cop%") return tok->isConstOp();
    if (pat == "%or%") return tok->str == "|";
    if (pat == "%oror%") return tok->str == "||";
    if (pat == "%comp%") return tok->isComparisonOp();
    if (pat == "%assign%") return tok->isAssignmentOp();
    if (pat == "%varid%") return tok->varId == varid && varid != 0;
    if (pat.size() >= 2 && pat[0] == '[' && pat.back() == ']') {
        if (tok->str.size() != 1) return false;
        return pat.find(tok->str[0], 1) != std::string::npos && pat.find(tok->str[0], 1) < pat.size() - 1;
    }
    // alternatives
    if (pat.find('|') != std::string::npos && pat != "|" && pat != "||" && pat != "|=") {
        std::string::size_type start = 0;
        while (true) {
            std::string::size_type bar = pat.find('|', start);
            std::string alt = pat.substr(start, bar == std::string::npos ? std::string::npos : bar - start);
            if (alt.empty()) { if (bar == std::string::npos) break; start = bar + 1; continue; }
            if (matchSingle(tok, alt, varid)) return true;
            if (bar == std::string::npos) break;
            start = bar + 1;
        }
        return false;
    }
    return tok->str == pat;
}

bool tokMatch(const Token *tok, const char pattern[], unsigned varid) {
    const char *p = pattern;
    while (*p) {
        while (*p == ' ') ++p;
        if (!*p) break;
        const char *start = p;
        while (*p && *p != ' ') ++p;
        std::string pat(start, p - start);
        if (pat == "!!" ) continue;
        bool negate = false;
        bool optional = false;
        if (pat.size() > 2 && pat[0] == '!' && pat[1] == '!') { negate = true; pat = pat.substr(2); }
        // optional "|" at end of alternatives means token may be absent: e.g. "const|"
        if (pat.size() > 1 && pat.back() == '|' && !negate) { optional = true; pat.pop_back(); }
        if (!tok) {
            if (negate) { return true; }
            if (optional) continue;
            return false;
        }
        if (negate) {
            if (matchSingle(tok, pat, varid)) return false;
            tok = tok->next;
            continue;
        }
        if (matchSingle(tok, pat, varid)) { tok = tok->next; continue; }
        if (optional) continue;
        return false;
    }
    return true;
}

bool tokSimpleMatch(const Token *tok, const char pattern[]) {
    const char *p = pattern;
    while (*p) {
        while (*p == ' ') ++p;
        if (!*p) break;
        const char *start = p;
        while (*p && *p != ' ') ++p;
        if (!tok) return false;
        if (tok->str.compare(0, std::string::npos, start, p - start) != 0) return false;
        tok = tok->next;
    }
    return true;
}

const Token *tokFindsimplematch(const Token *startTok, const char pattern[]) {
    for (const Token *tok = startTok; tok; tok = tok->next) if (tokSimpleMatch(tok, pattern)) return tok;
    return nullptr;
}
const Token *tokFindsimplematch(const Token *startTok, const char pattern[], const Token *end) {
    for (const Token *tok = startTok; tok && tok != end; tok = tok->next) if (tokSimpleMatch(tok, pattern)) return tok;
    return nullptr;
}
const Token *tokFindmatch(const Token *startTok, const char pattern[], unsigned varId) {
    for (const Token *tok = startTok; tok; tok = tok->next) if (tokMatch(tok, pattern, varId)) return tok;
    return nullptr;
}
const Token *tokFindmatch(const Token *startTok, const char pattern[], const Token *end, unsigned varId) {
    for (const Token *tok = startTok; tok && tok != end; tok = tok->next) if (tokMatch(tok, pattern, varId)) return tok;
    return nullptr;
}

