void TokenList::clear() {
    while (mFront) { Token *n = mFront->next; delete mFront; mFront = n; }
    mBack = nullptr;
}

static void setTokType(Token *t, bool cpp) {
    const std::string &s = t->str;
    if (s.empty()) { t->tokType = Token::eOther; return; }
    if (s == "true" || s == "false") { t->tokType = Token::eBoolean; return; }
    if (isalpha((unsigned char)s[0]) || s[0] == '_' || s[0] == '$') {
        if (s.size() > 1 && (s[0] == 'L' || s[0] == 'u' || s[0] == 'U') && (s[1] == '"' || s[1] == '\'' || (s.size() > 2 && s[1] == '8' && s[2] == '"'))) {
            t->tokType = (s.find('"') != std::string::npos) ? Token::eString : Token::eChar; return;
        }
        if (isKeywordStr(s, cpp) && !isStandardTypeStr(s)) t->tokType = Token::eKeyword;
        else t->tokType = Token::eName;
        if (isStandardTypeStr(s)) { t->isStandardType_ = true; t->tokType = Token::eType; }
        return;
    }
    if (isdigit((unsigned char)s[0]) || (s[0] == '.' && s.size() > 1 && isdigit((unsigned char)s[1]))) { t->tokType = Token::eNumber; return; }
    if (s[0] == '"') { t->tokType = Token::eString; return; }
    if (s[0] == '\'') { t->tokType = Token::eChar; return; }
    if (s == "(" || s == ")" || s == "[" || s == "]" || s == "{" || s == "}") { t->tokType = Token::eBracket; return; }
    if (s == "...") { t->tokType = Token::eEllipsis; return; }
    t->tokType = Token::eOp;
}

Token *TokenList::addtoken(const std::string &str, int line, int col, unsigned fileIndex) {
    Token *t = new Token();
    t->str = str;
    t->linenr = line;
    t->column = col;
    t->fileIndex = fileIndex;
    t->isCpp = isCPP;
    t->isC = !isCPP;
    setTokType(t, isCPP);
    if (mBack) { mBack->next = t; t->previous = mBack; mBack = t; }
    else { mFront = mBack = t; }
    return t;
}

Token *TokenList::insertToken(Token *after, const std::string &str) {
    Token *t = new Token();
    t->str = str;
    t->linenr = after->linenr;
    t->column = after->column;
    t->fileIndex = after->fileIndex;
    t->isCpp = isCPP;
    t->isC = !isCPP;
    setTokType(t, isCPP);
    t->previous = after;
    t->next = after->next;
    if (after->next) after->next->previous = t;
    else mBack = t;
    after->next = t;
    return t;
}

void TokenList::deleteToken(Token *tok) {
    if (!tok) return;
    if (tok->previous) tok->previous->next = tok->next; else mFront = tok->next;
    if (tok->next) tok->next->previous = tok->previous; else mBack = tok->previous;
    delete tok;
}

void TokenList::deleteNext(Token *tok, int count) {
    while (count-- > 0 && tok->next) deleteToken(tok->next);
}

void TokenList::eraseTokens(Token *begin, const Token *end) {
    while (begin->next && begin->next != end) deleteToken(begin->next);
}

std::string TokenList::stringify(bool withLines) const {
    std::ostringstream os;
    int line = -1;
    unsigned file = 0;
    for (const Token *t = mFront; t; t = t->next) {
        if (withLines) {
            if (t->fileIndex != file || t->linenr != line) {
                if (line != -1) os << "\n";
                os << t->linenr << ": ";
                line = t->linenr; file = t->fileIndex;
            } else os << " ";
        } else if (t != mFront) os << " ";
        os << t->str;
    }
    return os.str();
}

std::vector<Token*> TokenList::allTokens() const {
    std::vector<Token*> v;
    for (Token *t = mFront; t; t = t->next) v.push_back(t);
    return v;
}
