void Tokenizer::createTokens(const std::vector<PPToken> &pptokens, const std::vector<std::string> &files, bool isCPP) {
    list.clear();
    list.isCPP = isCPP;
    list.files = files;
    for (const PPToken &pt : pptokens) {
        Token *t = list.addtoken(pt.str, pt.line, pt.col, pt.fileIndex);
        if (!pt.macro.empty()) { t->isExpandedMacro = true; t->macroName = pt.macro; }
    }
}

static void linkBrackets(const Tokenizer &tokenizer, std::stack<const Token*> &type, std::stack<Token*> &links, Token * const token, const char open, const char close);

void Tokenizer::createLinks() {
    std::stack<const Token*> type;
    std::stack<Token*> links1, links2, links3;
    for (Token *token = list.front(); token; token = token->next) {
        if (token->link) token->link = nullptr;
        if (token->str == "(" || token->str == ")") {
            if (token->str == "(") { links1.push(token); type.push(token); }
            else {
                if (links1.empty()) unmatchedToken(token);
                if (type.top()->str != "(") unmatchedToken(type.top());
                type.pop();
                links1.top()->link = token; token->link = links1.top(); links1.pop();
            }
        } else if (token->str == "{" || token->str == "}") {
            if (token->str == "{") { links2.push(token); type.push(token); }
            else {
                if (links2.empty()) unmatchedToken(token);
                if (type.top()->str != "{") unmatchedToken(type.top());
                type.pop();
                links2.top()->link = token; token->link = links2.top(); links2.pop();
            }
        } else if (token->str == "[" || token->str == "]") {
            if (token->str == "[") { links3.push(token); type.push(token); }
            else {
                if (links3.empty()) unmatchedToken(token);
                if (type.top()->str != "[") unmatchedToken(type.top());
                type.pop();
                links3.top()->link = token; token->link = links3.top(); links3.pop();
            }
        }
    }
    if (!links1.empty()) unmatchedToken(links1.top());
    if (!links2.empty()) unmatchedToken(links2.top());
    if (!links3.empty()) unmatchedToken(links3.top());
}

// Link template brackets < >
void Tokenizer::createLinks2() {
    if (!isCPP()) return;
    std::stack<Token*> type;
    for (Token *token = list.front(); token; token = token->next) {
        if (token->link) {
            if (token->str == "{" || token->str == "(" || token->str == "[") { type.push(token); continue; }
            if (token->str == "}" || token->str == ")" || token->str == "]") {
                while (!type.empty() && type.top()->str == "<") { type.top()->link = nullptr; type.pop(); }
                if (!type.empty()) type.pop();
                continue;
            }
            if (token->str == "<" || token->str == ">") { token->link = nullptr; }
        }
        if (token->str == ";" ) {
            while (!type.empty() && type.top()->str == "<") { type.top()->link = nullptr; type.pop(); }
            continue;
        }
        if (token->str == "<" && token->previous && (token->previous->isName() || token->previous->str == ">") && !token->previous->isKeyword()) {
            // possible template
            // heuristic: next tokens up to '>' should look like types
            type.push(token);
        } else if (token->str == ">" || token->str == ">>") {
            if (type.empty() || type.top()->str != "<") continue;
            Token *top = type.top();
            // check whether this is a template close (prev is name or > or ] or * or &)
            if (!(token->previous && (token->previous->isName() || token->previous->str == ">" || token->previous->str == "*" || token->previous->str == "&" || token->previous->str == ")" || token->previous->str == "]" || token->previous->str == "::" || token->previous->isNumber()))) { continue; }
            if (token->str == ">>") {
                // split
                token->str = ">";
                Token *second = list.insertToken(token, ">");
                second->column = token->column + 1;
                type.pop();
                top->link = token; token->link = top;
                token = second;
                if (type.empty() || type.top()->str != "<") continue;
                top = type.top();
            }
            type.pop();
            top->link = token; token->link = top;
        }
    }
}

void Tokenizer::removeAttributes() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if ((tok->str == "__attribute__" || tok->str == "__attribute") && tok->next && tok->next->str == "(" && tok->next->link) {
            Token *paren = tok->next;
            Token *end = paren->link;
            // determine attribute content
            std::string content;
            for (Token *t = paren->next; t && t != end; t = t->next) content += t->str + " ";
            bool unused = content.find("unused") != std::string::npos;
            bool used = content.find("used ") != std::string::npos && !unused;
            bool noreturn = content.find("noreturn") != std::string::npos;
            bool ctor = content.find("constructor") != std::string::npos;
            bool dtor = content.find("destructor") != std::string::npos;
            // find target token: next name or previous name
            Token *target = end->next;
            while (target && (target->str == "*" || target->str == "&" || target->str == "const" || target->str == "static" || target->str == "inline" || (target->isName() && target->next && target->next->isName()))) target = target->next;
            if (!target || !target->isName()) {
                target = tok->previous;
                while (target && !target->isName() && target->str != ")" ) target = target->previous;
                if (target && target->str == ")" && target->link && target->link->previous) target = target->link->previous;
            }
            if (target && target->isName()) {
                if (unused) target->isAttributeUnused = true;
                if (used) target->isAttributeUsed = true;
                if (noreturn) target->isAttributeNoreturn = true;
                if (ctor) target->isAttributeConstructor = true;
                if (dtor) target->isAttributeDestructor = true;
            }
            Token *prev = tok->previous;
            list.eraseTokens(tok, end->next);
            list.deleteToken(tok);
            if (!prev) { tok = list.front(); if (!tok) break; }
            else tok = prev;
            continue;
        }
        if ((tok->str == "__declspec" || tok->str == "__cppcheck_in_range__" || tok->str == "__cppcheck_low__" || tok->str == "__cppcheck_high__") && tok->next && tok->next->str == "(" && tok->next->link) {
            Token *end = tok->next->link;
            Token *prev = tok->previous;
            list.eraseTokens(tok, end->next);
            list.deleteToken(tok);
            tok = prev ? prev : list.front();
            if (!tok) break;
            continue;
        }
        // [[attribute]]
        if (tok->str == "[" && tok->next && tok->next->str == "[" && tok->link && tok->link->previous && tok->link->previous->str == "]" && tok->next->link == tok->link->previous) {
            std::string content;
            for (Token *t = tok->next->next; t && t != tok->next->link; t = t->next) content += t->str + " ";
            Token *end = tok->link;
            Token *target = end->next;
            while (target && (target->str == "*" || target->str == "&" || target->str == "const" || target->str == "static" || target->str == "inline" || (target->isName() && target->next && target->next->isName()))) target = target->next;
            if (!target || !target->isName()) {
                target = tok->previous;
                while (target && !target->isName()) target = target->previous;
            }
            if (target && target->isName()) {
                if (content.find("maybe_unused") != std::string::npos) { target->isAttributeMaybeUnused = true; }
                if (content.find("noreturn") != std::string::npos) target->isAttributeNoreturn = true;
            }
            Token *prev = tok->previous;
            list.eraseTokens(tok, end->next);
            list.deleteToken(tok);
            tok = prev ? prev : list.front();
            if (!tok) break;
            continue;
        }
        // calling conventions
        if (tok->str == "__cdecl" || tok->str == "__stdcall" || tok->str == "__fastcall" || tok->str == "__thiscall" || tok->str == "__clrcall" || tok->str == "__syscall" || tok->str == "__pascal" || tok->str == "__fortran" || tok->str == "WINAPI" || tok->str == "APIENTRY" || tok->str == "CALLBACK" || tok->str == "__restrict" || tok->str == "__restrict__" || tok->str == "__extension__" || tok->str == "__inline" || tok->str == "__inline__" || tok->str == "__forceinline" || tok->str == "_Noreturn" || tok->str == "__thread" || tok->str == "__volatile" || tok->str == "__volatile__") {
            Token *prev = tok->previous;
            if (tok->str == "_Noreturn" || tok->str == "__noreturn__") { Token *t = tok->next; while (t && !t->isName()) t = t->next; }
            list.deleteToken(tok);
            tok = prev ? prev : list.front();
            if (!tok) break;
            continue;
        }
        if ((tok->str == "__asm__" || tok->str == "__asm" || tok->str == "asm") && tok->next && tok->next->str == "(" ) {
            // handled in simplifyAsm
        }
    }
}

void Tokenizer::combineStringAndCharLiterals() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->tokType != Token::eString) continue;
        while (tok->next && tok->next->tokType == Token::eString) {
            // merge: remove closing quote of first and opening of second
            std::string a = tok->str;
            std::string b = tok->next->str;
            std::string::size_type q1 = a.rfind('"');
            std::string::size_type q2 = b.find('"');
            if (q1 == std::string::npos || q2 == std::string::npos) break;
            tok->str = a.substr(0, q1) + b.substr(q2 + 1);
            list.deleteNext(tok);
        }
    }
}

void Tokenizer::concatenateNegativeNumberAndAnyPositive() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (!(tok->str == "-" || tok->str == "+") || !tok->next || !tok->next->isNumber()) continue;
        if (!tok->previous) continue;
        const Token *prev = tok->previous;
        // previous token must be an operator / '(' / ',' / '=' / 'return' / '[' / '{' / '?' / ':'  (not a value)
        bool prevIsValue = prev->isName() && !prev->isKeyword() && prev->str != "return" && prev->str != "case";
        if (prev->str == "return" || prev->str == "case") prevIsValue = false;
        if (prev->isNumber() || prev->str == ")" || prev->str == "]" || prev->tokType == Token::eString || prev->tokType == Token::eChar) prevIsValue = true;
        if (prev->str == "++" || prev->str == "--") prevIsValue = true;
        if (prev->isName() && (prev->str == "sizeof")) prevIsValue = false;
        if (prevIsValue) continue;
        if (prev->str == "-" || prev->str == "+") {
            // e.g. "- - 1": keep
        }
        if (tok->str == "+") {
            // remove unary plus
            Token *n = tok->next;
            n->column = tok->column;
            list.deleteToken(tok);
            tok = n;
            continue;
        }
        if (tok->next->str[0] == '-') continue;
        tok->str = "-" + tok->next->str;
        tok->tokType = Token::eNumber;
        list.deleteNext(tok);
    }
}

void Tokenizer::simplifyCAlternativeTokens() {
    static const std::map<std::string, std::string> alt = {
        {"and", "&&"}, {"and_eq", "&="}, {"bitand", "&"}, {"bitor", "|"}, {"compl", "~"}, {"not", "!"}, {"not_eq", "!="}, {"or", "||"}, {"or_eq", "|="}, {"xor", "^"}, {"xor_eq", "^="}
    };
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (!tok->isName()) continue;
        auto it = alt.find(tok->str);
        if (it == alt.end()) continue;
        if (!isCPP()) {
            // in C: only if it makes sense
            if (it->second == "!" || it->second == "~") {
                if (!(tok->next && (tok->next->isName() || tok->next->isNumber() || tok->next->str == "(")) ) continue;
                if (tok->previous && (tok->previous->isName() || tok->previous->isNumber() || tok->previous->str == ")")) continue;
            } else {
                if (!(tok->previous && (tok->previous->isName() || tok->previous->isNumber() || tok->previous->str == ")" || tok->previous->str == "]" || tok->previous->isLiteral()))) continue;
                if (!(tok->next && (tok->next->isName() || tok->next->isNumber() || tok->next->str == "(" || tok->next->str == "!" || tok->next->str == "-" || tok->next->isLiteral()))) continue;
            }
        }
        tok->originalName = tok->str;
        tok->str = it->second;
        tok->tokType = Token::eOp;
    }
}

void Tokenizer::simplifyKeywords() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "inline" || tok->str == "register" || tok->str == "restrict" || tok->str == "__restrict" || tok->str == "override" || tok->str == "final" || tok->str == "thread_local" || tok->str == "constinit" || tok->str == "consteval") {
            if (tok->str == "inline" && tok->previous) tok->previous->isInline = true;
            if ((tok->str == "override" || tok->str == "final") && !(tok->previous && tok->previous->str == ")")) continue;
            if (tok->str == "final" && tok->next && tok->next->str != "{" && tok->next->str != ":" && tok->next->str != ";" && tok->next->str != "=" ) continue;
            Token *prev = tok->previous;
            list.deleteToken(tok);
            if (!prev) { tok = list.front(); if (!tok) break; continue; }
            tok = prev;
            continue;
        }
        if (tok->str == "constexpr") {
            if (tok->next) tok->next->isConstexpr = true;
            // constexpr variable -> const
            tok->str = "const";
            tok->originalName = "constexpr";
            continue;
        }
        if (tok->str == "noexcept" ) {
            if (tok->next && tok->next->str == "(" && tok->next->link) {
                Token *end = tok->next->link;
                Token *prev = tok->previous;
                list.eraseTokens(tok, end->next);
                list.deleteToken(tok);
                tok = prev ? prev : list.front();
                if (!tok) break;
                continue;
            }
            // keep noexcept keyword for function declarations (as a flag)
            if (tok->previous && tok->previous->str == ")") {
                Token *prev = tok->previous;
                list.deleteToken(tok);
                tok = prev;
                continue;
            }
        }
        if (tok->str == "throw" && tok->previous && tok->previous->str == ")" && tok->next && tok->next->str == "(" && tok->next->link) {
            // exception specification
            Token *end = tok->next->link;
            Token *prev = tok->previous;
            list.eraseTokens(tok, end->next);
            list.deleteToken(tok);
            tok = prev;
            continue;
        }
        if (tok->str == "static_assert" || tok->str == "_Static_assert") {
            if (tok->next && tok->next->str == "(" && tok->next->link) {
                Token *end = tok->next->link;
                if (end->next && end->next->str == ";") end = end->next;
                Token *prev = tok->previous;
                list.eraseTokens(tok, end->next);
                list.deleteToken(tok);
                tok = prev ? prev : list.front();
                if (!tok) break;
                continue;
            }
        }
        if (tok->str == "alignas" || tok->str == "_Alignas") {
            if (tok->next && tok->next->str == "(" && tok->next->link) {
                Token *end = tok->next->link;
                Token *prev = tok->previous;
                list.eraseTokens(tok, end->next);
                list.deleteToken(tok);
                tok = prev ? prev : list.front();
                if (!tok) break;
                continue;
            }
        }
        if (tok->str == "volatile" || tok->str == "mutable") {
            // keep "volatile"? cppcheck removes volatile in simplifyKeyword
            if (tok->str == "volatile") {
                Token *prev = tok->previous;
                list.deleteToken(tok);
                tok = prev ? prev : list.front();
                if (!tok) break;
                continue;
            }
        }
        if (tok->str == "typename" && tok->next && tok->next->isName()) {
            Token *prev = tok->previous;
            list.deleteToken(tok);
            tok = prev ? prev : list.front();
            if (!tok) break;
            continue;
        }
        if (tok->str == "explicit" && tok->next) {
            // keep as flag: mark next name
            // cppcheck keeps "explicit" token (SymbolDatabase reads it). We keep it.
        }
    }
}

void Tokenizer::simplifyVoidParameter() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "(" && tok->next && tok->next->str == "void" && tok->next->next == tok->link && tok->previous && tok->previous->isName()) {
            list.deleteNext(tok);
        }
    }
}

void Tokenizer::simplifyVarDecl(Token *tokBegin, const Token *tokEnd, bool only_k_r_fpar) {
    (void)only_k_r_fpar;
    // Split up variable declarations: "int a , b ;" -> "int a ; int b ;" and "int a = 1 ;" -> "int a ; a = 1 ;"
    for (Token *tok = tokBegin; tok && tok != tokEnd; tok = tok->next) {
        // skip class/struct/union bodies? no - member declarations also split
        if (tok->str == "(" && tok->link) {
            // for-loop init: handled specially
            if (tok->previous && tok->previous->str == "for") {
                // split "int a = 0 , b = 0" inside for? keep
                tok = tok->link;
                continue;
            }
            tok = tok->link; continue;
        }
        if (tok->str == "[" && tok->link) { tok = tok->link; continue; }
        // statement start?
        if (!(tok->previous == nullptr || tok->previous->str == ";" || tok->previous->str == "{" || tok->previous->str == "}" || tok->previous->str == ":" || tok->previous->str == "public" || tok->previous->str == "private" || tok->previous->str == "protected"))
            continue;
        Token *type0 = tok;
        if (type0->str == "typedef" || type0->str == "return" || type0->str == "using" || type0->str == "goto" || type0->str == "case" || type0->str == "throw" || type0->str == "delete" || type0->str == "else" || type0->str == "do" || type0->str == "try") continue;
        // skip keywords that are not part of a type
        Token *tok2 = type0;
        bool isconst = false, isstatic = false;
        while (tok2 && (tok2->str == "const" || tok2->str == "static" || tok2->str == "extern" || tok2->str == "mutable" || tok2->str == "struct" || tok2->str == "union" || tok2->str == "enum" || tok2->str == "class" || tok2->str == "unsigned" || tok2->str == "signed" || tok2->str == "long" || tok2->str == "short")) {
            if (tok2->str == "const") isconst = true;
            if (tok2->str == "static") isstatic = true;
            tok2 = tok2->next;
        }
        (void)isconst; (void)isstatic;
        if (!tok2 || !tok2->isName() || tok2->isKeyword()) {
            if (!(tok2 && tok2->isName() && (tok2->isStandardType() || tok2->str == "auto"))) continue;
        }
        if (tok2->str == "return" || tok2->str == "if" || tok2->str == "while" || tok2->str == "for" || tok2->str == "switch" || tok2->str == "sizeof" || tok2->str == "new" || tok2->str == "typedef" || tok2->str == "namespace" || tok2->str == "using" || tok2->str == "template" || tok2->str == "operator" || tok2->str == "virtual" || tok2->str == "explicit" || tok2->str == "friend" || tok2->str == "public" || tok2->str == "private" || tok2->str == "protected" || tok2->str == "case" || tok2->str == "default" || tok2->str == "goto" || tok2->str == "break" || tok2->str == "continue" || tok2->str == "throw" || tok2->str == "delete" || tok2->str == "asm") continue;
        // type name with :: and templates
        Token *typeEnd = tok2;
        while (typeEnd) {
            if (typeEnd->str == "::" && typeEnd->next && typeEnd->next->isName()) { typeEnd = typeEnd->next; continue; }
            if (typeEnd->next && typeEnd->next->str == "::" && typeEnd->next->next && typeEnd->next->next->isName()) { typeEnd = typeEnd->next->next; continue; }
            if (typeEnd->next && typeEnd->next->str == "<" && typeEnd->next->link) { typeEnd = typeEnd->next->link; continue; }
            break;
        }
        // another type word (e.g. "unsigned int", "long long", "const")
        Token *t = typeEnd->next;
        while (t && t->isName() && (t->isStandardType() || t->str == "const" || t->str == "unsigned" || t->str == "signed") && t->next && !(t->next->str == "(" ) ) { typeEnd = t; t = t->next; }
        // pointers/refs
        Token *varTok = typeEnd->next;
        while (varTok && (varTok->str == "*" || varTok->str == "&" || varTok->str == "&&" || varTok->str == "const")) varTok = varTok->next;
        if (!varTok || !varTok->isName() || varTok->isKeyword()) continue;
        if (varTok == tok2) continue; // no type
        // varTok must be followed by "=", ",", ";", "[", "(" (constructor init), "{"
        Token *after = varTok->next;
        // array dims
        while (after && after->str == "[" && after->link) after = after->link->next;
        if (!after) continue;
        if (after->str == "(" && after->link && after->link->next && (after->link->next->str == "{" || after->link->next->str == ";" || after->link->next->str == "const")) continue; // function
        if (after->str == "(" ) continue; // constructor call or function decl: skip
        if (after->str == ":" ) continue; // bitfield
        if (after->str == "{" && after->link) {
            // brace init: int x{1}; -> keep
            continue;
        }
        if (after->str != "=" && after->str != "," && after->str != ";") continue;
        // Now handle: if "=" -> find end of initializer (',' at depth 0 or ';')
        // Collect declarators
        Token *typeStart = type0;
        Token *typeStop = varTok->previous; // last token of type (incl. pointer)
        // for the first declarator: handle "=" split
        Token *declVar = varTok;
        bool first = true;
        while (declVar) {
            Token *afterVar = declVar->next;
            while (afterVar && afterVar->str == "[" && afterVar->link) afterVar = afterVar->link->next;
            if (!afterVar) break;
            if (afterVar->str == "=") {
                // find end of initializer
                Token *e = afterVar->next;
                int depth = 0;
                while (e) {
                    if ((e->str == "(" || e->str == "[" || e->str == "{") && e->link) { e = e->link->next; continue; }
                    if (e->str == "<" && e->link) { e = e->link->next; continue; }
                    if (e->str == ";" ) break;
                    if (e->str == "," && depth == 0) break;
                    e = e->next;
                }
                if (!e) break;
                bool braceInit = afterVar->next && afterVar->next->str == "{";
                if (!braceInit && afterVar->next != e) {
                    // split: "T x = init ;" -> "T x ; x = init ;"
                    // insert "; x" before "="
                    Token *semi = list.insertToken(declVar->previous ? (afterVar->previous) : afterVar->previous, ";");
                    semi->linenr = afterVar->linenr; semi->column = afterVar->column;
                    Token *nameCopy = list.insertToken(semi, declVar->str);
                    nameCopy->linenr = declVar->linenr; nameCopy->column = declVar->column;
                    afterVar->isSplittedVarDeclEq = true;
                    // the array dims stay with declaration
                }
                if (e->str == ";") break;
                // e is ","
                Token *comma = e;
                comma->str = ";";
                comma->tokType = Token::eOp;
                // insert type copy after comma
                Token *ins = comma;
                for (Token *tt = typeStart; tt && tt != typeStop->next; tt = tt->next) {
                    if (tt->str == "static" || tt->str == "extern") { /* keep for each */ }
                    ins = list.insertToken(ins, tt->str);
                    ins->linenr = tt->linenr; ins->column = tt->column;
                    ins->isStandardType_ = tt->isStandardType_;
                    ins->tokType = tt->tokType;
                    ins->isUnsigned = tt->isUnsigned; ins->isSigned = tt->isSigned; ins->isLong = tt->isLong;
                }
                declVar = ins->next;
                // pointer marks "*" may belong to each declarator: "int *a, b" -> b is int; "int *a, *b"
                // if the declarator itself begins with "*", type copy above includes "*" from the first; fix by removing it
                {
                    // remove trailing * / & copied from first declarator type (they belong to first var)
                    Token *chk = ins;
                    while (chk && (chk->str == "*" || chk->str == "&" || chk->str == "&&")) { Token *p = chk->previous; list.deleteToken(chk); chk = p; }
                }
                declVar = comma->next;
                while (declVar && declVar->isName() && declVar->next && (declVar->next->isName() || declVar->next->str == "::" || declVar->next->str == "<")) {
                    if (declVar->next->str == "<" && declVar->next->link) { declVar = declVar->next->link->next; continue; }
                    declVar = declVar->next;
                }
                while (declVar && (declVar->str == "*" || declVar->str == "&" || declVar->str == "&&" || declVar->str == "const")) declVar = declVar->next;
                if (!declVar || !declVar->isName()) break;
                first = false;
                continue;
            }
            if (afterVar->str == ",") {
                Token *comma = afterVar;
                comma->str = ";";
                comma->tokType = Token::eOp;
                Token *ins = comma;
                for (Token *tt = typeStart; tt && tt != typeStop->next; tt = tt->next) {
                    ins = list.insertToken(ins, tt->str);
                    ins->linenr = tt->linenr; ins->column = tt->column;
                    ins->isStandardType_ = tt->isStandardType_;
                    ins->tokType = tt->tokType;
                    ins->isUnsigned = tt->isUnsigned; ins->isSigned = tt->isSigned; ins->isLong = tt->isLong;
                }
                {
                    Token *chk = ins;
                    while (chk && (chk->str == "*" || chk->str == "&" || chk->str == "&&")) { Token *p = chk->previous; list.deleteToken(chk); chk = p; }
                }
                declVar = comma->next;
                while (declVar && declVar->isName() && declVar->next && (declVar->next->isName() || declVar->next->str == "::" || declVar->next->str == "<")) {
                    if (declVar->next->str == "<" && declVar->next->link) { declVar = declVar->next->link->next; continue; }
                    declVar = declVar->next;
                }
                while (declVar && (declVar->str == "*" || declVar->str == "&" || declVar->str == "&&" || declVar->str == "const")) declVar = declVar->next;
                if (!declVar || !declVar->isName()) break;
                first = false;
                continue;
            }
            break;
        }
        (void)first;
    }
}

void Tokenizer::simplifyStaticConst() {
    // "const static int x" -> "static const int x"; also "int static x" etc. (simplified)
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "const" && tok->next && tok->next->str == "static") {
            tok->str = "static"; tok->next->str = "const";
        }
    }
}

void Tokenizer::simplifyAddBraces() {
    for (Token *tok = list.front(); tok; ) {
        Token *tokRet = simplifyAddBracesToCommand(tok);
        if (!tokRet) break;
        tok = tokRet->next;
    }
}

Token *Tokenizer::simplifyAddBracesToCommand(Token *tok) {
    Token *tokEnd = tok;
    if (tok->str == "for" || tok->str == "switch" || tok->str == "BOOST_FOREACH") {
        tokEnd = simplifyAddBracesPair(tok, true);
    } else if (tok->str == "while") {
        Token *tokPossibleDo = tok->previous;
        if (tokPossibleDo && tokPossibleDo->str == "{") tokPossibleDo = nullptr;
        else if (tokPossibleDo && tokPossibleDo->str == "}") tokPossibleDo = tokPossibleDo->link;
        if (!tokPossibleDo || tokPossibleDo->strAt(-1) != "do")
            tokEnd = simplifyAddBracesPair(tok, true);
    } else if (tok->str == "do") {
        tokEnd = simplifyAddBracesPair(tok, false);
        if (tokEnd != tok) {
            // walk on to next token, i.e. "while"
            // such that simplifyAddBracesPair does not close other braces
            // before the "while"
            if (tokEnd) {
                tokEnd = tokEnd->next;
                if (!tokEnd || tokEnd->str != "while") // no while
                    syntaxError(tok);
            }
        }
    } else if (tok->str == "if" && !(tok->previous && tok->previous->str == "#")) {
        tokEnd = simplifyAddBracesPair(tok, true);
        if (!tokEnd) return nullptr;
        if (tokEnd->strAt(1) == "else") {
            Token *tokEndNextNext = tokEnd->tokAt(2);
            if (!tokEndNextNext || tokEndNextNext->str == "}") syntaxError(tokEndNextNext);
            if (tokEndNextNext->str == "if") // do not change "else if ..." to "else { if ... }"
                tokEnd = simplifyAddBracesToCommand(tokEndNextNext);
            else
                tokEnd = simplifyAddBracesPair(tokEnd->next, false);
        }
    }
    return tokEnd;
}

Token *Tokenizer::simplifyAddBracesPair(Token *tok, bool commandWithCondition) {
    Token *tokCondition = tok->next;
    if (!tokCondition) return tok; // Missing condition
    Token *tokAfterCondition = tokCondition;
    if (commandWithCondition) {
        if (tokCondition->str == "(") tokAfterCondition = tokCondition->link;
        else syntaxError(tok);
        if (!tokAfterCondition || tokAfterCondition->strAt(1) == "]") syntaxError(tok);
        tokAfterCondition = tokAfterCondition->next;
        if (!tokAfterCondition || tokAfterCondition->str == ")" || tokAfterCondition->str == "]" || tokAfterCondition->str == ",") syntaxError(tokAfterCondition);
    }
    Token *tokBracesEnd = nullptr;
    if (tokAfterCondition->str == "{") {
        tokBracesEnd = tokAfterCondition->link;
    } else if (tokAfterCondition->str == ";") {
        // No tokens in braces
        tokAfterCondition->str = "{";
        tokAfterCondition->tokType = Token::eBracket;
        tokBracesEnd = list.insertToken(tokAfterCondition, "}");
        tokBracesEnd->linenr = tokAfterCondition->linenr; tokBracesEnd->column = tokAfterCondition->column;
        tokAfterCondition->link = tokBracesEnd; tokBracesEnd->link = tokAfterCondition;
    } else {
        Token *tokEnd = simplifyAddBracesToCommand(tokAfterCondition);
        if (!tokEnd) return nullptr;
        if (tokEnd->str != "}") {
            // Not a "}" - search for the next ";"
            while (tokEnd && tokEnd->str != ";") {
                if (tokEnd->str == "(" || tokEnd->str == "[" || tokEnd->str == "{") { if (!tokEnd->link) syntaxError(tokEnd); tokEnd = tokEnd->link; }
                tokEnd = tokEnd->next;
            }
            if (!tokEnd) syntaxError(tok);
        }
        Token *openBrace = list.insertToken(tokAfterCondition->previous, "{");
        openBrace->linenr = tokAfterCondition->linenr; openBrace->column = tokAfterCondition->column;
        tokBracesEnd = list.insertToken(tokEnd, "}");
        tokBracesEnd->linenr = tokEnd->linenr; tokBracesEnd->column = tokEnd->column;
        openBrace->link = tokBracesEnd; tokBracesEnd->link = openBrace;
    }
    return tokBracesEnd;
}

void Tokenizer::elseif() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str != "else" || !tok->next || tok->next->str != "if") continue;
        Token *ifTok = tok->next;
        // find end of if statement (including else chains)
        Token *end = ifTok->next; // "("
        if (!end || end->str != "(" || !end->link) continue;
        end = end->link->next; // "{"
        if (!end || end->str != "{" || !end->link) continue;
        end = end->link;
        while (end->next && end->next->str == "else") {
            Token *e = end->next->next;
            if (e && e->str == "if") { e = e->next; if (!e || !e->link) break; e = e->link->next; }
            if (!e || e->str != "{" || !e->link) break;
            end = e->link;
        }
        Token *openBrace = list.insertToken(tok, "{");
        openBrace->linenr = ifTok->linenr; openBrace->column = ifTok->column;
        Token *closeBrace = list.insertToken(end, "}");
        closeBrace->linenr = end->linenr; closeBrace->column = end->column;
        openBrace->link = closeBrace; closeBrace->link = openBrace;
    }
}

void Tokenizer::simplifyLabelsCaseDefault() {
    int executableScope = 0;
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "{" && tok->link) {
            if (tok->previous && (tok->previous->str == ")" || tok->previous->str == "else" || tok->previous->str == "do" || tok->previous->str == "try" || tok->previous->str == ";" || tok->previous->str == "{" || tok->previous->str == "}")) {
                if (executableScope > 0 || (tok->previous->str == ")")) { ++executableScope; }
                else continue;
            } else if (executableScope > 0) ++executableScope;
            continue;
        }
        if (tok->str == "}" && executableScope > 0) { --executableScope; continue; }
        if (executableScope == 0) continue;
        if (tok->str == "case" || tok->str == "default") {
            Token *t = tok->next;
            while (t && t->str != ":" && t->str != ";" && t->str != "{" && t->str != "}") {
                if (t->str == "(" && t->link) t = t->link;
                t = t->next;
            }
            if (t && t->str == ":") {
                if (!(t->next && t->next->str == ";")) {
                    Token *s = list.insertToken(t, ";");
                    s->linenr = t->linenr; s->column = t->column;
                }
                tok = t;
            }
        } else if (tok->isName() && tok->next && tok->next->str == ":" && tok->previous && (tok->previous->str == ";" || tok->previous->str == "{" || tok->previous->str == "}") && !(tok->next->next && tok->next->next->str == ":")) {
            // label
            if (!(tok->next->next && tok->next->next->str == ";")) {
                Token *s = list.insertToken(tok->next, ";");
                s->linenr = tok->linenr; s->column = tok->column;
            }
        }
    }
}

void Tokenizer::simplifyStructDecl() {
    unsigned count = 0;
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (!(tok->str == "struct" || tok->str == "union" || tok->str == "class" || tok->str == "enum")) continue;
        if (tok->previous && (tok->previous->str == "friend" || tok->previous->str == "typedef")) continue;
        Token *nameTok = tok->next;
        bool anonymous = false;
        if (nameTok && nameTok->str == "class" && tok->str == "enum") nameTok = nameTok->next; // enum class
        if (!nameTok) break;
        if (nameTok->str == "{") {
            anonymous = true;
            // insert a name
            Token *ins = list.insertToken(tok, "Anonymous" + std::to_string(count++));
            ins->linenr = tok->linenr; ins->column = tok->column;
            nameTok = ins;
        }
        Token *bodyStart = nameTok->next;
        // enum with underlying type
        if (bodyStart && bodyStart->str == ":" ) {
            while (bodyStart && bodyStart->str != "{" && bodyStart->str != ";") bodyStart = bodyStart->next;
        }
        if (!bodyStart || bodyStart->str != "{" || !bodyStart->link) {
            if (anonymous) { /* struct without body?? */ }
            continue;
        }
        Token *bodyEnd = bodyStart->link;
        Token *after = bodyEnd->next;
        if (!after) break;
        if (after->str == ";" ) continue;
        if (after->str == ":" || after->str == "{") continue;
        // "struct S { } s ;" -> "struct S { } ; struct S s ;"
        if (after->isName() || after->str == "*" || after->str == "&") {
            Token *semi = list.insertToken(bodyEnd, ";");
            semi->linenr = bodyEnd->linenr; semi->column = bodyEnd->column;
            Token *ins = semi;
            if (tok->str != "enum" || true) {
                Token *kw = list.insertToken(ins, tok->str);
                kw->linenr = after->linenr; kw->column = after->column;
                ins = kw;
            }
            Token *nm = list.insertToken(ins, nameTok->str);
            nm->linenr = after->linenr; nm->column = after->column;
            tok = nm;
        }
    }
}

void Tokenizer::simplifyTypedef() {
    // Simple typedef handling: "typedef <type tokens> name ;" and "typedef struct X {...} name ;" and "typedef struct {...} name ;"
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str != "typedef") continue;
        if (tok->previous && tok->previous->str != ";" && tok->previous->str != "{" && tok->previous->str != "}") { continue; }
        Token *start = tok->next;
        if (!start) break;
        // find terminating ';' at depth 0
        Token *end = start;
        while (end && end->str != ";") {
            if ((end->str == "{" || end->str == "(" || end->str == "[") && end->link) end = end->link;
            end = end->next;
        }
        if (!end) break;
        // function pointer typedef: typedef ret (*name)(args);
        Token *nameTok = nullptr;
        bool funcPtr = false;
        for (Token *t = start; t && t != end; t = t->next) {
            if (t->str == "(" && t->next && t->next->str == "*" && t->next->next && t->next->next->isName() && t->next->next->next && t->next->next->next->str == ")") {
                nameTok = t->next->next; funcPtr = true; break;
            }
        }
        if (funcPtr) {
            // replace uses: name -> (keep as is, mark as type) ; cppcheck replaces with the full pointer type. Simplify: remove typedef, remember name
            typedefNames.push_back(nameTok->str);
            Token *prev = tok->previous;
            list.eraseTokens(tok, end->next);
            list.deleteToken(tok);
            tok = prev ? prev : list.front();
            if (!tok) break;
            continue;
        }
        nameTok = end->previous;
        // array typedef: typedef int arr[10];
        std::vector<Token*> arrayDims;
        while (nameTok && nameTok->str == "]" && nameTok->link) { arrayDims.insert(arrayDims.begin(), nameTok->link); nameTok = nameTok->link->previous; }
        if (!nameTok || !nameTok->isName() || nameTok == start) { continue; }
        // struct/union/enum with body
        Token *bodyStart = nullptr;
        for (Token *t = start; t && t != nameTok; t = t->next) {
            if (t->str == "{" && t->link) { bodyStart = t; break; }
        }
        std::string typeName = nameTok->str;
        std::vector<Token*> typeTokens; // tokens between start and nameTok (exclusive), excluding body
        if (bodyStart) {
            // typedef struct [X] { ... } name ;
            Token *kw = start;
            if (!(kw->str == "struct" || kw->str == "union" || kw->str == "enum" || kw->str == "class")) continue;
            Token *tagTok = kw->next;
            std::string tag;
            if (tagTok->str == "{") {
                // anonymous: use typedef name as tag
                tag = typeName;
                Token *ins = list.insertToken(kw, typeName);
                ins->linenr = nameTok->linenr; ins->column = nameTok->column;
            } else {
                tag = tagTok->str;
            }
            // remove "typedef" and " name" after body: keep "struct tag {...} ;"
            Token *bodyEnd = bodyStart->link;
            // delete tokens between bodyEnd and end (the name and dims)
            list.eraseTokens(bodyEnd, end); // end is ';' kept
            // remove typedef token
            Token *prev = tok->previous;
            list.deleteToken(tok);
            // replacement for uses: "struct tag"
            for (Token *t = (prev ? prev->next : list.front()); t; t = t->next) {
                if (t == kw) { t = bodyEnd; continue; }
                if (t->str == typeName && t->isName() && !(t->previous && (t->previous->str == "struct" || t->previous->str == "union" || t->previous->str == "enum" || t->previous->str == "." || t->previous->str == "->" ))) {
                    // don't replace if this is a variable declaration of the same name (rare)
                    if (tag == typeName) {
                        // insert keyword before
                        Token *k2 = list.insertToken(t->previous ? t->previous : t, kw->str);
                        if (!t->previous || k2 == t) { /* front */ }
                        k2->linenr = t->linenr; k2->column = t->column;
                        if (k2->next != t) { /* inserted after t? */ }
                    } else {
                        t->str = tag;
                        Token *k2 = list.insertToken(t->previous, kw->str);
                        k2->linenr = t->linenr; k2->column = t->column;
                    }
                    t->originalName = typeName;
                    for (Token *d : arrayDims) {
                        // array typedef: add dims after variable name
                        Token *varName = t->next;
                        while (varName && (varName->str == "*" || varName->str == "&")) varName = varName->next;
                        if (varName && varName->isName()) {
                            Token *ins = varName;
                            for (Token *dt = d; dt && dt != d->link->next; dt = dt->next) { ins = list.insertToken(ins, dt->str); }
                        }
                    }
                }
            }
            tok = prev ? prev : list.front();
            if (!tok) break;
            continue;
        }
        for (Token *t = start; t && t != nameTok; t = t->next) typeTokens.push_back(t);
        if (typeTokens.empty()) continue;
        // copy the type token strings
        std::vector<Token> typeCopies;
        for (Token *t : typeTokens) typeCopies.push_back(*t);
        std::vector<std::string> dimStrs;
        for (Token *d : arrayDims) { std::string s; for (Token *dt = d; dt && dt != d->link->next; dt = dt->next) { s += dt->str; s += " "; } dimStrs.push_back(s); }
        Token *prev = tok->previous;
        Token *afterEnd = end->next;
        list.eraseTokens(tok, afterEnd);
        list.deleteToken(tok);
        typedefNames.push_back(typeName);
        // replace uses
        for (Token *t = (prev ? prev->next : list.front()); t; t = t->next) {
            if (t->str != typeName || !t->isName()) continue;
            if (t->previous && (t->previous->str == "." || t->previous->str == "->" || t->previous->str == "struct" || t->previous->str == "union" || t->previous->str == "enum" || t->previous->str == "class" || t->previous->str == "typedef" || t->previous->str == "goto")) continue;
            // if this is a declaration of a variable/function with the same name... skip heuristics
            if (t->next && (t->next->str == "=" || t->next->str == "[" ) && t->previous && (t->previous->isName() || t->previous->str == "*")) continue;
            // replace t with type tokens
            Token *ins = t->previous;
            Token *firstIns = nullptr;
            for (size_t k = 0; k < typeCopies.size(); ++k) {
                const Token &c = typeCopies[k];
                Token *n;
                if (ins) n = list.insertToken(ins, c.str);
                else { // front
                    n = list.insertToken(t, c.str); // temporarily after t; we will move t
                    // simpler: put after t then swap strings
                }
                n->linenr = t->linenr; n->column = t->column;
                n->tokType = c.tokType; n->isStandardType_ = c.isStandardType_;
                n->isUnsigned = c.isUnsigned; n->isSigned = c.isSigned; n->isLong = c.isLong;
                n->originalName = typeName;
                if (!firstIns) firstIns = n;
                ins = n;
            }
            // array dims: append after the variable name following
            if (!dimStrs.empty()) {
                Token *varName = t->next;
                while (varName && (varName->str == "*" || varName->str == "&")) varName = varName->next;
                if (varName && varName->isName()) {
                    Token *ins2 = varName;
                    for (const std::string &ds : dimStrs) {
                        std::string::size_type p = 0;
                        while (p < ds.size()) {
                            std::string::size_type sp = ds.find(' ', p);
                            std::string w = ds.substr(p, sp - p);
                            if (!w.empty()) { ins2 = list.insertToken(ins2, w); }
                            p = sp + 1;
                        }
                    }
                }
            }
            Token *nextTok = ins->next == t ? t->next : t->next;
            Token *resume = ins;
            if (!t->previous || firstIns == nullptr) { }
            list.deleteToken(t);
            t = resume;
            (void)nextTok;
        }
        // relink brackets inserted
        tok = prev ? prev : list.front();
        if (!tok) break;
    }
}

void Tokenizer::arraySize() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (!(tok->isName() && tok->next && tok->next->str == "[" && tok->next->next && tok->next->next->str == "]")) continue;
        if (!tok->previous || !(tok->previous->isName() || tok->previous->str == "*" || tok->previous->str == "&")) continue;
        Token *closeBracket = tok->next->next;
        Token *eq = closeBracket->next;
        if (!eq || eq->str != "=") continue;
        Token *init = eq->next;
        if (!init) continue;
        if (init->tokType == Token::eString) {
            // count chars
            const std::string &s = init->str;
            std::string::size_type q = s.find('"');
            std::string inner = s.substr(q + 1, s.size() - q - 2);
            size_t len = 0;
            for (size_t i = 0; i < inner.size(); ++i) {
                if (inner[i] == '\\') {
                    ++i;
                    if (i < inner.size() && inner[i] == 'x') { ++i; while (i < inner.size() && isxdigit((unsigned char)inner[i])) ++i; --i; }
                    else if (i < inner.size() && inner[i] >= '0' && inner[i] <= '7') { size_t j = i; while (j < inner.size() && j < i + 3 && inner[j] >= '0' && inner[j] <= '7') ++j; i = j - 1; }
                }
                ++len;
            }
            Token *sz = list.insertToken(tok->next, std::to_string(len + 1));
            sz->linenr = tok->next->linenr; sz->column = tok->next->column;
            continue;
        }
        if (init->str == "{" && init->link) {
            // count elements at depth 0
            size_t count = 0;
            Token *t = init->next;
            if (t == init->link) { continue; }
            count = 1;
            for (; t && t != init->link; t = t->next) {
                if ((t->str == "{" || t->str == "(" || t->str == "[") && t->link) { t = t->link; continue; }
                if (t->str == ",") { if (t->next != init->link) ++count; }
            }
            Token *sz = list.insertToken(tok->next, std::to_string(count));
            sz->linenr = tok->next->linenr; sz->column = tok->next->column;
        }
    }
}

void Tokenizer::sizeofAddParentheses() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str != "sizeof" || !tok->next) continue;
        if (tok->next->str == "(") continue;
        if (tok->next->str == "...") continue;
        Token *end = tok->next;
        // sizeof x.y[3]->z
        while (end->next) {
            if (end->next->str == "." || end->next->str == "->" || end->next->str == "::") { end = end->next->next; if (!end) break; continue; }
            if ((end->next->str == "[" ) && end->next->link) { end = end->next->link; continue; }
            break;
        }
        if (!end) break;
        Token *open = list.insertToken(tok, "(");
        open->linenr = tok->linenr; open->column = tok->column;
        Token *close = list.insertToken(end, ")");
        close->linenr = end->linenr; close->column = end->column;
        open->link = close; close->link = open;
    }
}

void Tokenizer::simplifyOperatorName() {
    if (!isCPP()) return;
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str != "operator" || !tok->next) continue;
        std::string op;
        Token *t = tok->next;
        if (t->str == "(" && t->link && t->link->next && t->link->next->str == "(") {
            op = "()"; list.deleteNext(tok, 2);
        } else if (t->str == "[" && t->link) {
            op = "[]"; list.deleteNext(tok, 2);
        } else if (t->str == "new" || t->str == "delete") {
            op = t->str;
            list.deleteNext(tok);
            if (tok->next && tok->next->str == "[" && tok->next->link) { op += "[]"; list.deleteNext(tok, 2); }
        } else if (!t->isName() && t->str != "(") {
            while (tok->next && !tok->next->isName() && tok->next->str != "(") { op += tok->next->str; list.deleteNext(tok); }
        } else if (t->isName()) {
            // conversion operator: operator int()
            while (tok->next && tok->next->str != "(") { op += (op.empty() ? "" : " ") + tok->next->str; list.deleteNext(tok); }
        }
        if (!op.empty()) { tok->str = "operator" + op; tok->isOperatorKeyword = true; tok->tokType = Token::eName; }
    }
}

void Tokenizer::simplifyAsm() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (!(tok->str == "asm" || tok->str == "__asm" || tok->str == "__asm__" || tok->str == "_asm")) continue;
        Token *t = tok->next;
        while (t && (t->str == "volatile" || t->str == "__volatile" || t->str == "__volatile__" || t->str == "inline" || t->str == "goto")) { list.deleteToken(t); t = tok->next; }
        if (t && t->str == "(" && t->link) {
            Token *end = t->link;
            list.eraseTokens(t, end);
            Token *s = list.insertToken(t, "\"\"");
            (void)s;
            tok->str = "asm";
            if (!end->next || end->next->str != ";") { Token *semi = list.insertToken(end, ";"); semi->linenr = end->linenr; semi->column = end->column; }
        } else if (t && t->str == "{" && t->link) {
            Token *end = t->link;
            list.eraseTokens(t, end);
            t->str = "("; t->tokType = Token::eBracket;
            end->str = ")"; end->tokType = Token::eBracket;
            list.insertToken(t, "\"\"");
            tok->str = "asm";
            if (!end->next || end->next->str != ";") { Token *semi = list.insertToken(end, ";"); semi->linenr = end->linenr; semi->column = end->column; }
        }
    }
}

void Tokenizer::removeRedundantSemicolons() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "(" && tok->link) { tok = tok->link; continue; }
        while (tok->str == "{" && tok->next && tok->next->str == ";" ) {
            // "{ ;" -> "{"
            if (tok->previous && (tok->previous->str == "=" || tok->previous->str == "," || tok->previous->str == "(" || tok->previous->str == "return")) break;
            list.deleteNext(tok);
        }
        while (tok->str == ";" && tok->next && tok->next->str == ";") list.deleteNext(tok);
        if (tok->str == "}" && tok->next && tok->next->str == ";" && tok->link && tok->link->previous && (tok->link->previous->str == ")" || tok->link->previous->str == "else" || tok->link->previous->str == "do" || tok->link->previous->str == "{" || tok->link->previous->str == "}" || tok->link->previous->str == ";")) {
            // "} ;" after a block statement -> remove ';' (not after class/struct/initializer)
            const Token *before = tok->link->previous;
            bool isBlock = false;
            if (before->str == ")" && before->link && before->link->previous && (before->link->previous->str == "if" || before->link->previous->str == "for" || before->link->previous->str == "while" || before->link->previous->str == "switch")) isBlock = true;
            if (before->str == "else" || before->str == "do") isBlock = true;
            if (before->str == "{" || before->str == "}" || before->str == ";") {
                // could be a function body end or nested block
                isBlock = true;
                // struct/initializer check: look backwards for '=' or 'struct' name
            }
            if (isBlock && !(before->str == "do")) {
                // ensure not "do { } while" - handled since do keeps
                list.deleteNext(tok);
            }
        }
    }
}

void Tokenizer::simplifyExternC() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "extern" && tok->next && tok->next->tokType == Token::eString) {
            Token *t = tok->next->next;
            if (t && t->str == "{" && t->link) {
                Token *end = t->link;
                for (Token *x = t->next; x && x != end; x = x->next) x->isExternC = true;
                list.deleteToken(end);
                Token *prev = tok->previous;
                list.deleteToken(t);
                list.deleteToken(tok->next);
                list.deleteToken(tok);
                tok = prev ? prev : list.front();
                if (!tok) break;
            } else {
                // extern "C" void f();
                if (t) t->isExternC = true;
                list.deleteNext(tok);
            }
        }
    }
}

