void Tokenizer::simplifyUsingToTypedef() {
    if (!isCPP()) return;
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "using" && tok->next && tok->next->isName() && tok->next->next && tok->next->next->str == "=") {
            // using X = type ; -> typedef type X ;
            Token *nameTok = tok->next;
            Token *eq = nameTok->next;
            Token *end = eq;
            while (end && end->str != ";") { if ((end->str == "(" || end->str == "<" || end->str == "[") && end->link) end = end->link; end = end->next; }
            if (!end) break;
            tok->str = "typedef";
            std::string name = nameTok->str;
            list.deleteToken(eq);
            list.deleteToken(nameTok);
            Token *n = list.insertToken(end->previous, name);
            n->linenr = tok->linenr; n->column = tok->column;
        }
    }
}

