void Tokenizer::removeMacrosInGlobalScope() {
    // Remove uppercase macro names before declarations at global scope: e.g. "EXPORT int f();" -> "int f();"
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "(" && tok->link) { tok = tok->link; continue; }
        if (tok->str == "{" && tok->link) { tok = tok->link; continue; }
        if (!tok->isName() || tok->isKeyword() || tok->isStandardType()) continue;
        if (tok->previous && !(tok->previous->str == ";" || tok->previous->str == "}" )) continue;
        // all uppercase name followed by a name (type) or by "(" ... ")" followed by name
        bool upper = true;
        for (char c : tok->str) if (!(isupper((unsigned char)c) || c == '_' || isdigit((unsigned char)c))) { upper = false; break; }
        if (!upper) continue;
        Token *next = tok->next;
        if (next && next->str == "(" && next->link) {
            Token *after = next->link->next;
            if (after && (after->isName() && !after->isKeyword()) && after->next && (after->next->isName() || after->next->str == "*")) {
                // MACRO(...) type name
                Token *prev = tok->previous;
                list.eraseTokens(tok, after);
                list.deleteToken(tok);
                tok = prev ? prev : list.front();
                if (!tok) break;
            }
            continue;
        }
        if (next && next->isName() && (next->isStandardType() || next->str == "struct" || next->str == "class" || next->str == "static" || next->str == "const" || next->str == "void" || next->str == "typedef" || next->str == "extern")) {
            // MACRO type ...
            if (tok->previous == nullptr || tok->previous->str == ";" || tok->previous->str == "}") {
                Token *prev = tok->previous;
                list.deleteToken(tok);
                tok = prev ? prev : list.front();
                if (!tok) break;
            }
        }
    }
}

