void Tokenizer::simplifyEmptyNamespaces() {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "namespace" && tok->next && tok->next->isName() && tok->next->next && tok->next->next->str == "{" && tok->next->next->next == tok->next->next->link) {
            Token *prev = tok->previous;
            list.eraseTokens(tok, tok->next->next->link->next);
            list.deleteToken(tok);
            tok = prev ? prev : list.front();
            if (!tok) break;
        }
    }
}

