void Tokenizer::reportUnknownMacros() {
    // Detect "MACRO(x) { ... }" style patterns at global scope that cannot be valid C/C++
    for (const Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "{" && tok->link) {
            const Token *prev = tok->previous;
            if (!prev) continue;
            if (prev->str == ")" && prev->link) {
                const Token *before = prev->link->previous;
                if (before && before->isName() && !before->isKeyword() && before->previous && (before->previous->str == ")" ) && before->previous->link) {
                    // "f(x) MACRO(y) {" -> unknown macro  (unless MACRO is e.g. const)
                }
            }
        }
        // "%name% %name% (" at statement start where first is uppercase and second is a known function-like structure? skip
    }
}

void Tokenizer::findGarbageCode() {
    // Some basic checks resembling cppcheck's findGarbageCode
    for (const Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "if" || tok->str == "while" || tok->str == "for" || tok->str == "switch") {
            if (!tok->next || tok->next->str != "(") {
                if (tok->previous && tok->previous->str == "#") continue;
                // "else if" handled; "if" must be followed by "("
                if (tok->str == "if" && tok->previous && tok->previous->str == "else") {}
                if (!tok->next || tok->next->str != "(") syntaxError(tok);
            }
        }
        if (tok->str == "else" && tok->next && (tok->next->str == ";" || tok->next->str == ")" || tok->next->str == "}")) syntaxError(tok);
        if (tok->str == "return" && tok->next && (tok->next->str == ")" || tok->next->str == "}" || tok->next->str == "]")) syntaxError(tok);
        if ((tok->str == ";" ) && tok->previous && tok->previous->str == "(" ) {
            // "( ;" - for loop ok
            if (!(tok->previous->previous && tok->previous->previous->str == "for")) syntaxError(tok);
        }
        if (tok->str == "(" && tok->link && tok->link->previous == tok && tok->previous && tok->previous->str == "for") syntaxError(tok);
        if (tok->isOp() && tok->next && tok->next->isOp() && !tok->isAssignmentOp() && tok->str != "(" ) {
            const std::string &a = tok->str, &b = tok->next->str;
            // consecutive binary operators like "+ *" are ok (unary), but "== ==", "&& ||" are not
            bool aBin = (a == "==" || a == "!=" || a == "<=" || a == ">=" || a == "&&" || a == "||" || a == "/" || a == "%" || a == "^" || a == "|" || a == "<<" || a == ">>" || a == "?" || a == ",");
            bool bBin = (b == "==" || b == "!=" || b == "<=" || b == ">=" || b == "&&" || b == "||" || b == "/" || b == "%" || b == "^" || b == "|" || b == "<<" || b == ">>" || b == "?" || b == "," || b == "=" || b == ")" || b == "]" || b == ";");
            if (aBin && bBin && !(b == ")" && a == ",") ) {
                if (!(a == "," && (b == ")" || b == "]"))) syntaxError(tok->next);
            }
        }
    }
}

