void Tokenizer::checkSyntax() {
    findGarbageCode();
}

// ---------------------------------------------------------------------------
// setVarId
// ---------------------------------------------------------------------------
namespace {
struct VarScope {
    std::map<std::string, unsigned> vars;
    bool isClass = false;
    bool isExecutable = false;
    std::string className;
};
}

static bool isTypeKeyword(const std::string &s) {
    return s == "const" || s == "static" || s == "extern" || s == "mutable" || s == "struct" || s == "union" || s == "enum" || s == "class" || s == "unsigned" || s == "signed" || s == "long" || s == "short" || s == "typename" || s == "volatile" || s == "auto" || s == "register";
}

// Determine if tokens starting at tok form a variable declaration. Returns the name token, or nullptr.
static Token *getVarDeclName(Token *tok, bool cpp, const std::set<std::string> &knownTypes, bool inFunctionArgs, bool &isFunctionArgList) {
    isFunctionArgList = false;
    Token *t = tok;
    bool hasType = false;
    bool hasKeywordType = false;
    bool structKw = false;
    while (t && t->isName() && isTypeKeyword(t->str)) {
        if (t->str == "struct" || t->str == "union" || t->str == "enum" || t->str == "class") structKw = true;
        if (t->str == "unsigned" || t->str == "signed" || t->str == "long" || t->str == "short" || t->str == "auto") hasKeywordType = true;
        t = t->next;
    }
    if (!t) return nullptr;
    if (t->isName() && !t->isKeyword()) {
        if (t->str == "return" || t->str == "goto" || t->str == "sizeof" || t->str == "delete" || t->str == "new" || t->str == "throw" || t->str == "typedef" || t->str == "using" || t->str == "namespace" || t->str == "template" || t->str == "operator" || t->str == "case" || t->str == "default" || t->str == "break" || t->str == "continue" || t->str == "else" || t->str == "do" || t->str == "try" || t->str == "catch" || t->str == "virtual" || t->str == "explicit" || t->str == "friend" || t->str == "public" || t->str == "private" || t->str == "protected" || t->str == "asm") return nullptr;
        // type name (possibly qualified / template)
        Token *typeTok = t;
        if (typeTok->varId != 0 && !structKw) return nullptr; // it's a variable, not a type
        while (true) {
            if (typeTok->next && typeTok->next->str == "::" && typeTok->next->next && typeTok->next->next->isName()) { typeTok = typeTok->next->next; continue; }
            if (typeTok->next && typeTok->next->str == "<" && typeTok->next->link) { typeTok = typeTok->next->link; continue; }
            break;
        }
        hasType = true;
        t = typeTok->next;
        // additional standard type words e.g. "unsigned int", "long int", "long double"
        while (t && t->isName() && (t->isStandardType() || t->str == "const" || t->str == "unsigned" || t->str == "signed" || t->str == "long") && t->next && (t->next->isName() || t->next->str == "*" || t->next->str == "&")) { t = t->next; }
    } else if (t->isName() && t->isKeyword() && (t->str == "struct" || t->str == "union" || t->str == "class" || t->str == "enum")) {
        return nullptr;
    } else if (!hasKeywordType) {
        return nullptr;
    }
    if (!t) return nullptr;
    // pointer/reference
    while (t && (t->str == "*" || t->str == "&" || t->str == "&&" || t->str == "const" || t->str == "restrict")) t = t->next;
    if (!t) return nullptr;
    // function pointer: "( * name ) ("
    if (t->str == "(" && t->next && t->next->str == "*" && t->next->next && t->next->next->isName() && t->next->next->next && t->next->next->next->str == ")" && t->link && t->link->next && t->link->next->str == "(") {
        return t->next->next;
    }
    if (!t->isName() || t->isKeyword()) return nullptr;
    if (!hasType && !hasKeywordType) return nullptr;
    // must be followed by ; , = [ ) { ( : 
    Token *after = t->next;
    if (!after) return nullptr;
    while (after->str == "[" && after->link) after = after->link->next;
    if (!after) return nullptr;
    if (after->str == ";" || after->str == "," || after->str == "=" || after->str == ")" || after->str == "{" || after->str == ":" || after->str == "}") {
        if (after->str == "{" ) {
            // could be a function body ("int f {" invalid) or brace init "int x{1}"; brace init is a var
            if (!cpp) return nullptr;
        }
        if (after->str == ":" && !inFunctionArgs) {
            // bitfield "int x : 3" or range for "auto x : v"
            if (!(after->next && (after->next->isNumber() || after->next->isName()))) return nullptr;
        }
        if (after->str == ")" && !inFunctionArgs) {
            // "(int x)" cast? treat as not a declaration unless inside function args
            return nullptr;
        }
        if (after->str == "}" ) return nullptr;
        return t;
    }
    if (after->str == "(" && after->link) {
        // function declaration/definition or constructor-style init "int x(5)"
        Token *afterParen = after->link->next;
        if (!cpp) return nullptr;
        if (afterParen && (afterParen->str == ";" || afterParen->str == ",")) {
            // "T x(args);" -> constructor init if args are not types
            Token *arg = after->next;
            if (arg == after->link) return nullptr; // "T x();" function declaration
            // if first arg looks like a type -> function
            if (arg->isName() && (arg->isStandardType() || knownTypes.count(arg->str) || arg->str == "const" || arg->str == "struct")) return nullptr;
            if (arg->isName() && arg->next && (arg->next->isName() || arg->next->str == "*" || arg->next->str == "&")) return nullptr;
            if (arg->isName() && arg->next && arg->next->str == "::") return nullptr;
            return t;
        }
        return nullptr;
    }
    return nullptr;
}

void Tokenizer::setVarId() {
    mVarId = 0;
    std::vector<VarScope> scopes;
    scopes.emplace_back();
    std::set<std::string> knownTypes;
    for (const std::string &s : typedefNames) knownTypes.insert(s);
    // collect struct/class names
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if ((tok->str == "struct" || tok->str == "class" || tok->str == "union" || tok->str == "enum") && tok->next && tok->next->isName()) {
            Token *n = tok->next;
            if (n->str == "class") n = n->next;
            if (n && n->isName()) knownTypes.insert(n->str);
        }
        if (tok->str == "typedef") {}
    }
    // class member variables: collect per class first so that member functions can refer to them
    std::map<std::string, std::map<std::string, unsigned>> classMembers;
    // first pass: assign ids
    std::vector<std::string> classStack;
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str == "{" && tok->link) {
            VarScope sc;
            const Token *prev = tok->previous;
            // class scope?
            const Token *classTok = nullptr;
            if (prev && prev->isName() && prev->previous && (prev->previous->str == "struct" || prev->previous->str == "class" || prev->previous->str == "union")) classTok = prev;
            else if (prev && prev->str == ":" ) {
                // inheritance: find "class X :"
                const Token *p = prev;
                while (p && p->str != "class" && p->str != "struct" && p->str != "{" && p->str != ";" && p->str != "}") p = p->previous;
                if (p && (p->str == "class" || p->str == "struct") && p->next) classTok = p->next;
            } else if (prev && prev->isName() && prev->previous && prev->previous->str == "enum") { sc.isClass = false; }
            if (classTok) { sc.isClass = true; sc.className = classTok->str; }
            else if (prev && (prev->str == ")" || prev->str == "else" || prev->str == "do" || prev->str == "try" || prev->str == ";" || prev->str == "{" || prev->str == "}" || prev->str == "const" || prev->str == "->" )) {
                // function body / block
                sc.isExecutable = true;
                if (prev->str == ")" && prev->link) {
                    // function definition: parameters were already handled as we encountered them
                }
            } else if (prev && prev->str == "namespace") sc.isExecutable = false;
            else if (prev && prev->isName() && prev->previous && prev->previous->str == "namespace") sc.isExecutable = false;
            else if (prev && prev->str == "=") { /* initializer list */ }
            if (sc.isClass) classStack.push_back(sc.className);
            // member function body in class: its enclosing class members should be visible -> they are, through scope chain
            scopes.push_back(sc);
            // For a function body whose definition is "Class :: f ( ... ) {" -> make class members visible
            if (sc.isExecutable && prev && prev->str == ")" && prev->link) {
                const Token *fname = prev->link->previous;
                if (fname && fname->isName() && fname->previous && fname->previous->str == "::" && fname->previous->previous && fname->previous->previous->isName()) {
                    const std::string cls = fname->previous->previous->str;
                    auto it = classMembers.find(cls);
                    if (it != classMembers.end()) {
                        VarScope &cur = scopes.back();
                        for (const auto &m : it->second) cur.vars.insert(m);
                    }
                }
            }
            continue;
        }
        if (tok->str == "}" && tok->link) {
            if (scopes.size() > 1) {
                if (scopes.back().isClass) { classMembers[scopes.back().className] = scopes.back().vars; classStack.pop_back(); }
                scopes.pop_back();
            }
            continue;
        }
        if (!tok->isName()) continue;
        // declaration?
        const Token *prev = tok->previous;
        bool stmtStart = (!prev || prev->str == ";" || prev->str == "{" || prev->str == "}" || prev->str == "(" || prev->str == "," || prev->str == ":" || (prev->str == ")" && false));
        // also "for ( int i" -> prev is "("
        bool inArgs = false;
        if (prev && (prev->str == "(" || prev->str == ",")) {
            // function parameter list? find the '('
            const Token *paren = prev;
            if (paren->str == ",") {
                int depth = 0;
                while (paren && !(paren->str == "(" && depth == 0)) {
                    if (paren->str == ")" ) ++depth;
                    else if (paren->str == "(" ) --depth;
                    paren = paren->previous;
                }
            }
            if (paren && paren->str == "(" && paren->previous && paren->previous->isName() && !paren->previous->isKeyword()) {
                // function (declaration or definition) or call
                const Token *afterParen = paren->link ? paren->link->next : nullptr;
                if (afterParen && (afterParen->str == "{" || afterParen->str == ";" || afterParen->str == "const" || afterParen->str == ":" || afterParen->str == "=" || afterParen->str == "override" || afterParen->str == "noexcept" || afterParen->str == "->"))
                    inArgs = true;
                if (paren->previous->str == "for" || paren->previous->str == "while" || paren->previous->str == "if" || paren->previous->str == "switch" || paren->previous->str == "catch") inArgs = (paren->previous->str == "catch");
                if (paren->previous->str == "operator" || paren->previous->isOperatorKeyword) inArgs = true;
            } else if (paren && paren->str == "(" && paren->previous && paren->previous->str == ">" ) {
                inArgs = true; // template function
            } else if (paren && paren->str == "(" && paren->previous && paren->previous->str == "operator") inArgs = true;
        }
        if (stmtStart || (prev && prev->str == "(" && prev->previous && (prev->previous->str == "for" || prev->previous->str == "catch")) ) {
            bool dummy;
            Token *nameTok = getVarDeclName(tok, isCPP(), knownTypes, inArgs, dummy);
            if (nameTok && (inArgs || prev == nullptr || prev->str != "(" || (prev->previous && (prev->previous->str == "for" || prev->previous->str == "catch")) || (prev->previous && prev->previous->str == "operator"))) {
                // don't treat function declaration "int f ( int x )" parameter as var at global scope? they are args -> yes vars
                // check for "else if" etc.
                if (prev && prev->str == "," && !inArgs) {
                    // comma separated declaration already split; could be function call args -> skip
                    nameTok = nullptr;
                }
                if (nameTok) {
                    // class member?
                    bool isMember = scopes.back().isClass;
                    unsigned id = ++mVarId;
                    nameTok->varId = id;
                    scopes.back().vars[nameTok->str] = id;
                    // mark type tokens
                    for (Token *tt = tok; tt && tt != nameTok; tt = tt->next) if (tt->isName() && !tt->isKeyword()) tt->tokType = Token::eType;
                    (void)isMember;
                    // for function params: register in the upcoming function body scope: find '{' after ')'
                    if (inArgs) {
                        // find the enclosing '('
                        const Token *paren = prev;
                        int depth = 0;
                        while (paren && !(paren->str == "(" && depth == 0)) { if (paren->str == ")") ++depth; else if (paren->str == "(") --depth; paren = paren->previous; }
                        if (paren && paren->link && paren->link->next) {
                            Token *after = paren->link->next;
                            while (after && (after->str == "const" || after->str == "override" || after->str == "noexcept" || (after->str == "->" ))) {
                                if (after->str == "->") { after = after->next; while (after && after->str != "{" && after->str != ";") after = after->next; break; }
                                after = after->next;
                            }
                            if (after && after->str == ":" ) { // constructor init list
                                // params visible in init list and body: we handle by pushing a pending scope
                            }
                            // Store pending: we emulate by inserting into a map keyed by the '{' token
                        }
                    }
                    tok = nameTok;
                    continue;
                }
            }
        }
        // usage: look up in scopes (innermost first)
        if (tok->varId == 0 && !(prev && (prev->str == "." || prev->str == "->")) && !(tok->next && tok->next->str == "::") && !(prev && prev->str == "::" && !(prev->previous && prev->previous->str == "::"))) {
            // skip if this is a function call name or type
            for (size_t i = scopes.size(); i-- > 0;) {
                auto it = scopes[i].vars.find(tok->str);
                if (it != scopes[i].vars.end()) { tok->varId = it->second; break; }
            }
            // member access "this->x" or "obj.x": member variables of known classes
            if (tok->varId == 0 && prev && (prev->str == "." || prev->str == "->")) {}
        }
        // member access via "." / "->" : assign varId of the member if the object's class is known - simplified: give members of the current class
        if (tok->varId == 0 && prev && (prev->str == "." || prev->str == "->")) {
            if (prev->str == "->" && prev->previous && prev->previous->str == "this") {
                for (size_t i = scopes.size(); i-- > 0;) {
                    auto it = scopes[i].vars.find(tok->str);
                    if (it != scopes[i].vars.end()) { tok->varId = it->second; break; }
                }
            }
        }
    }
    // Second pass: function parameters must be visible in the function body. The scoping above pushes a scope at '{'
    // but parameters were registered in the outer scope. Fix: for each function definition, assign varIds in body for params.
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str != "(" || !tok->link) continue;
        if (!tok->previous || !tok->previous->isName() || tok->previous->isKeyword()) {
            if (!(tok->previous && tok->previous->str == ">")) continue;
        }
        Token *after = tok->link->next;
        while (after && (after->str == "const" || after->str == "override" || after->str == "noexcept" || after->str == "final" || after->str == "throw")) after = after->next;
        if (after && after->str == "->") { while (after && after->str != "{" && after->str != ";") after = after->next; }
        if (after && after->str == ":") { // ctor init list
            while (after && after->str != "{") { if (after->str == "(" && after->link) after = after->link; after = after->next; }
        }
        if (!after || after->str != "{" || !after->link) continue;
        std::map<std::string, unsigned> params;
        for (Token *p = tok->next; p && p != tok->link; p = p->next) {
            if (p->varId && (p->next == tok->link || p->next->str == "," || p->next->str == "=" || p->next->str == "[" || p->next->str == ")")) params[p->str] = p->varId;
        }
        if (params.empty()) continue;
        // walk the body (and ctor init list) and set varIds for unassigned names matching params, respecting shadowing by local declarations
        std::vector<std::map<std::string, unsigned>> shadow;
        shadow.emplace_back();
        Token *start = tok->link->next;
        for (Token *b = start; b && b != after->link; b = b->next) {
            if (b->str == "{" ) { shadow.emplace_back(); continue; }
            if (b->str == "}" ) { if (shadow.size() > 1) shadow.pop_back(); continue; }
            if (!b->isName()) continue;
            if (b->varId != 0) {
                // a declaration inside the body shadows the parameter
                auto pit = params.find(b->str);
                if (pit != params.end() && b->varId != pit->second) {
                    // is this a declaration? (previous token is a type or * &)
                    const Token *pv = b->previous;
                    if (pv && (pv->tokType == Token::eType || pv->str == "*" || pv->str == "&" || (pv->isName() && !pv->isKeyword() && pv->varId == 0 && pv->str != "return" && pv->str != "sizeof" && pv->str != "delete"))) shadow.back()[b->str] = b->varId;
                }
                continue;
            }
            if (b->previous && (b->previous->str == "." || b->previous->str == "->")) continue;
            if (b->next && b->next->str == "(" && !params.count(b->str)) continue;
            bool shadowed = false;
            for (size_t i = shadow.size(); i-- > 0;) if (shadow[i].count(b->str)) { shadowed = true; break; }
            if (shadowed) continue;
            auto pit = params.find(b->str);
            if (pit != params.end()) b->varId = pit->second;
        }
    }
    // Third pass: struct member access "a.b" / "a->b": assign varId of member when the struct type of 'a' is known
    // Build map: varId -> struct name, from declarations "struct X a" or "X a" (X known class)
    std::map<unsigned, std::string> varClass;
    std::map<std::string, std::map<std::string, unsigned>> members = classMembers;
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->varId == 0 || !tok->isName()) continue;
        // declaration: previous tokens are type
        Token *p = tok->previous;
        while (p && (p->str == "*" || p->str == "&" || p->str == "const")) p = p->previous;
        if (p && p->isName() && !p->isKeyword() && members.count(p->str)) {
            if (!varClass.count(tok->varId)) varClass[tok->varId] = p->str;
        } else if (p && p->isName() && p->previous && (p->previous->str == "struct" || p->previous->str == "class" || p->previous->str == "union") && members.count(p->str)) {
            if (!varClass.count(tok->varId)) varClass[tok->varId] = p->str;
        }
    }
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (!(tok->str == "." || tok->str == "->") || !tok->next || !tok->next->isName() || tok->next->varId != 0) continue;
        Token *obj = tok->previous;
        if (obj && obj->str == "]" && obj->link) obj = obj->link->previous;
        if (obj && obj->str == ")" && obj->link) obj = obj->link->previous;
        if (!obj || obj->varId == 0) continue;
        auto vc = varClass.find(obj->varId);
        if (vc == varClass.end()) continue;
        auto mem = members.find(vc->second);
        if (mem == members.end()) continue;
        auto m = mem->second.find(tok->next->str);
        if (m != mem->second.end()) {
            tok->next->varId = m->second;
            // nested struct member: record class of this member for chained access
            auto vc2 = varClass.find(m->second);
            if (vc2 != varClass.end()) varClass[m->second] = vc2->second;
        }
    }
}

