static int binaryPrecedence(const Token *tok, bool &rightAssoc) {
    rightAssoc = false;
    const std::string &s = tok->str;
    if (s == "," ) return 1;
    if (tok->isAssignmentOp()) { rightAssoc = true; return 2; }
    if (s == "?") { rightAssoc = true; return 3; }
    if (s == "||") return 4;
    if (s == "&&") return 5;
    if (s == "|") return 6;
    if (s == "^") return 7;
    if (s == "&") return 8;
    if (s == "==" || s == "!=") return 9;
    if (s == "<" || s == ">" || s == "<=" || s == ">=") return 10;
    if (s == "<<" || s == ">>") return 11;
    if (s == "+" || s == "-") return 12;
    if (s == "*" || s == "/" || s == "%") return 13;
    if (s == ".*" || s == "->*") return 14;
    return -1;
}

bool AstBuilder::looksLikeType(Token *tok) const {
    if (!tok) return false;
    if (tok->str == "const" || tok->str == "struct" || tok->str == "union" || tok->str == "enum" || tok->str == "unsigned" || tok->str == "signed" || tok->str == "long" || tok->str == "short" || tok->str == "volatile") return true;
    if (tok->isStandardType()) return true;
    if (tok->tokType == Token::eType) return true;
    return false;
}

bool AstBuilder::looksLikeCast(Token *paren) const {
    // "( type ) expr"
    if (!paren->link) return false;
    Token *t = paren->next;
    if (t == paren->link) return false;
    if (!t->isName()) return false;
    if (t->varId != 0) return false;
    if (t->isKeyword() && !(t->str == "const" || t->str == "struct" || t->str == "union" || t->str == "enum" || t->str == "unsigned" || t->str == "signed" || t->str == "long" || t->str == "short" || t->isStandardType())) return false;
    bool sawType = looksLikeType(t);
    Token *last = t;
    for (Token *x = t; x && x != paren->link; x = x->next) {
        if (x->isName()) {
            if (x->varId != 0) return false;
            if (x->str == "sizeof") return false;
            if (x->next && x->next->str == "(" ) return false;
            if (looksLikeType(x)) sawType = true;
            last = x;
        } else if (x->str == "*" || x->str == "&" || x->str == "::" || x->str == "<" || x->str == ">" || x->str == "," ) {
            if (x->str == "::" || x->str == "<" || x->str == ">") continue;
            if (x->str == "," ) return false;
            last = x;
        } else if (x->str == "[" && x->link) { x = x->link; last = x; }
        else return false;
    }
    Token *after = paren->link->next;
    if (!after || after == end) return false;
    if (!sawType) {
        // "( Foo ) x" unknown type: only cast if followed by name/number/( /string and last token is a name or *
        if (!(last->str == "*" || last->str == "&")) {
            // "(x) y" is unlikely. "(T)x" with unknown T: treat as cast if after is name/num/( and previous of paren is not a name
            if (!(after->isName() || after->isNumber() || after->str == "(" || after->tokType == Token::eString || after->str == "-" || after->str == "&" || after->str == "*" || after->str == "!" || after->str == "~")) return false;
            if (paren->previous && (paren->previous->isName() && !paren->previous->isKeyword()) ) return false;
            if (paren->previous && (paren->previous->str == ")" || paren->previous->str == "]")) return false;
            // C++: unknown single name "(x)" followed by name likely not cast unless capitalized... accept
            if (t->next != paren->link) return true;
            if (!cpp) return isupper((unsigned char)t->str[0]) || t->str.find("_t") != std::string::npos;
            return true;
        }
    }
    if (after->str == ")" || after->str == "," || after->str == ";" || after->str == "]" || after->isComparisonOp() || after->str == "?" || after->str == ":" || after->str == "||" || after->str == "&&" || after->isAssignmentOp()) return false;
    if (after->str == "+" || after->str == "/" || after->str == "%" || after->str == "|" || after->str == "^" || after->str == "<<" || after->str == ">>") return false;
    return true;
}

Token *AstBuilder::parseArgs(Token *openParen) {
    Token *close = openParen->link;
    if (openParen->next == close) { cur = close->next; return nullptr; }
    cur = openParen->next;
    const Token *savedEnd = end;
    end = close;
    Token *args = parseExpression(0);
    end = savedEnd;
    cur = close->next;
    return args;
}

Token *AstBuilder::parseBraceList(Token *openBrace) {
    Token *close = openBrace->link;
    if (openBrace->next == close) { cur = close->next; return nullptr; }
    cur = openBrace->next;
    const Token *savedEnd = end;
    end = close;
    Token *args = parseExpression(0);
    end = savedEnd;
    cur = close->next;
    return args;
}

Token *AstBuilder::parsePrimary() {
    if (atEnd()) return nullptr;
    Token *tok = cur;
    if (tok->str == "(") {
        return parseCastOrParen();
    }
    if (tok->str == "{" && tok->link) {
        // initializer list
        Token *args = parseBraceList(tok);
        tok->astOperand1Set(args);
        return tok;
    }
    if (tok->str == "[" && tok->link && cpp) {
        // lambda: [captures] (params) { body }
        Token *close = tok->link;
        Token *after = close->next;
        if (after && after->str == "(" && after->link) after = after->link->next;
        if (after && after->str == "->") { while (after && after->str != "{") after = after->next; }
        if (after && after->str == "{" && after->link) {
            tok->tokType = Token::eLambda;
            cur = after->link->next;
            return tok;
        }
    }
    if (tok->isName() || tok->isNumber() || tok->isLiteral()) {
        // qualified names a::b::c
        cur = tok->next;
        if (tok->str == "::" ) {}
        Token *result = tok;
        while (!atEnd() && cur->str == "::" && cur->next && cur->next != end && cur->next->isName()) {
            Token *scopeOp = cur;
            Token *name = cur->next;
            cur = name->next;
            scopeOp->astOperand1Set(result);
            scopeOp->astOperand2Set(name);
            result = scopeOp;
        }
        // template args: name < ... >
        if (!atEnd() && cur->str == "<" && cur->link && (result->isName() || result->str == "::")) {
            cur = cur->link->next;
        }
        return result;
    }
    if (tok->str == "::" && tok->next && tok->next->isName()) {
        cur = tok->next->next;
        tok->astOperand1Set(tok->next);
        Token *result = tok;
        while (!atEnd() && cur->str == "::" && cur->next && cur->next->isName()) {
            Token *scopeOp = cur; Token *name = cur->next; cur = name->next;
            scopeOp->astOperand1Set(result); scopeOp->astOperand2Set(name); result = scopeOp;
        }
        return result;
    }
    // unknown: consume
    cur = tok->next;
    return tok;
}

Token *AstBuilder::parseCastOrParen() {
    Token *paren = cur;
    if (!paren->link) { cur = paren->next; return paren; }
    if (looksLikeCast(paren)) {
        paren->isCast = true;
        cur = paren->link->next;
        Token *operand = parseUnary();
        paren->astOperand1Set(operand);
        return paren;
    }
    // parenthesized expression - transparent
    Token *close = paren->link;
    cur = paren->next;
    const Token *savedEnd = end;
    end = close;
    Token *inner = parseExpression(0);
    end = savedEnd;
    cur = close->next;
    if (!inner) { return paren; }
    // Keep track: parenthesized expressions in cppcheck are transparent except for commas inside
    return inner;
}

Token *AstBuilder::parsePostfix(Token *operand) {
    while (!atEnd()) {
        Token *tok = cur;
        if (tok->str == "(" && tok->link) {
            // function call
            Token *args = parseArgs(tok);
            tok->astOperand1Set(operand);
            if (args) tok->astOperand2Set(args);
            operand = tok;
            continue;
        }
        if (tok->str == "[" && tok->link) {
            cur = tok->next;
            const Token *savedEnd = end;
            end = tok->link;
            Token *index = (tok->next == tok->link) ? nullptr : parseExpression(0);
            end = savedEnd;
            cur = tok->link->next;
            tok->astOperand1Set(operand);
            if (index) tok->astOperand2Set(index);
            operand = tok;
            continue;
        }
        if (tok->str == "{" && tok->link && operand && (operand->isName() || operand->str == "::" || operand->str == ">") && cpp) {
            // T{...} constructor
            Token *args = parseBraceList(tok);
            tok->astOperand1Set(operand);
            if (args) tok->astOperand2Set(args);
            operand = tok;
            continue;
        }
        if (tok->str == "." || tok->str == "->") {
            cur = tok->next;
            if (atEnd()) { tok->astOperand1Set(operand); return tok; }
            Token *member = cur;
            cur = member->next;
            // handle member template "a.b<int>" -> skip
            if (!atEnd() && cur->str == "<" && cur->link) cur = cur->link->next;
            tok->astOperand1Set(operand);
            tok->astOperand2Set(member);
            operand = tok;
            continue;
        }
        if (tok->str == "++" || tok->str == "--") {
            cur = tok->next;
            tok->astOperand1Set(operand);
            operand = tok;
            continue;
        }
        break;
    }
    return operand;
}

Token *AstBuilder::parseUnary() {
    if (atEnd()) return nullptr;
    Token *tok = cur;
    if (tok->str == "!" || tok->str == "~" || tok->str == "-" || tok->str == "+" || tok->str == "*" || tok->str == "&" || tok->str == "++" || tok->str == "--") {
        cur = tok->next;
        Token *operand = parseUnary();
        tok->astOperand1Set(operand);
        return tok;
    }
    if (tok->str == "sizeof" || tok->str == "alignof" || tok->str == "_Alignof" || tok->str == "typeof" || tok->str == "decltype" || tok->str == "typeid") {
        cur = tok->next;
        if (!atEnd() && cur->str == "(" && cur->link) {
            Token *paren = cur;
            // sizeof ( type ) or sizeof ( expr )
            cur = paren->next;
            const Token *savedEnd = end;
            end = paren->link;
            Token *inner = nullptr;
            if (paren->next != paren->link) {
                // type?
                bool isType = looksLikeType(paren->next) && (paren->next->varId == 0);
                if (isType) {
                    // represent type as the first token chain
                    inner = paren->next;
                    // treat "type *" etc as a simple node
                    cur = paren->link;
                } else inner = parseExpression(0);
            }
            end = savedEnd;
            cur = paren->link->next;
            paren->astOperand1Set(tok);
            if (inner) paren->astOperand2Set(inner);
            return parsePostfix(paren);
        }
        Token *operand = parseUnary();
        tok->astOperand1Set(operand);
        return tok;
    }
    if (cpp && (tok->str == "new")) {
        cur = tok->next;
        // new (placement)? type (args) / new type[expr]
        if (!atEnd() && cur->str == "(" && cur->link) {
            // placement or (type)
            Token *paren = cur;
            cur = paren->link->next;
        }
        // type
        Token *typeTok = cur;
        while (!atEnd() && (cur->isName() || cur->str == "::" || cur->str == "*" || cur->str == "<" || cur->str == ">" || cur->str == "&")) {
            if (cur->str == "<" && cur->link) { cur = cur->link->next; continue; }
            cur = cur->next;
        }
        if (!atEnd() && cur->str == "(" && cur->link) {
            Token *paren = cur;
            Token *args = parseArgs(paren);
            paren->astOperand1Set(typeTok);
            if (args) paren->astOperand2Set(args);
            tok->astOperand1Set(paren);
        } else if (!atEnd() && cur->str == "[" && cur->link) {
            Token *br = cur;
            cur = br->next;
            const Token *savedEnd = end; end = br->link;
            Token *sz = parseExpression(0);
            end = savedEnd;
            cur = br->link->next;
            br->astOperand1Set(typeTok);
            if (sz) br->astOperand2Set(sz);
            tok->astOperand1Set(br);
            if (!atEnd() && cur->str == "{" && cur->link) { Token *b = cur; parseBraceList(b); }
        } else if (!atEnd() && cur->str == "{" && cur->link) {
            Token *brace = cur;
            Token *args = parseBraceList(brace);
            brace->astOperand1Set(typeTok);
            if (args) brace->astOperand2Set(args);
            tok->astOperand1Set(brace);
        } else {
            tok->astOperand1Set(typeTok);
        }
        return tok;
    }
    if (cpp && tok->str == "delete") {
        cur = tok->next;
        if (!atEnd() && cur->str == "[" && cur->link) cur = cur->link->next;
        Token *operand = parseUnary();
        tok->astOperand1Set(operand);
        return tok;
    }
    if (tok->str == "throw" || tok->str == "co_await" || tok->str == "co_yield") {
        cur = tok->next;
        if (!atEnd() && cur->str != ";" && cur->str != ")") {
            Token *operand = parseExpression(2);
            tok->astOperand1Set(operand);
        }
        return tok;
    }
    if (cpp && (tok->str == "static_cast" || tok->str == "dynamic_cast" || tok->str == "reinterpret_cast" || tok->str == "const_cast") && tok->next && tok->next->str == "<" && tok->next->link) {
        Token *gt = tok->next->link;
        cur = gt->next;
        if (!atEnd() && cur->str == "(" && cur->link) {
            Token *paren = cur;
            Token *args = parseArgs(paren);
            paren->astOperand1Set(tok);
            if (args) paren->astOperand2Set(args);
            paren->isCast = true;
            return parsePostfix(paren);
        }
        return tok;
    }
    Token *prim = parsePrimary();
    return parsePostfix(prim);
}

Token *AstBuilder::parseExpression(int minPrec) {
    Token *lhs = parseUnary();
    while (!atEnd()) {
        Token *op = cur;
        bool rightAssoc;
        int prec = binaryPrecedence(op, rightAssoc);
        if (prec < 0 || prec < minPrec) break;
        if (op->str == "?") {
            cur = op->next;
            Token *a = parseExpression(0);
            Token *colon = nullptr;
            if (!atEnd() && cur->str == ":") {
                colon = cur;
                cur = colon->next;
                Token *b = parseExpression(prec);
                colon->astOperand1Set(a);
                colon->astOperand2Set(b);
            }
            op->astOperand1Set(lhs);
            op->astOperand2Set(colon ? colon : a);
            lhs = op;
            continue;
        }
        cur = op->next;
        Token *rhs = parseExpression(rightAssoc ? prec : prec + 1);
        op->astOperand1Set(lhs);
        op->astOperand2Set(rhs);
        lhs = op;
    }
    return lhs;
}

// Find end of a statement expression starting at tok (exclusive end: ";" or the given stop)
static Token *findStatementEnd(Token *tok, const Token *stop) {
    for (Token *t = tok; t && t != stop; t = t->next) {
        if (t->str == ";") return t;
        if ((t->str == "(" || t->str == "[" || t->str == "{") && t->link) {
            if (t->str == "{" ) {
                // brace in expression (initializer / lambda) -> skip
                t = t->link;
                continue;
            }
            t = t->link;
            continue;
        }
        if (t->str == "}") return t;
    }
    return nullptr;
}

static bool isDeclarationStart(Token *tok) {
    // "type name" patterns
    if (!tok->isName()) return false;
    if (tok->str == "return" || tok->str == "goto" || tok->str == "delete" || tok->str == "throw" || tok->str == "case" || tok->str == "sizeof" || tok->str == "new") return false;
    Token *t = tok;
    while (t && t->isName() && (t->str == "const" || t->str == "static" || t->str == "extern" || t->str == "struct" || t->str == "union" || t->str == "enum" || t->str == "class" || t->str == "unsigned" || t->str == "signed" || t->str == "long" || t->str == "short" || t->str == "mutable" || t->str == "typename")) t = t->next;
    if (!t || !t->isName()) return false;
    if (t->varId != 0) return false;
    // type then name
    Token *n = t->next;
    while (n && (n->str == "::" || (n->str == "<" && n->link))) {
        if (n->str == "<") n = n->link->next; else { n = n->next; if (n) n = n->next; }
    }
    while (n && n->isName() && (n->isStandardType() || n->str == "const" || n->str == "unsigned" || n->str == "signed" || n->str == "long") && n->next && (n->next->isName() || n->next->str == "*" || n->next->str == "&")) n = n->next;
    while (n && (n->str == "*" || n->str == "&" || n->str == "&&" || n->str == "const")) n = n->next;
    if (!n || !n->isName()) return false;
    if (n->varId == 0) return (t->isStandardType() || t->tokType == Token::eType) && !n->isKeyword();
    return true;
}

} // namespace

void createAst(TokenList &list) {
    const bool cpp = list.isCPP;
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->astParent || tok->astOperand1) continue;
        // control statements
        if ((tok->str == "if" || tok->str == "while" || tok->str == "switch") && tok->next && tok->next->str == "(" && tok->next->link) {
            Token *paren = tok->next;
            AstBuilder b{paren->next, paren->link, cpp};
            Token *cond = (paren->next == paren->link) ? nullptr : b.parseExpression(0);
            paren->astOperand1Set(tok);
            if (cond) paren->astOperand2Set(cond);
            tok = paren->link;
            continue;
        }
        if (tok->str == "for" && tok->next && tok->next->str == "(" && tok->next->link) {
            Token *paren = tok->next;
            paren->astOperand1Set(tok);
            // split by ';'
            Token *semi1 = nullptr, *semi2 = nullptr;
            int depth = 0;
            for (Token *t = paren->next; t && t != paren->link; t = t->next) {
                if ((t->str == "(" || t->str == "[" || t->str == "{") && t->link) { t = t->link; continue; }
                if (t->str == ";" && depth == 0) { if (!semi1) semi1 = t; else if (!semi2) { semi2 = t; break; } }
            }
            if (semi1 && semi2) {
                // init
                Token *initStart = paren->next;
                // skip declaration type tokens
                if (initStart != semi1 && isDeclarationStart(initStart)) {
                    Token *t = initStart;
                    while (t && t != semi1 && !(t->varId != 0)) t = t->next;
                    initStart = t;
                }
                Token *init = nullptr;
                if (initStart && initStart != semi1) { AstBuilder b{initStart, semi1, cpp}; init = b.parseExpression(0); }
                Token *cond = nullptr;
                if (semi1->next != semi2) { AstBuilder b{semi1->next, semi2, cpp}; cond = b.parseExpression(0); }
                Token *inc = nullptr;
                if (semi2->next != paren->link) { AstBuilder b{semi2->next, paren->link, cpp}; inc = b.parseExpression(0); }
                if (init) semi1->astOperand1Set(init);
                if (cond) semi2->astOperand1Set(cond);
                if (inc) semi2->astOperand2Set(inc);
                semi1->astOperand2Set(semi2);
                paren->astOperand2Set(semi1);
            } else {
                // range-based for: "for ( decl : expr )"
                Token *colon = nullptr;
                for (Token *t = paren->next; t && t != paren->link; t = t->next) {
                    if ((t->str == "(" || t->str == "[" || t->str == "{") && t->link) { t = t->link; continue; }
                    if (t->str == ":") { colon = t; break; }
                }
                if (colon) {
                    Token *var = colon->previous;
                    Token *expr = nullptr;
                    if (colon->next != paren->link) { AstBuilder b{colon->next, paren->link, cpp}; expr = b.parseExpression(0); }
                    colon->astOperand1Set(var);
                    if (expr) colon->astOperand2Set(expr);
                    paren->astOperand2Set(colon);
                }
            }
            tok = paren->link;
            continue;
        }
        if (tok->str == "return" ) {
            Token *end = findStatementEnd(tok->next, nullptr);
            if (end && end != tok->next) {
                AstBuilder b{tok->next, end, cpp};
                Token *e = b.parseExpression(0);
                tok->astOperand1Set(e);
            }
            tok = end ? end : tok;
            if (!tok) break;
            continue;
        }
        if (tok->str == "case") {
            Token *end = tok->next;
            while (end && end->str != ":" && end->str != ";") end = end->next;
            if (end && end != tok->next) { AstBuilder b{tok->next, end, cpp}; Token *e = b.parseExpression(0); tok->astOperand1Set(e); }
            if (end) tok = end;
            continue;
        }
        if (tok->str == "{" || tok->str == "}" || tok->str == ";" || tok->str == "else" || tok->str == "do" || tok->str == "try" || tok->str == "break" || tok->str == "continue" || tok->str == "default" || tok->str == "goto" || tok->str == "catch" || tok->str == "namespace" || tok->str == "public" || tok->str == "private" || tok->str == "protected" || tok->str == "typedef" || tok->str == "using" || tok->str == "template" || tok->str == "asm") {
            if (tok->str == "goto" && tok->next) tok = tok->next;
            if (tok->str == "typedef" || tok->str == "using" || tok->str == "asm") { Token *e = findStatementEnd(tok, nullptr); if (e) tok = e; }
            if (tok->str == "template" && tok->next && tok->next->str == "<" && tok->next->link) tok = tok->next->link;
            if (tok->str == "catch" && tok->next && tok->next->str == "(" && tok->next->link) tok = tok->next->link;
            continue;
        }
        if (tok->str == "(" && tok->link && tok->previous && (tok->previous->str == ")" || tok->previous->str == "]" || tok->previous->str == ">")) {
            // e.g. function pointer declaration "void (*fp)(int)" - skip
        }
        // statement: declaration or expression
        Token *stmtEnd = findStatementEnd(tok, nullptr);
        if (!stmtEnd) break;
        Token *start = tok;
        // skip declaration type part: find first token with varId that is a declaration name
        if (isDeclarationStart(start)) {
            Token *t = start;
            while (t && t != stmtEnd && !(t->varId != 0 && t->isName())) {
                if (t->str == "(" && t->link) { // function declaration/call in declaration?
                    break;
                }
                if (t->str == "<" && t->link) { t = t->link; }
                t = t->next;
            }
            if (t && t != stmtEnd && t->varId != 0) {
                // variable declaration: "T x ;" or "T x [ n ] ;" or "T x = ..." (array init) or "T x ( args )" / "T x { args }"
                Token *name = t;
                Token *after = name->next;
                while (after && after->str == "[" && after->link) {
                    // dimension expression
                    if (after->next != after->link) { AstBuilder b{after->next, after->link, cpp}; Token *d = b.parseExpression(0); after->astOperand2Set(d); }
                    after->astOperand1Set(name);
                    after = after->link->next;
                }
                if (after && after->str == "=" ) {
                    AstBuilder b{after->next, stmtEnd, cpp};
                    Token *rhs = b.parseExpression(0);
                    after->astOperand1Set(name);
                    after->astOperand2Set(rhs);
                } else if (after && (after->str == "(" || after->str == "{") && after->link) {
                    AstBuilder b{after, stmtEnd, cpp};
                    Token *args = (after->str == "(") ? b.parseArgs(after) : b.parseBraceList(after);
                    after->astOperand1Set(name);
                    if (args) after->astOperand2Set(args);
                } else if (after && after->str == ":" ) {
                    // bitfield
                }
                tok = stmtEnd;
                continue;
            }
            // function declaration or something else: skip the statement
            if (t && t->str == "(") {
                // check for function definition: "type name ( ... ) {"
                Token *close = t->link;
                if (close && close->next && close->next->str == "{") { tok = t->previous ? t->previous : tok; continue; }
                tok = stmtEnd;
                continue;
            }
            tok = stmtEnd;
            continue;
        }
        // function definition header "name ( ... ) {" -> skip header
        if (tok->isName() && tok->next && tok->next->str == "(" && tok->next->link && tok->next->link->next && (tok->next->link->next->str == "{" || tok->next->link->next->str == "const" || tok->next->link->next->str == ":") && tok->varId == 0) {
            const Token *prev = tok->previous;
            bool isDef = !prev || prev->isName() || prev->str == "*" || prev->str == "&" || prev->str == "::" || prev->str == "}" || prev->str == ";" || prev->str == "~";
            if (isDef) {
                // parse default arguments? skip
                tok = tok->next->link;
                continue;
            }
        }
        // class/struct/enum definitions: skip header
        if ((tok->str == "class" || tok->str == "struct" || tok->str == "union" || tok->str == "enum") && tok->next) {
            Token *t = tok->next;
            while (t && t->str != "{" && t->str != ";") t = t->next;
            if (t && t->str == "{") { tok = t; continue; }
            if (t) { tok = t; continue; }
        }
        AstBuilder b{start, stmtEnd, cpp};
        b.parseExpression(0);
        tok = stmtEnd;
    }
}
