                Token *q = p;
                // find "class|struct|union|enum NAME" before '{', allowing ": base..." in between
                int guard = 0;
                while (q && q->str != ";" && q->str != "{" && q->str != "}" && q->str != ")" && guard++ < 50) {
                    if ((q->str == "class" || q->str == "struct" || q->str == "union" || q->str == "enum") && q->next && q->next->isName()) break;
                    if (q->str == "typedef") break;
                    q = q->previous;
                }
                if (q && (q->str == "class" || q->str == "struct" || q->str == "union" || q->str == "enum") && q->next && q->next->isName() && !(q->previous && q->previous->str == "typedef" && false)) {
                    // make sure the name is followed by '{' or ':' or 'final'
