                for (const Scope *s : st.back()->nestedList) if (s->bodyStart == tok) { found = s; break; }
                tok->scope = st.back();
                if (found) st.push_back(found);
                else st.push_back(st.back());
                continue;
            }
            if (tok->str == "}" && tok->link) {
                if (st.size() > 1) st.pop_back();
                tok->scope = st.back();
                continue;
            }
            tok->scope = st.back();
        }
    }
    // functions
    for (Scope &scope : scopeList) {
        if (scope.type == Scope::eFunction || scope.type == Scope::eLambda) functionScopes.push_back(&scope);
        if (scope.isClassOrStruct()) classAndStructScopes.push_back(&scope);
    }
}

void SymbolDatabase::createFunctions(Scope &scope) {
    (void)scope;
}

void SymbolDatabase::createVariables() {
    // Enumerators
    for (Scope &scope : scopeList) {
        if (scope.type != Scope::eEnum) continue;
        long long value = 0;
        bool known = true;
        for (Token *t = const_cast<Token*>(scope.bodyStart)->next; t && t != scope.bodyEnd; t = t->next) {
            if (!t->isName()) continue;
            Enumerator e;
            e.name = t;
            e.scope = &scope;
            if (t->next && t->next->str == "=") {
                Token *v = t->next->next;
                if (v && v->isNumber() && v->next && (v->next->str == "," || v->next == scope.bodyEnd)) { value = toLongNumber(v->str); known = true; }
                else if (v && v->str == "-" && v->next && v->next->isNumber()) { value = -toLongNumber(v->next->str); known = true; }
                else known = false;
                while (t->next && t->next->str != "," && t->next != scope.bodyEnd) t = t->next;
            }
            e.value = value; e.valueKnown = known;
            scope.enumeratorList.push_back(e);
            ++value;
        }
        for (Enumerator &e : scope.enumeratorList) const_cast<Token*>(e.name)->enumerator = &e;
    }
    // Functions: find "name ( ... )" followed by "{" or ";" in non-executable scopes
    for (Scope &scope : scopeList) {
        if (scope.type != Scope::eFunction && scope.type != Scope::eLambda) continue;
        Token *nameTok = const_cast<Token*>(scope.classDef);
        if (!nameTok) continue;
        Function f;
        f.token = nameTok;
        f.tokenDef = nameTok;
        f.name = nameTok->str;
        f.hasBody = true;
        f.functionScope = &scope;
        // argument list
        Token *argStart = nameTok->next;
        if (scope.type == Scope::eLambda) {
            // "[ ... ] ( args ) {"
            Token *close = nameTok->link;
            argStart = close ? close->next : nullptr;
            f.type = Function::eLambda;
            f.name = "";
        }
        if (argStart && argStart->str == "(" && argStart->link) {
            f.arg = argStart; f.argDef = argStart;
            // return type
            Token *r = nameTok->previous;
            if (r && r->str == "::" ) { // Class::f
                Token *cls = r->previous;
                r = cls ? cls->previous : nullptr;
                // nestedIn = class scope
                if (cls) { const Scope *cs = findScopeByName(cls->str); if (cs) f.nestedIn = cs; }
            }
            if (r && r->str == "~") { f.type = Function::eDestructor; r = r->previous; }
            Token *retEnd = r;
            while (r && (r->isName() || r->str == "*" || r->str == "&" || r->str == "::" || (r->str == ">" && r->link)) && r->str != "}" && r->str != ";" && r->str != "{") {
                if (r->str == ">" && r->link) { r = r->link->previous; continue; }
                if (r->str == "virtual") f.isVirtual = true;
                if (r->str == "static") f.isStatic = true;
                if (r->str == "explicit") f.isExplicit = true;
                if (r->str == "friend") f.isFriend = true;
                if (r->str == "extern") f.isExtern = true;
                if (r->str == "inline") f.isInline = true;
                if (r->str == "template") break;
                r = r->previous;
            }
            f.retDef = r ? r->next : mTokenList.front();
            f.retEnd = retEnd;
            if (retEnd && retEnd != nameTok) {
                std::string rt;
                for (Token *x = const_cast<Token*>(f.retDef); x && x != nameTok && x != retEnd->next; x = x->next) {
                    if (x->str == "virtual" || x->str == "static" || x->str == "explicit" || x->str == "friend" || x->str == "inline" || x->str == "extern") continue;
                    if (!rt.empty()) rt += " ";
                    rt += x->str;
                    if (x->str == "*") f.returnsPointer = true;
                    if (x->str == "&") f.returnsReference = true;
                    if (x->str == "const") f.returnsConst = true;
                }
                f.returnTypeStr = rt;
                if (rt == "void") f.returnsVoid = true;
            }
            // qualifiers after ')'
            for (Token *q = argStart->link->next; q && q != scope.bodyStart; q = q->next) {
                if (q->str == "const") f.isConst = true;
                if (q->str == "=" && q->next && q->next->str == "0") f.isPureVirtual = true;
                if (q->str == ":") break;
            }
            // class membership
            if (!f.nestedIn) f.nestedIn = scope.nestedIn;
            if (f.nestedIn && f.nestedIn->isClassOrStructOrUnion()) {
                if (f.name == f.nestedIn->className) f.type = (f.type == Function::eDestructor) ? Function::eDestructor : Function::eConstructor;
                // access
            }
            if (f.type == Function::eConstructor && f.argDef) {
                // copy constructor: "Foo ( const Foo & x )"
                Token *a = argStart->next;
                if (a && a->str == "const") a = a->next;
                if (a && a->str == f.name && a->next && a->next->str == "&" && a->next->next && a->next->next->isName() && a->next->next->next == argStart->link) f.type = Function::eCopyConstructor;
                if (a && a->str == f.name && a->next && a->next->str == "&&") f.type = Function::eMoveConstructor;
            }
            if (f.name == "operator=") f.type = Function::eOperatorEqual;
            if (f.name.compare(0, 8, "operator") == 0) f.isOperator = true;
            if (nameTok->isAttributeUnused) f.isAttributeUnused = true;
            if (nameTok->isAttributeUsed) f.isAttributeUsed = true;
            if (nameTok->isAttributeNoreturn) f.isAttributeNoreturn = true;
            if (nameTok->isAttributeConstructor) f.isAttributeConstructor = true;
            if (nameTok->isAttributeDestructor) f.isAttributeDestructor = true;
            // template?
            {
                const Token *tp = f.retDef ? f.retDef->previous : nullptr;
                if (tp && tp->str == ">" && tp->link && tp->link->previous && tp->link->previous->str == "template") f.isTemplate = true;
            }
            // arguments
            int index = 0;
            for (Token *a = argStart->next; a && a != argStart->link; a = a->next) {
                if (a->str == "(" && a->link) { // function pointer parameter
                    Token *nm = a->next; if (nm && nm->str == "*") nm = nm->next;
                    if (nm && nm->varId) {
                        Variable v; fillVariable(v, nm, &scope, mLibrary, isCPP, mTypesByName);
                        v.isArgument = true; v.isLocal = false; v.index = index++;
                        f.argumentList.push_back(v);
                    }
                    a = a->link;
                    // skip the params of fp
                    if (a->next && a->next->str == "(" && a->next->link) a = a->next->link;
                    continue;
                }
                if (a->str == "..." ) { f.isVariadic = true; continue; }
                if (a->varId != 0 && a->isName()) {
                    Variable v;
                    fillVariable(v, a, &scope, mLibrary, isCPP, mTypesByName);
                    v.isArgument = true; v.isLocal = false;
                    v.index = index++;
                    // default value
                    Token *x = a->next;
                    while (x && x->str == "[" && x->link) x = x->link->next;
                    if (x && x->str == "=") v.hasDefault = true;
                    f.argumentList.push_back(v);
                    // skip to next ','
                    while (a->next && a->next != argStart->link && a->next->str != ",") { if ((a->next->str == "(" || a->next->str == "[" || a->next->str == "{" || a->next->str == "<") && a->next->link) a = a->next->link; else a = a->next; }
                }
            }
        }
        Scope *owner = const_cast<Scope*>(f.nestedIn ? f.nestedIn : scope.nestedIn);
        if (!owner) owner = &scopeList.front();
        owner->functionList.push_back(f);
        Function *fp = &owner->functionList.back();
        scope.function = fp;
        nameTok->function = fp;
        nameTok->functionDecl = fp;
        if (nameTok->tokType == Token::eName) nameTok->tokType = Token::eFunction;
    }
    // Function declarations (no body) in class/global/namespace scopes
    for (Scope &scope : scopeList) {
        if (scope.isExecutable()) continue;
        Token *start = scope.bodyStart ? const_cast<Token*>(scope.bodyStart)->next : mTokenList.front();
        if (scope.type == Scope::eGlobal) start = mTokenList.front();
        for (Token *tok = start; tok && tok != scope.bodyEnd; tok = tok->next) {
            if (tok->str == "{" && tok->link) { tok = tok->link; continue; }
            if (!tok->isName() || tok->isKeyword() || tok->varId != 0) continue;
            if (!(tok->next && tok->next->str == "(" && tok->next->link)) continue;
            Token *after = tok->next->link->next;
            while (after && (after->str == "const" || after->str == "override" || after->str == "final" || after->str == "noexcept")) after = after->next;
            bool isDecl = after && (after->str == ";" || (after->str == "=" && after->next && (after->next->str == "0" || after->next->str == "default" || after->next->str == "delete")));
            if (!isDecl) continue;
            // must have a return type before (or be a constructor in class)
            Token *prev = tok->previous;
            if (prev && prev->str == "~") prev = prev->previous;
            bool hasType = prev && (prev->isName() || prev->str == "*" || prev->str == "&" || prev->str == ">" );
            bool isCtor = scope.isClassOrStructOrUnion() && tok->str == scope.className;
            if (!hasType && !isCtor) continue;
            if (prev && (prev->str == "return" || prev->str == "sizeof" || prev->str == "new" || prev->str == "delete" || prev->str == "throw" || prev->str == "case" || prev->str == "goto")) continue;
            // already defined?
            Function *existing = nullptr;
            for (Function &f : scope.functionList) if (f.name == tok->str) { existing = &f; break; }
            if (existing) {
                if (!existing->tokenDef || existing->tokenDef == existing->token) existing->tokenDef = tok;
                tok->function = existing;
                tok->functionDecl = existing;
                if (tok->isAttributeUnused) existing->isAttributeUnused = true;
                if (tok->isAttributeUsed) existing->isAttributeUsed = true;
                if (tok->isAttributeNoreturn) existing->isAttributeNoreturn = true;
                if (tok->isAttributeConstructor) existing->isAttributeConstructor = true;
                if (tok->isAttributeDestructor) existing->isAttributeDestructor = true;
                continue;
            }
            Function f;
            f.tokenDef = tok;
            f.token = nullptr;
            f.name = tok->str;
            f.hasBody = false;
            f.isDeclaration = true;
            f.argDef = tok->next;
            f.nestedIn = &scope;
            Token *r = tok->previous;
            if (r && r->str == "~") { f.type = Function::eDestructor; r = r->previous; }
            while (r && (r->isName() || r->str == "*" || r->str == "&" || r->str == "::" || (r->str == ">" && r->link))) {
                if (r->str == ">" && r->link) { r = r->link->previous; continue; }
                if (r->str == "virtual") f.isVirtual = true;
                if (r->str == "static") f.isStatic = true;
                if (r->str == "explicit") f.isExplicit = true;
                if (r->str == "friend") f.isFriend = true;
                if (r->str == "extern") f.isExtern = true;
                r = r->previous;
            }
            f.retDef = r ? r->next : mTokenList.front();
            {
                std::string rt;
                for (Token *x = const_cast<Token*>(f.retDef); x && x != tok; x = x->next) {
                    if (x->str == "virtual" || x->str == "static" || x->str == "explicit" || x->str == "friend" || x->str == "inline" || x->str == "extern" || x->str == "~") continue;
                    if (!rt.empty()) rt += " ";
                    rt += x->str;
                    if (x->str == "*") f.returnsPointer = true;
                    if (x->str == "&") f.returnsReference = true;
                }
                f.returnTypeStr = rt;
                if (rt == "void") f.returnsVoid = true;
            }
            for (Token *q = tok->next->link->next; q && q->str != ";"; q = q->next) {
                if (q->str == "const") f.isConst = true;
                if (q->str == "=" && q->next) { if (q->next->str == "0") f.isPureVirtual = true; if (q->next->str == "default") f.isDefault = true; if (q->next->str == "delete") f.isDelete = true; }
            }
            if (isCtor) f.type = (f.type == Function::eDestructor) ? Function::eDestructor : Function::eConstructor;
            if (f.type == Function::eConstructor) {
                Token *a = tok->next->next;
                if (a && a->str == "const") a = a->next;
                if (a && a->str == f.name && a->next && a->next->str == "&" && a->next->next && a->next->next->isName() && a->next->next->next == tok->next->link) f.type = Function::eCopyConstructor;
                if (a && a->str == f.name && a->next && a->next->str == "&&") f.type = Function::eMoveConstructor;
            }
            if (f.name == "operator=") f.type = Function::eOperatorEqual;
            if (f.name.compare(0, 8, "operator") == 0) f.isOperator = true;
            if (tok->isAttributeUnused) f.isAttributeUnused = true;
            if (tok->isAttributeUsed) f.isAttributeUsed = true;
            if (tok->isAttributeNoreturn) f.isAttributeNoreturn = true;
            if (tok->isAttributeConstructor) f.isAttributeConstructor = true;
            if (tok->isAttributeDestructor) f.isAttributeDestructor = true;
            int index = 0;
            for (Token *a = tok->next->next; a && a != tok->next->link; a = a->next) {
                if (a->str == "..." ) { f.isVariadic = true; continue; }
                if (a->str == "(" && a->link) { Token *nm = a->next; if (nm && nm->str == "*") nm = nm->next; if (nm && nm->varId) { Variable v; fillVariable(v, nm, &scope, mLibrary, isCPP, mTypesByName); v.isArgument = true; v.isLocal = false; v.index = index++; f.argumentList.push_back(v); } a = a->link; if (a->next && a->next->str == "(" && a->next->link) a = a->next->link; continue; }
                if (a->varId != 0 && a->isName()) {
                    Variable v; fillVariable(v, a, &scope, mLibrary, isCPP, mTypesByName);
                    v.isArgument = true; v.isLocal = false; v.index = index++;
                    Token *x = a->next; while (x && x->str == "[" && x->link) x = x->link->next;
                    if (x && x->str == "=") v.hasDefault = true;
                    f.argumentList.push_back(v);
                    while (a->next && a->next != tok->next->link && a->next->str != ",") { if ((a->next->str == "(" || a->next->str == "[" || a->next->str == "{" || a->next->str == "<") && a->next->link) a = a->next->link; else a = a->next; }
                } else if (a->isName() && !a->isKeyword() && a->varId == 0 && (a->next == tok->next->link || a->next->str == ",") && !(a->previous == tok->next || a->previous->str == ",")) {
                    // unnamed parameter "int" -> count
                    Variable v; v.index = index++; v.typeName = a->str; v.isArgument = true; f.argumentList.push_back(v);
                } else if (a->isName() && !a->isKeyword() && a->varId == 0 && (a->next == tok->next->link || a->next->str == ",") && (a->previous == tok->next || a->previous->str == ",")) {
                    Variable v; v.index = index++; v.typeName = a->str; v.isArgument = true; f.argumentList.push_back(v);
                }
            }
            scope.functionList.push_back(f);
            tok->function = &scope.functionList.back();
            tok->functionDecl = tok->function;
            if (tok->tokType == Token::eName) tok->tokType = Token::eFunction;
        }
    }
    // Link definitions "Class :: f" to class scope declarations
    for (Scope &scope : scopeList) {
        for (Function &f : scope.functionList) {
            if (!f.hasBody) {
                // find definition elsewhere
                for (Scope &s2 : scopeList) {
                    for (Function &f2 : s2.functionList) {
                        if (&f2 == &f || !f2.hasBody || f2.name != f.name) continue;
                        if (f2.nestedIn == &scope || (f2.token && f2.token->previous && f2.token->previous->str == "::" && f2.token->previous->previous && f2.token->previous->previous->str == scope.className)) {
                            if (f2.argCount() == f.argCount()) {
                                f.token = f2.token; f.hasBody = true; f.functionScope = f2.functionScope; f.arg = f2.arg;
                                if (f2.tokenDef == f2.token) f2.tokenDef = f.tokenDef;
                                const_cast<Token*>(f2.token)->function = &f;
                                f2.isDeclaration = true; // mark duplicate
                            }
                        }
                    }
                }
            }
        }
    }
    // Variables: every token with varId that is a declaration name
    variableList.assign(1, nullptr);
    std::map<unsigned, Variable*> byId;
    for (Scope &scope : scopeList) {
        Token *start = scope.type == Scope::eGlobal ? mTokenList.front() : const_cast<Token*>(scope.bodyStart)->next;
        const Token *end = scope.bodyEnd;
        for (Token *tok = start; tok && tok != end; tok = tok->next) {
            if (tok->str == "{" && tok->link && tok != scope.bodyStart) {
                // skip nested scopes (they have their own Scope) but not initializer braces
                bool isScope = false;
                for (const Scope *n : scope.nestedList) if (n->bodyStart == tok) { isScope = true; break; }
                if (isScope) { tok = tok->link; continue; }
            }
            if (tok->varId == 0 || !tok->isName()) continue;
            if (byId.count(tok->varId)) continue;
            // declaration? previous token is type-ish
            const Token *prev = tok->previous;
            bool decl = false;
            if (prev && (prev->tokType == Token::eType || prev->str == "*" || prev->str == "&" || prev->str == "&&" || (prev->isName() && !prev->isKeyword() && prev->varId == 0 && prev->str != "return" && prev->str != "sizeof" && prev->str != "delete" && prev->str != "throw" && prev->str != "case" && prev->str != "goto") || (prev->isKeyword() && (prev->isStandardType() || prev->str == "const" || prev->str == "auto")) || prev->str == ">")) decl = true;
            if (prev && (prev->str == "." || prev->str == "->")) decl = false;
            if (prev && prev->str == "::" ) decl = false;
            if (!decl) continue;
            Variable v;
            fillVariable(v, tok, &scope, mLibrary, isCPP, mTypesByName);
            // function parameter? (scope of parameters is the function scope)
            bool isArg = false;
            {
                const Token *p = tok;
                int depth = 0;
                while (p && p->str != ";" && p->str != "{" && p->str != "}") {
                    if (p->str == ")") ++depth;
                    if (p->str == "(") { if (depth == 0) break; --depth; }
                    p = p->previous;
                }
                if (p && p->str == "(" && p->previous && p->previous->isName() && !p->previous->isKeyword() && p->link && p->link->next && (p->link->next->str == "{" || p->link->next->str == ";" || p->link->next->str == "const" || p->link->next->str == ":" || p->link->next->str == "override")) isArg = true;
                if (p && p->str == "(" && p->previous && p->previous->str == "catch") { v.isLocal = true; }
                if (p && p->str == "(" && p->previous && (p->previous->str == "for" )) { v.isLocal = true; }
            }
            if (isArg) {
                v.isArgument = true; v.isLocal = false; v.isGlobal = false; v.isMember = false;
                // scope: the function scope
                for (Scope *fs : scope.nestedList) {
                    if (fs->type == Scope::eFunction && fs->function && fs->function->arg) {
                        const Token *ap = fs->function->arg;
                        if (ap && tok->linenr >= ap->linenr && ap->link && (tok->linenr < ap->link->linenr || (tok->linenr == ap->link->linenr && tok->column < ap->link->column))) { v.scope = fs; break; }
                    }
                }
                // add to function scope varlist
                if (v.scope && v.scope != &scope) {
                    const_cast<Scope*>(v.scope)->varlist.push_back(v);
                    Variable *vp = &const_cast<Scope*>(v.scope)->varlist.back();
                    byId[tok->varId] = vp;
                    continue;
                }
                // declaration-only function: skip variable
                continue;
            }
            // access specifier for members
            if (scope.isClassOrStructOrUnion()) {
                v.isPublic = scope.type != Scope::eClass;
                for (const Token *p = tok; p && p != scope.bodyStart; p = p->previous) {
                    if (p->str == "public" && p->next && p->next->str == ":") { v.isPublic = true; v.isPrivate = v.isProtected = false; break; }
                    if (p->str == "private" && p->next && p->next->str == ":") { v.isPrivate = true; v.isPublic = false; break; }
                    if (p->str == "protected" && p->next && p->next->str == ":") { v.isProtected = true; v.isPublic = false; break; }
                    if (p->str == "}" && p->link) p = p->link;
                }
                if (scope.type == Scope::eClass && !v.isPublic && !v.isProtected) v.isPrivate = true;
            }
            scope.varlist.push_back(v);
            byId[tok->varId] = &scope.varlist.back();
        }
    }
    // argument variables of functions: use the Function's argumentList copies as canonical
    for (Scope &scope : scopeList) {
        for (Function &f : scope.functionList) {
            for (Variable &a : f.argumentList) {
                if (a.varId && !byId.count(a.varId)) {
                    a.scope = f.functionScope ? f.functionScope : &scope;
                    byId[a.varId] = &a;
                }
            }
        }
    }
    unsigned maxId = 0;
    for (auto &p : byId) maxId = std::max(maxId, p.first);
    variableList.assign(maxId + 1, nullptr);
    for (auto &p : byId) variableList[p.first] = p.second;
    // make sure argument variables in functionScope varlist match the function argumentList pointers
    for (Scope &scope : scopeList) {
        for (Function &f : scope.functionList) {
            if (!f.functionScope) continue;
            for (Variable &a : f.argumentList) {
                if (!a.varId) continue;
                const Variable *canon = variableList[a.varId];
                if (canon && canon != &a) {
                    // copy flags from canonical into argument entry so both are consistent
                    const_cast<Variable*>(canon)->isArgument = true;
                    const_cast<Variable*>(canon)->index = a.index;
                    const_cast<Variable*>(canon)->hasDefault = a.hasDefault;
                    const_cast<Variable*>(canon)->isLocal = false;
                }
            }
        }
    }
}

void SymbolDatabase::setTokenPointers() {
    for (Token *tok = mTokenList.front(); tok; tok = tok->next) {
        if (tok->varId != 0) {
            tok->variable = getVariableFromVarId(tok->varId);
            if (tok->variable) tok->tokType = Token::eVariable;
        }
    }
    // function calls
    for (Token *tok = mTokenList.front(); tok; tok = tok->next) {
        if (!tok->isName() || tok->varId != 0 || !tok->next || tok->next->str != "(") continue;
        if (tok->function) continue;
        if (tok->isKeyword()) continue;
        const Function *f = findFunction(tok);
        if (f) { tok->function = f; if (tok->tokType == Token::eName) tok->tokType = Token::eFunction; }
    }
    // type pointers
    for (Token *tok = mTokenList.front(); tok; tok = tok->next) {
        if (!tok->isName() || tok->varId != 0) continue;
        auto it = mTypesByName.find(tok->str);
        if (it != mTypesByName.end()) tok->type = it->second;
    }
}

void SymbolDatabase::createAST() {
    createAst(mTokenList);
    // update dimension values from AST
    for (Scope &scope : scopeList) {
        for (Variable &v : scope.varlist) {
            for (size_t i = 0; i < v.dimensions.size(); ++i) {
                if (v.dimensionKnown[i]) continue;
                const Token *d = v.dimensions[i];
                if (d->astOperand2 && d->astOperand2->hasKnownIntValue()) { v.dimensionValues[i] = d->astOperand2->getKnownIntValue(); v.dimensionKnown[i] = true; }
            }
        }
    }
}

const Scope *SymbolDatabase::findScopeByName(const std::string &name) const {
    for (const Scope &s : scopeList) if (s.className == name && (s.isClassOrStructOrUnion() || s.type == Scope::eNamespace)) return &s;
    return nullptr;
}

const Type *SymbolDatabase::findType(const Token *startTok, const Scope *startScope) const {
    (void)startScope;
    if (!startTok) return nullptr;
    auto it = mTypesByName.find(startTok->str);
    return it == mTypesByName.end() ? nullptr : it->second;
}

const Function *SymbolDatabase::findFunction(const Token *tok) const {
    if (!tok) return nullptr;
    // qualified: Class::f
    const Scope *searchScope = nullptr;
    if (tok->previous && tok->previous->str == "::" && tok->previous->previous && tok->previous->previous->isName()) {
        searchScope = findScopeByName(tok->previous->previous->str);
        if (!searchScope) return nullptr;
        return searchScope->findFunction(tok->str);
    }
    if (tok->previous && (tok->previous->str == "." || tok->previous->str == "->")) {
        // member call: find class of object
        const Token *obj = tok->previous->previous;
        if (obj && obj->str == ")" && obj->link) obj = obj->link->previous;
        if (obj && obj->str == "]" && obj->link) obj = obj->link->previous;
        if (obj && obj->variable && obj->variable->typeScope) return obj->variable->typeScope->findFunction(tok->str);
        if (obj && obj->str == "this" ) {
            const Scope *s = tok->scope;
            while (s && !s->isClassOrStructOrUnion()) s = s->nestedIn;
            if (s) return s->findFunction(tok->str);
        }
        return nullptr;
    }
    // search enclosing scopes
    int argCount = 0;
    if (tok->next && tok->next->str == "(" && tok->next->link) {
        if (tok->next->next != tok->next->link) {
            argCount = 1;
            for (const Token *a = tok->next->next; a && a != tok->next->link; a = a->next) {
                if ((a->str == "(" || a->str == "[" || a->str == "{" || a->str == "<") && a->link) { a = a->link; continue; }
                if (a->str == ",") ++argCount;
            }
        }
    }
    for (const Scope *s = tok->scope; s; s = s->nestedIn) {
        const Function *best = nullptr;
        for (const Function &f : s->functionList) {
            if (f.name != tok->str) continue;
            if (argCount >= f.minArgCount() && (argCount <= f.argCount() || f.isVariadic)) return &f;
            if (!best) best = &f;
        }
        if (best) return best;
    }
    return nullptr;
}
