static bool isTypeQualifier(const std::string &s) {
    return s == "const" || s == "static" || s == "extern" || s == "mutable" || s == "struct" || s == "union" || s == "enum" || s == "class" || s == "unsigned" || s == "signed" || s == "long" || s == "short" || s == "volatile" || s == "typename" || s == "register";
}

// Parse a variable declaration whose name token is nameTok (varId != 0). Fill Variable.
static void fillVariable(Variable &var, Token *nameTok, const Scope *scope, const Library &library, bool isCPP, std::map<std::string, const Type*> &typesByName) {
    var.nameToken = nameTok;
    var.name = nameTok->str;
    var.varId = nameTok->varId;
    var.scope = scope;
    // find type start: walk backwards over * & const and type names
    Token *t = nameTok->previous;
    Token *typeEnd = t;
    // function pointer "( * name )"
    if (t && t->str == "*" && t->previous && t->previous->str == "(") {
        var.isFunctionPointer = true;
        var.isPointer = true;
        Token *paren = t->previous;
        typeEnd = paren->previous;
        t = typeEnd;
    }
    while (t && (t->str == "*" || t->str == "&" || t->str == "&&" || t->str == "const" || t->str == "restrict")) {
        if (t->str == "*") { var.isPointer = true; ++var.pointerDepth; }
        if (t->str == "&") var.isReference = true;
        if (t->str == "&&") { var.isReference = true; var.isRValueRef = true; }
        if (t->str == "const" && var.isPointer) var.isConstPointer = true;
        t = t->previous;
    }
    // template args / qualified names
    while (t) {
        if (t->str == ">" && t->link) { t = t->link->previous; continue; }
        if (t->isName() && !t->isKeyword()) {
            if (t->previous && t->previous->str == "::") { t = t->previous->previous; continue; }
            // more type words before?
            Token *p = t->previous;
            if (p && p->isName() && (isTypeQualifier(p->str) || p->isStandardType())) { t = p; continue; }
            break;
        }
        if (t->isName() && t->isKeyword() && (isTypeQualifier(t->str) || t->isStandardType())) {
            Token *p = t->previous;
            if (p && p->isName() && (isTypeQualifier(p->str) || p->isStandardType() || (!p->isKeyword() && p->tokType == Token::eType))) { t = p; continue; }
            break;
        }
        if (t->str == "::" ) { t = t->previous; continue; }
        break;
    }
    var.typeStartToken = t ? t : nameTok;
    var.typeEndToken = typeEnd ? typeEnd : nameTok;
    // flags from type tokens
    std::string typeName;
    for (Token *x = var.typeStartToken; x && x != nameTok; x = x->next) {
        if (x->str == "static") var.isStatic = true;
        else if (x->str == "extern") var.isExtern = true;
        else if (x->str == "mutable") var.isMutable = true;
        else if (x->str == "volatile") var.isVolatile = true;
        else if (x->str == "const") { if (!var.isPointer || x == var.typeStartToken || (x->previous && x->previous->str != "*")) { if (!var.isPointer) var.isConst = true; } }
        else if (x->str == "unsigned") var.isUnsigned = true;
        else if (x->str == "*" || x->str == "&" || x->str == "&&") {}
        else if (x->isName()) {
            if (x->str == "struct" || x->str == "union" || x->str == "enum" || x->str == "class" || x->str == "signed" || x->str == "typename") continue;
            if (!typeName.empty()) typeName += " ";
            typeName += x->str;
        } else if (x->str == "::") typeName += "::";
        else if (x->str == "<" && x->link) {
            typeName += "<";
            for (Token *y = x->next; y && y != x->link; y = y->next) typeName += y->str;
            typeName += ">";
            x = x->link;
        }
    }
    // "T * const p" -> const pointer; "const T *p" -> pointer to const (isConst false)
    if (var.isPointer) {
        // isConst for pointer means the pointer itself is const
        var.isConst = var.isConstPointer;
    }
    var.typeName = typeName;
    const Token *baseTypeTok = nullptr;
    for (Token *x = var.typeStartToken; x && x != nameTok; x = x->next) {
        if (x->isName() && !isTypeQualifier(x->str) && x->str != "const") { baseTypeTok = x; }
    }
    if (baseTypeTok) {
        const std::string &bt = baseTypeTok->str;
        if (baseTypeTok->isStandardType()) {
            var.isIntegral = (bt == "int" || bt == "long" || bt == "short" || bt == "char" || bt == "size_t" || bt == "wchar_t" || bt == "bool" || bt == "_Bool" || bt == "char8_t" || bt == "char16_t" || bt == "char32_t");
            var.isFloatingType = (bt == "float" || bt == "double");
            var.isBool = (bt == "bool" || bt == "_Bool");
            var.isCharType = (bt == "char");
            var.isVoid = (bt == "void");
        } else {
            if (library.podTypes.count(bt)) { var.isIntegral = true; }
            else {
                var.isClass = true;
                auto it = typesByName.find(bt);
                if (it != typesByName.end()) { var.type = it->second; var.typeScope = it->second->classScope; var.isEnumType = it->second->isEnum; if (var.isEnumType) { var.isClass = false; var.isIntegral = true; } }
                if (typeName.compare(0, 5, "std::") == 0) var.isStlType = true;
                if (library.smartPointers.count(bt) || library.smartPointers.count(typeName.substr(0, typeName.find('<')))) var.isSmartPointer = true;
            }
        }
        if (var.isUnsigned && typeName.empty()) var.isIntegral = true;
    } else if (var.isUnsigned) { var.isIntegral = true; var.typeName = "int"; }
    // dimensions
    Token *d = nameTok->next;
    while (d && d->str == "[" && d->link) {
        var.isArray = true;
        var.dimensions.push_back(d);
        if (d->next != d->link && d->next->isNumber() && d->next->next == d->link) { var.dimensionValues.push_back(toLongNumber(d->next->str)); var.dimensionKnown.push_back(true); }
        else if (d->next == d->link) { var.dimensionValues.push_back(0); var.dimensionKnown.push_back(false); }
        else {
            // try constant expression
            long long v = 0; bool known = false;
            if (d->astOperand2 && d->astOperand2->hasKnownIntValue()) { v = d->astOperand2->getKnownIntValue(); known = true; }
            var.dimensionValues.push_back(v); var.dimensionKnown.push_back(known);
        }
        d = d->link->next;
    }
    var.declEndToken = d;
    if (d && d->str == "=") var.isInit = true;
    if (d && (d->str == "(" || d->str == "{") && isCPP) var.isInit = true;
    if (var.isReference) var.isInit = true;
    // location flags
    if (scope) {
        if (scope->type == Scope::eGlobal || scope->type == Scope::eNamespace) var.isGlobal = true;
        else if (scope->isClassOrStructOrUnion()) { var.isMember = true; var.isStructMember = true; }
        else var.isLocal = true;
    }
}

void SymbolDatabase::createScopes() {
    scopeList.emplace_back();
    Scope *global = &scopeList.back();
    global->type = Scope::eGlobal;
    global->bodyStart = mTokenList.front();
    std::vector<Scope*> stack;
    stack.push_back(global);
    std::map<std::string, const Type*> typesByName;

    for (Token *tok = mTokenList.front(); tok; tok = tok->next) {
        Scope *current = stack.back();
        if (tok->str == "{" && tok->link) {
            Scope sc;
            sc.nestedIn = current;
            sc.bodyStart = tok;
            sc.bodyEnd = tok->link;
            Token *prev = tok->previous;
            bool handled = false;
            // class/struct/union/enum
            {
                Token *p = prev;
                // skip inheritance list / enum base
                if (p && p->str == ":" ) {}
                Token *q = p;
                // find "class|struct|union|enum NAME" before '{', allowing ": base..." in between
                int guard = 0;
                while (q && q->str != ";" && q->str != "{" && q->str != "}" && q->str != ")" && guard++ < 50) {
                    if ((q->str == "class" || q->str == "struct" || q->str == "union" || q->str == "enum") && q->next && q->next->isName()) break;
                    if (q->str == "typedef") break;
                    q = q->previous;
                }
                if (q && (q->str == "class" || q->str == "struct" || q->str == "union" || q->str == "enum") && q->next && q->next->isName() && !(q->previous && q->previous->str == "typedef" && false)) {
                    // make sure the name is followed by '{' or ':' or 'final'
                    Token *n = q->next;
                    if (q->str == "enum" && n->str == "class") { sc.enumClass = true; n = n->next; }
                    Token *afterName = n->next;
                    if (afterName == tok || (afterName && (afterName->str == ":" || afterName->str == "final"))) {
                        if (q->str == "enum") sc.type = Scope::eEnum;
                        else if (q->str == "class") sc.type = Scope::eClass;
                        else if (q->str == "struct") sc.type = Scope::eStruct;
                        else sc.type = Scope::eUnion;
                        sc.className = n->str;
                        sc.classDef = q;
                        handled = true;
                        // Type
                        typeList.emplace_back();
                        Type &ty = typeList.back();
                        ty.classDef = q;
                        ty.name = n->str;
                        ty.enclosingScope = current;
                        ty.isEnum = sc.type == Scope::eEnum;
                        ty.isClass = sc.type == Scope::eClass;
                        ty.isStruct = sc.type == Scope::eStruct;
                        ty.isUnion = sc.type == Scope::eUnion;
                        sc.definedType = &ty;
                        typesByName[n->str] = &ty;
                    }
                }
            }
            if (!handled && prev && prev->str == "namespace") { sc.type = Scope::eNamespace; sc.classDef = prev; handled = true; }
            if (!handled && prev && prev->isName() && prev->previous && prev->previous->str == "namespace") { sc.type = Scope::eNamespace; sc.className = prev->str; sc.classDef = prev->previous; handled = true; }
            if (!handled && prev && prev->str == ")" && prev->link) {
                Token *kw = prev->link->previous;
                if (kw && (kw->str == "if" || kw->str == "for" || kw->str == "while" || kw->str == "switch" || kw->str == "catch")) {
                    if (kw->str == "if") sc.type = Scope::eIf;
                    else if (kw->str == "for") sc.type = Scope::eFor;
                    else if (kw->str == "while") sc.type = Scope::eWhile;
                    else if (kw->str == "switch") sc.type = Scope::eSwitch;
                    else sc.type = Scope::eCatch;
                    sc.classDef = kw;
                    handled = true;
                } else if (kw && kw->isName() && !kw->isKeyword()) {
                    // function definition
                    sc.type = Scope::eFunction;
                    sc.classDef = kw;
                    handled = true;
                } else if (kw && kw->str == "]" && kw->link) {
                    // lambda
                    sc.type = Scope::eLambda;
                    sc.classDef = kw->link;
                    handled = true;
                } else if (kw && (kw->str == ">" )) {
                    sc.type = Scope::eFunction; sc.classDef = kw; handled = true;
                }
            }
            if (!handled && prev && (prev->str == "const" || prev->str == "override" || prev->str == "final" || prev->str == "noexcept")) {
                // function with qualifiers: "f ( ) const {"
                Token *p = prev;
                while (p && p->isName()) p = p->previous;
                if (p && p->str == ")" && p->link && p->link->previous && p->link->previous->isName()) {
                    sc.type = Scope::eFunction; sc.classDef = p->link->previous; handled = true;
                }
            }
            if (!handled && prev && prev->str == ")" && prev->link && prev->link->previous && prev->link->previous->str == ")") {
                // constructor initializer list: "Foo ( ) : x ( 1 ) {"
                Token *p = prev;
                // walk back to ':' then to the ')' of the parameter list
                while (p && p->str != ":" && p->str != ";" && p->str != "{" && p->str != "}") { if (p->str == ")" && p->link) p = p->link; p = p->previous; }
                if (p && p->str == ":" && p->previous && p->previous->str == ")" && p->previous->link && p->previous->link->previous && p->previous->link->previous->isName()) {
                    sc.type = Scope::eFunction; sc.classDef = p->previous->link->previous; handled = true;
                }
            }
            if (!handled && prev && prev->isName() && !prev->isKeyword() && prev->previous && (prev->previous->str == "," || prev->previous->str == ":")) {
                // "Foo ( ) : x { 1 } {"  brace init in initializer list -> not a scope
                // treat as unconditional to keep structure
                Token *p = prev;
                while (p && p->str != ":" && p->str != ";" && p->str != "{" && p->str != "}") { if ((p->str == ")" || p->str == "}") && p->link) p = p->link; p = p->previous; }
                if (p && p->str == ":" && p->previous && p->previous->str == ")" ) {
                    // this '{' is an initializer, not a scope: skip
                    tok = tok->link;
                    continue;
                }
            }
            if (!handled && prev && prev->str == "else") { sc.type = Scope::eElse; sc.classDef = prev; handled = true; }
            if (!handled && prev && prev->str == "do") { sc.type = Scope::eDo; sc.classDef = prev; handled = true; }
            if (!handled && prev && prev->str == "try") { sc.type = Scope::eTry; sc.classDef = prev; handled = true; }
            if (!handled && prev && (prev->str == "=" || prev->str == "," || prev->str == "(" || prev->str == "return" || prev->str == "{" && current->type != Scope::eGlobal && false)) {
                // initializer list -> not a scope
                tok = tok->link;
                continue;
            }
            if (!handled && prev && prev->str == "{" ) {
                // nested braces in initializer? or block
                if (!current->isExecutable()) { tok = tok->link; continue; }
            }
            if (!handled && prev && prev->str == "]" && prev->link) {
                // lambda without params
                sc.type = Scope::eLambda; sc.classDef = prev->link; handled = true;
            }
            if (!handled && prev && prev->str == "->") { // lambda with trailing return type
                sc.type = Scope::eLambda; handled = true;
            }
            if (!handled) {
                if (current->isExecutable()) { sc.type = Scope::eUnconditional; sc.classDef = tok; handled = true; }
                else {
                    // unknown braces at non-executable scope (e.g. "struct X {" with typedef, "extern "C" {" handled earlier, macro bodies)
                    sc.type = Scope::eUnconditional; sc.classDef = tok; handled = true;
                }
            }
            scopeList.push_back(sc);
            Scope *nsc = &scopeList.back();
            if (nsc->definedType) const_cast<Type*>(nsc->definedType)->classScope = nsc;
            current->nestedList.push_back(nsc);
            stack.push_back(nsc);
            continue;
        }
        if (tok->str == "}" && tok->link) {
            if (stack.size() > 1) stack.pop_back();
            continue;
        }
    }
    mTypesByName = typesByName;
    // set scope pointers on tokens
    {
        std::vector<const Scope*> st;
        st.push_back(global);
        for (Token *tok = mTokenList.front(); tok; tok = tok->next) {
            if (tok->str == "{" && tok->link) {
                // find scope with this bodyStart
                const Scope *found = nullptr;
                for (const Scope *s : st.back()->nestedList) if (s->bodyStart == tok) { found = s; break; }
                tok->scope = st.back();
                if (found) st.push_back(found);
                else st.push_back(st.back());
                continue;
            }
            if (tok->str == "}" && tok->link) {
                if (st.size() > 1) st.pop_back();
                tok->scope = st.back();
                continue;
            }
            tok->scope = st.back();
        }
    }
    // functions
    for (Scope &scope : scopeList) {
        if (scope.type == Scope::eFunction || scope.type == Scope::eLambda) functionScopes.push_back(&scope);
        if (scope.isClassOrStruct()) classAndStructScopes.push_back(&scope);
    }
}

void SymbolDatabase::createFunctions(Scope &scope) {
    (void)scope;
}

void SymbolDatabase::createVariables() {
    // Enumerators
    for (Scope &scope : scopeList) {
        if (scope.type != Scope::eEnum) continue;
        long long value = 0;
        bool known = true;
        for (Token *t = const_cast<Token*>(scope.bodyStart)->next; t && t != scope.bodyEnd; t = t->next) {
            if (!t->isName()) continue;
            Enumerator e;
            e.name = t;
            e.scope = &scope;
            if (t->next && t->next->str == "=") {
                Token *v = t->next->next;
                if (v && v->isNumber() && v->next && (v->next->str == "," || v->next == scope.bodyEnd)) { value = toLongNumber(v->str); known = true; }
                else if (v && v->str == "-" && v->next && v->next->isNumber()) { value = -toLongNumber(v->next->str); known = true; }
                else known = false;
                while (t->next && t->next->str != "," && t->next != scope.bodyEnd) t = t->next;
            }
            e.value = value; e.valueKnown = known;
            scope.enumeratorList.push_back(e);
            ++value;
        }
        for (Enumerator &e : scope.enumeratorList) const_cast<Token*>(e.name)->enumerator = &e;
    }
    // Functions: find "name ( ... )" followed by "{" or ";" in non-executable scopes
    for (Scope &scope : scopeList) {
        if (scope.type != Scope::eFunction && scope.type != Scope::eLambda) continue;
        Token *nameTok = const_cast<Token*>(scope.classDef);
        if (!nameTok) continue;
        Function f;
        f.token = nameTok;
        f.tokenDef = nameTok;
        f.name = nameTok->str;
        f.hasBody = true;
        f.functionScope = &scope;
        // argument list
        Token *argStart = nameTok->next;
        if (scope.type == Scope::eLambda) {
            // "[ ... ] ( args ) {"
            Token *close = nameTok->link;
            argStart = close ? close->next : nullptr;
            f.type = Function::eLambda;
            f.name = "";
        }
        if (argStart && argStart->str == "(" && argStart->link) {
            f.arg = argStart; f.argDef = argStart;
            // return type
            Token *r = nameTok->previous;
            if (r && r->str == "::" ) { // Class::f
                Token *cls = r->previous;
                r = cls ? cls->previous : nullptr;
                // nestedIn = class scope
                if (cls) { const Scope *cs = findScopeByName(cls->str); if (cs) f.nestedIn = cs; }
            }
            if (r && r->str == "~") { f.type = Function::eDestructor; r = r->previous; }
            Token *retEnd = r;
            while (r && (r->isName() || r->str == "*" || r->str == "&" || r->str == "::" || (r->str == ">" && r->link)) && r->str != "}" && r->str != ";" && r->str != "{") {
                if (r->str == ">" && r->link) { r = r->link->previous; continue; }
                if (r->str == "virtual") f.isVirtual = true;
                if (r->str == "static") f.isStatic = true;
                if (r->str == "explicit") f.isExplicit = true;
                if (r->str == "friend") f.isFriend = true;
                if (r->str == "extern") f.isExtern = true;
                if (r->str == "inline") f.isInline = true;
                if (r->str == "template") break;
                r = r->previous;
            }
            f.retDef = r ? r->next : mTokenList.front();
            f.retEnd = retEnd;
            if (retEnd && retEnd != nameTok) {
                std::string rt;
                for (Token *x = const_cast<Token*>(f.retDef); x && x != nameTok && x != retEnd->next; x = x->next) {
                    if (x->str == "virtual" || x->str == "static" || x->str == "explicit" || x->str == "friend" || x->str == "inline" || x->str == "extern") continue;
                    if (!rt.empty()) rt += " ";
                    rt += x->str;
                    if (x->str == "*") f.returnsPointer = true;
                    if (x->str == "&") f.returnsReference = true;
                    if (x->str == "const") f.returnsConst = true;
                }
                f.returnTypeStr = rt;
                if (rt == "void") f.returnsVoid = true;
            }
            // qualifiers after ')'
            for (Token *q = argStart->link->next; q && q != scope.bodyStart; q = q->next) {
                if (q->str == "const") f.isConst = true;
                if (q->str == "=" && q->next && q->next->str == "0") f.isPureVirtual = true;
                if (q->str == ":") break;
            }
            // class membership
            if (!f.nestedIn) f.nestedIn = scope.nestedIn;
            if (f.nestedIn && f.nestedIn->isClassOrStructOrUnion()) {
                if (f.name == f.nestedIn->className) f.type = (f.type == Function::eDestructor) ? Function::eDestructor : Function::eConstructor;
                // access
            }
            if (f.type == Function::eConstructor && f.argDef) {
                // copy constructor: "Foo ( const Foo & x )"
                Token *a = argStart->next;
                if (a && a->str == "const") a = a->next;
                if (a && a->str == f.name && a->next && a->next->str == "&" && a->next->next && a->next->next->isName() && a->next->next->next == argStart->link) f.type = Function::eCopyConstructor;
                if (a && a->str == f.name && a->next && a->next->str == "&&") f.type = Function::eMoveConstructor;
            }
            if (f.name == "operator=") f.type = Function::eOperatorEqual;
            if (f.name.compare(0, 8, "operator") == 0) f.isOperator = true;
            if (nameTok->isAttributeUnused) f.isAttributeUnused = true;
            if (nameTok->isAttributeUsed) f.isAttributeUsed = true;
            if (nameTok->isAttributeNoreturn) f.isAttributeNoreturn = true;
            if (nameTok->isAttributeConstructor) f.isAttributeConstructor = true;
            if (nameTok->isAttributeDestructor) f.isAttributeDestructor = true;
