static bool matchglob(const std::string &pattern, const std::string &name) {
    const char *p = pattern.c_str();
    const char *n = name.c_str();
    std::vector<std::pair<const char*, const char*>> backtrack;
    for (;;) {
        bool matching = true;
        while (*p != '\0' && matching) {
            switch (*p) {
            case '*':
                while (*p == '*') ++p;
                if (*p == '\0') return true;
                backtrack.emplace_back(p, n);
                break;
            case '?':
                if (*n != '\0') { ++p; ++n; } else matching = false;
                break;
            case '[': {
                // simplified: character class
                const char *q = p + 1; bool neg = false; if (*q == '!' || *q == '^') { neg = true; ++q; }
                bool found = false;
                while (*q && *q != ']') { if (*q == *n) found = true; ++q; }
                if (*q == ']' && *n && (found != neg)) { p = q + 1; ++n; } else matching = false;
                break;
            }
            default:
                if (*n == *p) { ++p; ++n; } else matching = false;
            }
        }
        if (matching && *n == '\0') return true;
        if (backtrack.empty()) return false;
        p = backtrack.back().first;
        n = backtrack.back().second;
        backtrack.pop_back();
        if (*n == '\0') return false;
        ++n;
        backtrack.emplace_back(p, n);
    }
}

bool CppCheck::isSuppressed(const ErrorMessage &msg, bool global) {
    const bool unmatchedSuppression = msg.id == "unmatchedSuppression";
    bool returnValue = false;
    std::string file = msg.callStack.empty() ? "" : msg.callStack.back().file;
    int line = msg.callStack.empty() ? 0 : msg.callStack.back().line;
    for (Suppression &s : mSettings.suppressions) {
        if (!global && !s.isLocal()) continue;
        if (unmatchedSuppression && s.errorId != msg.id) continue;
        if (s.type == Suppression::macro) continue;
        // file match
        if (!s.fileName.empty()) {
            if (file.empty()) continue;
            if (!matchglob(s.fileName, file)) continue;
        }
        bool lineOk = true;
        if (s.type == Suppression::unique && s.lineNumber != -1 && s.lineNumber != line) {
            if (!(s.thisAndNextLine && s.lineNumber + 1 == line)) lineOk = false;
        }
        if (s.type == Suppression::block && (line < s.lineBegin || line > s.lineEnd)) lineOk = false;
        if (!lineOk) continue;
        if (!s.fileName.empty()) s.checked = true;
        if (!s.errorId.empty() && !matchglob(s.errorId, msg.id)) continue;
        if (!s.symbolName.empty()) {
            bool symOk = false;
            for (const std::string &sym : msg.symbolNames) if (matchglob(s.symbolName, sym)) symOk = true;
            if (!symOk) continue;
        }
        s.matched = true;
        s.checked = true;
        returnValue = true;
    }
    return returnValue;
}

void CppCheck::reportErr(ErrorMessage msg) {
    if (!mSettings.emitDuplicates) {
        const std::string key = msg.toString(false, "", "") + "\n" + msg.id + "\n" + (msg.callStack.empty() ? "" : msg.callStack.back().file + ":" + std::to_string(msg.callStack.back().line) + ":" + std::to_string(msg.callStack.back().column));
        if (mErrorList.count(key)) return;
        mErrorList.insert(key);
    }
    if (isSuppressed(msg, true)) return;
    if (isCriticalErrorId(msg.id)) criticalErrors.insert(msg.id);
    ++mExitCode;
    mLogger.reportErr(msg);
}

