static void parseInlineSuppressions(const std::vector<SuppressionComment> &comments, const std::string &file, Settings &settings, std::vector<ErrorMessage> &errors, const std::vector<PPToken> &rawTokens) {
    // Determine next code line for each comment
    std::list<Suppression> blockBegins;
    for (const SuppressionComment &c : comments) {
        std::string text = c.text;
        if (text.compare(0, 2, "//") == 0) text = text.substr(2);
        else if (text.compare(0, 2, "/*") == 0) { text = text.substr(2); if (text.size() >= 2 && text.compare(text.size() - 2, 2, "*/") == 0) text = text.substr(0, text.size() - 2); }
        // trim
        std::string::size_type s = text.find_first_not_of(" \t");
        if (s == std::string::npos) continue;
        text = text.substr(s);
        if (text.compare(0, 16, "cppcheck-suppress") != 0) continue;
        std::string rest = text.substr(16);
        Suppression::Type type = Suppression::unique;
        if (rest.compare(0, 6, "-begin") == 0) { type = Suppression::blockBegin; rest = rest.substr(6); }
        else if (rest.compare(0, 4, "-end") == 0) { type = Suppression::blockEnd; rest = rest.substr(4); }
        else if (rest.compare(0, 5, "-file") == 0) { type = Suppression::file; rest = rest.substr(5); }
        else if (rest.compare(0, 6, "-macro") == 0) { type = Suppression::macro; rest = rest.substr(6); }
        if (!rest.empty() && rest[0] != ' ' && rest[0] != '\t' && rest[0] != '[') continue;
        s = rest.find_first_not_of(" \t");
        if (s == std::string::npos) continue;
        rest = rest.substr(s);
        // strip trailing whitespace/newline
        while (!rest.empty() && (rest.back() == ' ' || rest.back() == '\t' || rest.back() == '\r' || rest.back() == '\n')) rest.pop_back();
        std::vector<std::string> specs;
        if (!rest.empty() && rest[0] == '[') {
            std::string::size_type e = rest.find(']');
            if (e == std::string::npos) continue;
            std::string inner = rest.substr(1, e - 1);
            std::string::size_type p = 0;
            while (p < inner.size()) {
                std::string::size_type comma = inner.find(',', p);
                std::string item = inner.substr(p, comma == std::string::npos ? std::string::npos : comma - p);
                std::string::size_type a = item.find_first_not_of(" \t"), b = item.find_last_not_of(" \t");
                if (a != std::string::npos) specs.push_back(item.substr(a, b - a + 1));
                if (comma == std::string::npos) break;
                p = comma + 1;
            }
        } else {
            // first word is the id, optional ";" separated attributes, rest is comment
            std::string::size_type sp = rest.find_first_of(" \t");
            specs.push_back(sp == std::string::npos ? rest : rest.substr(0, sp));
        }
        // find the line of the next code token after the comment (or same line if comment is after code)
        int line = c.line;
        bool thisAndNextLine = false;
        if (!c.sameLine) {
            // find next raw token with line > c.line (for block comments: after end)
            int afterLine = c.line;
            // compute end line of block comments
            for (char ch : c.text) if (ch == '\n') ++afterLine;
            int found = -1;
            for (const PPToken &t : rawTokens) {
                if (t.fileIndex != c.fileIndex) continue;
                if (t.line > afterLine || (t.line == afterLine && t.col > c.col)) { found = t.line; break; }
            }
            if (found > 0) line = found;
            else line = afterLine + 1;
            if (type == Suppression::unique) {
                // allow suppression for this and next line when a comment is between? cppcheck: thisAndNextLine when comment is on its own line? No.
            }
        }
        for (const std::string &spec : specs) {
            Suppression sup;
            // parse id and optional attributes "id symbolName=x"
            std::string id = spec;
            std::string::size_type semi = id.find(';');
            if (semi != std::string::npos) id = id.substr(0, semi);
            sup.errorId = id;
            sup.fileName = file;
            sup.isInline = true;
            sup.type = type;
            sup.thisAndNextLine = thisAndNextLine;
            if (type == Suppression::file) {
                if (c.line != 1 && !(c.line <= 1)) {
                    // must be at top of file: cppcheck checks that no code precedes
                    bool codeBefore = false;
                    for (const PPToken &t : rawTokens) { if (t.fileIndex == c.fileIndex && (t.line < c.line)) { codeBefore = true; break; } }
                    if (codeBefore) {
                        ErrorMessage err;
                        err.callStack.emplace_back(file, c.line, 0);
                        err.id = "invalidSuppression";
                        err.severity = Severity::error;
                        err.setMessage("File suppression should be at the top of the file");
                        errors.push_back(err);
                        continue;
                    }
                }
                sup.lineNumber = -1;
                sup.type = Suppression::unique;
                sup.fileName = file;
            } else if (type == Suppression::blockBegin) {
                sup.lineBegin = line;
                sup.lineNumber = line;
                blockBegins.push_back(sup);
                continue;
            } else if (type == Suppression::blockEnd) {
                bool found = false;
                for (auto it = blockBegins.begin(); it != blockBegins.end(); ++it) {
                    if (it->errorId == id) {
                        Suppression b = *it;
                        b.type = Suppression::block;
                        b.lineEnd = c.line;
                        blockBegins.erase(it);
                        bool dup = false;
                        for (const Suppression &e : settings.suppressions) if (e.errorId == b.errorId && e.fileName == b.fileName && e.lineBegin == b.lineBegin && e.type == b.type) dup = true;
                        if (!dup) settings.suppressions.push_back(b);
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    ErrorMessage err;
                    err.callStack.emplace_back(file, c.line, 0);
                    err.id = "invalidSuppression";
                    err.severity = Severity::error;
                    err.setMessage("Suppress End: No matching begin");
                    errors.push_back(err);
                }
                continue;
            } else if (type == Suppression::macro) {
                sup.macroName = id;
                sup.errorId = "";
                continue; // not supported
            } else {
                sup.lineNumber = line;
            }
            bool dup = false;
            for (const Suppression &e : settings.suppressions) if (e.errorId == sup.errorId && e.fileName == sup.fileName && e.lineNumber == sup.lineNumber && e.type == sup.type && e.isInline) dup = true;
            if (!dup) settings.suppressions.push_back(sup);
        }
    }
    for (const Suppression &b : blockBegins) {
        ErrorMessage err;
        err.callStack.emplace_back(file, b.lineBegin, 0);
        err.id = "invalidSuppression";
        err.severity = Severity::error;
        err.setMessage("Suppress Begin: No matching end");
        errors.push_back(err);
    }
}

unsigned CppCheck::check(const FileWithDetails &file) {
    mCurrentFile = file.path;
    const unsigned exitBefore = mExitCode;
    mErrorList.clear();
    const bool isCPP = file.lang == Settings::CPP || (file.lang == Settings::None && mSettings.enforcedLang != Settings::C);
    bool langCPP = isCPP;
    if (mSettings.enforcedLang == Settings::C) langCPP = false;
    else if (mSettings.enforcedLang == Settings::CPP) langCPP = true;

    auto a = computeActiveCheckers(mSettings, langCPP, mSettings.checkConfiguration);
    if (!mSettings.preprocessOnly) activeCheckers.insert(a.begin(), a.end());

    Preprocessor preprocessor(mSettings);
    std::string errmsg;
    if (!preprocessor.loadFile(file.path, errmsg)) {
        return 0;
    }

    // Library defines
    std::vector<std::string> libDefines = mLibrary.defineList;

    // inline suppressions
    if (mSettings.inlineSuppressions) {
        std::vector<ErrorMessage> errs;
        parseInlineSuppressions(preprocessor.comments(), file.path, mSettings, errs, preprocessor.rawTokens());
        for (ErrorMessage &e : errs) { e.file0 = file.path; reportErr(e); }
    }

    // configurations
    std::set<std::string> configurations;
    bool forceAll = mSettings.force;
    try {
        if ((mSettings.userDefinesStr.empty()) || mSettings.force) {
            // Need the include files' tokens for getConfigs: run a preliminary preprocess to populate cache
            std::vector<PPError> dummyErrors;
            preprocessor.preprocess(mSettings.userDefinesStr, libDefines, dummyErrors, false);
            configurations = preprocessor.getConfigs(libDefines);
        } else {
            configurations.insert(mSettings.userDefinesStr);
        }
    } catch (const std::runtime_error &e) {
        ErrorMessage msg;
        msg.callStack.emplace_back(file.path, 0, 0);
        msg.id = "internalError";
        msg.severity = Severity::error;
        msg.setMessage(std::string("Bailing out from analysis: Checking file failed: ") + e.what());
        reportErr(msg);
        return mExitCode - exitBefore;
    }

    if (mSettings.checkConfiguration) {
        // report missing includes only
        if (mSettings.checkMissingInclude || mSettings.sev_information) {
            for (const std::string &cfg : configurations) {
                std::vector<PPError> errors;
                preprocessor.preprocess(cfg, libDefines, errors, mSettings.checkMissingInclude);
                for (const PPError &e : errors) {
                    if (e.id == "__abort__") continue;
                    if (e.id == "missingInclude" || e.id == "missingIncludeSystem") {
                        ErrorMessage msg;
                        msg.callStack.emplace_back(e.file, e.line, e.col);
                        msg.id = e.id; msg.severity = Severity::information; msg.setMessage(e.msg);
                        msg.file0 = file.path;
                        reportErr(msg);
                    }
                }
            }
        }
        return mExitCode - exitBefore;
    }

    // Too many configurations
    if (!mSettings.force && (int)configurations.size() > mSettings.maxConfigs) {
        if (mSettings.sev_information) {
            ErrorMessage msg;
            msg.callStack.emplace_back(file.path, 0, 0);
            msg.id = "toomanyconfigs";
            msg.severity = Severity::information;
            msg.cwe = 398;
            msg.setMessage("Too many #ifdef configurations - cppcheck only checks " + std::to_string(mSettings.maxConfigs) + " of " + std::to_string(configurations.size()) + " configurations. Use --force to check all configurations.\nThe checking of the file will be interrupted because there are too many #ifdef configurations. Checking of all #ifdef configurations can be forced by --force command line option or from GUI preferences. However that may increase the checking time.");
            msg.file0 = file.path;
            reportErr(msg);
        }
    }

    int checkCount = 0;
    bool hasValidConfig = false;
    std::vector<std::string> configurationError;
    std::set<std::string> hashes;
    bool reportedMissingIncludes = false;
    for (const std::string &currCfg : configurations) {
        std::string cfg;
        if (!mSettings.userDefinesStr.empty()) {
            cfg = mSettings.userDefinesStr;
            // append config items not in user defines
            std::vector<std::string> v1;
            { std::string::size_type s = 0; while (true) { std::string::size_type p = mSettings.userDefinesStr.find(';', s); v1.push_back(mSettings.userDefinesStr.substr(s, p == std::string::npos ? std::string::npos : p - s)); if (p == std::string::npos) break; s = p + 1; } }
            std::string::size_type s = 0;
            while (s <= currCfg.size() && !currCfg.empty()) {
                std::string::size_type p = currCfg.find(';', s);
                std::string item = currCfg.substr(s, p == std::string::npos ? std::string::npos : p - s);
                if (!item.empty() && std::find(v1.begin(), v1.end(), item) == v1.end()) cfg += ";" + item;
                if (p == std::string::npos) break;
                s = p + 1;
            }
        } else cfg = currCfg;

        if (mSettings.preprocessOnly) {
            std::vector<PPError> errors;
            std::vector<PPToken> toks = preprocessor.preprocess(cfg, libDefines, errors, false);
            bool aborted = false;
            for (const PPError &e : errors) if (e.id == "__abort__") aborted = true;
            if (aborted) continue;
            std::string code = Preprocessor::stringify(toks, preprocessor.files());
            mLogger.reportOut(code);
            continue;
        }

        if (!mSettings.force && ++checkCount > mSettings.maxConfigs) break;

        std::vector<PPError> errors;
        std::vector<PPToken> toks = preprocessor.preprocess(cfg, libDefines, errors, (mSettings.checkMissingInclude) && !reportedMissingIncludes);
        bool aborted = false;
        PPError abortErr;
        for (size_t i = 0; i < errors.size(); ++i) {
            if (errors[i].id == "__abort__") { aborted = true; if (i > 0) abortErr = errors[i-1]; }
        }
        // missing include messages
        for (const PPError &e : errors) {
            if (e.id == "missingInclude" || e.id == "missingIncludeSystem") {
                ErrorMessage msg;
                msg.callStack.emplace_back(e.file, e.line, e.col);
                msg.id = e.id; msg.severity = Severity::information; msg.setMessage(e.msg);
                msg.file0 = file.path;
                reportErr(msg);
            }
        }
        reportedMissingIncludes = true;
        if (aborted) {
            configurationError.push_back((cfg.empty() ? "''" : cfg) + " : [" + abortErr.file + ':' + std::to_string(abortErr.line) + "] " + abortErr.msg);
            --checkCount;
            if (!hasValidConfig && currCfg == *configurations.rbegin()) {
                ErrorMessage msg;
                msg.callStack.emplace_back(abortErr.file, abortErr.line, abortErr.col);
                msg.id = abortErr.id.empty() ? "preprocessorErrorDirective" : abortErr.id;
                if (msg.id == "syntaxError") msg.id = "preprocessorErrorDirective";
                msg.severity = Severity::error;
                msg.setMessage(abortErr.msg);
                reportErr(msg);
            }
            continue;
        }
        hasValidConfig = true;

        Tokenizer tokenizer(mSettings, mLibrary);
        tokenizer.createTokens(toks, preprocessor.files(), langCPP);
        tokenizer.list.sourceFile = file.path;

        if (!mSettings.quiet && (!cfg.empty() || checkCount > 1)) {
            mLogger.reportOut("Checking " + file.path + ": " + cfg + "...");
        }
        if (!tokenizer.list.front()) continue;

        try {
            tokenizer.simplifyTokens1(cfg);
            // hash of simplified token list to skip duplicates
            if (mSettings.force || mSettings.maxConfigs > 1) {
                std::string h = tokenizer.list.stringify(true);
                if (hashes.count(h)) {
                    if (mSettings.debugwarnings) {
                        ErrorMessage msg;
                        msg.callStack.emplace_back(file.path, 0, 0);
                        msg.id = "purgedConfiguration"; msg.severity = Severity::information;
                        msg.setMessage("The configuration '" + cfg + "' was not checked because its code equals another one.");
                        reportErr(msg);
                    }
                    continue;
                }
                hashes.insert(h);
            }
            SymbolDatabase symdb(tokenizer.list, mSettings, mLibrary);
            runValueFlow(tokenizer.list, symdb, mSettings, mLibrary);
            if (mSettings.debugnormal) {
                mLogger.reportOut("\n\n##file " + file.path + "\n" + tokenizer.list.stringify(true));
            }
            std::vector<std::unique_ptr<Check>> checks = createChecks(tokenizer, symdb, mSettings, mLibrary, *this);
            for (auto &c : checks) {
                try { c->runChecks(); }
                catch (const InternalError &e) {
                    ErrorMessage msg;
                    if (e.token) msg.callStack.emplace_back(tokenizer.list.files[e.token->fileIndex], e.token->linenr, e.token->column);
                    else msg.callStack.emplace_back(file.path, 0, 0);
                    msg.id = e.id; msg.severity = Severity::error; msg.setMessage(e.errorMessage); msg.file0 = file.path;
                    reportErr(msg);
                }
            }
            // unused functions: collect
            if (mSettings.checkUnusedFunction) checkUnusedFunctionsParse(*this, tokenizer, symdb, file.path);
        } catch (const InternalError &e) {
            ErrorMessage msg;
            if (e.token) msg.callStack.emplace_back(tokenizer.list.files[e.token->fileIndex], e.token->linenr, e.token->column);
            else msg.callStack.emplace_back(file.path, 0, 0);
            msg.id = e.id;
            msg.severity = Severity::error;
            msg.setMessage(e.errorMessage + (e.details.empty() ? "" : "\n" + e.errorMessage + ": " + e.details));
            msg.file0 = file.path;
            reportErr(msg);
        }
    }

    if (!hasValidConfig && configurations.size() > 1 && mSettings.sev_information && !mSettings.preprocessOnly) {
        std::string msg = "This file is not analyzed. Cppcheck failed to extract a valid configuration. Use -v for more details.";
        msg += "\nThis file is not analyzed. Cppcheck failed to extract a valid configuration. The tested configurations have these preprocessor errors:";
        for (const std::string &s : configurationError) msg += '\n' + s;
        ErrorMessage err;
        err.callStack.emplace_back(file.path, 0, 0);
        err.id = "noValidConfiguration"; err.severity = Severity::information; err.setMessage(msg);
        reportErr(err);
    }

    // mark file-level suppressions as checked
    for (Suppression &s : mSettings.suppressions) {
        if (s.isLocal() && s.fileName == file.path && s.lineNumber == -1 && s.type == Suppression::unique) s.checked = true;
    }
    return mExitCode - exitBefore;
}

unsigned CppCheck::analyseWholeProgram() {
    const unsigned before = mExitCode;
    if (mSettings.checkUnusedFunction && !mSettings.checkConfiguration && !mSettings.preprocessOnly) {
        for (const auto &p : mFunctionUsage) {
            const FuncUsage &u = p.second;
            if (u.used || u.usedOtherFile) continue;
            if (u.file.empty() || u.line == 0) continue;
            const std::string &name = p.first;
            if (name == "main" || name == "WinMain" || name == "_tmain" || name == "if" || name == "wmain" || name == "DllMain") continue;
            if (name.compare(0, 4, "test") == 0 && false) continue;
            ErrorMessage msg;
            msg.callStack.emplace_back(u.file, u.line, u.col);
            msg.id = "unusedFunction";
            msg.severity = Severity::style;
            msg.cwe = 561;
            msg.setMessage("The function '" + name + "' is never used.");
            msg.file0 = u.displayFile;
            reportErr(msg);
        }
    }
    return mExitCode - before;
}
