static void setKnown(Token *tok, long long v) {
    for (ValueFlowValue &e : tok->values) if (e.valueType == ValueFlowValue::INT && e.isKnown()) { e.intvalue = v; return; }
    ValueFlowValue val; val.intvalue = v; val.known = true;
