#include "check.h"
#include <functional>
#include <algorithm>

static void setKnown(Token *tok, long long v) {
    for (ValueFlowValue &e : tok->values) if (e.valueType == ValueFlowValue::INT && e.isKnown()) { e.intvalue = v; return; }
    ValueFlowValue val; val.intvalue = v; val.known = true;
    tok->values.push_back(val);
}

static bool getKnown(const Token *tok, long long &v) {
    if (!tok) return false;
    const ValueFlowValue *val = tok->getKnownValue();
    if (!val) return false;
    v = val->intvalue;
    return true;
}

static void foldConstants(Token *tok) {
    // recursive post-order over AST
    if (!tok) return;
    if (tok->astOperand1) foldConstants(tok->astOperand1);
    if (tok->astOperand2) foldConstants(tok->astOperand2);
    if (tok->hasKnownIntValue()) return;
    const Token *a = tok->astOperand1, *b = tok->astOperand2;
    long long va, vb;
    if (tok->isCast && a && getKnown(a, va)) { setKnown(tok, va); return; }
    if (a && b) {
        const std::string &op = tok->str;
        if (op == "&&") {
            bool ka = getKnown(a, va), kb = getKnown(b, vb);
            if (ka && va == 0) setKnown(tok, 0);
            else if (kb && vb == 0) setKnown(tok, 0);
            else if (ka && kb) setKnown(tok, (va && vb) ? 1 : 0);
            return;
        }
        if (op == "||") {
            bool ka = getKnown(a, va), kb = getKnown(b, vb);
            if (ka && va != 0) setKnown(tok, 1);
            else if (kb && vb != 0) setKnown(tok, 1);
            else if (ka && kb) setKnown(tok, (va || vb) ? 1 : 0);
            return;
        }
        if (!getKnown(a, va) || !getKnown(b, vb)) return;
        if (op == "+") setKnown(tok, va + vb);
        else if (op == "-") setKnown(tok, va - vb);
        else if (op == "*") setKnown(tok, va * vb);
        else if (op == "/") { if (vb != 0) setKnown(tok, va / vb); }
        else if (op == "%") { if (vb != 0) setKnown(tok, va % vb); }
        else if (op == "<<") { if (vb >= 0 && vb < 64) setKnown(tok, va << vb); }
        else if (op == ">>") { if (vb >= 0 && vb < 64) setKnown(tok, va >> vb); }
        else if (op == "&") setKnown(tok, va & vb);
        else if (op == "|") setKnown(tok, va | vb);
        else if (op == "^") setKnown(tok, va ^ vb);
        else if (op == "==") setKnown(tok, va == vb);
        else if (op == "!=") setKnown(tok, va != vb);
        else if (op == "<") setKnown(tok, va < vb);
        else if (op == ">") setKnown(tok, va > vb);
        else if (op == "<=") setKnown(tok, va <= vb);
        else if (op == ">=") setKnown(tok, va >= vb);
        else if (op == "," ) {}
        return;
    }
    if (a && !b) {
        if (!getKnown(a, va)) return;
        if (tok->str == "!") setKnown(tok, !va);
        else if (tok->str == "-") setKnown(tok, -va);
        else if (tok->str == "+") setKnown(tok, va);
        else if (tok->str == "~") setKnown(tok, ~va);
        else if (tok->str == "(" && !tok->isCast) {}
    }
}

static void foldAll(TokenList &list) {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (!tok->astParent && (tok->astOperand1 || tok->astOperand2)) foldConstants(tok);
    }
}

// Is the variable modified in the given range (excluding reads)?
static bool isVarWrittenAt(const Token *tok) {
    // tok is a variable token. Determine whether this usage writes to it.
    const Token *parent = tok->astParent;
    const Token *cur = tok;
    // skip array index / member access on the lhs: a[i] = x counts as write to a (partial)
    while (parent && ((parent->str == "[" && parent->astOperand1 == cur) || (parent->str == "." && parent->astOperand1 == cur))) { cur = parent; parent = parent->astParent; }
    if (!parent) return false;
    if (parent->isAssignmentOp() && parent->astOperand1 == cur) return true;
    if ((parent->str == "++" || parent->str == "--")) return true;
    if (parent->str == "&" && !parent->astOperand2) {
        // address taken -> assume modified unless passed as const
        return true;
    }
    if (parent->str == "(" && parent->astOperand2 && cur == parent->astOperand2) {
        // passed by value to a function: no modification (for non-pointer). For pointer: may modify pointee, not the pointer.
        return false;
    }
    if (parent->str == "," ) {
        // function argument: find if passed by reference in C++ -> unknown. Assume unchanged for value.
        return false;
    }
    return false;
}

const Token *findVariableChanged(const Token *start, const Token *end, unsigned varid) {
    for (const Token *tok = start; tok && tok != end; tok = tok->next) {
        if (tok->varId != varid) continue;
        if (isVarWrittenAt(tok)) return tok;
        // passed to function by reference (C++) or as pointer "&x" handled by isVarWrittenAt
        const Token *parent = tok->astParent;
        if (parent && parent->str == "&" && !parent->astOperand2) return tok;
        // C++: passing non-const reference: unknown -> conservatively treat as changed when passed directly to a function call
        if (tok->isCpp) {
            const Token *p = tok;
            while (p->astParent && (p->astParent->str == "," )) p = p->astParent;
            if (p->astParent && p->astParent->str == "(" && p->astParent->astOperand2 && p->astParent->astOperand1 && p->astParent->astOperand1 != tok) {
                // argument of a function call
                const Token *fn = p->astParent->astOperand1;
                if (fn->function) {
                    // find the argument index
                    int idx = 0;
                    const Token *arg = tok;
                    while (arg->astParent && arg->astParent->str == ",") {
                        if (arg->astParent->astOperand2 == arg) { // count args in left subtree
                            const Token *l = arg->astParent->astOperand1; int c = 1; while (l && l->str == ",") { ++c; l = l->astOperand1; } idx += c;
                        }
                        arg = arg->astParent;
                    }
                    const Variable *av = fn->function->getArgumentVar(idx);
                    if (av && av->isReference && !av->isConst) return tok;
                    if (av && av->isReference && av->isConst) continue;
                } else if (!fn->isStandardType() && !(fn->isName() && fn->tokType == Token::eType)) {
                    // unknown function: assume by reference possible? cppcheck assumes unknown function may modify through reference
                    if (!tok->variable || (!tok->variable->isPointer && !tok->variable->isArray)) return tok;
                }
            }
            // member call x.f() -> may modify
            if (parent && (parent->str == "." ) && parent->astOperand1 == tok && parent->astParent && parent->astParent->str == "(") return tok;
        }
    }
    return nullptr;
}

bool isVariableChanged(const Token *start, const Token *end, unsigned varid, bool cpp) {
    (void)cpp;
    return findVariableChanged(start, end, varid) != nullptr;
}

static bool isEscapeFunction(const Token *tok, const Library &library) {
    if (!tok || !tok->isName()) return false;
    if (library.isnoreturn(tok->str)) return true;
    if (tok->function && tok->function->isAttributeNoreturn) return true;
    if (tok->isAttributeNoreturn) return true;
    return false;
}

bool isReturnScope(const Token *endToken) {
    if (!endToken || endToken->str != "}") return false;
    const Token *prev = endToken->previous;
    while (prev && prev->str == ";") prev = prev->previous;
    if (!prev) return false;
    if (prev->str == "}" && prev->link) {
        const Token *open = prev->link;
        if (open->previous && open->previous->str == "else") {
            // if/else both return?
            return false;
        }
        return false;
    }
    // find statement start
    const Token *stmt = prev;
    while (stmt->previous && stmt->previous->str != ";" && stmt->previous->str != "{" && stmt->previous->str != "}") stmt = stmt->previous;
    if (stmt->str == "return" || stmt->str == "throw" || stmt->str == "break" || stmt->str == "continue" || stmt->str == "goto") return true;
    if (stmt->isName() && stmt->next && stmt->next->str == "(" && stmt->isAttributeNoreturn) return true;
    return false;
}

bool isEscapeScope(const Token *start, const Library &library) {
    if (!start || start->str != "{" || !start->link) return false;
    const Token *end = start->link;
    const Token *prev = end->previous;
    while (prev && prev->str == ";") prev = prev->previous;
    if (!prev || prev == start) return false;
    const Token *stmt = prev;
    while (stmt->previous && stmt->previous->str != ";" && stmt->previous->str != "{" && stmt->previous->str != "}") stmt = stmt->previous;
    if (stmt->str == "return" || stmt->str == "throw" || stmt->str == "break" || stmt->str == "continue" || stmt->str == "goto") return true;
    if (stmt->isName() && stmt->next && stmt->next->str == "(" && isEscapeFunction(stmt, library)) return true;
    return false;
}

bool isFunctionCallNoReturn(const Token *nameTok, const Library &library) { return isEscapeFunction(nameTok, library); }

bool precedes(const Token *a, const Token *b) {
    if (!a || !b) return false;
    if (a->fileIndex != b->fileIndex) return a->fileIndex < b->fileIndex;
    for (const Token *t = a; t; t = t->next) if (t == b) return true;
    return false;
}

const Token *nextAfterAstRightmostLeaf(const Token *tok) {
    const Token *rightmost = tok;
    while (rightmost && (rightmost->astOperand2 || rightmost->astOperand1)) rightmost = rightmost->astOperand2 ? rightmost->astOperand2 : rightmost->astOperand1;
    if (rightmost && rightmost->link && (rightmost->str == "(" || rightmost->str == "[" || rightmost->str == "{")) return rightmost->link->next;
    return rightmost ? rightmost->next : nullptr;
}

bool astIsPointer(const Token *tok) {
    if (!tok) return false;
    if (tok->variable) {
        if (tok->astParent && tok->astParent->str == "[" && tok->astParent->astOperand1 == tok) return tok->variable->pointerDepth > 1 || (tok->variable->isArray && tok->variable->isPointer);
        return tok->variable->isPointer || tok->variable->isArray;
    }
    if (tok->str == "&" && !tok->astOperand2) return true;
    if (tok->str == "*" && !tok->astOperand2 && tok->astOperand1 && tok->astOperand1->variable) return tok->astOperand1->variable->pointerDepth > 1;
    if (tok->isCast && tok->astOperand1) {
        for (const Token *t = tok->next; t && t != tok->link; t = t->next) if (t->str == "*") return true;
        return false;
    }
    if (tok->str == "(" && tok->astOperand1 && tok->astOperand1->function) return tok->astOperand1->function->returnsPointer;
    if (tok->tokType == Token::eString) return true;
    if ((tok->str == "+" || tok->str == "-") && tok->astOperand1 && tok->astOperand2) return astIsPointer(tok->astOperand1) || astIsPointer(tok->astOperand2);
    if (tok->str == "?" && tok->astOperand2 && tok->astOperand2->str == ":") return astIsPointer(tok->astOperand2->astOperand1);
    return false;
}
bool astIsIntegral(const Token *tok) {
    if (!tok) return false;
    if (tok->variable) return tok->variable->isIntegral && !tok->variable->isPointer && !tok->variable->isArray;
    if (tok->isNumber()) return isIntLiteral(tok->str);
    if (tok->tokType == Token::eChar || tok->tokType == Token::eBoolean) return true;
    if (tok->isComparisonOp() || tok->isLogicalOp()) return true;
    if (tok->isArithmeticalOp() && tok->astOperand1 && tok->astOperand2) return astIsIntegral(tok->astOperand1) && astIsIntegral(tok->astOperand2);
    return false;
}
bool astIsBool(const Token *tok) {
    if (!tok) return false;
    if (tok->variable) return tok->variable->isBool && !tok->variable->isPointer;
    if (tok->tokType == Token::eBoolean) return true;
    if (tok->isComparisonOp() || tok->str == "&&" || tok->str == "||" || tok->str == "!") return true;
    if (tok->str == "(" && tok->astOperand1 && tok->astOperand1->function) return tok->astOperand1->function->returnTypeStr == "bool";
    return false;
}
bool astIsFloat(const Token *tok) {
    if (!tok) return false;
    if (tok->variable) return tok->variable->isFloatingType && !tok->variable->isPointer;
    if (tok->isNumber()) return !isIntLiteral(tok->str);
    if (tok->isArithmeticalOp() && tok->astOperand1 && tok->astOperand2) return astIsFloat(tok->astOperand1) || astIsFloat(tok->astOperand2);
    return false;
}
bool isConstExpression(const Token *tok) {
    if (!tok) return true;
    if (tok->varId) return false;
    if (tok->str == "(" && tok->astOperand1 && !tok->isCast) return false;
    return isConstExpression(tok->astOperand1) && isConstExpression(tok->astOperand2);
}

bool isSameExpression(const Token *tok1, const Token *tok2) {
    if (!tok1 || !tok2) return tok1 == tok2;
    if (tok1->str != tok2->str) return false;
    if (tok1->varId != tok2->varId) return false;
    if (tok1->isCast != tok2->isCast) return false;
    if (tok1->str == "(" && tok1->astOperand1 && !tok1->isCast) {
        // function call: only same if pure/const function - be conservative: not same
        const Token *fn = tok1->astOperand1;
        if (fn->isName() && !(fn->str == "sizeof")) return false;
    }
    if (!isSameExpression(tok1->astOperand1, tok2->astOperand1)) return false;
    if (!isSameExpression(tok1->astOperand2, tok2->astOperand2)) return false;
    return true;
}

std::string tokenTypeStr(const Variable *var) { return var ? var->typeName : ""; }

// ---------------------------------------------------------------------------
// Forward value flow for local variables
// ---------------------------------------------------------------------------
namespace {

struct VarValue {
    long long value;
    bool known;
    ErrorPath path;
    const Token *assignTok = nullptr;
    bool isNull = false;
    bool uninit = false;
    bool conditional = false;
};

static std::string valueToStr(long long v) { return std::to_string(v); }

static void addValue(Token *tok, const VarValue &vv) {
    ValueFlowValue val;
    val.intvalue = vv.value;
    val.known = vv.known;
    val.conditional = vv.conditional;
    for (const auto &p : vv.path) val.errorPath.push_back(p);
    if (vv.uninit) { val.valueType = ValueFlowValue::UNINIT; }
    // avoid duplicates
    for (const ValueFlowValue &e : tok->values) if (e.valueType == val.valueType && e.intvalue == val.intvalue) return;
    tok->values.push_back(val);
}

// Determine the scope-end token for forward analysis: walk tokens from start to end of the enclosing function scope.
static const Token *getScopeEnd(const Token *tok) {
    const Scope *s = tok->scope;
    while (s && !s->isExecutable()) s = s->nestedIn;
    if (!s) return nullptr;
    return s->bodyEnd;
}

// Is tok a read of the variable (not a write)?
static bool isWriteAccess(const Token *tok) {
    const Token *parent = tok->astParent;
    if (!parent) return false;
    if (parent->isAssignmentOp() && parent->astOperand1 == tok && parent->str == "=") return true;
    if ((parent->str == "++" || parent->str == "--")) return true;
    return false;
}

// Forward propagate variable value from assignment token to subsequent uses
static void forwardVar(Token *assignTok, Token *varTok, VarValue vv, const Library &library, const Settings &settings, bool cpp) {
    (void)settings;
    const unsigned varid = varTok->varId;
    const Variable *var = varTok->variable;
    if (!var) return;
    const Token *scopeEnd = getScopeEnd(varTok);
    if (!scopeEnd) return;
    // start after the statement
    Token *start = assignTok;
    while (start && start->str != ";" && start->str != "{" && start->str != "}") {
        if ((start->str == "(" || start->str == "[" || start->str == "{") && start->link && start->str != "{") start = start->link;
        start = start->next;
    }
    if (!start) return;
    // for "int x ; x = 1 ;" handled: start at ';'
    // track scope depth; conditional blocks make values "possible"
    int depth = 0;
    bool knownNow = vv.known;
    std::vector<bool> depthKnown;
    const Token *loopEnd = nullptr; // when inside a loop body entered after assignment, values are possible only
    for (Token *tok = start->next; tok && tok != scopeEnd; tok = tok->next) {
        if (tok->str == "{" && tok->link) {
            const Token *prev = tok->previous;
            bool conditional = false;
            if (prev && prev->str == ")" && prev->link) {
                const Token *kw = prev->link->previous;
                if (kw && (kw->str == "if" || kw->str == "for" || kw->str == "while" || kw->str == "switch")) {
                    conditional = true;
                    // the condition itself is evaluated with the known value (handled since condition tokens precede '{')
                    // inside a loop body the variable could be modified in the loop -> if modified in body, stop
                    if (kw->str == "for" || kw->str == "while") {
                        if (findVariableChanged(tok, tok->link, varid)) return;
                    }
                }
            } else if (prev && (prev->str == "else" || prev->str == "do")) conditional = true;
            else if (prev && prev->str == "=" ) { tok = tok->link; continue; }
            depthKnown.push_back(knownNow);
            if (conditional) knownNow = false;
            ++depth;
            continue;
        }
        if (tok->str == "}" ) {
            if (depth == 0) break;
            --depth;
            // after a conditional block: if the var was changed inside the block, the value becomes unknown
            const Token *open = tok->link;
            if (findVariableChanged(open, tok, varid)) return;
            // if the block is an escape scope (returns) - then the value remains known after it
            knownNow = depthKnown.back();
            depthKnown.pop_back();
            // 'else' following: handle by continuing
            continue;
        }
        if (tok->str == "return" || tok->str == "break" || tok->str == "continue" || tok->str == "goto" || tok->str == "throw") {
            // values in the return expression still apply; after the statement, this path ends
            // continue scanning the expression, then when we hit ';' at depth>0 we just continue (other paths)
            if (depth == 0) {
                // scan the return expression then stop
                for (Token *t = tok->next; t && t->str != ";"; t = t->next) {
                    if (t->varId == varid && !isWriteAccess(t)) addValue(t, vv);
                }
                return;
            }
        }
        if (tok->varId == varid) {
            if (isWriteAccess(tok)) {
                if (depth == 0) return; // reassigned
                // assigned inside conditional block: value after block unknown -> handled at '}' via findVariableChanged
                // skip rest of this block
                continue;
            }
            // address taken -> stop (value may change)
            if (tok->astParent && tok->astParent->str == "&" && !tok->astParent->astOperand2) {
                if (depth == 0) return;
                continue;
            }
            // passed by non-const reference (C++)
            if (cpp && findVariableChanged(tok, tok->next, varid)) { if (depth == 0) return; continue; }
            // pointer being dereferenced for write "*p = x" is not a change of p
            VarValue v2 = vv;
            v2.known = knownNow;
            addValue(tok, v2);
        }
        // function call with unknown side effects on a global/static -> stop
        if (tok->str == "(" && tok->previous && tok->previous->isName() && (var->isGlobal || var->isStatic)) {
            return;
        }
        // asm -> stop
        if (tok->str == "asm") return;
    }
}

static bool getAssignedValue(const Token *rhs, VarValue &vv) {
    if (!rhs) return false;
    const ValueFlowValue *val = rhs->getKnownValue();
    if (val) { vv.value = val->intvalue; vv.known = true; vv.isNull = (val->intvalue == 0); return true; }
    return false;
}

static void valueFlowAssignments(TokenList &list, const Library &library, const Settings &settings) {
    const bool cpp = list.isCPP;
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (tok->str != "=" || !tok->astOperand1 || !tok->astOperand2) continue;
        if (tok->astParent) continue; // nested assignment
        Token *lhs = tok->astOperand1;
        if (!lhs->varId || !lhs->variable) continue;
        const Variable *var = lhs->variable;
        if (!var->isLocal && !var->isArgument) continue;
        if (var->isStatic || var->isReference || var->isArray) continue;
        if (var->isClass && !var->isPointer) continue;
        VarValue vv;
        if (!getAssignedValue(tok->astOperand2, vv)) continue;
        std::string exprStr = lhs->str + "=" + tok->astOperand2->expressionString();
        vv.path.emplace_back(tok, "Assignment '" + exprStr + "', assigned value is " + valueToStr(vv.value));
        vv.assignTok = tok;
        forwardVar(tok, lhs, vv, library, settings, cpp);
    }
}

// Values from conditions: "if (x == 0) {" -> inside block x is 0 (possible); "if (!p)" -> p is 0; "if (p == NULL)".
static void valueFlowConditions(TokenList &list, const Library &library, const Settings &settings) {
    (void)library; (void)settings;
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (!(tok->str == "(" && tok->astOperand1 && (tok->astOperand1->str == "if" || tok->astOperand1->str == "while") && tok->astOperand2)) continue;
        const Token *cond = tok->astOperand2;
        Token *body = tok->link ? tok->link->next : nullptr;
        if (!body || body->str != "{" || !body->link) continue;
        // collect simple conditions: var == num, var != num, !var, var
        struct C { unsigned varid; long long value; bool inThen; const Token *varTok; };
        std::vector<C> conds;
        std::function<void(const Token*, bool)> collect = [&](const Token *c, bool negate) {
            if (!c) return;
            if (c->str == "&&" && !negate) { collect(c->astOperand1, false); collect(c->astOperand2, false); return; }
            if (c->str == "||" && negate) { collect(c->astOperand1, true); collect(c->astOperand2, true); return; }
            if (c->str == "!" && c->astOperand1 && !c->astOperand2) { collect(c->astOperand1, !negate); return; }
            if ((c->str == "==" || c->str == "!=") && c->astOperand1 && c->astOperand2) {
                const Token *v = nullptr, *n = nullptr;
                if (c->astOperand1->varId && c->astOperand2->hasKnownIntValue()) { v = c->astOperand1; n = c->astOperand2; }
                else if (c->astOperand2->varId && c->astOperand1->hasKnownIntValue()) { v = c->astOperand2; n = c->astOperand1; }
                if (!v) return;
                bool eq = (c->str == "==") != negate;
                if (eq) conds.push_back({v->varId, n->getKnownIntValue(), true, v});
                else conds.push_back({v->varId, n->getKnownIntValue(), false, v});
                return;
            }
            if (c->varId && c->variable) {
                // "if (p)" -> in else p is 0; "if (!p)" -> in then p is 0
                conds.push_back({c->varId, 0, negate, c});
                return;
            }
        };
        collect(cond, false);
        for (const C &c : conds) {
            const Variable *var = c.varTok->variable;
            if (!var) continue;
            if (var->isArray) continue;
            // then-branch: value applies in body; else-branch: applies in else block
            Token *blockStart = nullptr;
            if (c.inThen) blockStart = body;
            else {
                Token *after = body->link->next;
                if (after && after->str == "else" && after->next && after->next->str == "{") blockStart = after->next;
                else continue;
            }
            // if variable is modified in the block, bail
            if (findVariableChanged(blockStart, blockStart->link, c.varid)) continue;
            VarValue vv;
            vv.value = c.value;
            vv.known = false;
            vv.conditional = true;
            vv.isNull = (c.value == 0);
            std::string condStr = cond->expressionString();
            vv.path.emplace_back(cond, "Assuming that condition '" + condStr + "' is not redundant");
            for (Token *t = blockStart->next; t && t != blockStart->link; t = t->next) {
                if (t->varId == c.varid && !isWriteAccess(t)) {
                    if (t->astParent && t->astParent->str == "&" && !t->astParent->astOperand2) break;
                    addValue(t, vv);
                }
            }
            // after an if-block that returns, the opposite applies after the block (then-branch escape): "if (!p) return; *p" -> p nonzero; skip
        }
    }
}

// Uninitialized variables: mark reads of local variables without initialization before first write
static bool isLikelyInitFunctionArg(const Token *tok) {
    // &x passed to function -> treated as initialization
    const Token *p = tok->astParent;
    return p && p->str == "&" && !p->astOperand2;
}

static void valueFlowUninit(TokenList &list, SymbolDatabase &db, const Library &library) {
    (void)library;
    for (const Scope *scope : db.functionScopes) {
        for (const Variable &var : scope->varlist) {
            if (var.isArgument || var.isStatic || var.isExtern || var.isInit || var.isReference) continue;
            if (!var.nameToken || !var.declEndToken || var.declEndToken->str != ";") continue;
            if (var.isClass && !var.isPointer && !var.isArray) continue; // class with ctor
            if (var.isArray && var.isClass) continue;
            const unsigned varid = var.varId;
            // forward from declaration
            const Token *scopeEnd = var.scope ? var.scope->bodyEnd : nullptr;
            if (!scopeEnd) continue;
            int depth = 0;
            bool known = true;
            std::vector<bool> depthKnown;
            for (Token *tok = const_cast<Token*>(var.declEndToken)->next; tok && tok != scopeEnd; tok = tok->next) {
                if (tok->str == "{" && tok->link) {
                    const Token *prev = tok->previous;
                    bool conditional = false;
                    if (prev && prev->str == ")" && prev->link) {
                        const Token *kw = prev->link->previous;
                        if (kw && (kw->str == "if" || kw->str == "for" || kw->str == "while" || kw->str == "switch")) conditional = true;
                        // variable written in condition? e.g. while ((x = f()) ...)
                    } else if (prev && (prev->str == "else" || prev->str == "do")) conditional = true;
                    else if (prev && prev->str == "=") { tok = tok->link; continue; }
                    // if the variable is initialized inside a conditional block, we must stop after the block (possibly initialized)
                    depthKnown.push_back(known);
                    if (conditional) known = false;
                    ++depth;
                    continue;
                }
                if (tok->str == "}") {
                    if (depth == 0) break;
                    --depth;
                    const Token *open = tok->link;
                    // initialized inside block? -> stop analysis (may be initialized)
                    bool init = false;
                    for (const Token *t = open; t && t != tok; t = t->next) {
                        if (t->varId == varid) {
                            if (isWriteAccess(t) || isLikelyInitFunctionArg(t)) { init = true; break; }
                            if (var.isArray && t->astParent && t->astParent->str == "[" && t->astParent->astOperand1 == t) {
                                const Token *p = t->astParent; while (p->astParent && p->astParent->str == "[") p = p->astParent;
                                if (p->astParent && p->astParent->isAssignmentOp() && p->astParent->astOperand1 == p) { init = true; break; }
                            }
                            if (var.isPointer && t->astParent && t->astParent->str == "*" && !t->astParent->astOperand2) {}
                        }
                    }
                    if (init) { tok = nullptr; break; }
                    known = depthKnown.back();
                    depthKnown.pop_back();
                    continue;
                }
                if (tok->varId != varid) {
                    // goto/labels -> bail
                    if (tok->str == "goto" || tok->str == "asm") break;
                    continue;
                }
                // usage
                if (isWriteAccess(tok)) {
                    if (depth == 0) break;
                    continue;
                }
                if (isLikelyInitFunctionArg(tok)) { if (depth == 0) break; continue; }
                // array element write a[i] = x
                if (var.isArray) {
                    const Token *p = tok->astParent;
                    if (p && p->str == "[" && p->astOperand1 == tok) {
                        while (p->astParent && p->astParent->str == "[") p = p->astParent;
                        if (p->astParent && p->astParent->isAssignmentOp() && p->astParent->astOperand1 == p) { if (depth == 0) break; continue; }
                    }
                    // array passed to function: assume initialized (e.g. strcpy(buf, ..))
                    if (p && (p->str == "(" || p->str == ",")) {
                        // check library: if argument direction is 'in' -> read
                        const Token *call = tok; while (call->astParent && call->astParent->str == ",") call = call->astParent;
                        const Token *fn = (call->astParent && call->astParent->str == "(") ? call->astParent->astOperand1 : nullptr;
                        bool isRead = false;
                        if (fn && fn->isName()) {
                            const LibFunction *lf = library.getFunction(fn->str);
                            if (lf) {
                                int idx = 1; const Token *a = tok; while (a->astParent && a->astParent->str == ",") { if (a->astParent->astOperand2 == a) { const Token *l = a->astParent->astOperand1; int c = 1; while (l && l->str == ",") { ++c; l = l->astOperand1; } idx += c; } a = a->astParent; }
                                auto it = lf->args.find(idx);
                                if (it != lf->args.end() && (it->second.notuninit || it->second.direction == "in")) isRead = true;
                            }
                        }
                        if (!isRead) { if (depth == 0) break; continue; }
                    }
                    // sizeof(a) -> not a read
                    if (p && p->str == "(" && p->astOperand1 && p->astOperand1->str == "sizeof") continue;
