                    if (p && p->str == "[" && p->astOperand1 == tok) {
                        // report at tok
                    } else if (p && (p->str == "." || p->str == "->")) {
                    } else if (!p || !(p->str == "=" && p->astOperand2 == tok)) {
                        // array used as pointer: not uninit read (decays) except dereference
                        if (!(p && p->str == "*" && !p->astOperand2)) continue;
                    } else {
                        continue; // "ptr = arr" is fine
                    }
                }
                if (var.isPointer) {
                    // "p->x" / "*p" reads p; "p = ..." write handled. Passing "p" to function reads it.
                }
                // struct/union member write: "s.x = 1" -> partial init: cppcheck tracks members; we bail
                if (!var.isPointer && var.isClass) {
                    const Token *p = tok->astParent;
                    if (p && p->str == "." && p->astOperand1 == tok) {
                        const Token *q = p; while (q->astParent && q->astParent->str == ".") q = q->astParent;
                        if (q->astParent && q->astParent->isAssignmentOp() && q->astParent->astOperand1 == q) { if (depth == 0) break; continue; }
                    }
                    if (p && (p->str == "(" || p->str == ",")) { if (depth == 0) break; continue; }
                }
                // sizeof(x) is not a read
                {
                    const Token *p = tok->astParent;
                    bool inSizeof = false;
                    while (p) { if (p->str == "(" && p->astOperand1 && p->astOperand1->str == "sizeof") { inSizeof = true; break; } p = p->astParent; }
