                        bool byRef = false;
                        if (fn->function) {
                            int idx = 0; const Token *a = tok; while (a->astParent && a->astParent->str == ",") { if (a->astParent->astOperand2 == a) { const Token *l = a->astParent->astOperand1; int c = 1; while (l && l->str == ",") { ++c; l = l->astOperand1; } idx += c; } a = a->astParent; }
                            const Variable *av = fn->function->getArgumentVar(idx);
