}

// for loops: "for (int i = 0; i < N; i++)" -> i has possible values 0 and N-1 (or N for <=) inside body
static void valueFlowForLoop(TokenList &list) {
    for (Token *tok = list.front(); tok; tok = tok->next) {
        if (!(tok->str == "for" && tok->next && tok->next->str == "(" && tok->next->link)) continue;
        Token *paren = tok->next;
        Token *semi1 = paren->astOperand2;
        if (!semi1 || semi1->str != ";") continue;
        Token *init = semi1->astOperand1;
        Token *semi2 = semi1->astOperand2;
        if (!semi2) continue;
        Token *cond = semi2->astOperand1;
        Token *inc = semi2->astOperand2;
        if (!init || !cond || !inc) continue;
        if (init->str != "=" || !init->astOperand1 || !init->astOperand1->varId || !init->astOperand2 || !init->astOperand2->hasKnownIntValue()) continue;
        const unsigned varid = init->astOperand1->varId;
        long long startVal = init->astOperand2->getKnownIntValue();
        if (!cond->isComparisonOp() || !cond->astOperand1 || cond->astOperand1->varId != varid || !cond->astOperand2 || !cond->astOperand2->hasKnownIntValue()) continue;
        long long limit = cond->astOperand2->getKnownIntValue();
        long long lastVal;
        bool incrementing = false;
        if ((inc->str == "++" ) && inc->astOperand1 && inc->astOperand1->varId == varid) incrementing = true;
        else if (inc->str == "+=" && inc->astOperand1 && inc->astOperand1->varId == varid && inc->astOperand2 && inc->astOperand2->hasKnownIntValue() && inc->astOperand2->getKnownIntValue() == 1) incrementing = true;
        bool decrementing = false;
        if ((inc->str == "--") && inc->astOperand1 && inc->astOperand1->varId == varid) decrementing = true;
        if (incrementing) {
            if (cond->str == "<") lastVal = limit - 1;
            else if (cond->str == "<=") lastVal = limit;
            else if (cond->str == "!=") lastVal = limit - 1;
            else continue;
            if (lastVal < startVal) continue;
        } else if (decrementing) {
            if (cond->str == ">") lastVal = limit + 1;
            else if (cond->str == ">=") lastVal = limit;
            else continue;
            if (lastVal > startVal) continue;
        } else continue;
        Token *body = paren->link->next;
        if (!body || body->str != "{" || !body->link) continue;
        // variable modified in body? then skip
        if (findVariableChanged(body, body->link, varid)) continue;
        for (Token *t = body->next; t && t != body->link; t = t->next) {
            if (t->varId != varid) continue;
            if (isWriteAccess(t)) continue;
            // skip usages inside nested conditions where the condition restricts? keep simple
            // if usage is inside an if-block whose condition references the variable -> skip (likely guarded)
            bool guarded = false;
            {
                const Scope *s = t->scope;
                while (s && s->bodyStart != body) {
                    if (s->type == Scope::eIf || s->type == Scope::eElse) {
                        const Token *ifTok = s->classDef;
                        if (s->type == Scope::eElse) { const Token *ob = s->bodyStart->previous; (void)ob; }
                        if (ifTok && ifTok->next && ifTok->next->link) {
                            for (const Token *c = ifTok->next; c && c != ifTok->next->link; c = c->next) if (c->varId == varid) { guarded = true; break; }
                        }
                    }
                    if (guarded) break;
                    s = s->nestedIn;
                }
            }
            if (guarded) continue;
            ValueFlowValue v1; v1.intvalue = startVal; v1.known = false;
            v1.errorPath.emplace_back(init->astOperand1, "Assignment '" + init->astOperand1->str + "=" + std::to_string(startVal) + "', assigned value is " + std::to_string(startVal));
            ValueFlowValue v2; v2.intvalue = lastVal; v2.known = false;
            v2.errorPath.emplace_back(cond, "Assuming that condition '" + cond->expressionString() + "' is not redundant");
            bool have1 = false, have2 = false;
            for (const ValueFlowValue &e : t->values) { if (e.valueType == ValueFlowValue::INT && e.intvalue == startVal) have1 = true; if (e.valueType == ValueFlowValue::INT && e.intvalue == lastVal) have2 = true; }
            if (!have1) t->values.push_back(v1);
            if (!have2 && lastVal != startVal) t->values.push_back(v2);
        }
        // after loop: variable has known value lastVal+1 (for incrementing) if not modified in body and no break
        bool hasBreak = false;
        for (const Token *t = body->next; t && t != body->link; t = t->next) if (t->str == "break" ) { hasBreak = true; break; }
        if (!hasBreak && (incrementing || decrementing)) {
            long long after = incrementing ? lastVal + 1 : lastVal - 1;
            if (cond->str == "!=" ) after = limit;
            // propagate after the loop until modified
            const Token *scopeEnd = getScopeEnd(tok);
            int depth = 0;
            for (Token *t = body->link->next; t && t != scopeEnd; t = t->next) {
                if (t->str == "{" && t->link) { if (t->previous && t->previous->str == "=") { t = t->link; continue; } ++depth; continue; }
                if (t->str == "}") { if (depth == 0) break; --depth; if (findVariableChanged(t->link, t, varid)) break; continue; }
                if (t->varId == varid) {
                    if (isWriteAccess(t) || (t->astParent && t->astParent->str == "&" && !t->astParent->astOperand2)) break;
                    ValueFlowValue v; v.intvalue = after; v.known = (depth == 0);
                    v.errorPath.emplace_back(cond, "Assuming that condition '" + cond->expressionString() + "' is not redundant");
                    bool have = false; for (const ValueFlowValue &e : t->values) if (e.valueType == ValueFlowValue::INT && e.intvalue == after) have = true;
                    if (!have) t->values.push_back(v);
                }
            }
        }
    }
}

// re-fold after variable values are set: expressions with possible values get possible results
static void foldWithVarValues(Token *tok) {
    if (!tok) return;
    if (tok->astOperand1) foldWithVarValues(tok->astOperand1);
    if (tok->astOperand2) foldWithVarValues(tok->astOperand2);
    if (tok->hasKnownIntValue()) return;
    const Token *a = tok->astOperand1, *b = tok->astOperand2;
    auto intValues = [](const Token *t) {
        std::vector<const ValueFlowValue*> r;
        if (!t) return r;
        for (const ValueFlowValue &v : t->values) if (v.valueType == ValueFlowValue::INT && !v.impossible) r.push_back(&v);
        return r;
    };
    auto add = [&](long long v, bool known, const ValueFlowValue *src1, const ValueFlowValue *src2) {
        for (const ValueFlowValue &e : tok->values) if (e.valueType == ValueFlowValue::INT && e.intvalue == v) return;
        ValueFlowValue nv; nv.intvalue = v; nv.known = known;
        if (src1) { nv.errorPath = src1->errorPath; nv.conditional = src1->conditional; }
        if (src2) { for (auto &p : src2->errorPath) nv.errorPath.push_back(p); if (src2->conditional) nv.conditional = true; }
        tok->values.push_back(nv);
    };
    if (tok->isCast && a) { for (const ValueFlowValue *v : intValues(a)) add(v->intvalue, v->isKnown(), v, nullptr); return; }
    if (a && b) {
        const std::string &op = tok->str;
        auto va = intValues(a), vb = intValues(b);
        if (va.empty() || vb.empty()) return;
        if (va.size() * vb.size() > 16) return;
        for (const ValueFlowValue *x : va) for (const ValueFlowValue *y : vb) {
            long long p = x->intvalue, q = y->intvalue, r;
            bool known = x->isKnown() && y->isKnown();
            if (op == "+") r = p + q; else if (op == "-") r = p - q; else if (op == "*") r = p * q;
            else if (op == "/") { if (q == 0) continue; r = p / q; } else if (op == "%") { if (q == 0) continue; r = p % q; }
            else if (op == "==") r = p == q; else if (op == "!=") r = p != q; else if (op == "<") r = p < q; else if (op == ">") r = p > q;
            else if (op == "<=") r = p <= q; else if (op == ">=") r = p >= q; else if (op == "&&") r = p && q; else if (op == "||") r = p || q;
            else if (op == "&") r = p & q; else if (op == "|") r = p | q; else if (op == "^") r = p ^ q;
            else if (op == "<<") { if (q < 0 || q > 63) continue; r = p << q; } else if (op == ">>") { if (q < 0 || q > 63) continue; r = p >> q; }
            else continue;
            add(r, known, x, y);
        }
        return;
    }
    if (a && !b) {
        for (const ValueFlowValue *x : intValues(a)) {
            long long p = x->intvalue;
            if (tok->str == "!") add(!p, x->isKnown(), x, nullptr);
            else if (tok->str == "-") add(-p, x->isKnown(), x, nullptr);
            else if (tok->str == "~") add(~p, x->isKnown(), x, nullptr);
        }
    }
}

