void Check::reportError(const ErrorPath &errorPath, Severity severity, const std::string &id, const std::string &msg, int cwe, Certainty certainty) {
    if (certainty == Certainty::inconclusive && !mSettings.inconclusive) return;
    ErrorMessage em;
    for (const auto &p : errorPath) {
        if (!p.first) continue;
        em.callStack.push_back(locFromTok(p.first, mTokenizer, p.second));
    }
    em.id = id;
    em.severity = severity;
    em.setMessage(msg);
    em.cwe = cwe;
    em.certainty = certainty;
    em.file0 = mTokenizer.list.sourceFile;
    // symbol names from message: cppcheck adds symbols enclosed in $symbol: markers; we extract from "'name'" patterns where provided by callers via setMessage? Not available -> handled by callers through mSymbolNames
