class CheckBufferOverrun : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Bounds checking"; }
    void runChecks() override {
        arrayIndex();
        negativeArraySize();
        stringNotZeroTerminated();
    }
    void arrayIndex();
    void negativeArraySize();
    void stringNotZeroTerminated() {}
