                    }
                }
            }
        }
        if (reported) continue;
        // Possible values (warning-level: cppcheck reports as error with "possible" only with the condition path; message same but severity warning? No: arrayIndexOutOfBounds with possible value -> warning)
        if (indexTokens.size() == 1) {
            const Token *idx = indexTokens[0];
            if (idx->hasKnownIntValue()) continue;
            const ValueFlowValue *bad = nullptr;
            for (const ValueFlowValue &v : idx->values) {
                if (v.valueType != ValueFlowValue::INT || v.impossible) continue;
                if (v.intvalue >= dims[0] && !(addressOf && v.intvalue == dims[0])) { if (!bad || v.intvalue > bad->intvalue) bad = &v; }
            }
            if (bad) {
                if (!mSettings.sev_warning && !bad->isKnown()) {
                    // cppcheck reports possible values as warning (requires --enable=warning)
                    continue;
                }
                ErrorPath ep = bad->errorPath;
                ep.emplace_back(tok, "Array index out of bounds");
                std::vector<long long> iv{bad->intvalue};
                reportError(ep, bad->isKnown() ? Severity::error : Severity::warning, "arrayIndexOutOfBounds", arrayIndexMessage(tok, dims, {idx}, iv), 788);
                continue;
            }
            const ValueFlowValue *neg = nullptr;
            for (const ValueFlowValue &v : idx->values) {
                if (v.valueType != ValueFlowValue::INT || v.impossible) continue;
                if (v.intvalue < 0) { if (!neg || v.intvalue < neg->intvalue) neg = &v; }
            }
            if (neg) {
                if (!mSettings.sev_warning && !neg->isKnown()) continue;
                ErrorPath ep = neg->errorPath;
                ep.emplace_back(tok, "Negative array index");
                std::string array = arrayTok->expressionString();
                for (long long d : dims) array += "[" + std::to_string(d) + "]";
                reportError(ep, neg->isKnown() ? Severity::error : Severity::warning, "negativeIndex", "Array '" + array + "' accessed at index " + std::to_string(neg->intvalue) + ", which is out of bounds.", 786);
            }
        }
    }
}

void CheckBufferOverrun::negativeArraySize() {
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Variable &var : scope->varlist) {
            if (!var.isArray) continue;
            for (size_t i = 0; i < var.dimensions.size(); ++i) {
                if (var.dimensionKnown[i] && var.dimensionValues[i] < 0) {
                    reportError(var.nameToken, Severity::error, "negativeArraySize", "Declaration of array '" + var.name + "' with negative size is undefined behaviour", 758);
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// CheckNullPointer
// ---------------------------------------------------------------------------
class CheckNullPointer : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Null pointer"; }
    void runChecks() override {
        nullPointerByDeRefAndCheck();
        nullConstantDereference();
        arithmetic();
    }
    void nullPointerByDeRefAndCheck();
    void nullConstantDereference();
    void arithmetic();
    bool isPointerDeRef(const Token *tok, bool &unknown) const;
    void nullPointerError(const Token *tok, const std::string &varname, const ValueFlowValue *value, bool inconclusive);
};

bool CheckNullPointer::isPointerDeRef(const Token *tok, bool &unknown) const {
    unknown = false;
    const Token *parent = tok->astParent;
    if (!parent) return false;
    // *p
    if (parent->str == "*" && !parent->astOperand2 && parent->astOperand1 == tok) {
        // "&*p" is not a dereference
        if (parent->astParent && parent->astParent->str == "&" && !parent->astParent->astOperand2) return false;
        // sizeof(*p) not a dereference
        const Token *p = parent->astParent;
        while (p) { if (p->str == "(" && p->astOperand1 && p->astOperand1->str == "sizeof") return false; p = p->astParent; }
        return true;
    }
    // p[i]
    if (parent->str == "[" && parent->astOperand1 == tok) {
        if (parent->astParent && parent->astParent->str == "&" && !parent->astParent->astOperand2) return false;
        return true;
    }
    // p->x
    if (parent->str == "->" && parent->astOperand1 == tok) return true;
    if (parent->str == "." && parent->astOperand1 == tok && tok->variable && tok->variable->isPointer) return true;
    // function argument with not-null in library
    const Token *arg = tok;
    while (arg->astParent && arg->astParent->str == ",") arg = arg->astParent;
    if (arg->astParent && arg->astParent->str == "(" && arg->astParent->astOperand2 && arg->astParent->astOperand1 && arg->astParent->astOperand1->isName()) {
        const Token *fn = arg->astParent->astOperand1;
        const LibFunction *lf = mLibrary.getFunction(fn->str);
        if (lf) {
            int idx = 1; const Token *a = tok;
            while (a->astParent && a->astParent->str == ",") { if (a->astParent->astOperand2 == a) { const Token *l = a->astParent->astOperand1; int c = 1; while (l && l->str == ",") { ++c; l = l->astOperand1; } idx += c; } a = a->astParent; }
            auto it = lf->args.find(idx);
            if (it != lf->args.end() && it->second.notnull) return true;
        }
    }
    // assignment through: "*p = x" handled; "p = x" no
    return false;
}

void CheckNullPointer::nullPointerError(const Token *tok, const std::string &varname, const ValueFlowValue *value, bool inconclusive) {
    const std::string errmsgcond("$symbol:" + varname + '\n' + "Possible null pointer dereference if the default parameter value is used: $symbol");
    (void)errmsgcond;
    if (!tok) return;
    if (!value || value->isKnown()) {
        ErrorPath ep = getErrorPath(tok, value, "Null pointer dereference");
        ErrorMessage em;
        for (const auto &p : ep) em.callStack.push_back(FileLocation(mTokenizer.list.files[p.first->fileIndex], p.first->linenr, p.first->column, p.second));
        em.id = "nullPointer"; em.severity = Severity::error; em.cwe = 476;
        em.setMessage("Null pointer dereference: " + varname);
        em.symbolNames.push_back(varname);
        em.file0 = mTokenizer.list.sourceFile;
        em.certainty = inconclusive ? Certainty::inconclusive : Certainty::normal;
        if (inconclusive && !mSettings.inconclusive) return;
        mCppCheck.reportErr(em);
        return;
    }
    if (!mSettings.sev_warning) return;
    ErrorPath ep = getErrorPath(tok, value, "Null pointer dereference");
    ErrorMessage em;
    for (const auto &p : ep) em.callStack.push_back(FileLocation(mTokenizer.list.files[p.first->fileIndex], p.first->linenr, p.first->column, p.second));
    em.id = "nullPointer"; em.severity = Severity::warning; em.cwe = 476;
    if (value->conditional) {
        em.id = "nullPointerRedundantCheck";
        em.setMessage("Either the condition '" + (value->errorPath.empty() ? std::string("x") : value->errorPath.front().first->expressionString()) + "' is redundant or there is possible null pointer dereference: " + varname + ".");
    } else {
        em.setMessage("Possible null pointer dereference: " + varname);
    }
    em.symbolNames.push_back(varname);
    em.file0 = mTokenizer.list.sourceFile;
    em.certainty = inconclusive ? Certainty::inconclusive : Certainty::normal;
    if (inconclusive && !mSettings.inconclusive) return;
    mCppCheck.reportErr(em);
}

void CheckNullPointer::nullPointerByDeRefAndCheck() {
    for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
        if (!tok->variable || !(tok->variable->isPointer || (tok->variable->isArray && false))) continue;
        if (tok->variable->isArray && !tok->variable->isPointer) continue;
        const ValueFlowValue *value = nullptr;
        for (const ValueFlowValue &v : tok->values) if (v.valueType == ValueFlowValue::INT && !v.impossible && v.intvalue == 0) { if (!value || (v.isKnown() && !value->isKnown())) value = &v; }
        if (!value) continue;
        bool unknown;
        if (!isPointerDeRef(tok, unknown)) continue;
        // skip "if (p) ..." conditions
        nullPointerError(tok, tok->str, value, false);
    }
}

void CheckNullPointer::nullConstantDereference() {
    for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
        if (!(tok->str == "0" || tok->str == "NULL" || (mTokenizer.isCPP() && tok->str == "nullptr"))) continue;
        if (tok->varId) continue;
        const Token *parent = tok->astParent;
        if (!parent) continue;
        bool deref = false;
        if (parent->str == "*" && !parent->astOperand2 && parent->astOperand1 == tok) deref = true;
        else if (parent->str == "[" && parent->astOperand1 == tok) deref = true;
        else if (parent->str == "->" && parent->astOperand1 == tok) deref = true;
        else if (tok->str != "0") {
            // library not-null argument
            const Token *arg = tok;
            while (arg->astParent && arg->astParent->str == ",") arg = arg->astParent;
            if (arg->astParent && arg->astParent->str == "(" && arg->astParent->astOperand2 && arg->astParent->astOperand1 && arg->astParent->astOperand1->isName()) {
                const LibFunction *lf = mLibrary.getFunction(arg->astParent->astOperand1->str);
                if (lf) {
                    int idx = 1; const Token *a = tok;
                    while (a->astParent && a->astParent->str == ",") { if (a->astParent->astOperand2 == a) { const Token *l = a->astParent->astOperand1; int c = 1; while (l && l->str == ",") { ++c; l = l->astOperand1; } idx += c; } a = a->astParent; }
                    auto it = lf->args.find(idx);
                    if (it != lf->args.end() && it->second.notnull) deref = true;
                }
            }
        }
        if (!deref) continue;
        if (tok->str == "0" && !(parent->str == "*" || parent->str == "[")) continue;
        ErrorMessage em;
        em.callStack.push_back(FileLocation(mTokenizer.list.files[tok->fileIndex], tok->linenr, tok->column, "Null pointer dereference"));
        em.id = "nullPointer"; em.severity = Severity::error; em.cwe = 476;
        em.setMessage("Null pointer dereference: " + tok->str);
        em.symbolNames.push_back(tok->str);
        em.file0 = mTokenizer.list.sourceFile;
        mCppCheck.reportErr(em);
    }
}

void CheckNullPointer::arithmetic() {
    for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
        if (!(tok->str == "+" || tok->str == "-") || !tok->astOperand1 || !tok->astOperand2) continue;
        const Token *ptr = nullptr, *num = nullptr;
        if (tok->astOperand1->variable && tok->astOperand1->variable->isPointer) { ptr = tok->astOperand1; num = tok->astOperand2; }
        else if (tok->astOperand2->variable && tok->astOperand2->variable->isPointer && tok->str == "+") { ptr = tok->astOperand2; num = tok->astOperand1; }
        if (!ptr) continue;
        const ValueFlowValue *value = nullptr;
        for (const ValueFlowValue &v : ptr->values) if (v.valueType == ValueFlowValue::INT && !v.impossible && v.intvalue == 0) { if (!value || v.isKnown()) value = &v; }
        if (!value) continue;
        if (num->hasKnownIntValue() && num->getKnownIntValue() == 0) continue;
        if (!value->isKnown() && !mSettings.sev_warning) continue;
        ErrorPath ep = getErrorPath(tok, value, "Null pointer addition");
        std::string arithmetic = tok->str == "+" ? "addition" : "subtraction";
        ErrorMessage em;
        for (const auto &p : ep) em.callStack.push_back(FileLocation(mTokenizer.list.files[p.first->fileIndex], p.first->linenr, p.first->column, p.second == "Null pointer addition" ? "Null pointer " + arithmetic : p.second));
        em.id = "nullPointerArithmetic"; em.severity = value->isKnown() ? Severity::error : Severity::warning; em.cwe = 682;
        if (value->conditional) {
            em.id = "nullPointerArithmeticRedundantCheck";
            em.setMessage("Either the condition is redundant or there is overflow in pointer " + arithmetic + ".");
        } else {
            em.setMessage("Overflow in pointer arithmetic, NULL pointer is subtracted.");
            if (tok->str == "+") em.setMessage("Pointer addition with NULL pointer.");
        }
        em.file0 = mTokenizer.list.sourceFile;
        mCppCheck.reportErr(em);
    }
}

// ---------------------------------------------------------------------------
// CheckUninitVar
// ---------------------------------------------------------------------------
class CheckUninitVar : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Uninitialized variables"; }
    void runChecks() override { valueFlowUninit(); }
    void valueFlowUninit();
};

void CheckUninitVar::valueFlowUninit() {
    std::set<unsigned> reported;
    for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
        if (!tok->variable) continue;
        const ValueFlowValue *v = nullptr;
        for (const ValueFlowValue &e : tok->values) if (e.valueType == ValueFlowValue::UNINIT) v = &e;
        if (!v) continue;
        if (reported.count(tok->varId)) continue;
        if (!v->isKnown() && !mSettings.sev_warning) {
            // possible: cppcheck reports as warning? Actually uninitvar with possible value is still "error" but inconclusive-ish. Report as error.
        }
        reported.insert(tok->varId);
        ErrorMessage em;
        em.callStack.push_back(FileLocation(mTokenizer.list.files[tok->fileIndex], tok->linenr, tok->column));
        em.id = "uninitvar"; em.severity = Severity::error; em.cwe = 457;
        std::string varname = tok->str;
        if (tok->variable->isClass && !tok->variable->isPointer && tok->astParent && tok->astParent->str == "." && tok->astParent->astOperand2) {
            em.id = "uninitStructMember";
            em.setMessage("Uninitialized struct member: " + varname + "." + tok->astParent->astOperand2->str);
            em.symbolNames.push_back(varname + "." + tok->astParent->astOperand2->str);
        } else {
            em.setMessage("Uninitialized variable: " + varname);
            em.symbolNames.push_back(varname);
        }
        em.file0 = mTokenizer.list.sourceFile;
        mCppCheck.reportErr(em);
    }
}

std::vector<std::unique_ptr<Check>> createChecksCore(const Tokenizer &tokenizer, const SymbolDatabase &symdb, const Settings &settings, const Library &library, CppCheck &cppcheck) {
    std::vector<std::unique_ptr<Check>> v;
    v.push_back(std::make_unique<CheckBufferOverrun>(tokenizer, symdb, settings, library, cppcheck));
    v.push_back(std::make_unique<CheckNullPointer>(tokenizer, symdb, settings, library, cppcheck));
    v.push_back(std::make_unique<CheckUninitVar>(tokenizer, symdb, settings, library, cppcheck));
    return v;
}
