// ---------------------------------------------------------------------------
// CheckBufferOverrun
// ---------------------------------------------------------------------------
class CheckBufferOverrun : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Bounds checking"; }
    void runChecks() override {
        arrayIndex();
        negativeArraySize();
        stringNotZeroTerminated();
    }
    void arrayIndex();
    void negativeArraySize();
    void stringNotZeroTerminated() {}
};

static std::string arrayIndexMessage(const Token *tok, const std::vector<long long> &dims, const std::vector<const Token*> &indexTokens, const std::vector<long long> &indexValues) {
    std::string array = tok->astOperand1 ? tok->astOperand1->expressionString() : "x";
    for (long long d : dims) array += "[" + std::to_string(d) + "]";
    std::string index;
    if (indexValues.size() == 1) index = std::to_string(indexValues[0]);
    else {
        index = tok->astOperand1 ? tok->astOperand1->expressionString() : "x";
        for (long long v : indexValues) index += "[" + std::to_string(v) + "]";
    }
    (void)indexTokens;
    return "Array '" + array + "' accessed at index " + index + ", which is out of bounds.";
}

void CheckBufferOverrun::arrayIndex() {
    for (Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
        if (tok->str != "[" || !tok->astOperand1 || !tok->astOperand2) continue;
        // only outermost '[' of a chain: collect all indexes
        if (tok->astParent && tok->astParent->str == "[" && tok->astParent->astOperand1 == tok) continue;
        std::vector<Token*> indexTokens;
        Token *arrayTok = tok;
        while (arrayTok->str == "[" && arrayTok->astOperand1 && arrayTok->astOperand2) {
            indexTokens.insert(indexTokens.begin(), arrayTok->astOperand2);
            arrayTok = arrayTok->astOperand1;
        }
        if (!arrayTok->variable) continue;
        const Variable *var = arrayTok->variable;
        if (!var->isArray || var->dimensions.empty()) continue;
        if (var->isArgument && var->dimensions.size() == 1) continue; // array parameter decays to pointer
        if (indexTokens.size() > var->dimensions.size()) continue;
        // declaration itself? (tok is the dimension bracket)
        if (tok->astOperand1 == arrayTok && var->nameToken == arrayTok) continue;
        std::vector<long long> dims;
        bool allKnown = true;
        for (size_t i = 0; i < var->dimensions.size(); ++i) { if (!var->dimensionKnown[i]) { allKnown = false; break; } dims.push_back(var->dimensionValues[i]); }
        if (!allKnown) continue;
        // address-of: &a[N] is allowed
        const Token *parent = tok->astParent;
        bool addressOf = parent && parent->str == "&" && !parent->astOperand2;
        // check each index
        // Known values
        bool reported = false;
        {
            std::vector<long long> indexValues;
            std::vector<const ValueFlowValue*> vals;
            bool allKnownIdx = true;
            bool outOfBounds = false;
            for (size_t i = 0; i < indexTokens.size(); ++i) {
                const ValueFlowValue *v = indexTokens[i]->getKnownValue();
                if (!v) { allKnownIdx = false; break; }
                indexValues.push_back(v->intvalue);
                vals.push_back(v);
                if (v->intvalue >= dims[i] && !(addressOf && i == indexTokens.size() - 1 && v->intvalue == dims[i])) outOfBounds = true;
            }
            if (allKnownIdx && outOfBounds) {
                bool negative = false;
                for (long long v : indexValues) if (v < 0) negative = true;
                if (!negative) {
                    // only report when total index exceeds total size (cppcheck computes for multi-dim)
                    bool report = false;
                    if (indexValues.size() == dims.size()) {
                        long long total = 1; for (long long d : dims) total *= d;
                        long long flat = 0; long long mul = 1;
                        for (size_t i = dims.size(); i-- > 0;) { flat += indexValues[i] * mul; mul *= dims[i]; }
                        if (flat >= total) report = true;
                        if (!report && indexValues.size() == 1) report = indexValues[0] >= dims[0];
                    } else {
                        report = true;
                    }
                    if (report) {
                        ErrorPath ep;
                        for (const ValueFlowValue *v : vals) for (const auto &p : v->errorPath) ep.push_back(p);
                        ep.emplace_back(tok, "Array index out of bounds");
                        reportError(ep, Severity::error, "arrayIndexOutOfBounds", arrayIndexMessage(tok, dims, std::vector<const Token*>(indexTokens.begin(), indexTokens.end()), indexValues), 788);
                        reported = true;
                    }
                }
            }
            // negative index
            if (allKnownIdx && !reported) {
                for (size_t i = 0; i < indexValues.size(); ++i) {
                    if (indexValues[i] < 0) {
                        ErrorPath ep;
                        for (const ValueFlowValue *v : vals) for (const auto &p : v->errorPath) ep.push_back(p);
                        ep.emplace_back(tok, "Negative array index");
                        std::string array = arrayTok->expressionString();
                        for (long long d : dims) array += "[" + std::to_string(d) + "]";
                        std::string index;
                        if (indexValues.size() == 1) index = std::to_string(indexValues[0]);
                        else { index = arrayTok->expressionString(); for (long long v : indexValues) index += "[" + std::to_string(v) + "]"; }
                        reportError(ep, Severity::error, "negativeIndex", "Array '" + array + "' accessed at index " + index + ", which is out of bounds.", 786);
                        reported = true;
                        break;
                    }
                }
            }
        }
        if (reported) continue;
        // Possible values (warning-level: cppcheck reports as error with "possible" only with the condition path; message same but severity warning? No: arrayIndexOutOfBounds with possible value -> warning)
        if (indexTokens.size() == 1) {
            const Token *idx = indexTokens[0];
            if (idx->hasKnownIntValue()) continue;
            const ValueFlowValue *bad = nullptr;
            for (const ValueFlowValue &v : idx->values) {
                if (v.valueType != ValueFlowValue::INT || v.impossible) continue;
                if (v.intvalue >= dims[0] && !(addressOf && v.intvalue == dims[0])) { if (!bad || v.intvalue > bad->intvalue) bad = &v; }
            }
            if (bad) {
                if (!mSettings.sev_warning && !bad->isKnown()) {
                    // cppcheck reports possible values as warning (requires --enable=warning)
                    continue;
                }
                ErrorPath ep = bad->errorPath;
                ep.emplace_back(tok, "Array index out of bounds");
                std::vector<long long> iv{bad->intvalue};
                reportError(ep, bad->isKnown() ? Severity::error : Severity::warning, "arrayIndexOutOfBounds", arrayIndexMessage(tok, dims, {idx}, iv), 788);
                continue;
            }
            const ValueFlowValue *neg = nullptr;
            for (const ValueFlowValue &v : idx->values) {
                if (v.valueType != ValueFlowValue::INT || v.impossible) continue;
                if (v.intvalue < 0) { if (!neg || v.intvalue < neg->intvalue) neg = &v; }
            }
            if (neg) {
                if (!mSettings.sev_warning && !neg->isKnown()) continue;
                ErrorPath ep = neg->errorPath;
                ep.emplace_back(tok, "Negative array index");
                std::string array = arrayTok->expressionString();
                for (long long d : dims) array += "[" + std::to_string(d) + "]";
                reportError(ep, neg->isKnown() ? Severity::error : Severity::warning, "negativeIndex", "Array '" + array + "' accessed at index " + std::to_string(neg->intvalue) + ", which is out of bounds.", 786);
            }
        }
    }
}

void CheckBufferOverrun::negativeArraySize() {
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Variable &var : scope->varlist) {
            if (!var.isArray) continue;
            for (size_t i = 0; i < var.dimensions.size(); ++i) {
                if (var.dimensionKnown[i] && var.dimensionValues[i] < 0) {
                    reportError(var.nameToken, Severity::error, "negativeArraySize", "Declaration of array '" + var.name + "' with negative size is undefined behaviour", 758);
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// CheckNullPointer
// ---------------------------------------------------------------------------
class CheckNullPointer : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Null pointer"; }
    void runChecks() override {
        nullPointerByDeRefAndCheck();
        nullConstantDereference();
        arithmetic();
    }
    void nullPointerByDeRefAndCheck();
    void nullConstantDereference();
    void arithmetic();
    bool isPointerDeRef(const Token *tok, bool &unknown) const;
    void nullPointerError(const Token *tok, const std::string &varname, const ValueFlowValue *value, bool inconclusive);
};

bool CheckNullPointer::isPointerDeRef(const Token *tok, bool &unknown) const {
    unknown = false;
    const Token *parent = tok->astParent;
    if (!parent) return false;
    // *p
