#include "check.h"
#include "cppcheck.h"
#include <algorithm>
#include <map>

// ---------------------------------------------------------------------------
// Forward analysis: is the value assigned at 'assignTok' (to expression 'expr') read later?
// returns true if value is unused
// ---------------------------------------------------------------------------
namespace {

static bool exprReadsVar(const Token *tok, unsigned varid) {
    return tok && tok->varId == varid;
}

enum class FwdResult { Unused, Used, Bailout };

static bool isLoopScopeStart(const Token *brace) {
    const Token *prev = brace->previous;
    if (!prev) return false;
    if (prev->str == "do") return true;
    if (prev->str == ")" && prev->link) {
        const Token *kw = prev->link->previous;
        return kw && (kw->str == "for" || kw->str == "while");
    }
    return false;
}

// Does the expression 'expr' get re-assigned fully by the statement whose lhs is 'lhs'?
static bool sameLhs(const Token *expr, const Token *lhs) {
    return isSameExpression(expr, lhs);
}

static FwdResult fwdCheck(const Token *expr, const Token *start, const Token *end, unsigned varid, bool inLoop, int depth);

static FwdResult checkRange(const Token *expr, const Token *start, const Token *end, unsigned varid, bool inLoop, int depth) {
    if (depth > 20) return FwdResult::Bailout;
    for (const Token *tok = start; tok && tok != end; tok = tok->next) {
        if (tok->str == "{" && tok->link) {
            const Token *prev = tok->previous;
            if (prev && prev->str == "=") { // initializer
                for (const Token *t = tok; t != tok->link; t = t->next) if (t->varId == varid) return FwdResult::Used;
                tok = tok->link; continue;
            }
            bool loop = isLoopScopeStart(tok);
            // condition tokens were already scanned (they precede '{')
            FwdResult r = checkRange(expr, tok->next, tok->link, varid, inLoop || loop, depth + 1);
            if (r == FwdResult::Used || r == FwdResult::Bailout) return r;
            // r == Unused inside the block: if the block reassigns the variable fully we can't conclude for other paths: cppcheck bails out for conditional reassign? It continues.
            // if the variable was reassigned in the block, other paths still may read: continue scanning after block
            tok = tok->link;
            // else branch
            continue;
        }
        if (tok->str == "}") return FwdResult::Unused;
        if (tok->str == "asm" || tok->str == "goto") return FwdResult::Bailout;
        if (tok->isName() && tok->str == "return" ) {
            // read in return expression?
            for (const Token *t = tok; t && t->str != ";"; t = t->next) if (t->varId == varid) return FwdResult::Used;
            // returning: the value is not used on this path
            // other paths (if we are inside a conditional block) -> handled by caller continuing
            // skip to ';'
            while (tok && tok->str != ";") tok = tok->next;
            if (!tok) return FwdResult::Unused;
            if (depth == 0) return FwdResult::Unused;
            // inside block: value unused on this path; continue after block in caller
            return FwdResult::Unused;
        }
        if (tok->str == "break" || tok->str == "continue" || tok->str == "throw") {
            if (tok->str == "throw") { for (const Token *t = tok; t && t->str != ";"; t = t->next) if (t->varId == varid) return FwdResult::Used; }
            if (inLoop && tok->str == "continue") return FwdResult::Bailout;
            return FwdResult::Unused;
        }
        if (tok->varId == varid) {
            // Is this a full reassignment of the same expression?
            const Token *parent = tok->astParent;
            const Token *cur = tok;
            // climb through [ and . on lhs
            while (parent && ((parent->str == "[" && parent->astOperand1 == cur) || (parent->str == "." && parent->astOperand1 == cur))) { cur = parent; parent = parent->astParent; }
            if (parent && parent->str == "=" && parent->astOperand1 == cur) {
                if (sameLhs(expr, cur)) {
                    // rhs reads the var?
                    if (parent->astOperand2) {
                        bool reads = false;
                        std::vector<const Token*> stack{parent->astOperand2};
                        while (!stack.empty()) { const Token *t = stack.back(); stack.pop_back(); if (!t) continue; if (t->varId == varid) reads = true; stack.push_back(t->astOperand1); stack.push_back(t->astOperand2); }
                        if (reads) return FwdResult::Used;
                    }
                    if (inLoop) return FwdResult::Bailout; // maybe read in another iteration before? cppcheck: in loops the value could be read before reassignment -> bail
                    return FwdResult::Unused;
                }
                // partial write (different index/member) -> bailout like cppcheck
                if (cur != tok) return FwdResult::Bailout;
                return FwdResult::Unused;
            }
            if (parent && parent->isAssignmentOp() && parent->astOperand1 == cur) return FwdResult::Used; // compound assignment reads
            return FwdResult::Used;
        }
    }
    return FwdResult::Unused;
}

static FwdResult fwdCheck(const Token *expr, const Token *start, const Token *end, unsigned varid, bool inLoop, int depth) {
    return checkRange(expr, start, end, varid, inLoop, depth);
}

static bool isInLoop(const Token *tok) {
    for (const Scope *s = tok->scope; s && s->isExecutable(); s = s->nestedIn) if (s->isLoopScope()) return true;
    return false;
}

static bool scopeHasLabelOrGoto(const Scope *scope) {
    for (const Token *t = scope->bodyStart; t && t != scope->bodyEnd; t = t->next) {
        if (t->str == "goto") return true;
        if (t->isName() && t->next && t->next->str == ":" && t->previous && (t->previous->str == ";" || t->previous->str == "{" || t->previous->str == "}") && !(t->next->next && t->next->next->str == ":") && t->str != "default" && t->str != "case" && t->str != "public" && t->str != "private" && t->str != "protected") return true;
    }
    return false;
}

struct VarUsage {
    const Variable *var = nullptr;
    bool read = false;
    bool write = false;
    bool modified = false;
    bool allocateMemory = false;
    const Token *lastAccess = nullptr;
    bool bail = false; // aliased / address taken / unknown usage
    bool unused() const { return !read && !write; }
};

}

class CheckUnusedVar : public Check {
public:
    using Check::Check;
    std::string name() const override { return "UnusedVar"; }
    void runChecks() override {
        if (!mSettings.sev_style) return;
        checkStructMemberUsage();
        checkFunctionVariableUsage();
    }
    void checkFunctionVariableUsage();
    void checkStructMemberUsage();
    bool isRecordTypeWithoutSideEffects(const Type *type) const;
};

bool CheckUnusedVar::isRecordTypeWithoutSideEffects(const Type *type) const {
    if (!type || !type->classScope) return false;
    const Scope *s = type->classScope;
    // no constructors/destructor, members are standard types or records without side effects
    for (const Function &f : s->functionList) if (f.isConstructor() || f.isDestructor()) return false;
    for (const Variable &v : s->varlist) {
        if (v.isPointer || v.isArray) continue;
        if (v.isClass) { if (!isRecordTypeWithoutSideEffects(v.type)) return false; }
    }
    return true;
}

static const Token *findAllocFuncCallToken(const Token *expr, const Library &library, bool cpp) {
    if (!expr) return nullptr;
    if (expr->isCast && expr->astOperand1) return findAllocFuncCallToken(expr->astOperand1, library, cpp);
    if (expr->str == "(" && expr->astOperand1 && expr->astOperand1->isName() && library.getAlloc(expr->astOperand1->str)) return expr->astOperand1;
    if (cpp && expr->str == "new") return expr;
    return nullptr;
}

void CheckUnusedVar::checkFunctionVariableUsage() {
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        if (!scope->function || scope->type == Scope::eLambda) continue;
        if (scopeHasLabelOrGoto(scope)) continue;
        // Part 1: assignments with unused values
        for (const Token *tok = scope->bodyStart->next; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (tok->str != "=" || !tok->astOperand1 || !tok->astOperand2) continue;
            if (tok->astParent) continue;
            const Token *expr = tok->astOperand1;
            const Token *varTok = expr;
            while (varTok && (varTok->str == "[" || varTok->str == ".") && varTok->astOperand1) varTok = varTok->astOperand1;
            if (!varTok || !varTok->variable) continue;
            const Variable *var = varTok->variable;
            if (expr->str == "." ) continue; // struct member writes: skip (cppcheck handles struct members separately)
            if (expr->str == "[" && expr->astOperand1 != varTok) {
                // multi-dim
            }
            if (!var->isLocal || var->isStatic || var->isReference || var->isVolatile || var->isExtern) continue;
            if (var->isArgument) continue;
            if (var->isClass && !var->isPointer && !var->isArray && !isRecordTypeWithoutSideEffects(var->type)) continue;
            if (var->isArray && var->isClass) continue;
            if (expr->str == "[" && var->isPointer && !var->isArray) continue; // p[i] = x writes to pointee
            if (expr->str == "[" && var->isArray) {
                // index must be constant for exact tracking; otherwise bail (cppcheck: partial writes)
            }
            if (var->isPointer && expr == varTok) {
                // "p = ..." pointer assignment is tracked
            }
            // rhs with side effects? e.g. "x = f()" is still reported (unreadVariable) in cppcheck? yes, it is reported.
            // find end of statement
            const Token *stmtEnd = tok;
            while (stmtEnd && stmtEnd->str != ";") stmtEnd = stmtEnd->next;
            if (!stmtEnd) continue;
            const bool inLoop = isInLoop(tok);
            // special: assignment inside loop and variable read anywhere in the loop -> used
            if (inLoop) {
                const Scope *ls = tok->scope;
                while (ls && !ls->isLoopScope()) ls = ls->nestedIn;
                if (ls) {
                    bool readInLoop = false;
                    for (const Token *t = ls->classDef; t && t != ls->bodyEnd; t = t->next) {
                        if (t->varId == var->varId && t != varTok) {
                            const Token *p = t->astParent;
                            const Token *c = t;
                            while (p && ((p->str == "[" && p->astOperand1 == c) || (p->str == "." && p->astOperand1 == c))) { c = p; p = p->astParent; }
                            if (!(p && p->str == "=" && p->astOperand1 == c)) { readInLoop = true; break; }
                            // rhs of assignment reads?
                            std::vector<const Token*> st{p->astOperand2};
                            while (!st.empty()) { const Token *x = st.back(); st.pop_back(); if (!x) continue; if (x->varId == var->varId) { readInLoop = true; break; } st.push_back(x->astOperand1); st.push_back(x->astOperand2); }
                            if (readInLoop) break;
                        }
                    }
                    if (readInLoop) continue;
                    // not read in loop: check after loop
                    FwdResult r = fwdCheck(expr, ls->bodyEnd->next, scope->bodyEnd, var->varId, false, 0);
                    if (r != FwdResult::Unused) continue;
                    // handle do-while condition
                    if (ls->type == Scope::eDo) continue;
                    // rhs reads var itself? "x = x + 1" -> cppcheck still reports? It reports "x" assigned never used only if value unused later. ok
                } else continue;
            } else {
                FwdResult r = fwdCheck(expr, stmtEnd->next, scope->bodyEnd, var->varId, false, 0);
                if (r != FwdResult::Unused) continue;
            }
            // the variable must not be used in the rhs of the same statement after being assigned? "x = x + 1" -> rhs reads x (old value) -> still unused value
            // Report
            ErrorMessage em;
            em.callStack.push_back(FileLocation(mTokenizer.list.files[tok->fileIndex], tok->linenr, tok->column));
            em.id = "unreadVariable"; em.severity = Severity::style; em.cwe = 563;
            const std::string exprStr = expr->expressionString();
            em.setMessage("Variable '" + exprStr + "' is assigned a value that is never used.");
            em.symbolNames.push_back(exprStr);
            em.file0 = mTokenizer.list.sourceFile;
            mCppCheck.reportErr(em);
        }

        // Part 2: variable usage
        std::map<unsigned, VarUsage> usage;
        std::vector<unsigned> order;
        auto collectVars = [&](const Scope *s, auto &&self) -> void {
            for (const Variable &v : s->varlist) {
                if (v.isArgument || v.isStatic || v.isExtern) continue;
                if (v.isReference) continue;
                if (v.isClass && !v.isPointer) {
                    if (mTokenizer.isCPP() && !isRecordTypeWithoutSideEffects(v.type) && !v.isEnumType) continue;
                    if (v.isArray && mTokenizer.isCPP()) continue;
                }
                if (v.isPointer && v.pointerDepth > 1) continue; // pointerPointer skipped
                if (v.isArray && v.isPointer) continue; // pointerArray
                if (v.isArray && v.dimensions.size() > 1) continue;
                if (v.isFunctionPointer) continue;
                VarUsage u; u.var = &v;
                usage[v.varId] = u;
                order.push_back(v.varId);
            }
            for (const Scope *n : s->nestedList) if (n->type != Scope::eLambda) self(n, self);
        };
        collectVars(scope, collectVars);
        if (usage.empty()) continue;
        for (const Token *tok = scope->bodyStart->next; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (tok->varId == 0) continue;
            auto it = usage.find(tok->varId);
            if (it == usage.end()) continue;
            VarUsage &u = it->second;
            const Variable *var = u.var;
            if (tok == var->nameToken) continue; // declaration
            // initialization "T x ( args )" / "{ args }"
            const Token *parent = tok->astParent;
            if (!parent) {
                // bare usage e.g. "x ;" statement
                u.read = true; u.lastAccess = tok; continue;
            }
            // assignment "x = ..."
            if (parent->str == "=" && parent->astOperand1 == tok) {
                const Token *rhs = parent->astOperand2;
                const Token *alloc = findAllocFuncCallToken(rhs, mLibrary, mTokenizer.isCPP());
                if (var->isPointer && alloc) {
                    bool allocateMemory = true;
                    const LibAllocFunc *af = mLibrary.getAlloc(alloc->str);
                    if (af && af->isResource) allocateMemory = false;
                    if (alloc->str == "new") {
                        const Token *type = alloc->next;
                        if (type && type->str == "(" && type->link) type = type->link->next;
                        if (type && !type->isStandardType()) {
                            if (!var->type || !isRecordTypeWithoutSideEffects(var->type)) allocateMemory = false;
                        }
                    }
                    // last access token: emulate cppcheck's doAssignment walk
                    const Token *la = parent->next;
                    // skip C-style cast "( type * )"
                    if (la && la->str == "(" && la->isCast && la->link) {
                        la = la->next;
                        if (la && la->str == "const") la = la->next;
                        if (la && (la->str == "struct" || la->str == "union")) la = la->next;
                        while (la && ((la->isName() && la->varId == 0) || la->str == "*" || la->str == ")")) la = la->next;
                        if (la && la->str == "&") la = la->next;
                        else if (la && la->str == "(") { la = la->next; if (la && la->str == "&") la = la->next; }
                    }
                    if (allocateMemory) { u.allocateMemory = true; u.write = true; u.lastAccess = la ? la : tok; }
                    else { u.write = true; u.lastAccess = tok; }
                    // aliasing: pointer assigned address of other var -> bail
                } else {
                    u.write = true; u.lastAccess = tok;
                    // "p = &x" -> alias: bail for x
                    if (rhs && rhs->str == "&" && !rhs->astOperand2 && rhs->astOperand1 && rhs->astOperand1->varId) {
                        auto it2 = usage.find(rhs->astOperand1->varId);
                        if (it2 != usage.end()) it2->second.bail = true;
                    }
                    if (rhs && rhs->varId && var->isPointer) {
                        auto it2 = usage.find(rhs->varId);
                        if (it2 != usage.end() && it2->second.var->isArray) it2->second.bail = true;
                    }
                }
                continue;
            }
            // compound assignment / inc dec
            if ((parent->isAssignmentOp() && parent->astOperand1 == tok) || parent->str == "++" || parent->str == "--") {
                u.read = true; u.write = true; u.modified = true; u.lastAccess = tok; continue;
            }
            // array element write: a[i] = x
            if (parent->str == "[" && parent->astOperand1 == tok) {
                const Token *p = parent;
                while (p->astParent && p->astParent->str == "[") p = p->astParent;
                if (p->astParent && p->astParent->str == "=" && p->astParent->astOperand1 == p) {
                    // index read
                    if (var->isArray) { u.write = true; u.lastAccess = tok; }
                    else { u.read = true; u.lastAccess = tok; }
                    continue;
                }
                if (p->astParent && p->astParent->isAssignmentOp() && p->astParent->astOperand1 == p) { u.read = true; u.write = true; u.modified = true; u.lastAccess = tok; continue; }
                u.read = true; u.lastAccess = tok; continue;
            }
            // dereference write: *p = x  -> read of p
            if (parent->str == "*" && !parent->astOperand2) { u.read = true; u.lastAccess = tok; continue; }
            // member: s.x = 1 -> for struct var: write
            if (parent->str == "." && parent->astOperand1 == tok) {
                const Token *p = parent;
                while (p->astParent && p->astParent->str == ".") p = p->astParent;
                if (p->astParent && p->astParent->str == "=" && p->astParent->astOperand1 == p) { u.write = true; u.lastAccess = tok; continue; }
                if (p->astParent && p->astParent->str == "(" && p->astParent->astOperand1 == p) { u.read = true; u.write = true; u.modified = true; u.lastAccess = tok; continue; } // method call
                u.read = true; u.lastAccess = tok; continue;
            }
            if (parent->str == "->" && parent->astOperand1 == tok) { u.read = true; u.lastAccess = tok; continue; }
            // address taken
            if (parent->str == "&" && !parent->astOperand2) { u.bail = true; u.read = true; u.write = true; u.lastAccess = tok; continue; }
            // sizeof
            {
                const Token *p = parent; bool inSizeof = false;
                while (p) { if (p->str == "(" && p->astOperand1 && p->astOperand1->str == "sizeof") { inSizeof = true; break; } p = p->astParent; }
                if (inSizeof) { u.read = true; u.lastAccess = tok; continue; }
            }
            // function argument by reference (C++)
            if (mTokenizer.isCPP()) {
                const Token *a = tok;
                while (a->astParent && a->astParent->str == ",") a = a->astParent;
                if (a->astParent && a->astParent->str == "(" && a->astParent->astOperand2 && a->astParent->astOperand1 && a->astParent->astOperand1->isName()) {
                    const Token *fn = a->astParent->astOperand1;
                    int idx = 0; const Token *x = tok;
                    while (x->astParent && x->astParent->str == ",") { if (x->astParent->astOperand2 == x) { const Token *l = x->astParent->astOperand1; int c = 1; while (l && l->str == ",") { ++c; l = l->astOperand1; } idx += c; } x = x->astParent; }
                    if (fn->function) {
                        const Variable *av = fn->function->getArgumentVar(idx);
                        if (av && av->isReference && !av->isConst) { u.read = true; u.write = true; u.modified = true; u.lastAccess = tok; continue; }
                    } else if (!mLibrary.getFunction(fn->str) && !fn->isStandardType()) {
                        // unknown function: could take reference -> treat as use
                        u.read = true; u.write = true; u.modified = true; u.lastAccess = tok; continue;
                    }
                }
                if (parent->str == ">>" && parent->astOperand2 == tok) { u.write = true; u.modified = true; u.lastAccess = tok; continue; }
            }
            u.read = true; u.lastAccess = tok;
        }
        for (unsigned id : order) {
            const VarUsage &u = usage[id];
            const Variable *var = u.var;
            if (u.bail) continue;
            if (var->nameToken->isAttributeUnused || var->nameToken->isAttributeUsed || var->nameToken->isAttributeMaybeUnused) continue;
            const std::string &varname = var->name;
            if (u.unused() && !u.modified && u.allocateMemory) {
                // not reachable since allocateMemory implies write
            }
            if (u.allocateMemory && !u.read && !u.modified) {
                // variable has had memory allocated for it, but hasn't done anything with that memory other than, perhaps, freeing it
                ErrorMessage em;
                const Token *at = u.lastAccess ? u.lastAccess : var->nameToken;
                em.callStack.push_back(FileLocation(mTokenizer.list.files[at->fileIndex], at->linenr, at->column));
                em.id = "unusedAllocatedMemory"; em.severity = Severity::style; em.cwe = 563;
                em.setMessage("Variable '" + varname + "' is allocated memory that is never used.");
                em.symbolNames.push_back(varname);
                em.file0 = mTokenizer.list.sourceFile;
                mCppCheck.reportErr(em);
            } else if (u.unused() && !u.modified) {
                ErrorMessage em;
                em.callStack.push_back(FileLocation(mTokenizer.list.files[var->nameToken->fileIndex], var->nameToken->linenr, var->nameToken->column));
                em.id = "unusedVariable"; em.severity = Severity::style; em.cwe = 563;
                em.setMessage("Unused variable: " + varname);
                em.symbolNames.push_back(varname);
                em.file0 = mTokenizer.list.sourceFile;
                mCppCheck.reportErr(em);
            } else if (!u.write && !u.allocateMemory && !var->isStlType && !(var->isClass && !var->isPointer && var->type && var->type->classScope && var->type->classScope->varlist.empty())) {
                // read but never written
                if (var->isInit) continue;
                if (var->isArray && var->isInit) continue;
                ErrorMessage em;
                em.callStack.push_back(FileLocation(mTokenizer.list.files[var->nameToken->fileIndex], var->nameToken->linenr, var->nameToken->column));
                em.id = "unassignedVariable"; em.severity = Severity::style; em.cwe = 665;
                em.setMessage("Variable '" + varname + "' is not assigned a value.");
                em.symbolNames.push_back(varname);
                em.file0 = mTokenizer.list.sourceFile;
                mCppCheck.reportErr(em);
            }
        }
    }
}

void CheckUnusedVar::checkStructMemberUsage() {
    for (const Scope &scope : mSymbolDatabase.scopeList) {
        if (!scope.isClassOrStructOrUnion()) continue;
        if (scope.bodyStart->fileIndex != 0) continue; // only in source file (cppcheck: skips headers? it checks all) 
        if (scope.className.empty() || scope.className.compare(0, 9, "Anonymous") == 0) {}
        // skip if struct has base classes or is derived from
        bool skip = false;
        if (scope.definedType) {
            // inheritance
            const Token *t = scope.classDef ? scope.classDef->next : nullptr;
            if (t && t->next && t->next->str == ":") skip = true;
        }
        if (skip) continue;
        // skip unions and packed/anonymous
        if (scope.type == Scope::eUnion) continue;
        // skip if the struct is used in a way that we can't track: e.g. passed to unknown functions / memcpy / written to file
        // cppcheck: bail if struct type is used with "." in a way like &s or sizeof(struct)? It checks: isUsed in "memset|memcpy|..."; and if any variable of that type is passed to a function by address.
        bool bail = false;
        for (const Token *tok = mTokenizer.list.front(); tok && !bail; tok = tok->next) {
            if (tok->str != scope.className) continue;
            if (tok == scope.classDef->next) continue;
            // "struct S *p = (struct S*)..." casts -> bail
            if (tok->previous && (tok->previous->str == "struct" || tok->previous->str == "class" || tok->previous->str == "union") && tok->previous->previous && tok->previous->previous->str == "(") bail = true;
            if (tok->previous && tok->previous->str == "(" && tok->next && (tok->next->str == "*" || tok->next->str == ")")) bail = true;
            if (tok->next && tok->next->str == "::") continue;
        }
        if (bail) continue;
        for (const Variable &var : scope.varlist) {
            if (var.isStatic) continue;
            if (var.nameToken->isAttributeUnused || var.nameToken->isAttributeMaybeUnused) continue;
            // is member used anywhere?
            bool used = false;
            for (const Token *tok = mTokenizer.list.front(); tok && !used; tok = tok->next) {
                if (tok->str != var.name) continue;
                if (tok == var.nameToken) continue;
                if (tok->varId == var.varId) { used = true; break; }
                if (tok->previous && (tok->previous->str == "." || tok->previous->str == "->")) { used = true; break; }
                // used in same struct (e.g. array dimension) or as "Struct::member"
                if (tok->previous && tok->previous->str == "::") { used = true; break; }
                if (tok->scope == &scope && tok->varId == 0) { used = true; break; }
                // designated initializer ".name ="
            }
            if (used) continue;
            // struct passed to functions/casted -> skip (handled by bail)
            const char* kind = scope.type == Scope::eStruct ? "struct" : (scope.type == Scope::eClass ? "class" : "union");
            ErrorMessage em;
            em.callStack.push_back(FileLocation(mTokenizer.list.files[var.nameToken->fileIndex], var.nameToken->linenr, var.nameToken->column));
            em.id = "unusedStructMember"; em.severity = Severity::style; em.cwe = 563;
            em.setMessage(std::string(kind) + " member '" + scope.className + "::" + var.name + "' is never used.");
            em.symbolNames.push_back(scope.className + "::" + var.name);
            em.file0 = mTokenizer.list.sourceFile;
            mCppCheck.reportErr(em);
        }
    }
}

// ---------------------------------------------------------------------------
// Unused functions (whole program)
// ---------------------------------------------------------------------------
void checkUnusedFunctionsParse(CppCheck &cppcheck, const Tokenizer &tokenizer, const SymbolDatabase &symdb, const std::string &displayFile) {
    auto find = [&](const std::string &name) -> CppCheck::FuncUsage* {
        for (auto &p : cppcheck.mFunctionUsage) if (p.first == name) return &p.second;
        return nullptr;
    };
    // function definitions
    for (const Scope *scope : symdb.functionScopes) {
        const Function *func = scope->function;
        if (!func || !func->token || func->type == Function::eLambda) continue;
        if (func->isOperator || func->isAttributeConstructor || func->isAttributeDestructor || func->isAttributeUsed || func->isAttributeUnused || func->isAttributeMaybeUnused()) continue;
        if (func->isConstructor() || func->isDestructor()) continue;
        if (func->isTemplate) continue;
        // skip "main"
        if (func->name == "main" && (tokenizer.isC() || true)) continue;
        if (func->name.empty()) continue;
        // skip functions in header files? cppcheck checks only functions defined in the checked file? It includes all.
        if (func->token->fileIndex != 0) continue;
        CppCheck::FuncUsage *fu = find(func->name);
        if (!fu) {
            cppcheck.mFunctionUsage.emplace_back(func->name, CppCheck::FuncUsage());
            fu = &cppcheck.mFunctionUsage.back().second;
            fu->file = tokenizer.list.files[func->token->fileIndex];
            fu->displayFile = displayFile;
            fu->line = func->token->linenr;
            fu->col = func->token->column;
        } else if (fu->file.empty()) {
            fu->file = tokenizer.list.files[func->token->fileIndex];
            fu->displayFile = displayFile;
            fu->line = func->token->linenr;
            fu->col = func->token->column;
        } else if (fu->file != tokenizer.list.files[func->token->fileIndex]) {
            // defined in several files -> treat as used
            fu->usedOtherFile = true;
        }
        if (cppcheck.mCalledFunctions.count(func->name)) fu->used = true;
    }
    // usages
    for (const Token *tok = tokenizer.list.front(); tok; tok = tok->next) {
        if (!tok->isName() || tok->varId != 0 || tok->isKeyword()) continue;
        // skip definitions and declarations
        if (tok->functionDecl && (tok->function == nullptr || tok->function->token == tok || tok->function->tokenDef == tok)) {
            // definition or declaration token
            if (tok->next && tok->next->str == "(" && tok->next->link) {
                const Token *after = tok->next->link->next;
                while (after && (after->str == "const" || after->str == "override" || after->str == "noexcept" || after->str == "final")) after = after->next;
                if (after && (after->str == "{" || after->str == ";" || after->str == ":" || after->str == "=")) continue;
            }
        }
        if (tok->next && tok->next->str == "(" && tok->next->link) {
            const Token *after = tok->next->link->next;
            while (after && (after->str == "const" || after->str == "override" || after->str == "noexcept" || after->str == "final")) after = after->next;
            if (after && (after->str == "{" ) ) {
                // definition: skip unless this is a call inside a condition like "if (f(x)) {"
                const Token *prev = tok->previous;
                if (!(prev && (prev->str == "(" || prev->str == "," || prev->isOp() || prev->str == "return" || prev->str == "!" ))) continue;
            }
            if (after && after->str == ";" ) {
                // declaration "void f();" -> prev is type/name; call "f();" -> prev is ; { } or operator
                const Token *prev = tok->previous;
                if (prev && (prev->isName() && !prev->isKeyword() || prev->str == "*" || prev->str == "&") && prev->str != "return" && prev->str != "delete" && prev->str != "throw" && prev->str != "else" && prev->str != "do" && prev->str != "case") {
                    // looks like declaration "type f (" ... but could be "else f();" handled
                    if (tok->next->next == tok->next->link || (tok->next->next->isName() && !tok->next->next->varId && (tok->next->next->isStandardType() || tok->next->next->tokType == Token::eType || tok->next->next->str == "void" || tok->next->next->str == "const" || tok->next->next->str == "struct" || (tok->next->next->next && (tok->next->next->next->isName() || tok->next->next->next->str == "*" || tok->next->next->next->str == "&")))))
                        continue;
                }
                if (prev && prev->str == "::" ) {
                    const Token *p2 = prev->previous;
                    if (p2 && p2->previous && (p2->previous->isName() && !p2->previous->isKeyword())) continue;
                }
            }
        }
        // skip struct member access
        if (tok->previous && (tok->previous->str == "." || tok->previous->str == "->")) {
            // method call: counts as usage of the method
        }
        // function used (call, address, assignment)
        bool isUse = false;
        if (tok->next && tok->next->str == "(") isUse = true;
        else if (tok->previous && (tok->previous->str == "&" || tok->previous->str == "=" || tok->previous->str == "(" || tok->previous->str == "," || tok->previous->str == "return" || tok->previous->str == "?" || tok->previous->str == ":" || tok->previous->str == "{")) {
            // function pointer usage: "&f", "= f", "f," etc. Only if name is a known function
            if (tok->function || cppcheck.mCalledFunctions.count(tok->str) || find(tok->str)) isUse = true;
            // avoid declarations like "int x, f;" -> no function with that name anyway
        } else if (tok->next && (tok->next->str == "," || tok->next->str == ")" || tok->next->str == ";") && tok->previous && (tok->previous->str == "(" || tok->previous->str == "," )) {
            if (tok->function) isUse = true;
        }
        if (!isUse) continue;
        if (tok->function && tok->function->token == tok) continue;
        CppCheck::FuncUsage *fu = find(tok->str);
        if (fu) fu->used = true;
        cppcheck.mCalledFunctions.insert(tok->str);
    }
}

std::vector<std::unique_ptr<Check>> createChecksUnused(const Tokenizer &tokenizer, const SymbolDatabase &symdb, const Settings &settings, const Library &library, CppCheck &cppcheck) {
    std::vector<std::unique_ptr<Check>> v;
    v.push_back(std::make_unique<CheckUnusedVar>(tokenizer, symdb, settings, library, cppcheck));
    return v;
}
