// Helper for building messages with symbol names
static void report(Check &c, CppCheck &cppcheck, const Tokenizer &tokenizer, const ErrorPath &ep, Severity sev, const std::string &id, const std::string &msg, int cwe, const std::vector<std::string> &symbols = {}, Certainty cert = Certainty::normal, const Settings *settings = nullptr) {
