static std::string conditionString(const Token *tok) {
    if (!tok) return "";
    if (tok->isComparisonOp() && tok->astOperand1 && tok->astOperand2)
        return conditionString(tok->astOperand1) + " " + tok->str + " " + conditionString(tok->astOperand2);
    if ((tok->isConstOp() || tok->str == "&&" || tok->str == "||") && tok->astOperand1 && tok->astOperand2)
        return "(" + conditionString(tok->astOperand1) + " " + tok->str + " " + conditionString(tok->astOperand2) + ")";
    return tok->expressionString();
}

// ---------------------------------------------------------------------------
// CheckCondition
// ---------------------------------------------------------------------------
class CheckCondition : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Condition"; }
    void runChecks() override {
        multiCondition();
        duplicateCondition();
        checkIncorrectLogicOperator();
        alwaysTrueFalse();
        checkPointerAdditionResultNotNull();
    }
    void multiCondition() {}
    void duplicateCondition();
    void checkIncorrectLogicOperator();
    void alwaysTrueFalse();
    void checkPointerAdditionResultNotNull() {}
};

void CheckCondition::duplicateCondition() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!(tok->str == "if" && tok->next && tok->next->str == "(" && tok->next->link)) continue;
            const Token *cond1 = tok->next->astOperand2;
            const Token *brace = tok->next->link->next;
            if (!cond1 || !brace || brace->str != "{" || !brace->link) continue;
            // "if (x) {} if (x) {}" -> duplicateCondition when the first block has no side effects on condition vars... cppcheck: second if directly after first block (no else), variables not changed
            const Token *after = brace->link->next;
            if (!after || after->str != "if" || !after->next || after->next->str != "(") continue;
            const Token *cond2 = after->next->astOperand2;
            if (!cond2) continue;
            if (!isSameExpression(cond1, cond2)) continue;
            // variables changed in block?
            bool changed = false;
            std::vector<const Token*> stack{cond1};
            while (!stack.empty() && !changed) {
                const Token *t = stack.back(); stack.pop_back();
                if (!t) continue;
                if (t->varId && isVariableChanged(brace, brace->link, t->varId, mTokenizer.isCPP())) changed = true;
                if (t->str == "(" && t->astOperand1 && !t->isCast) changed = true; // function call -> unknown
                stack.push_back(t->astOperand1); stack.push_back(t->astOperand2);
            }
            if (changed) continue;
            ErrorPath ep{{cond1, "First condition"}, {cond2, "Second condition"}};
            report(*this, mCppCheck, mTokenizer, ep, Severity::style, "duplicateCondition", "The if condition is the same as the previous if condition", 398);
        }
    }
}

void CheckCondition::checkIncorrectLogicOperator() {
    if (!mSettings.sev_warning && !mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!(tok->str == "&&" || tok->str == "||") || !tok->astOperand1 || !tok->astOperand2) continue;
            const Token *c1 = tok->astOperand1, *c2 = tok->astOperand2;
            if (!c1->isComparisonOp() || !c2->isComparisonOp()) continue;
            // var op1 num1 && var op2 num2
            auto split = [](const Token *c, const Token *&var, long long &num, std::string &op) -> bool {
                if (!c->astOperand1 || !c->astOperand2) return false;
                if (c->astOperand1->varId && c->astOperand2->hasKnownIntValue() && !c->astOperand2->varId) { var = c->astOperand1; num = c->astOperand2->getKnownIntValue(); op = c->str; return true; }
                if (c->astOperand2->varId && c->astOperand1->hasKnownIntValue() && !c->astOperand1->varId) {
                    var = c->astOperand2; num = c->astOperand1->getKnownIntValue();
                    // swap operator
                    if (c->str == "<") op = ">"; else if (c->str == ">") op = "<"; else if (c->str == "<=") op = ">="; else if (c->str == ">=") op = "<="; else op = c->str;
                    return true;
                }
                return false;
            };
            const Token *v1, *v2; long long n1, n2; std::string op1, op2;
            if (!split(c1, v1, n1, op1) || !split(c2, v2, n2, op2)) continue;
            if (v1->varId != v2->varId) continue;
            if (!v1->variable || v1->variable->isFloatingType) continue;
            // evaluate for all relevant values: result of && / || over integers
            auto eval = [](const std::string &op, long long x, long long n) -> bool {
                if (op == "==") return x == n; if (op == "!=") return x != n; if (op == "<") return x < n; if (op == ">") return x > n; if (op == "<=") return x <= n; if (op == ">=") return x >= n; return false;
            };
            std::vector<long long> samples{n1 - 1, n1, n1 + 1, n2 - 1, n2, n2 + 1, (std::numeric_limits<long long>::min)() / 2, (std::numeric_limits<long long>::max)() / 2};
            bool alwaysTrue = true, alwaysFalse = true;
            bool firstRedundant = true, secondRedundant = true; // result equals cond2 only / cond1 only
            for (long long x : samples) {
                bool a = eval(op1, x, n1), b = eval(op2, x, n2);
                bool r = (tok->str == "&&") ? (a && b) : (a || b);
                if (r) alwaysFalse = false; else alwaysTrue = false;
                if (r != b) firstRedundant = false;
                if (r != a) secondRedundant = false;
            }
            const std::string cond1str = conditionString(c1);
            const std::string cond2str = conditionString(c2);
            const std::string condition = cond1str + " " + tok->str + " " + cond2str;
            ErrorPath ep;
            // value path of variable
            const ValueFlowValue *kv = v1->getKnownValue();
            if (kv) for (const auto &p : kv->errorPath) ep.push_back(p);
            if (alwaysTrue || alwaysFalse) {
                if (!mSettings.sev_warning) continue;
                ep.emplace_back(tok, "");
                const std::string msg = "Logical " + std::string(tok->str == "&&" ? "conjunction" : "disjunction") + " always evaluates to " + (alwaysTrue ? "true" : "false") + ": " + condition + ".";
                report(*this, mCppCheck, mTokenizer, ep, Severity::warning, "incorrectLogicOperator", msg + "\n" + msg + " Are these conditions necessary? Did you intend to use " + (tok->str == "&&" ? "||" : "&&") + " instead? Are the numbers correct? Are you comparing the correct variables?", 570);
            } else if (firstRedundant || secondRedundant) {
                if (!mSettings.sev_style) continue;
                ep.emplace_back(tok, "");
                const std::string msg = "Redundant condition: " + (firstRedundant ? cond2str : cond1str) + ". '" + condition + "' is equivalent to '" + (firstRedundant ? cond2str : cond1str) + "'";
                report(*this, mCppCheck, mTokenizer, ep, Severity::style, "redundantCondition", msg + "\n" + msg, 398);
            }
        }
    }
}

void CheckCondition::alwaysTrueFalse() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart->next; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (tok->link && tok->str == "<") { tok = tok->link; continue; }
            if (tok->str == "(" && tok->previous && (tok->previous->str == "static_assert" || tok->previous->str == "assert" || tok->previous->str == "ASSERT" || tok->previous->str == "sizeof" || tok->previous->str == "decltype")) { tok = tok->link; continue; }
            const ValueFlowValue *kv = tok->getKnownValue();
            if (!kv) continue;
            // is this a condition?
            const Token *parent = tok->astParent;
            while (parent && (parent->str == "||" || parent->str == "&&")) parent = parent->astParent;
            if (!parent) continue;
            const Token *condition = nullptr;
            if (parent->str == "?" && precedes(tok, parent)) condition = parent;
            else if (parent->str == "(" && parent->astOperand1 && (parent->astOperand1->str == "if" || parent->astOperand1->str == "while") && parent->astOperand2 == (tok->astParent && (tok->astParent->str == "||" || tok->astParent->str == "&&") ? [&]{ const Token *p = tok->astParent; while (p->astParent && (p->astParent->str == "||" || p->astParent->str == "&&")) p = p->astParent; return p; }() : tok)) condition = parent->astOperand1;
            else if (parent->str == ";" && parent->astParent && parent->astParent->str == ";" && parent->astOperand1 == tok) condition = parent; // for loop condition
            else if (parent->str == "return") condition = parent;
            else continue;
            if (tok->isNumber() || tok->tokType == Token::eBoolean || tok->tokType == Token::eChar) continue;
            if (tok->str == "!" && tok->astOperand1 && (tok->astOperand1->isNumber() || tok->astOperand1->tokType == Token::eBoolean)) continue;
            if ((tok->str == "||" || tok->str == "&&") && (tok->astOperand1->hasKnownIntValue() || tok->astOperand2->hasKnownIntValue())) continue;
            if (tok->isComparisonOp() && isSameExpression(tok->astOperand1, tok->astOperand2)) continue;
            // constant expression without variables -> skip (e.g. "sizeof(x) == 4", "1 + 2")
            {
                bool hasVar = false;
                std::vector<const Token*> st{tok};
                while (!st.empty()) { const Token *t = st.back(); st.pop_back(); if (!t) continue; if (t->varId) hasVar = true; if (t->str == "(" && t->astOperand1 && t->astOperand1->str == "sizeof") continue; st.push_back(t->astOperand1); st.push_back(t->astOperand2); }
                if (!hasVar) continue;
            }
            // skip if the comparison is with a variable having known value from duplicateExpression check (reported there)
            if (tok->isComparisonOp() && tok->astOperand1 && tok->astOperand2) {
                const Token *a = tok->astOperand1, *b = tok->astOperand2;
                if ((a->varId && a->hasKnownIntValue() && b->hasKnownIntValue() && !b->varId) || (b->varId && b->hasKnownIntValue() && a->hasKnownIntValue() && !a->varId)) continue;
            }
            const bool constIfWhileExpression = condition && (condition->str == "if" || condition->str == "while");
            const bool compExpr = tok->isComparisonOp() || tok->str == "!";
            const bool ternaryExpression = tok->astParent && tok->astParent->str == "?";
            const bool returnExpression = condition && condition->str == "return" && (tok->isComparisonOp() || tok->str == "&&" || tok->str == "||");
            if (!(constIfWhileExpression || compExpr || ternaryExpression || returnExpression)) continue;
            // skip pointer checks on arrays etc.
            if (tok->variable && !tok->variable->isPointer && tok->variable->isArray) continue;
            const bool alwaysTrue = kv->intvalue != 0;
            const std::string expr = tok->expressionString();
            const std::string conditionStr = (condition && condition->str == "return") ? "Return value" : "Condition";
            const std::string errmsg = conditionStr + " '" + expr + "' is always " + (alwaysTrue ? "true" : "false");
            ErrorPath ep = getErrorPath(tok, kv, errmsg);
            report(*this, mCppCheck, mTokenizer, ep, Severity::style, "knownConditionTrueFalse", errmsg, 570);
        }
    }
}

