void CheckFunctions::checkProhibitedFunctions() {
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!tok->isName() || !tok->next || tok->next->str != "(") continue;
            if (tok->varId || tok->function) continue;
            if (tok->previous && (tok->previous->str == "." || tok->previous->str == "->" || tok->previous->str == "::")) continue;
            const LibFunction *lf = mLibrary.getFunction(tok->str);
            if (!lf || lf->warnMessage.empty()) continue;
            Severity sev = severityFromString(lf->warnSeverity);
            if (sev == Severity::none) sev = Severity::style;
            if (!mSettings.isEnabled(sev)) continue;
            std::string msg = lf->warnMessage;
            if (!lf->warnAlternatives.empty()) {
                msg = "Obsolescent function '" + tok->str + "' called. It is recommended to use '" + lf->warnAlternatives + "' instead.";
                // alternatives list: a,b -> 'a' or 'b'
                std::string alts;
                std::string::size_type s = 0;
                while (true) { std::string::size_type c = lf->warnAlternatives.find(',', s); std::string a = lf->warnAlternatives.substr(s, c == std::string::npos ? std::string::npos : c - s); if (!alts.empty()) alts += (c == std::string::npos ? " or " : ", "); alts += "'" + a + "'"; if (c == std::string::npos) break; s = c + 1; }
                msg = (lf->warnReason.empty() ? "Obsolescent" : lf->warnReason) + " function '" + tok->str + "' called. It is recommended to use " + alts + " instead.";
            }
            report(*this, mCppCheck, mTokenizer, {{tok, ""}}, sev, tok->str + "Called", msg, 477);
        }
    }
}

void CheckFunctions::checkIgnoredReturnValue() {
    if (!mSettings.sev_warning && !mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!tok->isName() || !tok->next || tok->next->str != "(" || tok->varId) continue;
            if (tok->previous && (tok->previous->str == "." || tok->previous->str == "->")) continue;
            // statement start?
            const Token *prev = tok->previous;
            if (!prev || !(prev->str == ";" || prev->str == "{" || prev->str == "}")) continue;
            const Token *after = tok->next->link ? tok->next->link->next : nullptr;
            if (!after || after->str != ";") continue;
            const LibFunction *lf = mLibrary.getFunction(tok->str);
            if (!lf) continue;
            if (lf->useRetval) {
                if (!mSettings.sev_warning) continue;
                report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "ignoredReturnValue", "Return value of function " + tok->str + "() is not used.", 252, {tok->str});
            } else if (lf->pure || lf->isconst) {
                if (!mSettings.sev_style) continue;
                report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "ignoredReturnValue", "Return value of function " + tok->str + "() is not used.", 252, {tok->str});
            }
        }
    }
}

static bool isNoReturnScope(const Token *endToken, const Library &library) {
    // last statement of block is return/throw/noreturn call/exit; or if/else where both branches are noreturn; infinite loop
    if (!endToken || endToken->str != "}") return false;
    const Token *prev = endToken->previous;
    while (prev && prev->str == ";") prev = prev->previous;
    if (!prev) return false;
    if (prev == endToken->link) return false;
    if (prev->str == "}" && prev->link) {
        const Token *open = prev->link;
        const Token *before = open->previous;
        if (before && before->str == "else") {
            // else block: check both
            if (!isNoReturnScope(prev, library)) return false;
            const Token *ifEnd = before->previous;
            if (!ifEnd || ifEnd->str != "}" || !ifEnd->link) return false;
            // walk else-if chains: ifEnd belongs to "if (...) {" or "else { if"
            return isNoReturnScope(ifEnd, library);
        }
        if (before && before->str == ")" && before->link) {
            const Token *kw = before->link->previous;
            if (kw && (kw->str == "while" || kw->str == "for")) {
                // infinite loop? "while (1)" / "for (;;)"
                const Token *cond = before->link->astOperand2;
                if (kw->str == "for") {
                    const Token *semi1 = cond;
                    if (semi1 && semi1->str == ";" && semi1->astOperand2 && !semi1->astOperand2->astOperand1) {
                        // no condition -> infinite unless break
                        for (const Token *t = open; t != prev; t = t->next) if (t->str == "break") return false;
                        return true;
                    }
                    return false;
                }
                if (cond && cond->hasKnownIntValue() && cond->getKnownIntValue() != 0) {
                    for (const Token *t = open; t != prev; t = t->next) if (t->str == "break") return false;
                    return true;
                }
                return false;
            }
            if (kw && kw->str == "if") return false; // if without else
            if (kw && kw->str == "switch") {
                // all cases return and there is a default?
                bool hasDefault = false;
                for (const Token *t = open; t != prev; t = t->next) if (t->str == "default" && t->next && t->next->str == ":") hasDefault = true;
                if (!hasDefault) return false;
                // check that each case ends with return: simplified - check the last statement before each "case"/"default" and the end
                for (const Token *t = open->next; t && t != prev; t = t->next) {
                    if (t->str == "{" && t->link) { t = t->link; continue; }
                    if ((t->str == "case" || t->str == "default") && t->previous && t->previous != open) {
                        const Token *p = t->previous;
                        while (p && p->str == ";") p = p->previous;
                        // previous statement
                        const Token *stmt = p;
                        while (stmt && stmt->previous && stmt->previous->str != ";" && stmt->previous->str != "{" && stmt->previous->str != "}") stmt = stmt->previous;
                        if (!stmt || !(stmt->str == "return" || stmt->str == "throw" || (stmt->isName() && isFunctionCallNoReturn(stmt, library)) || (p && p->str == ":" ))) {
                            if (p && p->str == ";" ) {}
                            if (!(p && p->str == ":")) return false;
                        }
                    }
                }
                const Token *p = prev->previous;
                while (p && p->str == ";") p = p->previous;
                const Token *stmt = p;
                while (stmt && stmt->previous && stmt->previous->str != ";" && stmt->previous->str != "{" && stmt->previous->str != "}") stmt = stmt->previous;
                return stmt && (stmt->str == "return" || stmt->str == "throw" || (stmt->isName() && isFunctionCallNoReturn(stmt, library)));
            }
        }
        if (before && before->str == "do") return false;
        // plain block
        return isNoReturnScope(prev, library);
    }
    const Token *stmt = prev;
    while (stmt->previous && stmt->previous->str != ";" && stmt->previous->str != "{" && stmt->previous->str != "}") stmt = stmt->previous;
    if (stmt->str == "return" || stmt->str == "throw" || stmt->str == "goto") return true;
    if (stmt->isName() && stmt->next && stmt->next->str == "(" && isFunctionCallNoReturn(stmt, library)) return true;
    if (stmt->str == "asm") return true;
    return false;
}

void CheckFunctions::checkMissingReturn() {
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        const Function *function = scope->function;
        if (!function || !function->hasBody || scope->type == Scope::eLambda) continue;
        if (function->isConstructor() || function->isDestructor()) continue;
        if (function->returnsVoid || function->returnTypeStr.empty()) continue;
        if (function->returnTypeStr == "auto" || function->returnTypeStr.find("decltype") != std::string::npos) continue;
        if (function->name == "main" && mTokenizer.isCPP()) continue;
        if (function->name == "main" && !mTokenizer.isCPP() && mSettings.standards.c >= Standards::C99) continue;
        if (function->isOperator && (function->name.find("operator") == 0) && false) continue;
        // conversion operators etc
        if (function->returnTypeStr == "void" || function->returnTypeStr.compare(0, 5, "void ") == 0 && !function->returnsPointer) continue;
        if (function->isTemplate) continue;
        // if body empty "{ }" -> cppcheck skips? no, it reports. but skip "{ }" to be safe only for... report.
        const Token *end = scope->bodyEnd;
        if (isNoReturnScope(end, mLibrary)) continue;
        // body contains asm or goto? skip
        bool skip = false;
        for (const Token *t = scope->bodyStart; t && t != end; t = t->next) if (t->str == "asm" || t->str == "goto" || (t->isName() && t->next && t->next->str == ":" && t->str != "default" && t->str != "case" && !(t->previous && t->previous->str == "?") && (t->previous && (t->previous->str == ";" || t->previous->str == "{" || t->previous->str == "}")) && !(t->next->next && t->next->next->str == ":"))) { skip = true; break; }
        if (skip) continue;
        report(*this, mCppCheck, mTokenizer, {{end, ""}}, Severity::error, "missingReturn", "Found an exit path from function with non-void return type that has missing return statement", 758);
    }
}

void CheckFunctions::memsetZeroBytes() {
    if (!mSettings.sev_warning) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!(tok->str == "memset" || tok->str == "wmemset") || !tok->next || tok->next->str != "(") continue;
            if (!mLibrary.getFunction(tok->str) && tok->function) continue;
            const Token *args = tok->next->astOperand2;
            // third argument
            std::vector<const Token*> argv;
            const Token *a = args;
            while (a && a->str == ",") { argv.insert(argv.begin(), a->astOperand2); a = a->astOperand1; }
            if (a) argv.insert(argv.begin(), a);
            if (argv.size() != 3) continue;
            if (argv[2]->hasKnownIntValue() && argv[2]->getKnownIntValue() == 0 && !(argv[1]->hasKnownIntValue() && argv[1]->getKnownIntValue() == 0 && false)) {
                report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "memsetZeroBytes", tok->str + "() called to fill 0 bytes.\n" + tok->str + "() called to fill 0 bytes. The second and third arguments might be inverted. The function " + tok->str + "() is called to fill a block of memory with the second argument, repeated third argument times.", 687, {tok->str});
            }
        }
    }
}

