}

static std::string conditionString(const Token *tok) {
    if (!tok) return "";
    if (tok->isComparisonOp() && tok->astOperand1 && tok->astOperand2)
        return conditionString(tok->astOperand1) + " " + tok->str + " " + conditionString(tok->astOperand2);
    if ((tok->isConstOp() || tok->str == "&&" || tok->str == "||") && tok->astOperand1 && tok->astOperand2)
        return "(" + conditionString(tok->astOperand1) + " " + tok->str + " " + conditionString(tok->astOperand2) + ")";
    return tok->expressionString();
}

// ---------------------------------------------------------------------------
// CheckCondition
// ---------------------------------------------------------------------------
class CheckCondition : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Condition"; }
    void runChecks() override {
        multiCondition();
        duplicateCondition();
        checkIncorrectLogicOperator();
        alwaysTrueFalse();
        checkPointerAdditionResultNotNull();
    }
    void multiCondition() {}
    void duplicateCondition();
    void checkIncorrectLogicOperator();
    void alwaysTrueFalse();
    void checkPointerAdditionResultNotNull() {}
};

void CheckCondition::duplicateCondition() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!(tok->str == "if" && tok->next && tok->next->str == "(" && tok->next->link)) continue;
            const Token *cond1 = tok->next->astOperand2;
            const Token *brace = tok->next->link->next;
            if (!cond1 || !brace || brace->str != "{" || !brace->link) continue;
            // "if (x) {} if (x) {}" -> duplicateCondition when the first block has no side effects on condition vars... cppcheck: second if directly after first block (no else), variables not changed
            const Token *after = brace->link->next;
            if (!after || after->str != "if" || !after->next || after->next->str != "(") continue;
            const Token *cond2 = after->next->astOperand2;
            if (!cond2) continue;
            if (!isSameExpression(cond1, cond2)) continue;
            // variables changed in block?
            bool changed = false;
            std::vector<const Token*> stack{cond1};
            while (!stack.empty() && !changed) {
                const Token *t = stack.back(); stack.pop_back();
                if (!t) continue;
                if (t->varId && isVariableChanged(brace, brace->link, t->varId, mTokenizer.isCPP())) changed = true;
                if (t->str == "(" && t->astOperand1 && !t->isCast) changed = true; // function call -> unknown
                stack.push_back(t->astOperand1); stack.push_back(t->astOperand2);
            }
            if (changed) continue;
            ErrorPath ep{{cond1, "First condition"}, {cond2, "Second condition"}};
            report(*this, mCppCheck, mTokenizer, ep, Severity::style, "duplicateCondition", "The if condition is the same as the previous if condition", 398);
        }
    }
}

void CheckCondition::checkIncorrectLogicOperator() {
    if (!mSettings.sev_warning && !mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!(tok->str == "&&" || tok->str == "||") || !tok->astOperand1 || !tok->astOperand2) continue;
            const Token *c1 = tok->astOperand1, *c2 = tok->astOperand2;
            if (!c1->isComparisonOp() || !c2->isComparisonOp()) continue;
            // var op1 num1 && var op2 num2
            auto split = [](const Token *c, const Token *&var, long long &num, std::string &op) -> bool {
                if (!c->astOperand1 || !c->astOperand2) return false;
                if (c->astOperand1->varId && c->astOperand2->hasKnownIntValue() && !c->astOperand2->varId) { var = c->astOperand1; num = c->astOperand2->getKnownIntValue(); op = c->str; return true; }
                if (c->astOperand2->varId && c->astOperand1->hasKnownIntValue() && !c->astOperand1->varId) {
                    var = c->astOperand2; num = c->astOperand1->getKnownIntValue();
                    // swap operator
                    if (c->str == "<") op = ">"; else if (c->str == ">") op = "<"; else if (c->str == "<=") op = ">="; else if (c->str == ">=") op = "<="; else op = c->str;
                    return true;
                }
                return false;
            };
            const Token *v1, *v2; long long n1, n2; std::string op1, op2;
            if (!split(c1, v1, n1, op1) || !split(c2, v2, n2, op2)) continue;
            if (v1->varId != v2->varId) continue;
            if (!v1->variable || v1->variable->isFloatingType) continue;
            // evaluate for all relevant values: result of && / || over integers
            auto eval = [](const std::string &op, long long x, long long n) -> bool {
                if (op == "==") return x == n; if (op == "!=") return x != n; if (op == "<") return x < n; if (op == ">") return x > n; if (op == "<=") return x <= n; if (op == ">=") return x >= n; return false;
            };
            std::vector<long long> samples{n1 - 1, n1, n1 + 1, n2 - 1, n2, n2 + 1, (std::numeric_limits<long long>::min)() / 2, (std::numeric_limits<long long>::max)() / 2};
            bool alwaysTrue = true, alwaysFalse = true;
            bool firstRedundant = true, secondRedundant = true; // result equals cond2 only / cond1 only
            for (long long x : samples) {
                bool a = eval(op1, x, n1), b = eval(op2, x, n2);
                bool r = (tok->str == "&&") ? (a && b) : (a || b);
                if (r) alwaysFalse = false; else alwaysTrue = false;
                if (r != b) firstRedundant = false;
                if (r != a) secondRedundant = false;
            }
            const std::string cond1str = conditionString(c1);
            const std::string cond2str = conditionString(c2);
            const std::string condition = cond1str + " " + tok->str + " " + cond2str;
            ErrorPath ep;
            // value path of variable
            const ValueFlowValue *kv = v1->getKnownValue();
            if (kv) for (const auto &p : kv->errorPath) ep.push_back(p);
            if (alwaysTrue || alwaysFalse) {
                if (!mSettings.sev_warning) continue;
                ep.emplace_back(tok, "");
                const std::string msg = "Logical " + std::string(tok->str == "&&" ? "conjunction" : "disjunction") + " always evaluates to " + (alwaysTrue ? "true" : "false") + ": " + condition + ".";
                report(*this, mCppCheck, mTokenizer, ep, Severity::warning, "incorrectLogicOperator", msg + "\n" + msg + " Are these conditions necessary? Did you intend to use " + (tok->str == "&&" ? "||" : "&&") + " instead? Are the numbers correct? Are you comparing the correct variables?", 570);
            } else if (firstRedundant || secondRedundant) {
                if (!mSettings.sev_style) continue;
                ep.emplace_back(tok, "");
                const std::string msg = "Redundant condition: " + (firstRedundant ? cond2str : cond1str) + ". '" + condition + "' is equivalent to '" + (firstRedundant ? cond2str : cond1str) + "'";
                report(*this, mCppCheck, mTokenizer, ep, Severity::style, "redundantCondition", msg + "\n" + msg, 398);
            }
        }
    }
}

void CheckCondition::alwaysTrueFalse() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart->next; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (tok->link && tok->str == "<") { tok = tok->link; continue; }
            if (tok->str == "(" && tok->previous && (tok->previous->str == "static_assert" || tok->previous->str == "assert" || tok->previous->str == "ASSERT" || tok->previous->str == "sizeof" || tok->previous->str == "decltype")) { tok = tok->link; continue; }
            const ValueFlowValue *kv = tok->getKnownValue();
            if (!kv) continue;
            // is this a condition?
            const Token *parent = tok->astParent;
            while (parent && (parent->str == "||" || parent->str == "&&")) parent = parent->astParent;
            if (!parent) continue;
            const Token *condition = nullptr;
            if (parent->str == "?" && precedes(tok, parent)) condition = parent;
            else if (parent->str == "(" && parent->astOperand1 && (parent->astOperand1->str == "if" || parent->astOperand1->str == "while") && parent->astOperand2 == (tok->astParent && (tok->astParent->str == "||" || tok->astParent->str == "&&") ? [&]{ const Token *p = tok->astParent; while (p->astParent && (p->astParent->str == "||" || p->astParent->str == "&&")) p = p->astParent; return p; }() : tok)) condition = parent->astOperand1;
            else if (parent->str == ";" && parent->astParent && parent->astParent->str == ";" && parent->astOperand1 == tok) condition = parent; // for loop condition
            else if (parent->str == "return") condition = parent;
            else continue;
            if (tok->isNumber() || tok->tokType == Token::eBoolean || tok->tokType == Token::eChar) continue;
            if (tok->str == "!" && tok->astOperand1 && (tok->astOperand1->isNumber() || tok->astOperand1->tokType == Token::eBoolean)) continue;
            if ((tok->str == "||" || tok->str == "&&") && (tok->astOperand1->hasKnownIntValue() || tok->astOperand2->hasKnownIntValue())) continue;
            if (tok->isComparisonOp() && isSameExpression(tok->astOperand1, tok->astOperand2)) continue;
            // constant expression without variables -> skip (e.g. "sizeof(x) == 4", "1 + 2")
            {
                bool hasVar = false;
                std::vector<const Token*> st{tok};
                while (!st.empty()) { const Token *t = st.back(); st.pop_back(); if (!t) continue; if (t->varId) hasVar = true; if (t->str == "(" && t->astOperand1 && t->astOperand1->str == "sizeof") continue; st.push_back(t->astOperand1); st.push_back(t->astOperand2); }
                if (!hasVar) continue;
            }
            // skip if the comparison is with a variable having known value from duplicateExpression check (reported there)
            if (tok->isComparisonOp() && tok->astOperand1 && tok->astOperand2) {
                const Token *a = tok->astOperand1, *b = tok->astOperand2;
                if ((a->varId && a->hasKnownIntValue() && b->hasKnownIntValue() && !b->varId) || (b->varId && b->hasKnownIntValue() && a->hasKnownIntValue() && !a->varId)) continue;
            }
            const bool constIfWhileExpression = condition && (condition->str == "if" || condition->str == "while");
            const bool compExpr = tok->isComparisonOp() || tok->str == "!";
            const bool ternaryExpression = tok->astParent && tok->astParent->str == "?";
            const bool returnExpression = condition && condition->str == "return" && (tok->isComparisonOp() || tok->str == "&&" || tok->str == "||");
            if (!(constIfWhileExpression || compExpr || ternaryExpression || returnExpression)) continue;
            // skip pointer checks on arrays etc.
            if (tok->variable && !tok->variable->isPointer && tok->variable->isArray) continue;
            const bool alwaysTrue = kv->intvalue != 0;
            const std::string expr = tok->expressionString();
            const std::string conditionStr = (condition && condition->str == "return") ? "Return value" : "Condition";
            const std::string errmsg = conditionStr + " '" + expr + "' is always " + (alwaysTrue ? "true" : "false");
            ErrorPath ep = getErrorPath(tok, kv, errmsg);
            report(*this, mCppCheck, mTokenizer, ep, Severity::style, "knownConditionTrueFalse", errmsg, 570);
        }
    }
}

// ---------------------------------------------------------------------------
// CheckFunctions
// ---------------------------------------------------------------------------
class CheckFunctions : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Check function usage"; }
    void runChecks() override {
        checkProhibitedFunctions();
        invalidFunctionUsage();
        checkIgnoredReturnValue();
        checkMissingReturn();
        memsetZeroBytes();
        checkLibraryMatchFunctions();
    }
    void checkProhibitedFunctions();
    void invalidFunctionUsage() {}
    void checkIgnoredReturnValue();
    void checkMissingReturn();
    void memsetZeroBytes();
    void checkLibraryMatchFunctions() {}
};

void CheckFunctions::checkProhibitedFunctions() {
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!tok->isName() || !tok->next || tok->next->str != "(") continue;
            if (tok->varId || tok->function) continue;
            if (tok->previous && (tok->previous->str == "." || tok->previous->str == "->" || tok->previous->str == "::")) continue;
            const LibFunction *lf = mLibrary.getFunction(tok->str);
            if (!lf || lf->warnMessage.empty()) continue;
            Severity sev = severityFromString(lf->warnSeverity);
            if (sev == Severity::none) sev = Severity::style;
            if (!mSettings.isEnabled(sev)) continue;
            std::string msg = lf->warnMessage;
            if (!lf->warnAlternatives.empty()) {
                msg = "Obsolescent function '" + tok->str + "' called. It is recommended to use '" + lf->warnAlternatives + "' instead.";
                // alternatives list: a,b -> 'a' or 'b'
                std::string alts;
                std::string::size_type s = 0;
                while (true) { std::string::size_type c = lf->warnAlternatives.find(',', s); std::string a = lf->warnAlternatives.substr(s, c == std::string::npos ? std::string::npos : c - s); if (!alts.empty()) alts += (c == std::string::npos ? " or " : ", "); alts += "'" + a + "'"; if (c == std::string::npos) break; s = c + 1; }
                msg = (lf->warnReason.empty() ? "Obsolescent" : lf->warnReason) + " function '" + tok->str + "' called. It is recommended to use " + alts + " instead.";
            }
            report(*this, mCppCheck, mTokenizer, {{tok, ""}}, sev, tok->str + "Called", msg, 477);
        }
    }
}

void CheckFunctions::checkIgnoredReturnValue() {
    if (!mSettings.sev_warning && !mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!tok->isName() || !tok->next || tok->next->str != "(" || tok->varId) continue;
            if (tok->previous && (tok->previous->str == "." || tok->previous->str == "->")) continue;
            // statement start?
            const Token *prev = tok->previous;
            if (!prev || !(prev->str == ";" || prev->str == "{" || prev->str == "}")) continue;
            const Token *after = tok->next->link ? tok->next->link->next : nullptr;
            if (!after || after->str != ";") continue;
            const LibFunction *lf = mLibrary.getFunction(tok->str);
            if (!lf) continue;
            if (lf->useRetval) {
                if (!mSettings.sev_warning) continue;
                report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "ignoredReturnValue", "Return value of function " + tok->str + "() is not used.", 252, {tok->str});
            } else if (lf->pure || lf->isconst) {
                if (!mSettings.sev_style) continue;
                report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "ignoredReturnValue", "Return value of function " + tok->str + "() is not used.", 252, {tok->str});
            }
        }
    }
}

static bool isNoReturnScope(const Token *endToken, const Library &library) {
    // last statement of block is return/throw/noreturn call/exit; or if/else where both branches are noreturn; infinite loop
    if (!endToken || endToken->str != "}") return false;
    const Token *prev = endToken->previous;
    while (prev && prev->str == ";") prev = prev->previous;
    if (!prev) return false;
    if (prev == endToken->link) return false;
    if (prev->str == "}" && prev->link) {
        const Token *open = prev->link;
        const Token *before = open->previous;
        if (before && before->str == "else") {
            // else block: check both
            if (!isNoReturnScope(prev, library)) return false;
            const Token *ifEnd = before->previous;
            if (!ifEnd || ifEnd->str != "}" || !ifEnd->link) return false;
            // walk else-if chains: ifEnd belongs to "if (...) {" or "else { if"
            return isNoReturnScope(ifEnd, library);
        }
        if (before && before->str == ")" && before->link) {
            const Token *kw = before->link->previous;
            if (kw && (kw->str == "while" || kw->str == "for")) {
                // infinite loop? "while (1)" / "for (;;)"
                const Token *cond = before->link->astOperand2;
                if (kw->str == "for") {
                    const Token *semi1 = cond;
                    if (semi1 && semi1->str == ";" && semi1->astOperand2 && !semi1->astOperand2->astOperand1) {
                        // no condition -> infinite unless break
                        for (const Token *t = open; t != prev; t = t->next) if (t->str == "break") return false;
                        return true;
                    }
                    return false;
                }
                if (cond && cond->hasKnownIntValue() && cond->getKnownIntValue() != 0) {
                    for (const Token *t = open; t != prev; t = t->next) if (t->str == "break") return false;
                    return true;
                }
                return false;
            }
            if (kw && kw->str == "if") return false; // if without else
            if (kw && kw->str == "switch") {
                // all cases return and there is a default?
                bool hasDefault = false;
                for (const Token *t = open; t != prev; t = t->next) if (t->str == "default" && t->next && t->next->str == ":") hasDefault = true;
                if (!hasDefault) return false;
                // check that each case ends with return: simplified - check the last statement before each "case"/"default" and the end
                for (const Token *t = open->next; t && t != prev; t = t->next) {
                    if (t->str == "{" && t->link) { t = t->link; continue; }
                    if ((t->str == "case" || t->str == "default") && t->previous && t->previous != open) {
                        const Token *p = t->previous;
                        while (p && p->str == ";") p = p->previous;
                        // previous statement
                        const Token *stmt = p;
                        while (stmt && stmt->previous && stmt->previous->str != ";" && stmt->previous->str != "{" && stmt->previous->str != "}") stmt = stmt->previous;
                        if (!stmt || !(stmt->str == "return" || stmt->str == "throw" || (stmt->isName() && isFunctionCallNoReturn(stmt, library)) || (p && p->str == ":" ))) {
                            if (p && p->str == ";" ) {}
                            if (!(p && p->str == ":")) return false;
                        }
                    }
                }
                const Token *p = prev->previous;
                while (p && p->str == ";") p = p->previous;
                const Token *stmt = p;
                while (stmt && stmt->previous && stmt->previous->str != ";" && stmt->previous->str != "{" && stmt->previous->str != "}") stmt = stmt->previous;
                return stmt && (stmt->str == "return" || stmt->str == "throw" || (stmt->isName() && isFunctionCallNoReturn(stmt, library)));
            }
        }
        if (before && before->str == "do") return false;
        // plain block
        return isNoReturnScope(prev, library);
    }
    const Token *stmt = prev;
    while (stmt->previous && stmt->previous->str != ";" && stmt->previous->str != "{" && stmt->previous->str != "}") stmt = stmt->previous;
    if (stmt->str == "return" || stmt->str == "throw" || stmt->str == "goto") return true;
    if (stmt->isName() && stmt->next && stmt->next->str == "(" && isFunctionCallNoReturn(stmt, library)) return true;
    if (stmt->str == "asm") return true;
    return false;
}

void CheckFunctions::checkMissingReturn() {
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        const Function *function = scope->function;
        if (!function || !function->hasBody || scope->type == Scope::eLambda) continue;
        if (function->isConstructor() || function->isDestructor()) continue;
        if (function->returnsVoid || function->returnTypeStr.empty()) continue;
        if (function->returnTypeStr == "auto" || function->returnTypeStr.find("decltype") != std::string::npos) continue;
        if (function->name == "main" && mTokenizer.isCPP()) continue;
        if (function->name == "main" && !mTokenizer.isCPP() && mSettings.standards.c >= Standards::C99) continue;
        if (function->isOperator && (function->name.find("operator") == 0) && false) continue;
        // conversion operators etc
        if (function->returnTypeStr == "void" || function->returnTypeStr.compare(0, 5, "void ") == 0 && !function->returnsPointer) continue;
        if (function->isTemplate) continue;
        // if body empty "{ }" -> cppcheck skips? no, it reports. but skip "{ }" to be safe only for... report.
        const Token *end = scope->bodyEnd;
        if (isNoReturnScope(end, mLibrary)) continue;
        // body contains asm or goto? skip
        bool skip = false;
        for (const Token *t = scope->bodyStart; t && t != end; t = t->next) if (t->str == "asm" || t->str == "goto" || (t->isName() && t->next && t->next->str == ":" && t->str != "default" && t->str != "case" && !(t->previous && t->previous->str == "?") && (t->previous && (t->previous->str == ";" || t->previous->str == "{" || t->previous->str == "}")) && !(t->next->next && t->next->next->str == ":"))) { skip = true; break; }
        if (skip) continue;
        report(*this, mCppCheck, mTokenizer, {{end, ""}}, Severity::error, "missingReturn", "Found an exit path from function with non-void return type that has missing return statement", 758);
    }
}

void CheckFunctions::memsetZeroBytes() {
    if (!mSettings.sev_warning) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!(tok->str == "memset" || tok->str == "wmemset") || !tok->next || tok->next->str != "(") continue;
            if (!mLibrary.getFunction(tok->str) && tok->function) continue;
            const Token *args = tok->next->astOperand2;
            // third argument
            std::vector<const Token*> argv;
            const Token *a = args;
            while (a && a->str == ",") { argv.insert(argv.begin(), a->astOperand2); a = a->astOperand1; }
            if (a) argv.insert(argv.begin(), a);
            if (argv.size() != 3) continue;
            if (argv[2]->hasKnownIntValue() && argv[2]->getKnownIntValue() == 0 && !(argv[1]->hasKnownIntValue() && argv[1]->getKnownIntValue() == 0 && false)) {
                report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "memsetZeroBytes", tok->str + "() called to fill 0 bytes.\n" + tok->str + "() called to fill 0 bytes. The second and third arguments might be inverted. The function " + tok->str + "() is called to fill a block of memory with the second argument, repeated third argument times.", 687, {tok->str});
            }
        }
    }
}

