void CheckOther::warningOldStylePointerCast() {
    if (!mSettings.sev_style || !mTokenizer.isCPP()) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (tok->str != "(" || !tok->isCast || !tok->link) continue;
            // (type *) or (type &)
            const Token *last = tok->link->previous;
            if (!last || !(last->str == "*" || last->str == "&")) continue;
            // skip casts of literals like (char*)0 ? cppcheck: skip if operand is NULL/0? It warns for "(char*)0"? "warningOldStylePointerCast" is reported unless the cast is on "0"/"NULL"... it skips: if (Token::Match(tok->link()->next(), "%num%|%bool%|%char%|%str%")) continue;  hmm.
            const Token *operand = tok->link->next;
            if (operand && (operand->isNumber() || operand->tokType == Token::eBoolean || operand->tokType == Token::eChar || operand->tokType == Token::eString)) continue;
            if (operand && operand->str == "NULL") continue;
            // skip if type is const? no
            report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "cstyleCast", "C-style pointer casting", 398);
        }
    }
}

void CheckOther::checkRedundantAssignment() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        if (!scope->function) continue;
        for (const Token *tok = scope->bodyStart->next; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (tok->str != "=" || tok->astParent || !tok->astOperand1 || !tok->astOperand2) continue;
            const Token *lhs = tok->astOperand1;
            if (!lhs->variable) continue;
            const Variable *var = lhs->variable;
            if (!var->isLocal || var->isStatic || var->isReference || var->isVolatile) continue;
            if (var->isClass && !var->isPointer) continue;
            if (var->isArray) continue;
            // rhs has side effects (function call)? cppcheck still reports if rhs is a function call? It skips when rhs has side effects (non-const function calls) only for... keep: skip function calls
            {
                bool call = false;
                std::vector<const Token*> st{tok->astOperand2};
                while (!st.empty()) { const Token *t = st.back(); st.pop_back(); if (!t) continue; if (t->str == "(" && !t->isCast && t->astOperand1) call = true; if (t->isAssignmentOp() || t->str == "++" || t->str == "--") call = true; st.push_back(t->astOperand1); st.push_back(t->astOperand2); }
                if (call) continue;
            }
            // find next statement that reads or reassigns lhs in same scope, straight-line
            const Token *stmtEnd = tok;
            while (stmtEnd && stmtEnd->str != ";") stmtEnd = stmtEnd->next;
            if (!stmtEnd) continue;
            bool inLoop = false;
            for (const Scope *s = tok->scope; s && s->isExecutable(); s = s->nestedIn) if (s->isLoopScope()) inLoop = true;
            if (inLoop) continue;
            const Token *reassign = nullptr;
            bool read = false;
            int depth = 0;
            for (const Token *t = stmtEnd->next; t && t != scope->bodyEnd; t = t->next) {
                if (t->str == "{" && t->link) { if (t->previous && t->previous->str == "=") { t = t->link; continue; } ++depth; continue; }
                if (t->str == "}") { if (depth == 0) break; --depth; continue; }
                if (t->str == "return" || t->str == "break" || t->str == "continue" || t->str == "goto" || t->str == "throw" || t->str == "asm") { for (const Token *x = t; x && x->str != ";"; x = x->next) if (x->varId == lhs->varId) read = true; break; }
                if (t->varId != lhs->varId) {
                    // function call could read a global/static? var is local -> fine. But address of var taken before? check at any time
                    continue;
                }
                const Token *p = t->astParent;
                if (p && p->str == "=" && p->astOperand1 == t && !p->astParent) {
                    // rhs reads t?
                    bool rhsReads = false;
                    std::vector<const Token*> st{p->astOperand2};
                    while (!st.empty()) { const Token *x = st.back(); st.pop_back(); if (!x) continue; if (x->varId == lhs->varId) rhsReads = true; st.push_back(x->astOperand1); st.push_back(x->astOperand2); }
                    if (rhsReads) { read = true; break; }
                    if (depth > 0) { read = true; break; } // conditional reassignment: cppcheck bails
                    reassign = p;
                    break;
                }
                read = true;
                break;
            }
            if (read || !reassign) continue;
            // check rhs of second assignment has no side-effect function call
            {
                bool call = false;
                std::vector<const Token*> st{reassign->astOperand2};
                while (!st.empty()) { const Token *t = st.back(); st.pop_back(); if (!t) continue; if (t->str == "(" && !t->isCast && t->astOperand1) call = true; st.push_back(t->astOperand1); st.push_back(t->astOperand2); }
                if (call) continue;
            }
            const bool isInit = tok->isSplittedVarDeclEq;
            if (isInit) {
                ErrorPath ep{{tok, var->name + " is initialized"}, {reassign, var->name + " is overwritten"}};
                report(*this, mCppCheck, mTokenizer, ep, Severity::style, "redundantInitialization", "Redundant initialization for '" + var->name + "'. The initialized value is overwritten before it is read.", 563, {var->name});
            } else {
                ErrorPath ep{{tok, var->name + " is assigned"}, {reassign, var->name + " is overwritten"}};
                report(*this, mCppCheck, mTokenizer, ep, Severity::style, "redundantAssignment", "Variable '" + var->name + "' is reassigned a value before the old one has been used.", 563, {var->name});
            }
        }
    }
}

static bool sameTokenRange(const Token *s1, const Token *e1, const Token *s2, const Token *e2) {
    const Token *a = s1, *b = s2;
    while (a != e1 && b != e2) {
        if (!a || !b) return false;
        if (a->str != b->str) return false;
        a = a->next; b = b->next;
    }
    return a == e1 && b == e2;
}

void CheckOther::checkDuplicateBranch() {
    if (!mSettings.sev_style || !mSettings.inconclusive) return;
    for (const Scope &scope : mSymbolDatabase.scopeList) {
        if (scope.type != Scope::eIf) continue;
        const Token *elseTok = scope.bodyEnd->next;
        if (!elseTok || elseTok->str != "else" || !elseTok->next || elseTok->next->str != "{") continue;
        const Token *elseStart = elseTok->next;
        if (elseStart->next && elseStart->next->str == "if") continue;
        // empty branches skip
        if (scope.bodyStart->next == scope.bodyEnd) continue;
        if (!sameTokenRange(scope.bodyStart->next, scope.bodyEnd, elseStart->next, elseStart->link)) continue;
        // cppcheck skips when branches contain declarations? no. Report at "if" token and else
        ErrorPath ep{{elseStart->previous, ""}, {scope.classDef, ""}};
        // Actually callstack: tok (if) first then else "{"? Observed: primary location 'if' (3:5) and note order: else at 5:7 first then if 3:5
        ErrorPath ep2{{elseTok->next, ""}, {scope.classDef, ""}};
        (void)ep;
        report(*this, mCppCheck, mTokenizer, ep2, Severity::style, "duplicateBranch", "Found duplicate branches for 'if' and 'else'.\nFinding the same code in an 'if' and related 'else' branch is suspicious and might indicate a cut and paste or logic error. Please examine this code carefully to determine if it is correct.", 398, {}, Certainty::inconclusive, &mSettings);
    }
}

void CheckOther::checkDuplicateExpression() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!tok->astOperand1 || !tok->astOperand2) continue;
            const Token *a = tok->astOperand1, *b = tok->astOperand2;
            if (tok->isComparisonOp() || tok->str == "&&" || tok->str == "||" || tok->str == "-" || tok->str == "/" || tok->str == "%" || tok->str == "&" || tok->str == "|" || tok->str == "^" ) {
                // x == x etc.
                if (tok->str == "-" || tok->str == "/" || tok->str == "%") {
                    if (!(a->varId || a->str == "(" ) || !isSameExpression(a, b)) continue;
                    if (a->varId == 0) continue;
                    if (astIsFloat(a)) continue;
                } else if (!isSameExpression(a, b)) {
                    // follow variable: compare var with constant where var has known value from assignment
                    if (tok->isComparisonOp()) {
                        const Token *var = nullptr, *cst = nullptr;
                        if (a->varId && !b->varId && b->hasKnownIntValue() && !b->astOperand1) { var = a; cst = b; }
                        else if (b->varId && !a->varId && a->hasKnownIntValue() && !a->astOperand1) { var = b; cst = a; }
                        if (!var || !var->variable) continue;
                        const ValueFlowValue *kv = var->getKnownValue();
                        if (!kv || kv->errorPath.empty()) continue;
                        // the known value must come from a plain assignment of the same constant token string
                        if (kv->intvalue != cst->getKnownIntValue()) continue;
                        // only for plain variables of integral type
                        if (var->variable->isPointer || var->variable->isArray) continue;
                        const std::string expr1 = a->expressionString(), expr2 = b->expressionString();
                        std::string msg = "The comparison '" + expr1 + " " + tok->str + " " + expr2 + "' is always ";
                        if (tok->str == "==" || tok->str == ">=" || tok->str == "<=") msg += "true";
                        else msg += "false";
                        ErrorPath ep;
                        for (const auto &p : kv->errorPath) {
                            // cppcheck followVar note: "'x' is assigned value 'N' here."
                            ep.emplace_back(p.first, "'" + var->str + "' is assigned value '" + std::to_string(kv->intvalue) + "' here.");
                        }
                        ep.emplace_back(tok, "");
                        report(*this, mCppCheck, mTokenizer, ep, Severity::style, "knownConditionTrueFalse", msg + ".\nFinding the same expression on both sides of an operator is suspicious and might indicate a cut and paste or logic error. Please examine this code carefully to determine if it is correct.", 398);
                    }
                    continue;
                }
                if (!a->varId && a->str != "(" && !a->astOperand1) continue; // literals
                if (a->isNumber() || a->isLiteral()) continue;
                // function calls are not same
                bool call = false;
                std::vector<const Token*> st{a};
                while (!st.empty()) { const Token *t = st.back(); st.pop_back(); if (!t) continue; if (t->str == "(" && !t->isCast && t->astOperand1) call = true; st.push_back(t->astOperand1); st.push_back(t->astOperand2); }
                if (call) continue;
                // floating point "x != x" is a NaN check -> skip
                if (tok->isComparisonOp() && astIsFloat(a)) continue;
                if (tok->str == "&&" || tok->str == "||") {
                    // "x && x" -> duplicateExpression
                }
                const std::string expr1 = a->expressionString();
                std::string msg = "Same expression on both sides of '" + tok->str + "'";
                std::string id = "duplicateExpression";
                if (tok->isComparisonOp() || tok->str == "&&" || tok->str == "||") {
                    // same expression: "knownConditionTrueFalse"? cppcheck: expr1 == expr2 -> duplicateExpression
                }
                ErrorPath ep{{tok, ""}};
                report(*this, mCppCheck, mTokenizer, ep, Severity::style, id, msg + ".\nFinding the same expression on both sides of an operator is suspicious and might indicate a cut and paste or logic error. Please examine this code carefully to determine if it is correct.", 398);
                continue;
            }
            // self assignment "x = x"
            if (tok->str == "=" && a->varId && isSameExpression(a, b) && mSettings.sev_style) {
                if (tok->astParent) continue;
                report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "selfAssignment", "Redundant assignment of '" + a->expressionString() + "' to itself.", 398, {a->expressionString()});
            }
        }
    }
}

void CheckOther::checkUnreachableCode() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            const Token *secondBreak = nullptr;
            const Token *labelName = nullptr;
            if (tok->link && (tok->str == "(" || tok->str == "[" || tok->str == "<")) { tok = tok->link; continue; }
            if (tok->str == "break" || tok->str == "continue") secondBreak = tok->next ? tok->next->next : nullptr; // "break ;" -> token after ';'
            else if (tok->str == "return" || tok->str == "throw" || tok->str == "goto") {
                const Token *semi = tok;
                while (semi && semi->str != ";") semi = semi->next;
                if (!semi) continue;
                secondBreak = semi->next;
                if (tok->str == "goto") labelName = tok->next;
            } else if (tok->isName() && tok->next && tok->next->str == "(" && tok->next->link && isFunctionCallNoReturn(tok, mLibrary) && tok->previous && (tok->previous->str == ";" || tok->previous->str == "{" || tok->previous->str == "}")) {
                const Token *semi = tok->next->link->next;
                if (semi && semi->str == ";") secondBreak = semi->next;
            }
            if (!secondBreak) continue;
            if (secondBreak->str == "}" ) continue;
            // label or case/default is fine
            if (secondBreak->str == "case" || secondBreak->str == "default") continue;
            if (secondBreak->isName() && secondBreak->next && secondBreak->next->str == ":" ) continue;
            if (secondBreak->str == ";" ) continue;
            if (secondBreak->str == "{" ) continue;
            if (secondBreak->str == "break" || secondBreak->str == "continue") {
                if (secondBreak->str == "break" && tok->str != "break" ) {
                    // "return; break;" in switch -> duplicateBreak
                }
                const bool inconclusive = secondBreak->isExpandedMacro;
                report(*this, mCppCheck, mTokenizer, {{secondBreak, ""}}, Severity::style, "duplicateBreak", "Consecutive return, break, continue, goto or throw statements are unnecessary.\nConsecutive return, break, continue, goto or throw statements are unnecessary. The second statement can never be executed, and so should be removed.", 561, {}, inconclusive ? Certainty::inconclusive : Certainty::normal, &mSettings);
                tok = secondBreak;
                continue;
            }
            if (secondBreak->str == "return" || secondBreak->str == "throw" || secondBreak->str == "goto") {
                if (tok->str == "return" && secondBreak->str == "return" ) {
                    const bool inconclusive = secondBreak->isExpandedMacro;
                    report(*this, mCppCheck, mTokenizer, {{secondBreak, ""}}, Severity::style, "duplicateBreak", "Consecutive return, break, continue, goto or throw statements are unnecessary.\nConsecutive return, break, continue, goto or throw statements are unnecessary. The second statement can never be executed, and so should be removed.", 561, {}, inconclusive ? Certainty::inconclusive : Certainty::normal, &mSettings);
                    tok = secondBreak; continue;
                }
                const bool inconclusive = secondBreak->isExpandedMacro;
                report(*this, mCppCheck, mTokenizer, {{secondBreak, ""}}, Severity::style, "duplicateBreak", "Consecutive return, break, continue, goto or throw statements are unnecessary.\nConsecutive return, break, continue, goto or throw statements are unnecessary. The second statement can never be executed, and so should be removed.", 561, {}, inconclusive ? Certainty::inconclusive : Certainty::normal, &mSettings);
                tok = secondBreak; continue;
            }
            // declaration after return: skip (cppcheck: "if (Token::Match(secondBreak, "%type% %var%")) continue? no it warns for executable statements only")
            if (secondBreak->isName() && secondBreak->next && (secondBreak->next->varId || secondBreak->next->str == "*" || secondBreak->next->str == "&") && (secondBreak->isStandardType() || secondBreak->tokType == Token::eType || secondBreak->isKeyword())) {
                // variable declaration: cppcheck skips declarations
                continue;
            }
            if (labelName && false) {}
            // unreachable code
            {
                const bool inconclusive = secondBreak->isExpandedMacro;
                std::string stmt = tok->str;
                if (tok->isName() && tok->next && tok->next->str == "(" && !(tok->str == "return" || tok->str == "throw" || tok->str == "goto" || tok->str == "break" || tok->str == "continue"))
                    report(*this, mCppCheck, mTokenizer, {{secondBreak, ""}}, Severity::style, "unreachableCode", "Statements following noreturn function '" + tok->str + "()' will never be executed.", 561, {}, inconclusive ? Certainty::inconclusive : Certainty::normal, &mSettings);
                else
                    report(*this, mCppCheck, mTokenizer, {{secondBreak, ""}}, Severity::style, "unreachableCode", "Statements following '" + stmt + "' will never be executed.", 561, {}, inconclusive ? Certainty::inconclusive : Certainty::normal, &mSettings);
            }
            tok = secondBreak;
        }
    }
}

void CheckOther::checkSuspiciousSemicolon() {
    if (!mSettings.sev_warning || !mSettings.inconclusive) return;
    for (const Scope &scope : mSymbolDatabase.scopeList) {
        if (scope.type != Scope::eIf && scope.type != Scope::eWhile && scope.type != Scope::eFor) continue;
        // body is "{ }" created from ";" : braces inserted have same line/col as ';'
        if (scope.bodyStart->next != scope.bodyEnd) continue;
        const Token *cond = scope.classDef->next;
        if (!cond || !cond->link) continue;
        // original ";" directly after ")" on the same line and the next statement on a following line
        if (scope.bodyStart->linenr != cond->link->linenr) continue;
        const Token *after = scope.bodyEnd->next;
        if (after && after->linenr == scope.bodyEnd->linenr) continue;
        if (after && after->str == "else") continue;
        report(*this, mCppCheck, mTokenizer, {{scope.bodyStart, ""}}, Severity::warning, "suspiciousSemicolon", "Suspicious use of ; at the end of '" + scope.classDef->str + "' statement.", 398, {}, Certainty::inconclusive, &mSettings);
    }
}

static bool isSimpleType(const Variable *var) {
    return !var->isClass && !var->isArray || (var->isArray && !var->isClass);
}

void CheckOther::checkVariableScope() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Variable &var : scope->varlist) {
            if (var.isArgument || var.isStatic || var.isGlobal || var.isReference || var.isExtern || var.isVolatile) continue;
            if (var.scope != scope) continue;
            if (var.isClass && !var.isPointer && !var.isEnumType) continue;
            if (var.isArray && var.isClass) continue;
            if (var.isPointer && var.isInit) {
                // pointer initialized with address? cppcheck: pointers initialized with non-constant -> skip
            }
            // initializer must be constant or absent
            const Token *declEnd = var.declEndToken;
            if (!declEnd) continue;
            if (declEnd->str == "=") {
                const Token *rhs = declEnd->astOperand2;
                if (!rhs) continue;
                bool constInit = (rhs->isNumber() || rhs->isLiteral() || rhs->str == "NULL" || rhs->str == "nullptr") || (rhs->str == "-" && rhs->astOperand1 && rhs->astOperand1->isNumber() && !rhs->astOperand2) || rhs->str == "{" ;
                if (!constInit) continue;
            } else if (declEnd->str == "(" || declEnd->str == "{") {
                continue;
            }
            // find all usages
            const Token *firstUse = nullptr;
            const Scope *useScope = nullptr;
            bool bail = false;
            bool usedInMultipleScopes = false;
            std::vector<const Token*> uses;
            for (const Token *t = scope->bodyStart; t && t != scope->bodyEnd; t = t->next) {
                if (t->varId != var.varId || t == var.nameToken) continue;
                uses.push_back(t);
            }
            if (uses.empty()) continue;
            // determine the innermost scope containing all uses
            auto scopeDepth = [&](const Scope *s) { int d = 0; while (s && s != scope) { ++d; s = s->nestedIn; } return d; };
            const Scope *common = uses[0]->scope;
            for (const Token *u : uses) {
                const Scope *s = u->scope;
                // find common ancestor
                while (common && scopeDepth(common) > scopeDepth(s)) common = common->nestedIn;
                const Scope *s2 = s;
                while (s2 && scopeDepth(s2) > scopeDepth(common)) s2 = s2->nestedIn;
                while (common != s2 && common) { common = common->nestedIn; s2 = s2->nestedIn; }
            }
            if (!common || common == scope) continue;
            // common must be a nested scope: if it's a loop scope, the variable must not be used in a way that depends on previous iterations
            // cppcheck: if used in loop, variable must be assigned before read in each iteration (checkInnerScope). Simplify: if the common scope (or any ancestor up to function) is a loop and first use is a read -> skip
            const Scope *s = common;
            bool inLoop = false;
            while (s && s != scope) { if (s->isLoopScope()) inLoop = true; s = s->nestedIn; }
            if (inLoop) {
                // first use must be a write (assignment) and the variable must not be read before written... conservative: require first use to be "x =" at statement level and no "break"-dependent usage
                const Token *fu = uses[0];
                bool firstIsWrite = fu->astParent && fu->astParent->str == "=" && fu->astParent->astOperand1 == fu && !fu->astParent->astParent;
                if (!firstIsWrite) continue;
                // the first write must dominate: it must be directly in the common scope (not nested)
                if (fu->scope != common) continue;
                // all uses must be inside the loop scope (common) - yes by construction
                // if variable is read in loop condition? no (would be outside)
            }
            // all uses are inside 'common'. Also the first use must be a write unless const-initialized
            if (declEnd->str != "=") {
                const Token *fu = uses[0];
                bool firstIsWrite = (fu->astParent && fu->astParent->str == "=" && fu->astParent->astOperand1 == fu);
                if (!firstIsWrite && !(var.isArray)) continue;
                if (var.isArray) {
                    // array written via element or passed to function first
                }
            }
            // check that scopes between: e.g. "for" scopes: the variable's "used" scope is a for loop body -> cppcheck checks checkInnerScope; skip loops that read before write handled above
            // report
            (void)firstUse; (void)useScope; (void)bail; (void)usedInMultipleScopes;
            report(*this, mCppCheck, mTokenizer, {{var.nameToken, ""}}, Severity::style, "variableScope", "The scope of the variable '" + var.name + "' can be reduced.\nThe scope of the variable '" + var.name + "' can be reduced. Warning: Be careful when fixing this message, especially when there are inner loops. Here is an example where cppcheck will write that the scope for 'i' can be reduced:\nvoid f(int x)\n{\n    int i = 0;\n    if (x) {\n        // it's safe to move 'int i = 0;' here\n        for (int n = 0; n < 10; ++n) {\n            // it is possible but not safe to move 'int i = 0;' here\n            do_something(&i);\n        }\n    }\n}\nWhen you see this message it is always safe to reduce the variable scope 1 level.", 398, {var.name});
        }
    }
}

void CheckOther::checkSignOfUnsignedVariable() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!tok->isComparisonOp() || !tok->astOperand1 || !tok->astOperand2) continue;
            const Token *a = tok->astOperand1, *b = tok->astOperand2;
            auto isUnsignedVar = [](const Token *t) { return t->variable && t->variable->isUnsigned && !t->variable->isPointer && !t->variable->isArray; };
            auto isZero = [](const Token *t) { return t->isNumber() && t->hasKnownIntValue() && t->getKnownIntValue() == 0; };
            if (isUnsignedVar(a) && isZero(b)) {
                if (tok->str == "<") report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "unsignedLessThanZero", "Checking if unsigned expression '" + a->expressionString() + "' is less than zero.\nThe unsigned expression '" + a->expressionString() + "' will never be negative so it is either pointless or an error to check if it is.", 570, {a->expressionString()});
                else if (tok->str == ">=") report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "unsignedPositive", "Unsigned expression '" + a->expressionString() + "' can't be negative so it is unnecessary to test it.", 570, {a->expressionString()});
            } else if (isUnsignedVar(b) && isZero(a)) {
                if (tok->str == ">") report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "unsignedLessThanZero", "Checking if unsigned expression '" + b->expressionString() + "' is less than zero.\nThe unsigned expression '" + b->expressionString() + "' will never be negative so it is either pointless or an error to check if it is.", 570, {b->expressionString()});
                else if (tok->str == "<=") report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "unsignedPositive", "Unsigned expression '" + b->expressionString() + "' can't be negative so it is unnecessary to test it.", 570, {b->expressionString()});
            }
        }
    }
}

void CheckOther::checkZeroDivision() {
    for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
        if (!(tok->str == "/" || tok->str == "%" || tok->str == "/=" || tok->str == "%=") || !tok->astOperand1 || !tok->astOperand2) continue;
        if (tok->str == "/" && astIsFloat(tok->astOperand1)) continue;
        if (tok->str == "/" && astIsFloat(tok->astOperand2)) continue;
        const Token *rhs = tok->astOperand2;
        if (rhs->tokType == Token::eString) continue;
        const ValueFlowValue *value = nullptr;
        for (const ValueFlowValue &v : rhs->values) if (v.valueType == ValueFlowValue::INT && !v.impossible && v.intvalue == 0) { if (!value || (v.isKnown() && !value->isKnown())) value = &v; }
        if (!value) continue;
        if (!value->isKnown() && !mSettings.sev_warning) continue;
        // skip "sizeof" results
        ErrorPath ep = getErrorPath(tok, value, "Division by zero");
        if (value->isKnown()) {
            report(*this, mCppCheck, mTokenizer, ep, Severity::error, "zerodiv", "Division by zero.", 369);
        } else if (value->conditional) {
            const std::string cond = value->errorPath.empty() ? "x" : value->errorPath.front().first->expressionString();
            report(*this, mCppCheck, mTokenizer, ep, Severity::warning, "zerodivcond", "Either the condition '" + cond + "' is redundant or there is division by zero at line " + std::to_string(tok->linenr) + ".", 369);
        } else {
            report(*this, mCppCheck, mTokenizer, ep, Severity::warning, "zerodiv", "Division by zero.", 369);
        }
    }
}

void CheckOther::checkNegativeBitwiseShift() {
    for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
        if (!(tok->str == "<<" || tok->str == ">>" || tok->str == "<<=" || tok->str == ">>=") || !tok->astOperand1 || !tok->astOperand2) continue;
        // skip streams
        if (tok->astOperand1->variable && tok->astOperand1->variable->isClass) continue;
        if (tok->astOperand1->str == "(" && !tok->astOperand1->isCast && tok->astOperand1->astOperand1 && !tok->astOperand1->astOperand1->function) {}
        if (mTokenizer.isCPP() && (tok->astOperand1->str == "cout" || tok->astOperand1->str == "cerr" || tok->astOperand1->str == "cin" || (tok->astOperand1->str == "::" ) || tok->astOperand1->str == "<<" || tok->astOperand1->str == ">>")) continue;
        if (tok->astOperand2->hasKnownIntValue() && tok->astOperand2->getKnownIntValue() < 0) {
            report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::error, "shiftNegative", "Shifting by a negative value is undefined behaviour", 758);
        } else if (tok->astOperand1->hasKnownIntValue() && tok->astOperand1->getKnownIntValue() < 0 && tok->astOperand1->isNumber() == false) {
            if (mSettings.sev_portability) report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::portability, "shiftNegativeLHS", "Shifting a negative value is technically undefined behaviour", 758);
        }
    }
}

void CheckOther::checkUnusedLabel() {
    if (!mSettings.sev_style && !mSettings.sev_warning) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!tok->isName() || !tok->next || tok->next->str != ":" || tok->varId) continue;
            if (!(tok->previous && (tok->previous->str == ";" || tok->previous->str == "{" || tok->previous->str == "}"))) continue;
            if (tok->str == "default" || tok->str == "case" || tok->str == "public" || tok->str == "private" || tok->str == "protected") continue;
            if (tok->next->next && tok->next->next->str == ":") continue;
            // used by goto?
            bool used = false;
            for (const Token *t = scope->bodyStart; t && t != scope->bodyEnd; t = t->next) if (t->str == "goto" && t->next && t->next->str == tok->str) { used = true; break; }
            if (used) continue;
            if (!mSettings.sev_style) continue;
            report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "unusedLabel", "Label '" + tok->str + "' is not used.", 398, {tok->str});
        }
    }
}

void CheckOther::checkShadowVariables() {
    if (!mSettings.sev_style) return;
    for (const Scope &scope : mSymbolDatabase.scopeList) {
        if (!scope.isExecutable() || scope.type == Scope::eFunction && false) continue;
        for (const Variable &var : scope.varlist) {
            if (var.isArgument && scope.type != Scope::eLambda) {}
            // look in enclosing scopes
            for (const Scope *outer = scope.nestedIn; outer; outer = outer->nestedIn) {
                if (outer->type == Scope::eGlobal || outer->type == Scope::eNamespace) break;
                if (outer->isClassOrStructOrUnion()) break;
                const Variable *shadowed = outer->getVariable(var.name);
                if (shadowed && shadowed != &var && shadowed->nameToken != var.nameToken) {
                    if (shadowed->isArgument && scope.type != Scope::eLambda) {
                        report(*this, mCppCheck, mTokenizer, {{shadowed->nameToken, "Shadowed declaration"}, {var.nameToken, ""}}, Severity::style, "shadowArgument", "Local variable '" + var.name + "' shadows outer argument", 398, {var.name});
                    } else {
                        report(*this, mCppCheck, mTokenizer, {{shadowed->nameToken, "Shadowed declaration"}, {var.nameToken, ""}}, Severity::style, "shadowVariable", "Local variable '" + var.name + "' shadows outer variable", 398, {var.name});
                    }
                    break;
                }
            }
        }
    }
}

void CheckOther::checkIncompleteStatement() {
    if (!mSettings.sev_warning) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (tok->astParent) continue;
            if (!tok->astOperand1 && !tok->astOperand2) {
                // single literal/variable statement: "x ;" or "1 ;"
                if (!(tok->previous && (tok->previous->str == ";" || tok->previous->str == "{" || tok->previous->str == "}"))) continue;
                if (!tok->next || tok->next->str != ";") continue;
                if (tok->isNumber() || tok->tokType == Token::eString || tok->tokType == Token::eChar || tok->tokType == Token::eBoolean) {
                    const std::string type = tok->isNumber() ? "numeric" : tok->tokType == Token::eString ? "string" : tok->tokType == Token::eChar ? "character" : "bool";
                    report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "constStatement", "Redundant code: Found a statement that begins with " + type + " constant.", 398);
                } else if (tok->variable && !tok->isExpandedMacro) {
                    report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "constStatement", "Unused variable value '" + tok->str + "'", 398);
                }
                continue;
            }
            // expression statements with no side effects: "x + 1;" "x == 1;"
            if ((tok->isComparisonOp() || (tok->isArithmeticalOp() && tok->astOperand2) || tok->str == "!" ) && tok->next == nullptr) {}
            if (tok->isComparisonOp() && tok->astOperand1 && tok->astOperand2) {
                const Token *end = nextAfterAstRightmostLeaf(tok);
                const Token *start = tok->astOperand1; while (start->astOperand1) start = start->astOperand1;
                if (end && end->str == ";" && start->previous && (start->previous->str == ";" || start->previous->str == "{" || start->previous->str == "}") && !tok->isExpandedMacro) {
                    report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "constStatement", "Found suspicious operator '" + tok->str + "', result is not used.", 398);
                }
            }
        }
    }
}

void CheckOther::clarifyCalculation() {
    if (!mSettings.sev_style) return;
    for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
        if (tok->str != "?" || !tok->astOperand1) continue;
        const Token *cond = tok->astOperand1;
        if (!cond->isArithmeticalOp() && !cond->isBitOp()) continue;
        if (!cond->astOperand1 || !cond->astOperand2) continue;
        if (cond->str == "<<" || cond->str == ">>") continue;
        // skip when parenthesized: cond is the token range... check if "(" precedes operand1 start
        const Token *start = cond->astOperand1; while (start->astOperand1) start = start->astOperand1;
        if (start->previous && start->previous->str == "(" && start->previous->link && start->previous->link == tok->previous) continue;
        if (!cond->astOperand1->varId && !cond->astOperand2->varId) continue;
        report(*this, mCppCheck, mTokenizer, {{cond, ""}}, Severity::style, "clarifyCalculation", "Clarify calculation precedence for '" + cond->str + "' and '?'.\nSuspicious calculation. Please use parentheses to clarify the code. The code ''a" + cond->str + "b?c:d'' should be written as either ''(a" + cond->str + "b)?c:d'' or ''a" + cond->str + "(b?c:d)''.", 783);
    }
}

void CheckOther::checkPassByReference() {
    if (!mSettings.sev_performance || !mTokenizer.isCPP()) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        const Function *f = scope->function;
        if (!f) continue;
        for (const Variable &var : f->argumentList) {
            if (!var.isClass || var.isPointer || var.isReference || var.isArray || var.isEnumType) continue;
            if (!var.nameToken || !var.varId) continue;
            bool inconclusive = false;
            if (!var.type || !var.type->classScope) {
                // unknown type: library container std::string etc -> cppcheck knows via library; otherwise skip
                const std::string &tn = var.typeName;
                bool isContainer = false;
                for (const auto &c : mLibrary.containers) { (void)c; }
                if (tn == "std::string" || tn.compare(0, 11, "std::vector") == 0 || tn.compare(0, 8, "std::map") == 0 || tn.compare(0, 8, "std::set") == 0 || tn.compare(0, 9, "std::list") == 0 || tn == "std::wstring" || tn.compare(0, 10, "std::deque") == 0 || tn.compare(0, 18, "std::unordered_map") == 0 || tn.compare(0, 18, "std::unordered_set") == 0) isContainer = true;
                if (!isContainer || mLibrary.containers.empty()) continue;
            } else {
                // user type: must be "large": cppcheck checks sizeof>=... it uses isLargeType: class with non-standard members or arrays or more than N bytes
                const Scope *cs = var.type->classScope;
                bool large = false;
                int bytes = 0;
                for (const Variable &m : cs->varlist) {
                    if (m.isStatic) continue;
                    if (m.isArray) { large = true; break; }
                    if (m.isClass && !m.isPointer) { large = true; break; }
                    if (m.isPointer) bytes += mSettings.platform.sizeof_pointer;
                    else if (m.typeName == "char" || m.typeName == "bool") bytes += 1;
                    else if (m.typeName == "short") bytes += 2;
                    else if (m.typeName == "long long" || m.typeName == "double") bytes += 8;
                    else if (m.typeName == "long") bytes += mSettings.platform.sizeof_long;
                    else bytes += 4;
                }
                if (bytes > 2 * mSettings.platform.sizeof_pointer) large = true;
                if (!large) continue;
                // class must have copy constructor that is trivial? cppcheck checks "if (var->type()->classScope->... hasCopyCtor" -> skip types with user copy ctor
                for (const Function &cf : cs->functionList) if (cf.type == Function::eCopyConstructor) { inconclusive = true; }
            }
            // variable must not be modified in function
            if (isVariableChanged(scope->bodyStart, scope->bodyEnd, var.varId, true)) continue;
            // used as non-const? e.g. member function call non-const -> changed (handled approx by isVariableChanged)
            if (inconclusive && !mSettings.inconclusive) continue;
            report(*this, mCppCheck, mTokenizer, {{var.nameToken, ""}}, Severity::performance, "passedByValue", "Function parameter '" + var.name + "' should be passed by const reference.\nParameter '" + var.name + "' is passed by value. It could be passed as a const reference which is usually faster and recommended in C++.", 398, {var.name}, inconclusive ? Certainty::inconclusive : Certainty::normal, &mSettings);
        }
    }
}

bool CheckOther::isVariableUsedAsNonConstPointer(const Variable *var, const Scope *scope, bool &unknown) const {
    unknown = false;
    const Token *start = var->isArgument ? scope->bodyStart : var->nameToken;
    for (const Token *tok = start; tok && tok != scope->bodyEnd; tok = tok->next) {
        if (tok->varId != var->varId || tok == var->nameToken) continue;
        const Token *parent = tok->astParent;
        if (!parent) { continue; }
        // *p = x  / p[i] = x  / p->m = x : write through pointer
        const Token *cur = tok; const Token *p = parent;
        if (p->str == "*" && !p->astOperand2) { cur = p; p = p->astParent; if (!p) continue; }
        else if (p->str == "[" && p->astOperand1 == tok) { cur = p; p = p->astParent; if (!p) continue; }
        else if (p->str == "->" && p->astOperand1 == tok) { cur = p; p = p->astParent; if (!p) continue; }
        else if (p->str == "." && p->astOperand1 == tok) { cur = p; p = p->astParent; if (!p) continue; }
        else {
            // pointer itself: assigned to another non-const pointer, passed to function, returned, compared ...
            if (p->str == "=" && p->astOperand1 == tok) continue; // reassigning pointer itself is fine
            if (p->isComparisonOp()) continue;
            if (p->str == "!" || p->str == "&&" || p->str == "||") continue;
            if (p->str == "return") {
                // returning non-const pointer -> if function returns non-const pointer type: used as non-const
                const Function *f = scope->function;
                if (f && f->returnsPointer && !f->returnsConst) return true;
                continue;
            }
            if (p->str == "=" && p->astOperand2 == tok) {
                // assigned to another variable: if that variable is a non-const pointer -> non-const use
                const Token *lhs = p->astOperand1;
                if (lhs && lhs->variable && lhs->variable->isPointer && !lhs->variable->isPointerToConst()) return true;
                if (lhs && !lhs->variable) { unknown = true; return true; }
                continue;
            }
            if (p->str == "(" || p->str == ",") {
                // function argument
                const Token *a = tok; while (a->astParent && a->astParent->str == ",") a = a->astParent;
                const Token *call = a->astParent;
                if (!call || call->str != "(" || !call->astOperand1) { unknown = true; return true; }
                const Token *fn = call->astOperand1;
                int idx = 0; const Token *x = tok;
                while (x->astParent && x->astParent->str == ",") { if (x->astParent->astOperand2 == x) { const Token *l = x->astParent->astOperand1; int c = 1; while (l && l->str == ",") { ++c; l = l->astOperand1; } idx += c; } x = x->astParent; }
                if (fn->function) {
                    const Variable *av = fn->function->getArgumentVar(idx);
                    if (!av) { if (fn->function->isVariadic) continue; unknown = true; return true; }
                    if (av->isPointer && av->isPointerToConst()) continue;
                    if (av->isPointer) return true;
                    if (av->isArray) return true;
                    if (!av->isPointer && !av->isReference) return true; // e.g. passing pointer to int param? unlikely
                    return true;
                }
                const LibFunction *lf = fn->isName() ? mLibrary.getFunction(fn->str) : nullptr;
                if (lf) {
                    auto it = lf->args.find(idx + 1);
                    if (it != lf->args.end()) {
                        if (it->second.direction == "in") continue;
                        if (it->second.direction == "out" || it->second.direction == "inout") return true;
                        // no direction: assume non-const if not strz/not-uninit? cppcheck: if the arg has "not-uninit"/"strz" and no out -> const ok
                        if (it->second.notuninit || it->second.strz) continue;
                    }
                    unknown = true; return true;
                }
                unknown = true;
                return true;
            }
            if (p->str == "+" || p->str == "-") {
                // pointer arithmetic: result used how? climb
                cur = p; p = p->astParent;
                if (!p) continue;
                if (p->str == "=" && p->astOperand2 == cur) { const Token *lhs = p->astOperand1; if (lhs && lhs->variable && lhs->variable->isPointer && !lhs->variable->isPointerToConst()) return true; continue; }
                if (p->str == "*" && !p->astOperand2) { cur = p; p = p->astParent; if (!p) continue; }
                else { unknown = true; return true; }
            } else if (p->str == "++" || p->str == "--") continue;
            else if (p->isCast) { unknown = true; return true; }
            else if (p->str == "?" || p->str == ":") { unknown = true; return true; }
            else { unknown = true; return true; }
        }
        // cur is the dereferenced expression; p its parent
        if (p->isAssignmentOp() && p->astOperand1 == cur) return true;
        if (p->str == "++" || p->str == "--") return true;
        if (p->str == "&" && !p->astOperand2) {
            // address of pointee passed somewhere -> assume non-const
            return true;
        }
        if (p->str == "(" && cur == p->astOperand1) return true; // calling a function pointer / method through pointer
        if (p->str == "." && p->astOperand1 == cur) {
            // method call on pointee: non-const unless known const method
            const Token *m = p->astOperand2;
            if (p->astParent && p->astParent->str == "(" && p->astParent->astOperand1 == p) {
                if (m && m->function && m->function->isConst) continue;
                return true;
            }
            // member access: chained write handled by assignment check at higher level
            const Token *q = p; const Token *qp = p->astParent;
            while (qp && (qp->str == "." || qp->str == "[" || qp->str == "->") && qp->astOperand1 == q) { q = qp; qp = qp->astParent; }
            if (qp && qp->isAssignmentOp() && qp->astOperand1 == q) return true;
            if (qp && (qp->str == "++" || qp->str == "--")) return true;
            if (qp && qp->str == "&" && !qp->astOperand2) return true;
            continue;
        }
        if (p->str == "->" && p->astOperand1 == cur) {
            const Token *q = p; const Token *qp = p->astParent;
            while (qp && (qp->str == "." || qp->str == "[" || qp->str == "->") && qp->astOperand1 == q) { q = qp; qp = qp->astParent; }
            if (qp && qp->isAssignmentOp() && qp->astOperand1 == q) return true;
            if (qp && (qp->str == "++" || qp->str == "--")) return true;
            if (qp && qp->str == "&" && !qp->astOperand2) return true;
            if (qp && qp->str == "(" && qp->astOperand1 == q) { const Token *m = q->astOperand2; if (m && m->function && m->function->isConst) continue; return true; }
            continue;
        }
        if (p->str == "=" && p->astOperand2 == cur) {
            // "T *q = p[0]" style? if cur is dereferenced value of pointer-to-pointer... assume read
            continue;
        }
        if (p->str == "(" || p->str == ",") {
            // *p passed to a function by reference (C++) -> unknown
            if (mTokenizer.isCPP()) {
                const Token *a = cur; while (a->astParent && a->astParent->str == ",") a = a->astParent;
                const Token *call = a->astParent;
                if (call && call->str == "(" && call->astOperand1 && call->astOperand1->function) {
                    int idx = 0; const Token *x = cur;
                    while (x->astParent && x->astParent->str == ",") { if (x->astParent->astOperand2 == x) { const Token *l = x->astParent->astOperand1; int c = 1; while (l && l->str == ",") { ++c; l = l->astOperand1; } idx += c; } x = x->astParent; }
                    const Variable *av = call->astOperand1->function->getArgumentVar(idx);
                    if (av && av->isReference && !av->isConst) return true;
                    continue;
                }
                if (call && call->str == "(" && call->astOperand1 && !mLibrary.getFunction(call->astOperand1->str)) { unknown = true; return true; }
            }
            continue;
        }
        if (p->str == "return") {
            const Function *f = scope->function;
            if (f && f->returnsReference && !f->returnsConst) return true;
            continue;
        }
    }
    return false;
}

void CheckOther::checkConstVariable() {
    if (!mSettings.sev_style || !mTokenizer.isCPP()) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        const Function *f = scope->function;
        if (!f) continue;
        for (const Variable &var : f->argumentList) {
            if (!var.isReference || var.isConst || var.isRValueRef || !var.varId) continue;
            if (var.isPointer) continue;
            // is it modified?
            bool modified = false;
            for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
                if (tok->varId != var.varId) continue;
                const Token *p = tok->astParent;
                const Token *cur = tok;
                while (p && ((p->str == "[" && p->astOperand1 == cur) || (p->str == "." && p->astOperand1 == cur))) { cur = p; p = p->astParent; }
                if (!p) continue;
                if (p->isAssignmentOp() && p->astOperand1 == cur) { modified = true; break; }
                if (p->str == "++" || p->str == "--") { modified = true; break; }
                if (p->str == "&" && !p->astOperand2) { modified = true; break; }
                if (p->str == "(" || p->str == ",") { modified = true; break; } // passed to function: unknown
                if (p->str == "." && p->astOperand1 == cur && p->astParent && p->astParent->str == "(") { const Token *m = p->astOperand2; if (!(m && m->function && m->function->isConst)) { modified = true; break; } }
                if (p->str == "return" ) { if (f->returnsReference && !f->returnsConst) { modified = true; break; } }
                if (p->str == "=" && p->astOperand2 == cur) { const Token *lhs = p->astOperand1; if (lhs && lhs->variable && lhs->variable->isReference && !lhs->variable->isConst) { modified = true; break; } }
                if (p->str == "<<" || p->str == ">>") { if (p->astOperand2 == cur && p->str == ">>") { modified = true; break; } }
            }
            if (modified) continue;
            if (var.isClass && !var.type) { continue; } // unknown type: cppcheck needs the type to know about const methods
            report(*this, mCppCheck, mTokenizer, {{var.nameToken, ""}}, Severity::style, "constParameterReference", "Parameter '" + var.name + "' can be declared as reference to const", 398, {var.name});
        }
    }
}

void CheckOther::checkConstPointer() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        const Function *f = scope->function;
        if (!f) continue;
        std::vector<const Variable*> candidates;
        for (const Variable &var : f->argumentList) if (var.varId) candidates.push_back(&var);
        auto collectLocals = [&](const Scope *s, auto &&self) -> void {
            for (const Variable &v : s->varlist) if (!v.isArgument) candidates.push_back(&v);
            for (const Scope *n : s->nestedList) if (n->type != Scope::eLambda) self(n, self);
        };
        collectLocals(scope, collectLocals);
        for (const Variable *var : candidates) {
            if (!var->isPointer || var->isPointerToConst() || var->pointerDepth != 1 || var->isArray) continue;
            if (var->isFunctionPointer) continue;
            if (var->isStatic || var->isExtern || var->isVolatile) continue;
            if (var->typeName == "void" ) {}
            if (!var->nameToken) continue;
            // Only if the pointer is dereferenced at least once (used) - cppcheck requires that the pointee is read somewhere? It reports even if just assigned (e.g. buf = malloc) -> yes reported for 'buf' in sample.
            bool unknown = false;
            if (isVariableUsedAsNonConstPointer(var, scope, unknown)) continue;
            // if the pointer is never used at all except declaration: cppcheck still reports? In sample "char *buf = malloc(10);" (unused) was reported. yes.
            // pointer initialized/assigned from non-const source is fine.
            // pointee type must not be const already; also skip "char *" string literal assignments? no
            if (var->isArgument)
                report(*this, mCppCheck, mTokenizer, {{var->nameToken, ""}}, Severity::style, "constParameterPointer", "Parameter '" + var->name + "' can be declared as pointer to const", 398, {var->name});
            else
                report(*this, mCppCheck, mTokenizer, {{var->nameToken, ""}}, Severity::style, "constVariablePointer", "Variable '" + var->name + "' can be declared as pointer to const", 398, {var->name});
        }
    }
}

void CheckOther::checkModuloOfOne() {
    if (!mSettings.sev_style) return;
    for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
        if (tok->str != "%" || !tok->astOperand2) continue;
        if (tok->astOperand2->hasKnownIntValue() && tok->astOperand2->getKnownIntValue() == 1 && tok->astOperand2->isNumber()) {
            report(*this, mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "moduloofone", "Modulo of one is always equal to zero", 398);
        }
    }
}

std::vector<std::unique_ptr<Check>> createChecksOther(const Tokenizer &tokenizer, const SymbolDatabase &symdb, const Settings &settings, const Library &library, CppCheck &cppcheck, int which) {
    std::vector<std::unique_ptr<Check>> v;
    if (which == 0) v.push_back(std::make_unique<CheckFunctions>(tokenizer, symdb, settings, library, cppcheck));
    if (which == 1) v.push_back(std::make_unique<CheckCondition>(tokenizer, symdb, settings, library, cppcheck));
    if (which == 2) v.push_back(std::make_unique<CheckOther>(tokenizer, symdb, settings, library, cppcheck));
    return v;
}
