class CheckClass : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Class"; }
    void runChecks() override {
        if (!mTokenizer.isCPP()) return;
        constructors();
        checkExplicitConstructors();
        initializationListUsage();
        checkConst();
    }
    void constructors();
    void checkExplicitConstructors();
    void initializationListUsage();
    void checkConst();
};

static bool isMemberAssignedInCtor(const Scope *ctorScope, const Function *ctor, const Variable &member) {
    // init list
    const Token *argEnd = ctor->arg ? ctor->arg->link : nullptr;
    if (argEnd) {
        for (const Token *t = argEnd->next; t && t != ctorScope->bodyStart; t = t->next) {
            if (t->str == member.name && t->next && (t->next->str == "(" || t->next->str == "{")) return true;
        }
    }
    // body
    for (const Token *t = ctorScope->bodyStart; t && t != ctorScope->bodyEnd; t = t->next) {
        if (t->varId == member.varId || (t->str == member.name && t->previous && t->previous->str == "->" && t->previous->previous && t->previous->previous->str == "this")) {
            const Token *p = t->astParent;
            const Token *cur = t;
            while (p && ((p->str == "." || p->str == "->") && p->astOperand2 == cur)) { cur = p; p = p->astParent; }
            while (p && ((p->str == "[" || p->str == ".") && p->astOperand1 == cur)) { cur = p; p = p->astParent; }
            if (p && p->isAssignmentOp() && p->astOperand1 == cur) return true;
            if (p && (p->str == "&" && !p->astOperand2)) return true;
            if (p && (p->str == "(" || p->str == ",")) return true; // passed to function -> may init
            if (p && p->str == ">>" ) return true;
            if (p && (p->str == "++" || p->str == "--")) return true;
        }
        // function call to other member function -> may initialize: bail
        if (t->isName() && t->next && t->next->str == "(" && t->function && t->function->nestedIn == ctor->nestedIn && !t->function->isConstructor()) return true;
        // memset(this...) etc
        if (t->str == "memset" || t->str == "memcpy") return true;
    }
    return false;
}

void CheckClass::constructors() {
    const bool printStyle = mSettings.sev_style;
    const bool printWarnings = mSettings.sev_warning;
    if (!printStyle && !printWarnings) return;
    for (const Scope *scope : mSymbolDatabase.classAndStructScopes) {
        // skip if class has no constructors and no member variables needing init
        bool hasCtor = false;
        for (const Function &f : scope->functionList) if (f.isConstructor()) hasCtor = true;
        if (!hasCtor) {
            // noConstructor: class with private members and no constructor
            if (printStyle && scope->type == Scope::eClass) {
                bool hasNonStaticPrivate = false;
                bool hasFunctions = !scope->functionList.empty();
                for (const Variable &v : scope->varlist) if (v.isPrivate && !v.isStatic && !v.isClass) hasNonStaticPrivate = true;
                if (hasNonStaticPrivate && hasFunctions) {
                    reportMsg(mCppCheck, mTokenizer, {{scope->classDef, ""}}, Severity::style, "noConstructor", "The class 'X' does not declare a constructor although it has private member variables which likely require initialization.\nThe class 'X' does not declare a constructor although it has private member variables. Member variables of builtin types are left uninitialized unless the class implements a constructor. Therefore, the implementation should declare a constructor to initialize all member variables.", 398, {scope->className});
                }
            }
            continue;
        }
        if (!printWarnings) continue;
        for (const Function &f : scope->functionList) {
            if (!f.isConstructor() || !f.hasBody || !f.functionScope) continue;
            if (f.isDefault || f.isDelete) continue;
            if (f.type == Function::eCopyConstructor || f.type == Function::eMoveConstructor) {
                // uninitMemberVar for copy ctor as well (cppcheck reports "uninitMemberVar" for copy constructor too)
            }
            // delegating constructor?
            {
                const Token *argEnd = f.arg ? f.arg->link : nullptr;
                bool delegating = false;
                if (argEnd) for (const Token *t = argEnd->next; t && t != f.functionScope->bodyStart; t = t->next) if (t->str == scope->className && t->next && t->next->str == "(") delegating = true;
                if (delegating) continue;
            }
            for (const Variable &var : scope->varlist) {
                if (var.isStatic || var.isInit) continue;
                if (var.isClass && !var.isPointer && !var.isArray) {
                    // class type with ctor -> ok; unknown type -> skip
                    continue;
                }
                if (var.isClass && var.isArray) continue;
                if (var.isReference) continue; // must be in init list anyway
                if (isMemberAssignedInCtor(f.functionScope, &f, var)) continue;
                // skip if ctor body is empty and class is struct? cppcheck reports anyway.
                const char* kind = (f.type == Function::eCopyConstructor) ? "copy constructor" : (f.type == Function::eMoveConstructor ? "move constructor" : "constructor");
                reportMsg(mCppCheck, mTokenizer, {{f.token, ""}}, Severity::warning, "uninitMemberVar", "Member variable '" + scope->className + "::" + var.name + "' is not initialized in the " + kind + ".", 398, {scope->className + "::" + var.name});
            }
        }
    }
}

void CheckClass::checkExplicitConstructors() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.classAndStructScopes) {
        // skip if class has aggregate-like? cppcheck: skip if class is used as "T x = {...}"? no. It skips if all functions are... just report
        bool hasNonTrivial = false;
        for (const Function &f : scope->functionList) if (f.isConstructor()) hasNonTrivial = true;
        if (!hasNonTrivial) continue;
        for (const Function &f : scope->functionList) {
            if (!f.isConstructor() || f.isExplicit || f.isDelete) continue;
            if (f.type == Function::eCopyConstructor || f.type == Function::eMoveConstructor) continue;
            if (f.minArgCount() != 1) continue;
            if (f.argumentList.size() == 1 && f.argumentList[0].typeName == "std::initializer_list") continue;
            // argument being the same class by value? already excluded
            const Token *tok = f.tokenDef ? f.tokenDef : f.token;
            reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "noExplicitConstructor", std::string(scope->type == Scope::eStruct ? "Struct" : "Class") + " '" + scope->className + "' has a constructor with 1 argument that is not explicit.\n" + std::string(scope->type == Scope::eStruct ? "Struct" : "Class") + " '" + scope->className + "' has a constructor with 1 argument that is not explicit. Such, so called \"Converting constructors\", should in general be explicit for type safety reasons as that prevents unintended implicit conversions.", 398, {scope->className});
        }
    }
}

void CheckClass::initializationListUsage() {
    if (!mSettings.sev_performance) return;
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        const Function *f = scope->function;
        if (!f || !f->isConstructor() || !f->nestedIn || !f->nestedIn->isClassOrStructOrUnion()) continue;
        if (f->type == Function::eCopyConstructor && false) {}
        const Scope *owner = f->nestedIn;
        for (const Token *tok = scope->bodyStart->next; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (tok->str == "{" && tok->link) { tok = tok->link; continue; } // only top level statements
            if (tok->str == "(" && tok->link) { tok = tok->link; continue; }
            if (tok->str != "=" || tok->astParent || !tok->astOperand1 || !tok->astOperand2) continue;
            const Token *lhs = tok->astOperand1;
            const Variable *var = lhs->variable;
            if (!var || !var->isMember || var->scope != owner) continue;
            // only class-type members (not builtin) are reported
            if (!var->isClass || var->isPointer || var->isArray || var->isReference) continue;
            if (var->isStatic) continue;
            // rhs must not reference other members / this
            bool bad = false;
            std::vector<const Token*> st{tok->astOperand2};
            while (!st.empty()) { const Token *t = st.back(); st.pop_back(); if (!t) continue; if (t->str == "this") bad = true; if (t->variable && t->variable->isMember && t->variable->scope == owner) bad = true; st.push_back(t->astOperand1); st.push_back(t->astOperand2); }
            if (bad) continue;
            // the member must not be used before this assignment in the ctor body
            bool usedBefore = false;
            for (const Token *t = scope->bodyStart; t != tok; t = t->next) if (t->varId == var->varId) usedBefore = true;
            if (usedBefore) continue;
            reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::performance, "useInitializationList", "Variable '" + var->name + "' is assigned in constructor body. Consider performing initialization in initialization list.\nWhen an object of a class is created, the constructors of all member variables are called consecutively in the order the variables are declared, even if you don't explicitly write them to the initialization list. You could avoid assigning '" + var->name + "' a value by passing the value to the constructor in the initialization list.", 398, {var->name});
        }
    }
}

void CheckClass::checkConst() {
    if (!mSettings.sev_style) return;
    for (const Scope *scope : mSymbolDatabase.classAndStructScopes) {
        for (const Function &func : scope->functionList) {
            if (!func.hasBody || !func.functionScope) continue;
            if (func.isConst || func.isStatic || func.isVirtual || func.isConstructor() || func.isDestructor() || func.isOperator || func.isFriend) continue;
            if (func.type != Function::eFunction) continue;
            if (func.returnsVoid && false) {}
            // returns non-const reference/pointer to member? -> skip
            // body must not modify members or call non-const member functions
            bool modifies = false;
            bool usesMember = false;
            bool bail = false;
            for (const Token *tok = func.functionScope->bodyStart; tok && tok != func.functionScope->bodyEnd; tok = tok->next) {
                if (tok->str == "this") {
                    const Token *p = tok->astParent;
                    if (p && p->str == "return") { bail = true; break; }
                    if (p && p->str == "->" && p->astOperand2 && p->astOperand2->varId) {
                        // member access via this
                        const Variable *mv = p->astOperand2->variable;
                        if (mv && mv->isMember) {
                            usesMember = true;
                            const Token *q = p; const Token *qp = p->astParent;
                            while (qp && ((qp->str == "[" || qp->str == ".") && qp->astOperand1 == q)) { q = qp; qp = qp->astParent; }
                            if (qp && qp->isAssignmentOp() && qp->astOperand1 == q) { modifies = true; break; }
                            if (qp && (qp->str == "++" || qp->str == "--")) { modifies = true; break; }
                        }
                        continue;
                    }
                    bail = true; break;
                }
                if (!tok->variable || !tok->variable->isMember || tok->variable->scope != scope) {
                    // calling member function?
                    if (tok->isName() && tok->next && tok->next->str == "(" && tok->function && tok->function->nestedIn == scope && !(tok->previous && (tok->previous->str == "." || tok->previous->str == "->"))) {
                        usesMember = true;
                        if (!tok->function->isConst && !tok->function->isStatic) { modifies = true; break; }
                    } else if (tok->isName() && tok->next && tok->next->str == "(" && !tok->function && !tok->varId && !mLibrary.getFunction(tok->str) && !(tok->previous && (tok->previous->str == "." || tok->previous->str == "->" || tok->previous->str == "::")) && !tok->isStandardType() && !tok->isKeyword()) {
                        // unknown function call: cppcheck bails out? It continues unless the member is passed... keep
                    }
                    continue;
                }
                if (tok->variable->isStatic) continue;
                if (tok->variable->isMutable) continue;
                usesMember = true;
                const Token *cur = tok; const Token *p = tok->astParent;
                while (p && ((p->str == "[" || p->str == ".") && p->astOperand1 == cur)) { cur = p; p = p->astParent; }
                if (p && p->isAssignmentOp() && p->astOperand1 == cur) { modifies = true; break; }
                if (p && (p->str == "++" || p->str == "--")) { modifies = true; break; }
                if (p && p->str == "&" && !p->astOperand2) { modifies = true; break; }
                if (p && (p->str == "(" || p->str == ",")) {
                    // passed to function: by reference? -> assume modified if non-const ref/unknown
                    const Token *a = cur; while (a->astParent && a->astParent->str == ",") a = a->astParent;
                    const Token *call = a->astParent;
                    if (call && call->str == "(" && call->astOperand1 && call->astOperand1->function) {
                        int idx = 0; const Token *x = cur;
                        while (x->astParent && x->astParent->str == ",") { if (x->astParent->astOperand2 == x) { const Token *l = x->astParent->astOperand1; int c = 1; while (l && l->str == ",") { ++c; l = l->astOperand1; } idx += c; } x = x->astParent; }
                        const Variable *av = call->astOperand1->function->getArgumentVar(idx);
                        if (av && ((av->isReference && !av->isConst) || (av->isPointer && !av->isPointerToConst() && tok->variable->isArray))) { modifies = true; break; }
                    } else if (call && call->str == "(" && call->astOperand1 && !mLibrary.getFunction(call->astOperand1->str)) {
                        if (tok->variable->isClass || tok->variable->isArray) { bail = true; break; }
                    }
                }
                if (p && p->str == "." && p->astOperand1 == cur && p->astParent && p->astParent->str == "(") {
                    const Token *m = p->astOperand2;
                    if (!(m && m->function && m->function->isConst)) { modifies = true; break; }
                }
                if (p && p->str == "return" && (tok->variable->isPointer || tok->variable->isArray) && func.returnsPointer && !func.returnsConst) { modifies = true; break; }
                if (p && p->str == "return" && func.returnsReference && !func.returnsConst) { modifies = true; break; }
                if (p && p->str == "=" && p->astOperand2 == cur && tok->variable->isPointer) {
                    const Token *lhs = p->astOperand1; if (lhs && lhs->variable && lhs->variable->isPointer && !lhs->variable->isPointerToConst()) { modifies = true; break; }
                }
            }
            if (bail || modifies) continue;
            // function must be declared in class (tokenDef in class scope) and not be a template
            if (func.isTemplate) continue;
            if (func.returnsReference && !func.returnsConst) continue;
            if (func.returnsPointer && !func.returnsConst && usesMember) continue;
            const Token *tok = func.tokenDef ? func.tokenDef : func.token;
            const std::string fullName = scope->className + "::" + func.name;
            if (usesMember) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "functionConst", "Technically the member function '" + fullName + "' can be const.\nThe member function '" + fullName + "' can be made a const function. Making this function 'const' should not cause compiler errors. Even though the function can be made const function technically it may not make sense conceptually. Think about your design and the task of the function first - is it a function that must not change object internal state?", 398, {fullName}, Certainty::inconclusive);
            } else {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::performance, "functionStatic", "Technically the member function '" + fullName + "' can be static (but you may consider moving to unnamed namespace).\nThe member function '" + fullName + "' can be made a static function. Making a function static can bring a performance benefit since no 'this' instance is passed to the function. This change should not cause compiler errors but it does not necessarily make sense conceptually. Think about your design and the task of the function first - is it a function that must not access members of class instances? And maybe it is more appropriate to move this function to an unnamed namespace.", 398, {fullName}, Certainty::inconclusive);
            }
        }
    }
}

