std::vector<std::unique_ptr<Check>> createChecksCore(const Tokenizer &, const SymbolDatabase &, const Settings &, const Library &, CppCheck &);
std::vector<std::unique_ptr<Check>> createChecksUnused(const Tokenizer &, const SymbolDatabase &, const Settings &, const Library &, CppCheck &);
std::vector<std::unique_ptr<Check>> createChecksOther(const Tokenizer &, const SymbolDatabase &, const Settings &, const Library &, CppCheck &, int which);
std::vector<std::unique_ptr<Check>> createChecksLeak(const Tokenizer &, const SymbolDatabase &, const Settings &, const Library &, CppCheck &, int which);
std::vector<std::unique_ptr<Check>> createChecksClass(const Tokenizer &, const SymbolDatabase &, const Settings &, const Library &, CppCheck &);

// Order follows cppcheck's check instance ordering (sorted by name)
std::vector<std::unique_ptr<Check>> createChecks(const Tokenizer &tokenizer, const SymbolDatabase &symdb, const Settings &settings, const Library &library, CppCheck &cppcheck) {
    std::vector<std::unique_ptr<Check>> v;
    auto add = [&](std::vector<std::unique_ptr<Check>> &&c) { for (auto &x : c) v.push_back(std::move(x)); };
    // Auto Variables
    add(createChecksLeak(tokenizer, symdb, settings, library, cppcheck, 0));
    // Bounds checking, Null pointer, Uninitialized variables (core) -> need splitting by order
    auto core = createChecksCore(tokenizer, symdb, settings, library, cppcheck);
    // core[0]=BufferOverrun, core[1]=NullPointer, core[2]=UninitVar
    v.push_back(std::move(core[0]));                        // Bounds checking
    add(createChecksOther(tokenizer, symdb, settings, library, cppcheck, 0)); // Check function usage
    add(createChecksClass(tokenizer, symdb, settings, library, cppcheck));    // Class
    add(createChecksOther(tokenizer, symdb, settings, library, cppcheck, 1)); // Condition
    add(createChecksLeak(tokenizer, symdb, settings, library, cppcheck, 1));  // Leaks (auto variables)
    add(createChecksLeak(tokenizer, symdb, settings, library, cppcheck, 2));  // Memory leaks (address not taken)
    v.push_back(std::move(core[1]));                        // Null pointer
    add(createChecksOther(tokenizer, symdb, settings, library, cppcheck, 2)); // Other
    v.push_back(std::move(core[2]));                        // Uninitialized variables
    add(createChecksUnused(tokenizer, symdb, settings, library, cppcheck));   // UnusedVar
    return v;
}
