// ---------------------------------------------------------------------------
// CheckLeakAutoVar (simplified)
// ---------------------------------------------------------------------------
class CheckLeakAutoVar : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Leaks (auto variables)"; }
    void runChecks() override { check(); }
    void check();

    struct VarInfo {
        enum Status { ALLOC, DEALLOC, NOALLOC } status = NOALLOC;
        int groupId = 0;
        bool isResource = false;
        const Token *allocTok = nullptr;
        const Token *deallocTok = nullptr;
        bool conditional = false;
    };
    using VarMap = std::map<unsigned, VarInfo>;
    void checkScope(const Token *start, const Token *end, VarMap &vars, int depth);
    void leakAtEnd(const Token *tok, const VarMap &vars, const std::set<unsigned> &skip);
    bool isDeallocFunctionCall(const Token *tok, unsigned &varid, int &groupId, bool &isResource) const;
    const Token *getAllocCall(const Token *rhs, int &groupId, bool &isResource, bool &isRealloc) const;
    std::set<unsigned> reportedLeak;
};

const Token *CheckLeakAutoVar::getAllocCall(const Token *rhs, int &groupId, bool &isResource, bool &isRealloc) const {
    if (!rhs) return nullptr;
    if (rhs->isCast && rhs->astOperand1) return getAllocCall(rhs->astOperand1, groupId, isResource, isRealloc);
    if (rhs->str == "(" && rhs->astOperand1 && rhs->astOperand1->isName() && !rhs->astOperand1->function) {
        const LibAllocFunc *af = mLibrary.getAlloc(rhs->astOperand1->str);
        if (af) { groupId = af->groupId; isResource = af->isResource; isRealloc = af->isRealloc; return rhs->astOperand1; }
    }
    if (mTokenizer.isCPP() && rhs->str == "new") { groupId = -1; isResource = false; isRealloc = false; return rhs; }
    return nullptr;
}

bool CheckLeakAutoVar::isDeallocFunctionCall(const Token *tok, unsigned &varid, int &groupId, bool &isResource) const {
    // tok: function name token
    if (!tok->isName() || !tok->next || tok->next->str != "(") return false;
    if (tok->function) return false;
    const LibDeallocFunc *df = mLibrary.getDealloc(tok->str);
    if (!df) {
        if (mTokenizer.isCPP() && tok->str == "delete") {}
        return false;
    }
    // argument
    const Token *arg = tok->next->astOperand2;
    int idx = df->arg;
    std::vector<const Token*> args;
    const Token *a = arg;
    while (a && a->str == ",") { args.insert(args.begin(), a->astOperand2); a = a->astOperand1; }
    if (a) args.insert(args.begin(), a);
    if (idx < 1 || idx > (int)args.size()) return false;
    const Token *v = args[idx - 1];
    while (v && v->isCast && v->astOperand1) v = v->astOperand1;
    if (!v || !v->varId) return false;
    varid = v->varId;
    groupId = df->groupId;
    isResource = df->isResource;
    return true;
}

void CheckLeakAutoVar::leakAtEnd(const Token *tok, const VarMap &vars, const std::set<unsigned> &skip) {
    for (const auto &p : vars) {
        if (p.second.status != VarInfo::ALLOC) continue;
        if (skip.count(p.first)) continue;
        const Variable *var = mSymbolDatabase.getVariableFromVarId(p.first);
        if (!var) continue;
        if (!var->isLocal || var->isStatic) continue;
        if (reportedLeak.count(p.first) && false) continue;
        const std::string &name = var->name;
        if (p.second.isResource)
            reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::error, "resourceLeak", "Resource leak: " + name, 775, {name});
        else
            reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::error, "memleak", "Memory leak: " + name, 401, {name});
    }
}

// Is the variable used after 'tok' in a way that indicates it is stored/returned (escape)?
static bool isEscaped(const Token *varTok) {
    const Token *p = varTok->astParent;
    if (!p) return false;
    // assigned to something else: "x = p", "s->ptr = p", "arr[i] = p"
    if (p->str == "=" && p->astOperand2 == varTok) return true;
    if (p->str == "return") return true;
    if (p->str == "(" || p->str == ",") return true; // passed to function (may store)
    if (p->str == "?" || p->str == ":") return true;
    if (p->isCast && p->astParent) return isEscaped(p);
    return false;
}

void CheckLeakAutoVar::checkScope(const Token *start, const Token *end, VarMap &vars, int depth) {
    (void)depth;
    for (const Token *tok = start; tok && tok != end; tok = tok->next) {
        // nested scope
        if (tok->str == "{" && tok->link) {
            const Token *prev = tok->previous;
            if (prev && prev->str == "=") { tok = tok->link; continue; }
            // if/else/loop
            bool isIf = prev && prev->str == ")" && prev->link && prev->link->previous && prev->link->previous->str == "if";
            bool isLoop = (prev && prev->str == ")" && prev->link && prev->link->previous && (prev->link->previous->str == "for" || prev->link->previous->str == "while")) || (prev && prev->str == "do");
            bool isElse = prev && prev->str == "else";
            if (isIf || isElse) {
                // analyze branch with a copy; handle "if (p) free(p)" patterns: condition may test the pointer
                VarMap branch = vars;
                // condition "if (!p)" / "if (p == NULL)" -> in branch p is null (not allocated)
                if (isIf) {
                    const Token *cond = prev->link->astOperand2;
                    auto nullTest = [&](const Token *c, bool &isNull, unsigned &vid) {
                        isNull = false; vid = 0;
                        if (!c) return;
                        if (c->str == "!" && c->astOperand1 && c->astOperand1->varId) { isNull = true; vid = c->astOperand1->varId; }
                        else if ((c->str == "==" || c->str == "!=") && c->astOperand1 && c->astOperand2) {
                            const Token *v = c->astOperand1->varId ? c->astOperand1 : (c->astOperand2->varId ? c->astOperand2 : nullptr);
                            const Token *n = (v == c->astOperand1) ? c->astOperand2 : c->astOperand1;
                            if (v && n && n->hasKnownIntValue() && n->getKnownIntValue() == 0) { vid = v->varId; isNull = (c->str == "=="); }
                        } else if (c->varId) { vid = c->varId; isNull = false; }
                    };
                    bool isNull; unsigned vid;
                    nullTest(cond, isNull, vid);
                    if (vid && branch.count(vid)) {
                        if (isNull) branch[vid].status = VarInfo::NOALLOC; // in then-branch p is NULL
                    }
                    checkScope(tok->next, tok->link, branch, depth + 1);
                    // else branch
                    const Token *after = tok->link->next;
                    VarMap elseBranch = vars;
                    if (vid && elseBranch.count(vid) && !isNull) elseBranch[vid].status = VarInfo::NOALLOC;
                    if (after && after->str == "else" && after->next && after->next->str == "{" && after->next->link) {
                        checkScope(after->next->next, after->next->link, elseBranch, depth + 1);
                        // merge: a variable is ALLOC after if/else if allocated in either branch (not deallocated in all)
                        bool thenEscapes = isEscapeScope(tok, mLibrary);
                        bool elseEscapes = isEscapeScope(after->next, mLibrary);
                        for (auto &p : vars) {
                            VarInfo::Status s1 = branch.count(p.first) ? branch[p.first].status : p.second.status;
                            VarInfo::Status s2 = elseBranch.count(p.first) ? elseBranch[p.first].status : p.second.status;
                            if (thenEscapes) s1 = s2;
                            if (elseEscapes) s2 = s1;
                            if (s1 == VarInfo::DEALLOC || s2 == VarInfo::DEALLOC) { if (s1 == s2) p.second.status = VarInfo::DEALLOC; else p.second = VarInfo(); }
                            else if (s1 == VarInfo::ALLOC || s2 == VarInfo::ALLOC) { p.second.status = VarInfo::ALLOC; p.second.conditional = (s1 != s2); if (s1 == VarInfo::ALLOC && branch.count(p.first)) p.second = branch[p.first]; else if (elseBranch.count(p.first)) p.second = elseBranch[p.first]; p.second.conditional = (s1 != s2); }
                            else p.second.status = VarInfo::NOALLOC;
                        }
                        // variables allocated only inside branches
                        for (auto &p : branch) if (!vars.count(p.first) && p.second.status == VarInfo::ALLOC && !thenEscapes) { vars[p.first] = p.second; vars[p.first].conditional = true; }
                        for (auto &p : elseBranch) if (!vars.count(p.first) && p.second.status == VarInfo::ALLOC && !elseEscapes) { vars[p.first] = p.second; vars[p.first].conditional = true; }
                        tok = after->next->link;
                        continue;
                    }
                    // no else: merge then-branch with fallthrough
                    bool thenEscapes = isEscapeScope(tok, mLibrary);
                    for (auto &p : vars) {
                        if (!branch.count(p.first)) continue;
                        VarInfo::Status s1 = branch[p.first].status;
                        if (thenEscapes) continue;
                        if (s1 == VarInfo::DEALLOC && p.second.status == VarInfo::ALLOC) { p.second = VarInfo(); p.second.status = VarInfo::NOALLOC; }
                        else if (s1 != p.second.status) { if (s1 == VarInfo::ALLOC || p.second.status == VarInfo::ALLOC) { if (s1 == VarInfo::ALLOC) p.second = branch[p.first]; p.second.conditional = true; } }
                    }
                    for (auto &p : branch) if (!vars.count(p.first) && p.second.status == VarInfo::ALLOC && !thenEscapes) { vars[p.first] = p.second; vars[p.first].conditional = true; }
                    tok = tok->link;
                    continue;
                }
                if (isElse) { tok = tok->link; continue; }
            }
            if (isLoop) {
                // conservative: variables allocated/freed inside loops -> stop tracking them
                for (const Token *t = tok; t && t != tok->link; t = t->next) {
                    if (t->varId && vars.count(t->varId)) vars[t->varId].status = VarInfo::NOALLOC;
                    unsigned vid; int gid; bool res;
                    if (isDeallocFunctionCall(t, vid, gid, res) && vars.count(vid)) vars[vid].status = VarInfo::NOALLOC;
                }
                tok = tok->link;
                continue;
            }
            // switch/unconditional: treat as straight code
            if (prev && prev->str == ")" && prev->link && prev->link->previous && prev->link->previous->str == "switch") {
                for (const Token *t = tok; t && t != tok->link; t = t->next) if (t->varId && vars.count(t->varId)) vars[t->varId].status = VarInfo::NOALLOC;
                tok = tok->link; continue;
            }
            checkScope(tok->next, tok->link, vars, depth + 1);
            tok = tok->link;
            continue;
        }
        // return / exit / throw
        if (tok->str == "return" || tok->str == "throw") {
            std::set<unsigned> returned;
            for (const Token *t = tok->next; t && t->str != ";"; t = t->next) if (t->varId) returned.insert(t->varId);
            leakAtEnd(tok, vars, returned);
            for (auto &p : vars) p.second.status = VarInfo::NOALLOC;
            while (tok && tok->str != ";") tok = tok->next;
            if (!tok) return;
            continue;
        }
        if (tok->str == "break" || tok->str == "continue" || tok->str == "goto") {
            // leaving scope: for break in loops we don't know; cppcheck reports leak at break only if... skip: mark as unknown
            for (auto &p : vars) p.second.status = VarInfo::NOALLOC;
            continue;
        }
        if (tok->isName() && tok->next && tok->next->str == "(" && isFunctionCallNoReturn(tok, mLibrary) && tok->previous && (tok->previous->str == ";" || tok->previous->str == "{" || tok->previous->str == "}")) {
            for (auto &p : vars) p.second.status = VarInfo::NOALLOC;
            tok = tok->next->link;
            continue;
        }
        // assignment: p = alloc(...)
        if (tok->str == "=" && tok->astOperand1 && tok->astOperand2 && !tok->astParent) {
            const Token *lhs = tok->astOperand1;
            if (lhs->varId && lhs->variable && lhs->variable->isLocal && !lhs->variable->isStatic && (lhs->variable->isPointer || lhs->variable->isClass == false)) {
                // old value leaked?
                auto it = vars.find(lhs->varId);
                int gid; bool res; bool realloc;
                const Token *alloc = getAllocCall(tok->astOperand2, gid, res, realloc);
                bool rhsHasVar = false;
                { std::vector<const Token*> st{tok->astOperand2}; while (!st.empty()) { const Token *t = st.back(); st.pop_back(); if (!t) continue; if (t->varId == lhs->varId) rhsHasVar = true; st.push_back(t->astOperand1); st.push_back(t->astOperand2); } }
                if (it != vars.end() && it->second.status == VarInfo::ALLOC && !rhsHasVar) {
                    // overwriting allocated pointer -> leak
                    std::set<unsigned> none;
                    VarMap one; one[lhs->varId] = it->second;
                    leakAtEnd(tok, one, none);
                    it->second.status = VarInfo::NOALLOC;
                }
                if (alloc) {
                    VarInfo vi; vi.status = VarInfo::ALLOC; vi.groupId = gid; vi.isResource = res; vi.allocTok = alloc;
                    if (realloc) {
                        // realloc(p, n): old pointer deallocated
                    }
                    vars[lhs->varId] = vi;
                } else {
                    vars[lhs->varId] = VarInfo();
                    // "q = p" -> p's allocation is now shared: stop tracking p
                    const Token *rhs = tok->astOperand2;
                    while (rhs && rhs->isCast && rhs->astOperand1) rhs = rhs->astOperand1;
                    if (rhs && rhs->varId && vars.count(rhs->varId)) vars[rhs->varId].status = VarInfo::NOALLOC;
                }
                // skip rest of statement
                continue;
            } else {
                // assignment to non-local (e.g. struct member / global): rhs variable escapes
                std::vector<const Token*> st{tok->astOperand2};
                while (!st.empty()) { const Token *t = st.back(); st.pop_back(); if (!t) continue; if (t->varId && vars.count(t->varId)) vars[t->varId].status = VarInfo::NOALLOC; st.push_back(t->astOperand1); st.push_back(t->astOperand2); }
            }
        }
        // dealloc
        unsigned vid; int gid; bool res;
        if (isDeallocFunctionCall(tok, vid, gid, res)) {
            auto it = vars.find(vid);
            if (it != vars.end()) {
                if (it->second.status == VarInfo::DEALLOC) {
                    const Variable *var = mSymbolDatabase.getVariableFromVarId(vid);
                    const std::string nm = var ? var->name : "x";
                    ErrorPath ep{{it->second.deallocTok, ""}, {tok, ""}};
                    if (res) reportMsg(mCppCheck, mTokenizer, ep, Severity::error, "doubleFree", "Resource handle '" + nm + "' freed twice.", 415, {nm});
                    else reportMsg(mCppCheck, mTokenizer, ep, Severity::error, "doubleFree", "Memory pointed to by '" + nm + "' is freed twice.", 415, {nm});
                } else if (it->second.status == VarInfo::ALLOC && it->second.groupId != gid && it->second.groupId > 0 && gid > 0) {
                    const Variable *var = mSymbolDatabase.getVariableFromVarId(vid);
                    const std::string nm = var ? var->name : "x";
                    ErrorPath ep{{it->second.allocTok, ""}, {tok, ""}};
                    std::string allocName = it->second.allocTok ? it->second.allocTok->str : "x";
                    reportMsg(mCppCheck, mTokenizer, ep, Severity::error, "mismatchAllocDealloc", "Mismatching allocation and deallocation: " + nm, 762, {nm});
                    (void)allocName;
                }
                it->second.status = VarInfo::DEALLOC;
                it->second.deallocTok = tok;
                it->second.isResource = res;
            } else {
                const Variable *var = mSymbolDatabase.getVariableFromVarId(vid);
                if (var && var->isLocal && !var->isStatic && !var->isArgument) {
                    VarInfo vi; vi.status = VarInfo::DEALLOC; vi.deallocTok = tok; vi.isResource = res; vi.groupId = gid;
                    vars[vid] = vi;
                }
            }
            tok = tok->next->link;
            continue;
        }
        if (mTokenizer.isCPP() && tok->str == "delete" && tok->astOperand1) {
            const Token *v = tok->astOperand1;
            while (v && v->isCast && v->astOperand1) v = v->astOperand1;
            if (v && v->varId) {
                auto it = vars.find(v->varId);
                if (it != vars.end()) {
                    if (it->second.status == VarInfo::DEALLOC) {
                        const Variable *var = mSymbolDatabase.getVariableFromVarId(v->varId);
                        const std::string nm = var ? var->name : "x";
                        ErrorPath ep{{it->second.deallocTok, ""}, {tok, ""}};
                        reportMsg(mCppCheck, mTokenizer, ep, Severity::error, "doubleFree", "Memory pointed to by '" + nm + "' is freed twice.", 415, {nm});
                    }
                    it->second.status = VarInfo::DEALLOC; it->second.deallocTok = tok;
                } else {
                    const Variable *var = mSymbolDatabase.getVariableFromVarId(v->varId);
                    if (var && var->isLocal && !var->isStatic && !var->isArgument) { VarInfo vi; vi.status = VarInfo::DEALLOC; vi.deallocTok = tok; vars[v->varId] = vi; }
                }
            }
            while (tok && tok->str != ";") tok = tok->next;
            if (!tok) return;
            continue;
        }
        // use after free / escaping
        if (tok->varId && vars.count(tok->varId)) {
            VarInfo &vi = vars[tok->varId];
            const Token *p = tok->astParent;
            if (vi.status == VarInfo::DEALLOC) {
                // dereference after free
                bool deref = p && ((p->str == "*" && !p->astOperand2) || (p->str == "[" && p->astOperand1 == tok) || (p->str == "->" && p->astOperand1 == tok));
                // "free(p); p = NULL;" ok (assignment handled above). comparisons ok.
                if (deref) {
                    const Variable *var = mSymbolDatabase.getVariableFromVarId(tok->varId);
                    const std::string nm = var ? var->name : "x";
                    ErrorPath ep{{vi.deallocTok, ""}, {tok, ""}};
                    reportMsg(mCppCheck, mTokenizer, ep, Severity::error, "deallocuse", "Dereferencing '" + nm + "' after it is deallocated / released", 416, {nm});
                    vi.status = VarInfo::NOALLOC;
                } else if (p && (p->str == "(" || p->str == ",") ) {
                    // passed to function after free: deallocuse if function uses it? cppcheck reports "deallocuse" for most functions except free-like
                    const Token *a = tok; while (a->astParent && a->astParent->str == ",") a = a->astParent;
                    const Token *call = a->astParent;
                    if (call && call->str == "(" && call->astOperand1 && call->astOperand1->isName()) {
                        const std::string &fn = call->astOperand1->str;
                        const LibFunction *lf = mLibrary.getFunction(fn);
                        if (lf && !mLibrary.getDealloc(fn)) {
                            const Variable *var = mSymbolDatabase.getVariableFromVarId(tok->varId);
                            const std::string nm = var ? var->name : "x";
                            ErrorPath ep{{vi.deallocTok, ""}, {tok, ""}};
                            reportMsg(mCppCheck, mTokenizer, ep, Severity::error, "deallocuse", "Dereferencing '" + nm + "' after it is deallocated / released", 416, {nm});
                            vi.status = VarInfo::NOALLOC;
                        } else if (!lf) {
                            vi.status = VarInfo::NOALLOC;
                        }
                    }
                }
            } else if (vi.status == VarInfo::ALLOC) {
                if (p && (p->str == "(" || p->str == ",")) {
                    // passed to a function: library leak-ignore -> fine; unknown function -> might store -> stop tracking
                    const Token *a = tok; while (a->astParent && a->astParent->str == ",") a = a->astParent;
                    const Token *call = a->astParent;
                    if (call && call->str == "(" && call->astOperand1 && call->astOperand1->isName()) {
                        const std::string &fn = call->astOperand1->str;
                        const LibFunction *lf = mLibrary.getFunction(fn);
                        if (lf && lf->leakIgnore) {}
                        else if (lf && !lf->leakIgnore) { if (!mLibrary.getDealloc(fn)) vi.status = VarInfo::NOALLOC; }
                        else if (call->astOperand1->function) {
                            // user function: analyze whether argument is freed/stored - unknown -> stop tracking (cppcheck analyses the function). Simplify: stop.
                            vi.status = VarInfo::NOALLOC;
                        } else vi.status = VarInfo::NOALLOC;
                    } else vi.status = VarInfo::NOALLOC;
                } else if (p && p->str == "=" && p->astOperand2 == tok) {
                    // "q = p" or "s.x = p"
                    const Token *lhs = p->astOperand1;
                    if (!(lhs && lhs->varId && lhs->variable && lhs->variable->isLocal && !lhs->variable->isStatic)) vi.status = VarInfo::NOALLOC;
                } else if (p && (p->str == "return" || p->str == "?" || p->str == ":" )) {
                    vi.status = VarInfo::NOALLOC;
                } else if (p && p->isCast && isEscaped(p)) {
                    vi.status = VarInfo::NOALLOC;
                } else if (p && (p->str == "+" || p->str == "-") ) {
                    vi.status = VarInfo::NOALLOC;
                } else if (p && p->str == "&" && !p->astOperand2) {
                    vi.status = VarInfo::NOALLOC;
                } else if (p && (p->str == "++" || p->str == "--")) {
                    vi.status = VarInfo::NOALLOC;
                }
            }
        }
    }
}

void CheckLeakAutoVar::check() {
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        if (!scope->function || scope->type == Scope::eLambda) continue;
        VarMap vars;
        checkScope(scope->bodyStart->next, scope->bodyEnd, vars, 0);
        // end of function
        std::set<unsigned> none;
        // don't report at '}' when last statement is return (already handled)
        const Token *last = scope->bodyEnd->previous;
        while (last && last->str == ";") last = last->previous;
        if (last && last->str != "{" ) {
            const Token *stmt = last;
            while (stmt->previous && stmt->previous->str != ";" && stmt->previous->str != "{" && stmt->previous->str != "}") stmt = stmt->previous;
            if (stmt->str == "return") continue;
        }
        leakAtEnd(scope->bodyEnd, vars, none);
    }
}

// ---------------------------------------------------------------------------
// CheckMemoryLeakNoVar: "malloc(10);" result not used
// ---------------------------------------------------------------------------
class CheckMemoryLeakNoVar : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Memory leaks (address not taken)"; }
    void runChecks() override {
        for (const Scope *scope : mSymbolDatabase.functionScopes) {
            for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
                if (!tok->isName() || !tok->next || tok->next->str != "(" || tok->function) continue;
                if (!tok->previous || !(tok->previous->str == ";" || tok->previous->str == "{" || tok->previous->str == "}")) continue;
                if (!tok->next->link || !tok->next->link->next || tok->next->link->next->str != ";") continue;
                const LibAllocFunc *af = mLibrary.getAlloc(tok->str);
                if (!af || af->isRealloc) continue;
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::error, "leakReturnValNotUsed", "Return value of allocation function '" + tok->str + "' is not stored.", 771, {tok->str});
            }
        }
    }
};

// ---------------------------------------------------------------------------
// CheckAutoVariables (simplified)
// ---------------------------------------------------------------------------
class CheckAutoVariables : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Auto Variables"; }
    void runChecks() override {
        for (const Scope *scope : mSymbolDatabase.functionScopes) {
            const Function *f = scope->function;
            if (!f) continue;
            for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
                // return &local / return local array
                if (tok->str == "return" && tok->astOperand1) {
                    const Token *e = tok->astOperand1;
                    while (e && e->isCast && e->astOperand1) e = e->astOperand1;
                    if (e && e->str == "&" && !e->astOperand2 && e->astOperand1 && e->astOperand1->variable) {
                        const Variable *v = e->astOperand1->variable;
                        if (v->isLocal && !v->isStatic && !v->isPointer && !v->isReference && !v->isArray && !v->isArgument && e->astOperand1->astOperand1 == nullptr) {
                            ErrorPath ep{{e, "Address of variable taken here."}, {tok, "Returning pointer to local variable '" + v->name + "' that will be invalid when returning."}};
                            // cppcheck: returnDanglingLifetime with variable declaration note? Use: tok and variable
                            ErrorPath ep2{{e, "Address of variable taken here."}, {v->nameToken, "Variable created here."}, {tok, ""}};
                            reportMsg(mCppCheck, mTokenizer, ep2, Severity::error, "returnDanglingLifetime", "Returning pointer to local variable '" + v->name + "' that will be invalid when returning.", 562, {v->name});
                        }
                    } else if (e && e->variable && e->variable->isArray && e->variable->isLocal && !e->variable->isStatic && !e->variable->isArgument && !e->astOperand1 && f->returnsPointer) {
                        const Variable *v = e->variable;
                        ErrorPath ep{{e, "Array decayed to pointer here."}, {v->nameToken, "Variable created here."}, {tok, ""}};
                        reportMsg(mCppCheck, mTokenizer, ep, Severity::error, "returnDanglingLifetime", "Returning pointer to local variable '" + v->name + "' that will be invalid when returning.", 562, {v->name});
                    }
                }
                // assigning address of local to function argument pointer: "*p = &x" -> autoVariables? cppcheck: "Address of local auto-variable assigned to a function parameter."
                if (tok->str == "=" && tok->astOperand1 && tok->astOperand2 && !tok->astParent) {
                    const Token *lhs = tok->astOperand1;
                    const Token *rhs = tok->astOperand2;
                    if (lhs->str == "*" && !lhs->astOperand2 && lhs->astOperand1 && lhs->astOperand1->variable && lhs->astOperand1->variable->isArgument && lhs->astOperand1->variable->pointerDepth >= 2 && rhs->str == "&" && !rhs->astOperand2 && rhs->astOperand1 && rhs->astOperand1->variable && rhs->astOperand1->variable->isLocal && !rhs->astOperand1->variable->isStatic && !rhs->astOperand1->variable->isArgument) {
                        reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::error, "autoVariables", "Address of local auto-variable assigned to a function parameter.\nDangerous assignment - the function parameter is assigned the address of a local auto-variable. Local auto-variables are reserved from the stack which is freed when the function ends. So the pointer to a local variable is invalid after the function ends.", 562);
                    }
                }
            }
        }
    }
};

std::vector<std::unique_ptr<Check>> createChecksLeak(const Tokenizer &tokenizer, const SymbolDatabase &symdb, const Settings &settings, const Library &library, CppCheck &cppcheck, int which) {
    std::vector<std::unique_ptr<Check>> v;
    if (which == 0) v.push_back(std::make_unique<CheckAutoVariables>(tokenizer, symdb, settings, library, cppcheck));
    if (which == 1) v.push_back(std::make_unique<CheckLeakAutoVar>(tokenizer, symdb, settings, library, cppcheck));
    if (which == 2) v.push_back(std::make_unique<CheckMemoryLeakNoVar>(tokenizer, symdb, settings, library, cppcheck));
    return v;
}
