static void reportMsg(CppCheck &cppcheck, const Tokenizer &tokenizer, const ErrorPath &ep, Severity sev, const std::string &id, const std::string &msg, int cwe, const std::vector<std::string> &symbols = {}, Certainty cert = Certainty::normal) {
    ErrorMessage em;
    for (const auto &p : ep) { if (!p.first) continue; em.callStack.push_back(FileLocation(tokenizer.list.files[p.first->fileIndex], p.first->linenr, p.first->column, p.second)); }
    em.id = id; em.severity = sev; em.cwe = cwe; em.certainty = cert;
    em.setMessage(msg);
    em.symbolNames = symbols;
    em.file0 = tokenizer.list.sourceFile;
    cppcheck.reportErr(em);
}

static std::vector<const Token*> getArguments(const Token *ftok) {
    std::vector<const Token*> args;
    if (!ftok || !ftok->next || ftok->next->str != "(") return args;
    const Token *a = ftok->next->astOperand2;
    while (a && a->str == ",") { args.insert(args.begin(), a->astOperand2); a = a->astOperand1; }
    if (a) args.insert(args.begin(), a);
    return args;
}

// ---------------------------------------------------------------------------
// CheckSizeof
// ---------------------------------------------------------------------------
class CheckSizeof : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Sizeof"; }
    void runChecks() override {
        sizeofsizeof();
        sizeofCalculation();
        sizeofFunction();
        checkSizeofForNumericParameter();
        checkSizeofForArrayParameter();
        sizeofVoid();
    }
    void sizeofsizeof() {
        if (!mSettings.sev_warning) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (tok->str == "sizeof" && tok->next && tok->next->str == "(" && tok->next->next && tok->next->next->str == "sizeof") {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "sizeofsizeof", "Calling sizeof for 'sizeof'.\nCalling sizeof for 'sizeof looks like a suspicious code and most likely there should be just one 'sizeof'. The current code is equivalent to 'sizeof(size_t)'", 682);
            }
        }
    }
    void sizeofCalculation() {
        if (!mSettings.sev_warning) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (tok->str != "sizeof" || !tok->next || tok->next->str != "(" || !tok->next->link) continue;
            const Token *argument = tok->next->astOperand2;
            if (!argument) continue;
            // skip "sizeof(x) * y" inside: argument is the expression inside parentheses
            if (argument->isArithmeticalOp() && argument->astOperand1 && argument->astOperand2 && !argument->isExpandedMacro) {
                // skip e.g. sizeof(a * b) if macro
                const bool inconclusive = argument->isExpandedMacro;
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "sizeofCalculation", "Found calculation inside sizeof().", 682, {}, inconclusive ? Certainty::inconclusive : Certainty::normal);
            } else if (argument->str == "++" || argument->str == "--" || (argument->isArithmeticalOp() && argument->astOperand1 && argument->astOperand2)) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "sizeofCalculation", "Found calculation inside sizeof().", 682);
            }
        }
    }
    void sizeofFunction() {
        if (!mSettings.sev_warning) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (tok->str != "sizeof" || !tok->next || tok->next->str != "(" || !tok->next->link) continue;
            const Token *argument = tok->next->astOperand2;
            if (argument && argument->str == "(" && argument->astOperand1 && argument->astOperand1->function && !argument->isCast) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "sizeofFunctionCall", "Found function call inside sizeof().", 682);
            }
        }
    }
    void checkSizeofForNumericParameter() {
        if (!mSettings.sev_warning) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (tok->str != "sizeof" || !tok->next || tok->next->str != "(") continue;
            const Token *arg = tok->next->next;
            if (arg && arg->isNumber() && arg->next == tok->next->link) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "sizeofwithnumericparameter", "Suspicious usage of 'sizeof' with a numeric constant as parameter.\nIt is unusual to use a constant value with sizeof. For example, 'sizeof(10)' returns 4 (in 32-bit systems) or 8 (in 64-bit systems) instead of 10. 'sizeof('A')' and 'sizeof(char)' can return different results.", 682);
            }
        }
    }
    void checkSizeofForArrayParameter() {
        if (!mSettings.sev_warning) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (tok->str != "sizeof" || !tok->next || tok->next->str != "(") continue;
            const Token *arg = tok->next->next;
            if (arg && arg->variable && arg->next == tok->next->link && arg->variable->isArgument && arg->variable->isArray) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "sizeofwithsilentarraypointer", "Using 'sizeof' on array given as function argument returns size of a pointer.\nUsing 'sizeof' for array given as function argument returns the size of a pointer. It does not return the size of the whole array in bytes as might be expected. For example, this code:\n     int f(char a[100]) {\n         return sizeof(a);\n     }\nreturns 4 (in 32-bit systems) or 8 (in 64-bit systems) instead of 100 (the size of the array in bytes).", 467, {arg->str});
            }
        }
    }
    void sizeofVoid() {
        if (!mSettings.sev_portability) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (tok->str == "sizeof" && tok->next && tok->next->str == "(" && tok->next->next && tok->next->next->str == "void" && tok->next->next->next == tok->next->link) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::portability, "sizeofVoid", "Behaviour of 'sizeof(void)' is not covered by the ISO C standard.\nA value for 'sizeof(void)' is defined only as part of a GNU C extension, which defines 'sizeof(void)' to be 1.", 682);
            }
        }
    }
};

// ---------------------------------------------------------------------------
// CheckString
// ---------------------------------------------------------------------------
class CheckString : public Check {
public:
    using Check::Check;
    std::string name() const override { return "String"; }
    void runChecks() override {
        strPlusChar();
        checkSuspiciousStringCompare();
        checkAlwaysTrueOrFalseStringCompare();
        stringLiteralWrite();
    }
    void strPlusChar() {
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (tok->str != "+" || !tok->astOperand1 || !tok->astOperand2) continue;
            const Token *a = tok->astOperand1, *b = tok->astOperand2;
            if (a->tokType == Token::eString && (b->tokType == Token::eChar || (b->variable && b->variable->isCharType && !b->variable->isPointer && !b->variable->isArray))) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::error, "strPlusChar", "Unusual pointer arithmetic. A value of type 'char' is added to a string literal.", 665);
            }
        }
    }
    void checkSuspiciousStringCompare() {
        if (!mSettings.sev_warning) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (!(tok->str == "==" || tok->str == "!=") || !tok->astOperand1 || !tok->astOperand2) continue;
            const Token *varTok = tok->astOperand1, *litTok = tok->astOperand2;
            if (litTok->tokType != Token::eString) std::swap(varTok, litTok);
            if (litTok->tokType != Token::eString) continue;
            if (!varTok->variable) continue;
            const Variable *var = varTok->variable;
            if (var->isArray && !var->isPointer) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "literalWithCharPtrCompare", "String literal compared with variable '" + varTok->str + "'. Did you intend to use strcmp() instead?", 595, {varTok->str});
            } else if (var->isPointer && var->isCharType && var->pointerDepth == 1) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "literalWithCharPtrCompare", "String literal compared with variable '" + varTok->str + "'. Did you intend to use strcmp() instead?", 595, {varTok->str});
            }
        }
    }
    void checkAlwaysTrueOrFalseStringCompare() {
        if (!mSettings.sev_warning) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (!tok->isName() || !tok->next || tok->next->str != "(" || tok->function) continue;
            const std::string &n = tok->str;
            if (!(n == "strcmp" || n == "strncmp" || n == "stricmp" || n == "strcmpi" || n == "strcasecmp" || n == "strncasecmp" || n == "wcscmp" || n == "wcsncmp" || n == "wcscasecmp" || n == "wcsncasecmp" || n == "memcmp" || n == "_stricmp" || n == "_strnicmp")) continue;
            std::vector<const Token*> args = getArguments(tok);
            if (args.size() < 2) continue;
            const Token *a = args[0], *b = args[1];
            if (a->tokType == Token::eString && b->tokType == Token::eString) {
                if (a->str == b->str)
                    reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "staticStringCompare", "Unnecessary comparison of static strings.\nThe compared strings, '" + a->str + "' and '" + b->str + "', are always identical. Therefore the comparison is unnecessary and looks suspicious.", 570);
                else
                    reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "staticStringCompare", "Unnecessary comparison of static strings.\nThe compared strings, '" + a->str + "' and '" + b->str + "', are static and always different. Therefore the comparison is unnecessary and looks suspicious.", 570);
            } else if (a->varId && a->varId == b->varId && a->variable && (a->variable->isArray || a->variable->isPointer)) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "stringCompare", "Comparison of identical string variables.\nThe compared strings, '" + a->str + "' and '" + b->str + "', are identical. This could be a logic bug.", 570, {a->str});
            }
        }
    }
    void stringLiteralWrite() {
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (tok->tokType != Token::eString) continue;
            const Token *p = tok->astParent;
            if (!p) continue;
            // "abc"[0] = x
            if (p->str == "[" && p->astOperand1 == tok && p->astParent && p->astParent->isAssignmentOp() && p->astParent->astOperand1 == p) {
                reportMsg(mCppCheck, mTokenizer, {{p->astParent, ""}}, Severity::error, "stringLiteralWrite", "Modifying string literal " + tok->str + " directly or indirectly is undefined behaviour.", 758);
            }
        }
    }
};

// ---------------------------------------------------------------------------
// CheckType
// ---------------------------------------------------------------------------
class CheckType : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Type"; }
    void runChecks() override {
        checkTooBigBitwiseShift();
    }
    void checkTooBigBitwiseShift() {
        if (mSettings.platform.type == Platform::Unspecified) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (!(tok->str == "<<" || tok->str == ">>" || tok->str == "<<=" || tok->str == ">>=") || !tok->astOperand1 || !tok->astOperand2) continue;
            const Token *lhs = tok->astOperand1;
            int bits = 0;
            bool isSigned = true;
            if (lhs->variable && !lhs->variable->isPointer && !lhs->variable->isArray && lhs->variable->isIntegral) {
                const std::string &t = lhs->variable->typeName;
                if (t == "int" || t == "unsigned int" || t == "unsigned" || t == "signed int") bits = mSettings.platform.sizeof_int * 8;
                else if (t == "long" || t == "unsigned long") bits = mSettings.platform.sizeof_long * 8;
                else if (t == "long long" || t == "unsigned long long") bits = mSettings.platform.sizeof_long_long * 8;
                else if (t == "short" || t == "unsigned short") bits = mSettings.platform.sizeof_int * 8; // promoted
                else if (t == "char" || t == "unsigned char" || t == "signed char") bits = mSettings.platform.sizeof_int * 8;
                isSigned = !lhs->variable->isUnsigned;
            } else if (lhs->isNumber() && isIntLiteral(lhs->str)) {
                std::string sfx; for (char c : lhs->str) if (c == 'L' || c == 'l' || c == 'U' || c == 'u') sfx += (char)toupper(c);
                if (sfx.find("LL") != std::string::npos) bits = mSettings.platform.sizeof_long_long * 8;
                else if (sfx.find('L') != std::string::npos) bits = mSettings.platform.sizeof_long * 8;
                else bits = mSettings.platform.sizeof_int * 8;
                isSigned = sfx.find('U') == std::string::npos;
            } else continue;
            if (bits == 0) continue;
            const ValueFlowValue *v = tok->astOperand2->getKnownValue();
            if (!v) {
                // possible values
                for (const ValueFlowValue &pv : tok->astOperand2->values) if (pv.valueType == ValueFlowValue::INT && !pv.impossible && (pv.intvalue >= bits)) { v = &pv; break; }
                if (!v) continue;
                if (!v->isKnown() && !mSettings.sev_warning) continue;
            }
            if (v->intvalue < 0) continue;
            if (v->intvalue >= bits) {
                ErrorPath ep = getErrorPath(tok, v, "Shift");
                reportMsg(mCppCheck, mTokenizer, ep, v->errorSeverity() ? Severity::error : Severity::warning, "shiftTooManyBits", "Shifting " + std::to_string(bits) + "-bit value by " + std::to_string(v->intvalue) + " bits is undefined behaviour", 758);
            } else if (isSigned && v->intvalue == bits - 1 && mSettings.sev_portability && (tok->str == "<<" || tok->str == "<<=")) {
                // only when lhs value is known positive? cppcheck: shiftTooManyBitsSigned for signed lhs
                const ValueFlowValue *lv = lhs->getKnownValue();
                if (lv && lv->intvalue <= 0) continue;
                if (!lv) continue;
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::portability, "shiftTooManyBitsSigned", "Shifting signed " + std::to_string(bits) + "-bit value by " + std::to_string(v->intvalue) + " bits is implementation-defined behaviour", 758);
            }
        }
    }
};

// ---------------------------------------------------------------------------
// CheckBool
// ---------------------------------------------------------------------------
class CheckBool : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Boolean"; }
    void runChecks() override {
        checkAssignBoolToPointer();
        checkIncrementBoolean();
        checkComparisonOfBoolWithInt();
    }
    void checkAssignBoolToPointer() {
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (tok->str != "=" || !tok->astOperand1 || !tok->astOperand2) continue;
            if (!astIsPointer(tok->astOperand1)) continue;
            if (tok->astOperand1->variable && (tok->astOperand1->variable->isArray || tok->astOperand1->variable->isClass)) continue;
            if (astIsBool(tok->astOperand2) && !tok->astOperand2->isCast) {
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::error, "assignBoolToPointer", "Boolean value assigned to pointer.", 587);
            }
        }
    }
    void checkIncrementBoolean() {
        if (!mSettings.sev_style) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (tok->str != "++" || !tok->astOperand1 || !tok->astOperand1->variable) continue;
            const Variable *var = tok->astOperand1->variable;
            if (var->isBool && !var->isPointer && !var->isArray)
                reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::style, "incrementboolean", "Incrementing a variable of type 'bool' with postfix operator++ is deprecated by the C++ Standard. You should assign it the value 'true' instead.\nThe operand of a postfix increment operator may be of type bool but it is deprecated by C++ Standard (Annex D-1) and the operand is always set to true. You should assign it the value 'true' instead.", 398, {var->name});
        }
    }
    void checkComparisonOfBoolWithInt() {
        if (!mSettings.sev_warning || !mTokenizer.isCPP()) return;
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (!tok->isComparisonOp() || !tok->astOperand1 || !tok->astOperand2) continue;
            const Token *a = tok->astOperand1, *b = tok->astOperand2;
            const Token *boolTok = nullptr, *numTok = nullptr;
            if (a->variable && a->variable->isBool && !a->variable->isPointer && b->isNumber()) { boolTok = a; numTok = b; }
            else if (b->variable && b->variable->isBool && !b->variable->isPointer && a->isNumber()) { boolTok = b; numTok = a; }
            if (!boolTok) continue;
            long long v = toLongNumber(numTok->str);
            if (v == 0 || v == 1) continue;
            reportMsg(mCppCheck, mTokenizer, {{tok, ""}}, Severity::warning, "comparisonOfBoolWithInvalidComparator", "Comparison of a boolean value using relational operator (<, >, <= or >=).", 398);
        }
    }
};

// ---------------------------------------------------------------------------
// Library-based invalid function argument checks (CheckFunctions::invalidFunctionUsage)
// ---------------------------------------------------------------------------
static bool isValidValue(const std::string &valid, long long value) {
    // format: "0:", ":10", "1:5", "1,3,5:7", "-1:"
    std::stringstream ss(valid);
    std::string part;
    bool any = false;
    while (std::getline(ss, part, ',')) {
        if (part.empty()) continue;
        any = true;
        std::string::size_type colon = part.find(':');
        if (colon == std::string::npos) { if (atoll(part.c_str()) == value) return true; continue; }
        std::string lo = part.substr(0, colon), hi = part.substr(colon + 1);
        bool okLo = lo.empty() || value >= atoll(lo.c_str());
        bool okHi = hi.empty() || value <= atoll(hi.c_str());
        if (okLo && okHi) return true;
    }
    return !any;
}

class CheckFunctionsLib : public Check {
public:
    using Check::Check;
    std::string name() const override { return "Check function usage (library)"; }
    void runChecks() override {
        for (const Token *tok = mTokenizer.list.front(); tok; tok = tok->next) {
            if (!tok->isName() || !tok->next || tok->next->str != "(" || tok->function || tok->varId) continue;
            if (tok->previous && (tok->previous->str == "." || tok->previous->str == "->")) continue;
            const LibFunction *lf = mLibrary.getFunction(tok->str);
            if (!lf) continue;
            std::vector<const Token*> args = getArguments(tok);
            for (size_t i = 0; i < args.size(); ++i) {
                auto it = lf->args.find((int)i + 1);
                if (it == lf->args.end()) continue;
                const LibArg &la = it->second;
                const Token *arg = args[i];
                if (!la.valid.empty()) {
                    const ValueFlowValue *v = arg->getKnownValue();
                    if (v && !isValidValue(la.valid, v->intvalue)) {
                        std::ostringstream os;
                        os << "Invalid " << tok->str << "() argument nr " << (i + 1) << ". The value is " << v->intvalue << " but the valid values are '" << la.valid << "'.";
                        ErrorPath ep = getErrorPath(arg, v, "");
                        ep.back().second = "";
                        reportMsg(mCppCheck, mTokenizer, ep, Severity::error, "invalidFunctionArg", os.str(), 628);
                    }
                }
                if (la.notbool && astIsBool(arg) && !arg->isNumber()) {
                    std::ostringstream os;
                    os << "Invalid " << tok->str << "() argument nr " << (i + 1) << ". A non-boolean value is required.";
                    reportMsg(mCppCheck, mTokenizer, {{arg, ""}}, Severity::error, "invalidFunctionArgBool", os.str(), 628);
                }
                if (la.strz && arg->tokType == Token::eChar) {}
            }
        }
    }
};

std::vector<std::unique_ptr<Check>> createChecksMisc(const Tokenizer &tokenizer, const SymbolDatabase &symdb, const Settings &settings, const Library &library, CppCheck &cppcheck, int which) {
    std::vector<std::unique_ptr<Check>> v;
    if (which == 0) v.push_back(std::make_unique<CheckBool>(tokenizer, symdb, settings, library, cppcheck));
    if (which == 1) v.push_back(std::make_unique<CheckSizeof>(tokenizer, symdb, settings, library, cppcheck));
    if (which == 2) v.push_back(std::make_unique<CheckString>(tokenizer, symdb, settings, library, cppcheck));
    if (which == 3) v.push_back(std::make_unique<CheckType>(tokenizer, symdb, settings, library, cppcheck));
    if (which == 4) v.push_back(std::make_unique<CheckFunctionsLib>(tokenizer, symdb, settings, library, cppcheck));
    return v;
}
