static void reportMsg(CppCheck &cppcheck, const Tokenizer &tokenizer, const ErrorPath &ep, Severity sev, const std::string &id, const std::string &msg, int cwe, const std::vector<std::string> &symbols = {}, Certainty cert = Certainty::normal) {
