                for (const auto &p : v->errorPath) vv.path.push_back(p);
                vv.path.emplace_back(argtok, "Calling function '" + f->name + "', " + ordinal((int)i + 1) + " argument '" + argtok->expressionString() + "' value is " + std::to_string(v->intvalue));
                // forward inside function body
