                for (Token *t = const_cast<Token*>(fs->bodyStart)->next; t && t != fs->bodyEnd && !stop; t = t->next) {
                    if (t->str == "{" && t->link) {
                        const Token *prev = t->previous;
                        if (prev && prev->str == "=") { t = t->link; continue; }
                        if (prev && prev->str == ")" && prev->link) {
                            const Token *kw = prev->link->previous;
                            if (kw && (kw->str == "for" || kw->str == "while")) { if (findVariableChanged(t, t->link, param.varId)) { stop = true; break; } }
