                                if (res == 0) { t = t->link; if (t->next && t->next->str == "else" && t->next->next && t->next->next->str == "{") { if (isEscapeScope(t->next->next, library)) { stop = true; break; } ++depth; t = t->next->next; } continue; }
                                if (res == 1) {
                                    if (isEscapeScope(t, library)) {
                                        for (Token *x = t->next; x && x != t->link; x = x->next) if (x->varId == param.varId && !isWriteAccess(x)) addValue(x, vv);
                                        stop = true; break;
                                    }
                                } else { stop = true; break; }
                            }
                        }
                        ++depth;
                        continue;
