static long long elementSize(const Variable *var, const Settings &settings) {
    if (var->isPointer && !var->isArray) return settings.platform.sizeof_pointer;
    const std::string &t = var->typeName;
    if (t == "char" || t == "unsigned char" || t == "signed char" || t == "bool") return 1;
    if (t == "short" || t == "unsigned short") return settings.platform.sizeof_short;
    if (t == "int" || t == "unsigned int" || t == "unsigned" || t == "signed" || t == "float") return settings.platform.sizeof_int;
    if (t == "long" || t == "unsigned long") return settings.platform.sizeof_long;
    if (t == "long long" || t == "unsigned long long" || t == "double") return settings.platform.sizeof_long_long;
    if (t == "wchar_t") return settings.platform.sizeof_wchar_t;
    if (t == "size_t") return settings.platform.sizeof_size_t;
    if (var->isPointer) return settings.platform.sizeof_pointer;
    return 0;
}

static long long stringLiteralLength(const std::string &s) {
    std::string::size_type q = s.find('"');
    std::string inner = s.substr(q + 1, s.size() - q - 2);
    long long len = 0;
    for (size_t i = 0; i < inner.size(); ++i) {
        if (inner[i] == '\\\\') {
            ++i;
            if (i < inner.size() && inner[i] == 'x') { ++i; while (i < inner.size() && isxdigit((unsigned char)inner[i])) ++i; --i; }
            else if (i < inner.size() && inner[i] >= '0' && inner[i] <= '7') { size_t j = i; while (j < inner.size() && j < i + 3 && inner[j] >= '0' && inner[j] <= '7') ++j; i = j - 1; }
        }
        ++len;
    }
    return len;
}

void CheckBufferOverrun::bufferOverflow() {
    for (const Scope *scope : mSymbolDatabase.functionScopes) {
        for (const Token *tok = scope->bodyStart; tok && tok != scope->bodyEnd; tok = tok->next) {
            if (!tok->isName() || !tok->next || tok->next->str != "(" || tok->function || tok->varId) continue;
            if (tok->previous && (tok->previous->str == "." || tok->previous->str == "->")) continue;
            const LibFunction *lf = mLibrary.getFunction(tok->str);
            if (!lf) continue;
            std::vector<const Token*> args;
            { const Token *a = tok->next->astOperand2; while (a && a->str == ",") { args.insert(args.begin(), a->astOperand2); a = a->astOperand1; } if (a) args.insert(args.begin(), a); }
            for (size_t i = 0; i < args.size(); ++i) {
                auto it = lf->args.find((int)i + 1);
                if (it == lf->args.end() || it->second.minsizeType.empty()) continue;
                const LibArg &la = it->second;
                const Token *bufTok = args[i];
                while (bufTok && bufTok->isCast && bufTok->astOperand1) bufTok = bufTok->astOperand1;
                if (!bufTok || !bufTok->variable || !bufTok->variable->isArray || bufTok->astOperand1) continue;
                const Variable *var = bufTok->variable;
                if (var->isArgument) continue;
                long long bytes = elementSize(var, mSettings);
                if (bytes <= 0) continue;
                for (size_t d = 0; d < var->dimensions.size(); ++d) { if (!var->dimensionKnown[d]) { bytes = 0; break; } bytes *= var->dimensionValues[d]; }
                if (bytes <= 0) continue;
                long long needed = -1;
                const ValueFlowValue *val = nullptr;
                if (la.minsizeType == "strlen") {
                    if (la.minsizeArg <= 0 || la.minsizeArg > (int)args.size()) continue;
                    const Token *s2 = args[la.minsizeArg - 1];
                    if (s2->tokType == Token::eString) needed = stringLiteralLength(s2->str) + 1;
                    else continue;
                } else if (la.minsizeType == "argvalue") {
                    if (la.minsizeArg <= 0 || la.minsizeArg > (int)args.size()) continue;
                    const Token *s2 = args[la.minsizeArg - 1];
                    val = s2->getKnownValue();
                    if (!val) continue;
                    needed = val->intvalue;
                    if (la.minsizeArg2 > 0 && la.minsizeArg2 <= (int)args.size()) { const ValueFlowValue *v2 = args[la.minsizeArg2 - 1]->getKnownValue(); if (!v2) continue; needed *= v2->intvalue; }
                } else if (la.minsizeType == "mul") {
                    if (la.minsizeArg <= 0 || la.minsizeArg > (int)args.size() || la.minsizeArg2 <= 0 || la.minsizeArg2 > (int)args.size()) continue;
                    const ValueFlowValue *v1 = args[la.minsizeArg - 1]->getKnownValue();
                    const ValueFlowValue *v2 = args[la.minsizeArg2 - 1]->getKnownValue();
                    if (!v1 || !v2) continue;
                    needed = v1->intvalue * v2->intvalue;
                    val = v1;
                } else if (la.minsizeType == "value") {
                    needed = atoll(la.minsizeValue.c_str());
                } else if (la.minsizeType == "sizeof") {
                    if (la.minsizeArg <= 0 || la.minsizeArg > (int)args.size()) continue;
                    const Token *s2 = args[la.minsizeArg - 1];
                    if (s2->tokType == Token::eString) needed = stringLiteralLength(s2->str) + 1;
                    else if (s2->variable && s2->variable->isArray && !s2->astOperand1) {
                        long long b = elementSize(s2->variable, mSettings);
                        for (size_t d = 0; d < s2->variable->dimensions.size(); ++d) { if (!s2->variable->dimensionKnown[d]) { b = 0; break; } b *= s2->variable->dimensionValues[d]; }
                        if (b <= 0) continue;
                        needed = b;
                    } else continue;
                } else continue;
                if (needed > bytes) {
                    ErrorPath ep;
                    if (val) for (const auto &p : val->errorPath) ep.push_back(p);
                    ep.emplace_back(tok, "");
                    ErrorMessage em;
                    for (const auto &p : ep) em.callStack.push_back(FileLocation(mTokenizer.list.files[p.first->fileIndex], p.first->linenr, p.first->column, p.second));
                    em.id = "bufferAccessOutOfBounds"; em.severity = Severity::error; em.cwe = 788;
                    em.setMessage("Buffer is accessed out of bounds: " + var->name);
                    em.symbolNames.push_back(var->name);
                    em.file0 = mTokenizer.list.sourceFile;
                    mCppCheck.reportErr(em);
                }
            }
        }
    }
