        }
        st.push_back(t->astOperand1); st.push_back(t->astOperand2);
    }
    return changed;
}

void CheckCondition::multiCondition() {
    if (!mSettings.sev_style) return;
    for (const Scope &scope : mSymbolDatabase.scopeList) {
        if (scope.type != Scope::eIf) continue;
        const Token *tok1 = scope.classDef->next; // '('
        if (!tok1 || !tok1->link) continue;
        const Token *cond1 = tok1->astOperand2;
        if (!cond1) continue;
        const Token *tok2 = tok1->link->next; // '{'
        if (!tok2 || tok2->str != "{" || !tok2->link) continue;
        tok2 = tok2->link->next; // else?
        if (!tok2 || tok2->str != "else") continue;
        tok2 = tok2->next; // '{' of else (inserted by elseif) or
        if (!tok2) continue;
        if (tok2->str == "{" && tok2->next && tok2->next->str == "if") tok2 = tok2->next;
        if (tok2->str != "if" || !tok2->next || tok2->next->str != "(") continue;
        const Token *cond2 = tok2->next->astOperand2;
        if (!cond2) continue;
        if (!isSameExpression(cond1, cond2)) continue;
