static bool condVarsChanged(const Token *cond, const Token *start, const Token *end, bool cpp) {
    bool changed = false;
    std::vector<const Token*> st{cond};
    while (!st.empty() && !changed) {
        const Token *t = st.back(); st.pop_back();
        if (!t) continue;
        if (t->varId && isVariableChanged(start, end, t->varId, cpp)) changed = true;
