        }
        st.push_back(t->astOperand1); st.push_back(t->astOperand2);
    }
    return changed;
}

void CheckCondition::multiCondition() {
    if (!mSettings.sev_style) return;
    for (const Scope &scope : mSymbolDatabase.scopeList) {
